(function(){
  var C=window.YLT_CFG||{};var books=C.books||(window.GAME_CONFIG&&window.GAME_CONFIG.books)||[];var byId={};for(var i=0;i<books.length;i++)byId[books[i].id]=books[i];
  function acc(id,chs){var b=byId[id];if(!b)return;b.chapters=(b.chapters||[]).concat(chs);}
  acc("b_jingyue",[{"n": 1, "text": "卷一\n\n<篇名>景岳全书\n书名：景岳全书\n作者：张介宾  \n朝代：明  \n年份：公元1640年  \n\n\n\n<目录>\n\n<篇名>贾序\n\n属性：人情莫不欲寿，恒讳疾而忌医，孰知延寿之方，匪药石不为功；得病之由，多半服食不 \n审，致庸医之误人，曰药之不如其勿药，是由因噎废食也。原夫天地生物，以好生为心，草 \n木、金石、飞潜、溲渤之类，皆可已病，听其人之自取。古之圣人，又以天地之心为己心， \n着为《素问》《难经》，定为君臣佐使方旨，待其人善用之。用之善，出为良医，药石方旨 \n，惟吾所使，寿夭荣谢之数，自我操之，如执左券，皆稽古之力也。庸医反是，执古方，泥 \n古法，罔然不知病所自起，为表、为里、为虚、为实，一旦杀人，不知自反，反归咎于食忌 \n，洗其耻于方册，此不善学人之过也。故曰∶肱三折而成良医，言有所试也；不三世不服其 \n药，言有所受之也。假试之知而不行，受之传而不习，己先病矣，己之不暇，何暇于已人之 \n病？是无怪乎忌医者之纷纷也。 \n越人张景岳，豪杰士也。先世以军功起家，食禄千户。结发读书，不 章句。 \n初学万人敌，得鱼腹八阵不传之秘，仗策游侠，往来燕冀间，慨然有封野狼胥、勒燕然之想， \n榆林、碣石、凤城、鸭江，足迹几遍。投笔弃 ，绝塞失其天险；谈兵说剑，壮士逊其 \n颜色。所遇数奇，未尝浼首求合也。由是落落难偶，浩然归里，肆力于轩岐之学，以养 \n其亲。遇有危证，世医拱手，得其一匕，矍然起矣。常出其平生之技，着为医学全书，凡六 \n十有四卷。语其徒曰∶医之用药，犹用兵也。治病如治寇攘，知寇所在，精兵攻之，兵不血 \n刃矣。故所着书，仿佛八阵遗意。古方，经也；新方，权也，经权互用，天下无难事矣。书 \n既成，限于资，未及流传而殁，遗草属诸外孙林君日蔚。蔚载与南游，初见赏于方伯鲁公， \n捐资付梓。板成北去，得其书者，视为肘后之珍，世罕见之。予生平颇好稽古，犹专意于养 \n生家言，是书诚养生之秘笈也。惜其流传不广，出俸翻刻，公诸宇内。善读其书者，庶免庸 \n医误人之咎，讳疾忌医者，毋因噎而废食也可。 \n\\x时康熙五十年岁次辛卯孟春两广运使瀛海贾棠题于羊城官舍之退思堂\\x \n\n\n\n<目录>\n\n<篇名>范序\n\n属性：我皇上御极五十年，惠政频施，仁风洋溢，民尽雍熙，物无夭札，固无藉于《灵枢》《 \n素问》之书，而后臻斯世于寿域也。虽然，先文正公有言∶不为良相，当为良医。乃知有圣 \n君不可无良相，而良医之权又与良相等，医之一道，又岂可忽乎哉！自轩辕、岐伯而下，代 \n有奇人，惟长沙张仲景为最着。厥后，或刘或李或朱，并能以良医名，然其得力处，不能不 \n各循一己之见，犹儒者尊陆尊朱，异同之论，纷纷莫一。 \n越人张景岳，盖医而良者也。天分既高，师古复细，是能融会乎百家，而贯通乎诸子者 \n，名其书曰“全”，其自负亦可知矣。他不具论，观其《逆数》一篇，逆者得阳，顺者得阴 \n，降以升为主，此开阴阳之秘，盖医而仙者也。世有以仙为医，而尚不得谓之良哉？而或者 \n曰∶医，生道也；兵，杀机也。医以阵名，毋乃不伦乎？不知元气盛而外邪不能攻，亦由壁 \n垒固而侵劫不能犯也。况兵之虚实成败，其机在于俄顷；而医之寒热攻补，其差不容于毫发 \n，孰谓医与兵之不相通哉？若将不得人，是以兵与敌也；医不得人，是以人试药也。此又景 \n岳以阵名篇之微意也。 \n是书为谦庵鲁方伯任粤时所刻，纸贵五都，求者不易。转运使贾君，明于顺逆之道，精 \n于升降之理，济世情殷，重登梨枣。予于庚寅孟冬，奉天子命，带星就道，未获观其告竣。 \n阅两月，贾君以札见示，《景岳全书》重刻已成，命予作序。余虽不敏，然以先文正公良医 \n良相之意广之，安知昔日之张君足为良医，而异日之贾君不为良相，以佐我皇上万寿无疆之 \n历服耶？故为数语以弁卷首。 \n\\x闽浙制使沈阳范时崇撰\\x \n\n\n\n<目录>\n\n<篇名>查序\n\n属性：天地之道，不过曰阴与阳，二气之相宣，而万物于以发育。人固一物耳，皆秉是气以生 \n，赋以成形，不能无所疵疠，而况物情之相感，物欲之相攻，此疾疚之所由兴，往往至于夭 \n札而莫之拯。有古圣人者起，为斯民忧，调健顺之所宜，酌刚柔之所济，分疏暑寒燥湿之治 \n理，而着之为经，至今读《灵枢》《素问》诸篇，未尝不叹圣人之卫民生者远也。及览汉史 \n方技传，若仓公、扁鹊之流，多传其治疾之神奇，而其方不着。洎仲景、立斋、丹溪、东垣 \n辈出，多采其精微，勒为成书，以嬗后世。及诸家踵接，各祖所传，同途异趋，且致抵牾， \n即有高识之士，览之茫无津涯，欲求其会归，卒未易得也。 \n越人张景岳者，少负经世才，晚专于医，能决诸家之旨要，乃着集六十有四卷，以集斯 \n道之大成。其甥林汝晖携之至岭外，为鲁谦庵方伯所赏识，始为之梓行，凡言医之家，莫不 \n奉为法守。后其板浸失，贾青南都运复刊之，寻挟以北归，其行未广。余族子礼南客粤，以 \n其才鸣于时，而尚义强仁，有古烈士之概。慨是书之不广暨也，毅然倡其同志诸君，醵金以 \n授梓人，锓板摹发。会余奉命典试，事竟，礼南从余游，出其书视余，请为弁首。余读其集 \n分八阵，数组诸科，科次以方，方征诸治，其义简，其法该，其功用正而神，是为百氏之正 \n轨，而其究盈虚之理数，析顺逆之经权，则又与大《易》相参，而阴阳之道备是矣。学人苟 \n得其体用，随宜而措施，则足以利济群黎，可无夭札之患。且今圣天子方臻仁寿，保合太和 \n，至泽之涵濡，使天下咸登寿域。更得是书而广其术，行之四方，其于天地生物之心，圣人 \n仁民之化，赞襄补益，厥用良多，而礼南诸君乐善之功，亦将与是集共传不朽。 \n\\x癸巳科广东典试正主考翰林院编修查嗣 撰\\x \n\n\n\n<目录>\n\n<篇名>鲁序\n\n属性：人身一小天地也。天地之气，不越阴阳，阴阳和，而后覆载得其清宁，渊岳得其 \n峙，以至草木鸟兽咸若。《易》有之∶山泽通气，水火不相射，是谓阴阳和之之谓也，所以 \n《易》与天地准，故能弥纶天地之道。向余亦谓医与《易》准，故能神明阖辟之原。人之一 \n身，五脏六腑，四肢百骸备矣，非气不生，非血不行，气血者，阴阳之属也。而医则阴中求 \n阳，阳中求阴，循环无已，从逆得顺，从消得长，从虚得盈，分先后之天，审燥湿之宜，察 \n刚柔之用。二气之帮助，则表里虚实，无不洞然于中，斯酌古可以剂今，所谓神而明之，存 \n乎其人，善《易》者，未有不善医者也。 \n夫荣卫调而后经络顺，阴阳错而后疾病生，轩岐具挽回造化之神功，而《灵枢》《素问 \n》一书，犹日月经天，江河行地，后之人虽穷幽极渺，尚恐理解未明，用违其术。唯仲景张 \n氏、立斋薛氏、丹溪朱氏、东垣李氏诸君，朗悟通神，能窥其奥，皆有着述，为医家指南， \n以名于越人、淳于之后。而《医宗》《医录》《医统》《拔萃》《宝镜》诸篇，亦足以羽翼 \n《内经》者，犹之《六经》而外，诸子百家不可废也。但浩博泛滥，童年习之，皓首而不得 \n其源。倘能采掇精华，不支不漏，灿若云汉，明若列星，俾人披其集而漱涤五脏，练精易形 \n，有所宗旨，斯亦窥《易》简之奥，而具参赞之功者矣。 \n吾郡张会卿先生，名介宾，自号通一子，于书无所不窥，壮年好谈兵击剑，思有所用于 \n世，筮《易》得天山之遁，遂决意石隐，避世壶中。精轩岐之道，而于生死疑难之际 \n，审呼吸于毫芒，辨浮沉于影响，君臣佐使，无不析其源流，问切望闻，无不穷其 奥 \n。汇成《景岳全书》一集，列为八阵，中为九宫，前分门，后方剂，去陈言之糟粕，阐前哲 \n之心思，合者参之，疑者剖之，略者补之，诚度世之津梁，卫生之丹诀也。 \n是书脍炙海内已久，余以不得一见为怅，适林汝晖侄倩携之来粤，如获拱璧。因谓儿辈 \n曰∶兹编宏济之仁，不在良相下，岂一身一家之所敢私哉。特付剞劂，以公诸世，庶不没作 \n者之苦心，而同于长桑禁方之授也夫。 \n\\x会稽鲁超序\\x \n\n\n\n<目录>\n\n<篇名>全书纪略\n\n属性：先外祖张景岳公，名介宾，字会卿。先世居四川绵竹县，明初以军功世授绍兴卫指挥， \n卜室郡城会稽之东。生颖异，读书不屑章句，韬钤轩岐之学，尤所淹贯。壮岁游燕冀间，从 \n戎幕府，出榆关，履碣石，经凤城，渡鸭绿，居数年无所就，亲益老，家益贫，翻然而归。 \n功名壮志，消磨殆尽，尽弃所学而肆力于轩岐，探隐研神，医日进，名日彰，时人比之仲景 \n、东垣云。苦志编辑《内经》，穷年缕析，汇成《类经》若干卷问世，世奉为金匮玉函者久 \n矣。《全书》者，博采前人之精义，考验心得之玄微，以自成一家之书。首《传忠录》，统 \n论阴阳六气，先贤可否，凡三卷。次《脉神章》，择诸家珍要精髓，以测病情，凡二卷。着 \n伤寒为典，杂症为谟，妇人为规，小儿为则，痘疹为诠，外科为钤，凡四十卷。采药味三百 \n种，人参、附子、熟地、大黄为药中四维，更推参、地为良相，黄、附为良将，凡二卷。创 \n药方，分八阵，曰补，曰和，曰寒，曰热，曰固，曰因，曰攻，曰散，名新方八阵，凡四十 \n卷。集古方，分八阵，名古方八阵，凡八卷。别辑妇人、小儿、痘疹、外科方，总皆出入古 \n方八阵以神其用，凡四卷，共六十四卷，名《景岳全书》。是书也，继往开来，功岂小补哉 \n！以兵法部署方略者，古人用药如用兵也。或云公生平善韬钤，不得遂其幼学壮行之志，而 \n寓意于医，以发泄其五花八门之奇。余曰∶此盖有天焉，特老其才，救世而接医统之精传， \n造物之意，夫岂其微欤？是编成于晚年，力不能梓，授先君，先君复授日蔚。余何人斯，而 \n能继先人之遗志哉！岁庚辰，携走粤东，告方伯鲁公。公曰∶此济世慈航也！天下之宝，当与 \n天下共之。捐俸付剞劂，阅数月工竣。不肖得慰籍先人，以慰先外祖于九原，先外祖可不朽矣。 \n\\x外孙林日蔚跋\\x \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>明理（一）\n\n属性：万事不能外乎理，而医之于理为尤切。散之则理为万象，会之则理归一心。夫医者，一 \n心也；病者，万象也。举万病之多，则医道诚难，然而万病之病，不过各得一病耳。譬之北 \n极者，医之一心也；万星者，病之万象也。欲以北极而对万星，则不胜其对。以北极而对一 \n星，则自有一线之直。彼此相照，何得有差？故医之临证，必期以我之一心，洞病者之一本 \n。以我之一，对彼之一，既得一真，万疑俱释，岂不甚易？一也者，理而已矣。苟吾心之理 \n明，则阴者自阴，阳者自阳，焉能相混？阴阳既明，则表与里对，虚与实对，寒与热对，明 \n此六变，明此阴阳，则天下之病固不能出此八者。是编也，列门为八，列方亦为八。盖古有 \n兵法之八门，予有医家之八阵。一而八之，所以神变化，八而一之，所以溯渊源。故予于此 \n录，首言明理，以统阴阳诸论，详中求备，用帅八门。夫兵系兴亡，医司性命，执中心学， \n孰先乎此？是即曰传中可也，曰传心亦可也。然传中传心，总无非为斯人斯世之谋耳，故复 \n命为传忠录。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>阴阳篇（二）\n\n属性：凡诊病施治，必须先审阴阳，乃为医道之纲领。阴阳无谬，治焉有差？医道虽繁，而可 \n以一言蔽之者，曰阴阳而已。故证有阴阳，脉有阴阳，药有阴阳。以证而言，则表为阳，里 \n为阴；热为阳，寒为阴；上为阳，下为阴；气为阳，血为阴；动为阳，静为阴；多言者为阳 \n，无声者为阴；喜明者为阳，欲暗者为阴。阳微者不能呼，阴微者不能吸；阳病者不能俯， \n阴病者不能仰。以脉而言，则浮大滑数之类，皆阳也；沉微细涩之类，皆阴也。以药而言， \n则升散者为阳，敛降者为阴；辛热者为阳，苦寒者为阴；行气分者为阳，行血分者为阴；性 \n动而走者为阳，性静而守者为阴。此皆医中之大法。至于阴中复有阳，阳中复有静，疑似之 \n间，辨须的确。此而不识，极易差讹，是又最为紧要，然总不离于前之数者。但两气相兼， \n则此少彼多，其中便有变化，一皆以理测之，自有显然可见者。若阳有余而更施阳治，则阳 \n愈炽而阴愈消；阳不足而更用阴方，则阴愈盛而阳斯灭矣。设能明彻阴阳，则医理虽玄，思 \n一、道产阴阳，原同一气。火为水之主，水即火之源，水火原不相离也。何以见之？如 \n水为阴，火为阳，象分冰炭。何谓同源？盖火性本热，使火中无水，其热必极，热极则亡阴 \n，而万物焦枯矣。水性本寒，使水中无火，其寒必极，寒极则亡阳，而万物寂灭矣。此水火 \n之气，果可呼吸相离乎？其在人身，是即元阴元阳，所谓先天之元气也。欲得先天，当思根 \n柢。命门为受生之窍，为水火之家，此即先天之北阙也。舍此他求，如涉海问津矣。学人宜识之。 \n一、凡人之阴阳，但知以气血、脏腑、寒热为言，此特后天有形之阴阳耳。至若先天无 \n形之阴阳，则阳曰元阳，阴曰元阴。元阳者，即无形之火，以生以化，神机是也。性命系之 \n，故亦曰元气。元阴者，即无形之水，以长以立，天癸是也。强弱系之，故亦曰元精。元精 \n元气者，即化生精气之元神也。生气通天，惟赖乎此。经曰∶得神者昌，失神者亡，即为之 \n谓。今之人，多以后天劳欲戕及先天，今之医，只知有形邪气，不知无形元气。夫有形者， \n迹也，盛衰昭着，体认无难；无形者，神也，变幻倏忽，挽回非易。故经曰∶粗守形，上守 \n神。嗟呼！又安得有通神明而见无形者，与之共谈斯道哉。 \n一、天地阴阳之道，本贵和平，则气令调而万物生，此造化生成之理也。然阳为生之本 \n，阴实死之基。故道家曰∶分阴未尽则不仙，分阳未尽则不死。华元化曰∶得其阳者生，得 \n其阴者死。故凡欲保生重命者，尤当爱惜阳气，此即以生以化之元神，不可忽也。曩自刘河 \n间出，以暑火立论，专用寒凉，伐此阳气，其害已甚。赖东垣先生论脾胃之火必须温养，然 \n尚未能尽斥一偏之谬，而丹溪复出，又立阴虚火动之论，制补阴、大补等丸，俱以黄柏、知 \n母为君，寒凉之弊又复盛行。夫先受其害者，既去而不返。后习而用者，犹迷而不悟。嗟乎 \n！法高一尺，魔高一丈，若二子者，谓非轩歧之魔乎？余深悼之，故直削于此，实冀夫尽洗积 \n陋，以苏生命之厄，诚不得不然也。观者其谅之、察之，勿以诽谤先辈为责也。幸甚！ \n一、阴阳虚实。经曰∶阳虚则外寒，阴虚则内热，阳盛则外热，阴盛则内寒。 \n一、经曰∶阳气有余，为身热无汗。此言表邪之实也。又曰∶阴气有余，为多汗身寒。 \n此言阳气之虚也。仲景曰∶发热恶寒发于阳，无热恶寒发于阴。又曰∶极寒反汗出，身必 \n冷如冰。此与经旨义相上下。 \n一、经曰∶阴盛则阳病，阳盛则阴病。阳胜则热，阴盛则寒。 \n一、阴根于阳，阳根于阴。凡病有不可正治者，当从阳以引阴，从阴以引阳，各求其属 \n而衰之。如求汗于血，生气于精，从阳引阴也。又如引火归源，纳气归肾，从阴引阳也。此 \n即水中取火，火中取水之义。 \n一、阴之病也，来亦缓而去亦缓；阳之病也，来亦速而去亦速。阳生于热，热则舒缓； \n阴生于寒，寒则拳急。寒邪中于下，热邪中于上，饮食之邪中于中。 \n一、考之《中藏经》曰∶阳病则旦静，阴病则夜宁；阳虚则暮乱，阴虚则朝争。盖阳虚 \n喜阳助，所以朝轻而暮重；阴虚喜阴助，所以朝重而暮轻。此言阴阳之虚也。若实邪之候， \n则与此相反。凡阳邪盛者，必朝重暮轻；阴邪盛者，必朝轻暮重。此阳逢阳王，阴得阴强也 \n。其有或昼或夜，时作时止，不时而动者，以正气不能主持，则阴阳盛负，交相错乱，当以 \n培养正气为主，则阴阳将自和矣。但或水或火，宜因虚实以求之。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>六变辨（三）\n\n属性：六变者，表里寒热虚实也。是即医中之关键。明此六者，万病皆指诸掌矣。以表里言之 \n，则风、寒、暑、湿、火、燥感于外者是也。以里言之，则七情、劳欲、饮食伤于内者是也 \n。寒者，阴之类也。或为内寒，或为外寒，寒者多虚。热者，阳之类也。或为内热，或为外 \n热，热者多实。虚者，正气不足也，内出之病多不足。实者，邪气有余也，外入之病多有余 \n。六者之详，条列如下。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>表证篇（四）\n\n属性：表证者，邪气之自外而入者也。凡风寒暑湿火燥，气有不正，皆是也。经曰∶清风大来 \n，燥之胜也。风木受邪，肝病生焉。热气大来，火之胜也。金燥受邪，肺病生焉。寒气大来 \n，水之胜也。火热受邪，心病生焉。湿气大来，土之胜也。寒水受邪，肾病生焉。风气大来 \n，木之胜也。土湿受邪，脾病生焉。又曰∶冬伤于寒，春必病温。春伤于风，夏生飧泄。夏 \n伤于暑，秋必咳疟。秋伤于湿，冬生咳嗽。又曰∶风从其冲后来者为虚风，伤人者也，主杀 \n主害者。凡此之类，皆言外来之邪。但邪有阴阳之辨，而所伤亦自不同。盖邪虽有六，化止 \n阴阳。阳邪化热，热则伤气；阴邪化寒，寒则伤形。伤气者，气通于鼻，鼻通于脏。故凡外 \n受暑热而病有发于中者，以热邪伤气也。伤形者，浅则皮毛，深则经络，故凡外受风寒而病 \n为身热体痛者，以寒邪伤形也。经曰∶寒则腠理闭，气不行，故气收矣。炅则腠理开，营卫 \n通，汗大泄，故气泄矣。此六气阴阳之辨也。然而六邪之感于外者，又惟风寒为最。盖风为 \n百病之长，寒为杀厉之气。人身内有脏腑，外有经络，凡邪气之客于形也，必先舍于皮毛； \n留而不去，乃入于孙络；留而不去，乃入于络脉；留而不去，乃入于经脉，然后内连五脏， \n散于肠胃，阴阳俱感，五脏乃伤，此邪气自外而内之次也。然邪气在表，必有表证，既见表 \n证，则不可攻里。若误攻之，非惟无涉，且恐里虚则邪气乘虚愈陷也。表证既明，则里证可 \n因而解矣。故表证之辨，不可不为之先察。 \n一、人身脏腑在内，经络在外，故脏腑为里，经络为表。在表者，手足各有六经，是为 \n十二经脉。以十二经脉分阴阳，则六阳属腑为表，六阴属脏为里。以十二经脉分手足，则足 \n经之脉长而且远，自上及下，遍络四体，故可按之以察周身之病。手经之脉短而且近，皆出 \n入于足经之间，故凡诊伤寒外感者，则但言足经不言手经也。然而足之六经，又以三阳为表 \n，三阴为里。而三阳之经，则又以太阳为阳中之表，以其脉行于背，背为阳也。阳明为阳中 \n之里，以其脉行于腹，腹为阴也。少阳为半表半里，以其脉行于侧，三阳传遍而渐入三阴也 \n。故凡欲察表证者，但当分前后左右，而以足三阳经为主。然三阳之中，则又惟太阳一经， \n包覆肩背，外为周身之之纲维，内连五脏六腑之肓 ？此诸阳之主气，犹四通八达之衢也。 \n故凡风寒之伤人，必多自太阳经始。 \n一、足三阴之经皆自脚上腹，虽亦在肌表之间，然三阴主里，而凡风寒自表而入者，未 \n有不由阳经而入阴分也。若不由阳经迳入三阴者，即为直中阴经，必连脏矣。故阴经无可据 \n之表证。 \n一、寒邪在表者，必身热无汗，以邪闭皮毛也。 \n一、寒邪客于经络，必身体疼痛，或拘急而酸者，以邪气乱营气，血脉不利也。 \n一、寒邪在表而头痛者，有四经焉。足太阳脉挟于头顶，足阳明脉上至头维，足少阳脉 \n上行两角，足厥阴脉上会于巅，皆能为头痛也。故惟太阴、少阴皆无头痛之证。 \n一、寒邪在表多恶寒者，盖伤于此者必恶此，所谓伤食恶食，伤寒恶寒也。 \n一、邪气在表，脉必紧数者，营气为邪所乱也。 \n一、太阳经脉起目内 ，上顶巅，下项，挟脊行腰 ，故邪在太阳者，必恶寒发热而 \n兼头项痛，腰脊强，或膝 酸疼也。 \n一、阳明经脉起自目下，循面鼻，行胸腹。故邪在阳明者，必发热微恶寒，而兼目痛鼻 \n干不眠也。 \n一、少阳为半表半里之经，其脉绕耳前后，由肩井下胁肋。故邪在少阳者，必发热而兼 \n耳聋胁痛，口苦而呕，或往来寒热也。 \n以上皆三阳之表证，但见表证，则不可攻里。或发表，或微解，或温散，或凉散，或温 \n中托里而为不散之散，或补阴助阴而为云蒸雨化之散。呜呼！意有在而言难尽也。惟慧者之心悟之。 \n一、表证之脉。仲景曰∶寸口脉浮而紧，浮则为风，紧则为寒，风则伤卫，寒则伤营， \n营卫俱病，骨节烦疼，当发其汗也。《脉经》注曰∶风为阳，寒为阴，卫为阳，营为阴，风 \n则伤阳，寒则伤阴，各从其类而伤也。故卫得风则热，营得寒则痛，营卫俱病，故致骨节烦 \n疼，当发汗解表而愈。 \n一、浮脉本为属表，此固然也。然有邪寒初感之甚者，拘束卫气，脉不能达，则必沉而 \n兼紧，此但当以发热身痛等表证参合而察之，自可辨也。又若血虚动血者，脉必浮大。阴虚 \n水亏者，脉必浮大。内火炽盛者，脉必浮大。关阴格阳者，脉必浮大。若此者，俱不可一概 \n以浮为表论，必当以形气病气有无外证参酌之。若本非表证，而误认为表，则杀人于反掌之间矣。 \n一、外感寒邪，脉大者，必病进，以邪气日盛也。然必大而兼紧，方为病进。若先小而 \n后大，及渐大渐缓者，此以阴转阳，为胃气渐至，将解之兆也。 \n一、寒邪未解，脉息紧而无力者，无愈期也。何也？盖紧者，邪气也。力者，元气也， \n紧而无力，则邪气有余而元气不足也。元气不足，何以逐邪？临此证者，必能使元阳渐充， \n则脉渐有力，自小而大，自虚而实，渐至洪滑，则阳气渐达，表将解矣。若日见无力，而紧 \n数日进，则危亡之兆也。 \n一、病必自表而入者，方得谓之表证，若由内以及外，便非表证矣。经曰∶从内之外者 \n调其内，从外之内者治其外。从内之外而盛于外者，先治其内而后治其外；从外之内而盛于 \n内者，先治其外而后调其内。此内外先后之不可不知也。 \n一、伤风、中风，虽皆有风之名，不可均作表证。盖伤风之病，风自外入者也。可散之 \n、温之而已，此表证也。中风之病，虽形证似风，实由内伤所致。本无外邪，故不可以表证论治。法具本条。 \n一、发热之类，本为火证，但当分辨表里。凡邪气在表发热者，表热而里无热也，此因 \n寒邪，治宜解散。邪气在里发热者，必里热先甚而后及于表也，此是火证，治宜清凉。凡此 \n内外，皆可以邪热论也。若阴虚水亏而为骨蒸夜热者，此虚热也。又不可以邪热为例，惟壮 \n水滋阴可以治之。 \n一、湿燥二气，虽亦外邪之类，但湿有阴阳，燥亦有阴阳。湿从阴者为寒湿，湿从阳者 \n为湿热。燥从阳者因于火，燥从阴者发于寒。热则伤阴，必连于脏。寒则伤阳，必连于经。 \n此所以湿燥皆有表里，必须辨明而治之。 \n一、湿证之辨，当辨表里。经曰∶因于湿，首如裹。又曰∶伤于湿者，下先受之。若道 \n路冲风冒雨，或动作辛苦之人，汗湿沾衣，此皆湿从外入者也。若嗜好酒浆生冷，以致泄泻 \n、黄胆、肿胀之类，此湿从内出者也。在上在外者，宜微从汗解；在下在里者，宜分利之。 \n湿热者宜清宜利；寒湿者宜补脾温肾。 \n一、燥证之辨，亦有表里。经曰∶清气大来，燥之胜也，风木受邪，肝病生焉。此中风 \n之属也。盖燥胜则阴虚，阴虚则血少，所以或为牵引，或为拘急，或为皮腠风消，或为脏腑 \n干结，此燥从阳化，营气不足，而伤乎内者也。治当以养营补阴为主。若秋令太过，金气胜 \n而风从之，则肺先受病，此伤风之属也。盖风寒外束，气应皮毛，故或为身热无汗，或为咳 \n嗽喘满，或鼻塞声哑，或咽喉干燥，此燥以阴生，卫气受邪，而伤乎表者也。治当以轻扬温 \n散之剂，暖肺去寒为主。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>里证篇（五）\n\n属性：里证者，病之在内在脏也。凡病自内生，则或因七情，或因劳倦，或因饮食所伤，或为 \n酒色所困，皆为里证。以此言之，实属易见，第于内伤外感之间，疑似之际，若有不明，未 \n免以表作里，以里作表，乃致大害。故当详辨也。 \n一、身虽微热，而 汗出不止，及无身体酸疼拘急，而脉不紧数者，此热非 \n在表也。 \n一、证似外感，不恶寒，反恶热，而绝无表证者，此热盛于内也。 \n一、凡病表证，而小便清利者，知邪未入里也。 \n一、表证已具，而饮食如故，胸腹无碍者，病不及里也。若见呕恶口苦，或心胸满闷不 \n食，乃表邪传至胸中，渐入于里也。若烦躁不眠，干渴谵语，腹痛自利等证，皆邪入于里也 \n。若腹胀喘满，大便结硬，潮热斑黄，脉滑而实者，此正阳明胃腑里实之证，可下之也。 \n一、七情内伤，过于喜者，伤心而气散。心气散者，收之养之。过于怒者，伤肝而气逆 \n，肝气逆者，平之抑之。过于思者，伤脾而气结，脾气结者，温之豁之。过于忧者，伤肺而 \n气沉，肺气沉者，舒之举之。过于恐者，伤肾而气怯，肾气怯者，安之壮之。 \n一、饮食内伤，气滞而积者，脾之实也。宜消之逐之；不能运化者，脾之虚也。宜暖之 \n助之。 \n一、酒湿伤阴，热而烦满者，湿热为病也。清之泄之；酒湿伤阳，腹痛泻利呕恶者，寒 \n湿之病也，温之补之。 \n一、劳倦伤脾者，脾主四肢也。须补其中气。 \n一、色欲伤肾而阳虚无火者，兼培其气血；阴虚有火者，纯补其真阴。 \n一、痰饮为患者，必有所本，求所从来，方为至治。若但治标，非良法也。详具本条。 \n一、五脏受伤，本不易辨，但有诸中必形诸外，故肝病则目不能视而色青，心病则舌不 \n能言而舌赤，脾病则口不知味而色黄，肺病则鼻不闻香臭而色白，肾病则耳不能听而色黑。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>虚实篇（六）\n\n属性：虚实者，有余不足也。有表里之虚实，有气血之虚实，有脏腑之虚实，有阴阳之虚实。 \n凡外入之病多有余，内出之病多不足。实言邪气实则当泻，虚言正气虚则当补。凡欲察虚实 \n者，为欲知根本之何如，攻补之宜否耳。夫疾病之实，固为可虑，而元气之虚，虑尤甚焉。 \n故凡诊病者，必当先察元气为主，而后求疾病。若实而误补，随可解救，虚而误攻，不可生 \n矣。然总之虚实之要，莫逃乎脉。如脉之真有力真有神者，方是真实证，脉之似有力似有神 \n者，便是假实证，矧脉之无力无神，以至全无力全无神者哉，临证者万毋忽此。 \n一、表实者，或为发热，或为身痛，或为恶热掀衣，或为恶寒鼓栗。寒束于表者无汗， \n火盛于表者有疡。走注而红痛者，知营卫之有热；拘急而酸疼者，知经络之有寒。 \n一、里实者，或为胀为痛，或为痞为坚，或为闭为结，或为喘为满，或懊 不宁， \n或躁烦不眠，或气血积聚，结滞腹中不散，或寒邪热毒深留脏腑之间。 \n一、阳实者，为多热恶热。阴实者，为痛结而寒。气实者，气必喘促而声色壮厉。血实 \n者，血必凝聚而且痛且坚。 \n一、心实者，多火而多笑。肝实者，两胁少腹多有疼痛，且复多怒。脾实者，为胀满气 \n闭，或为身重。肺实者，多上焦气逆，或为咳喘。肾实者，多下焦壅闭，或痛或胀，或热见 \n于二便。 \n一、表虚者，或为汗多，或为肉战，或为怯寒，或为目暗羞明，或为耳聋眩运，或肢体 \n多见麻木，或举动不胜劳烦，或为毛槁而肌肉削，或为颜色憔悴而神气索然。 \n一、里虚者，为心怯心跳，为惊惶，为神魂之不宁，为津液之不足。或为饥不能食，或 \n为渴不喜冷，或畏张目而视，或闻人声而惊。上虚则饮食不能运化，或多呕恶而气虚中满。 \n下虚则二阴不能流利，或便尿失禁，肛门脱出，而泄泻遗精。在妇人则为血枯经闭，及堕胎崩淋带浊等证。 \n一、阳虚者，火虚也，为神气不足，为眼黑头眩，或多寒而畏寒。阴虚者，水亏也，为 \n亡血失血，为戴阳，为骨蒸劳热。气虚者，声音微而气短似喘。血虚者，肌肤干涩而筋脉拘挛。 \n一、心虚者，阳虚而多悲。肝虚者，目KT KT 无所见，或阴缩筋挛而善恐。脾虚 \n者，为四肢不用，或饮食不化，腹多痞满而善忧。肺虚者，少气息微，而皮毛燥涩。肾虚者 \n，或为二阴不通，或为两便失禁，或多遗泄，或腰脊不可俯仰，而骨酸痿厥。 \n一、诸痛之可按者为虚，拒按者为实。 \n一、胀满之虚实。仲景曰∶腹满不减，减不足言，当下之。腹满时减，复如故，此为寒 \n，当与温药。夫减不足言者，以中满之甚，无时或减，此实胀也，故当下之。腹满时减者， \n以腹中本无实邪，所以有时或减。既减而腹满如故者，以脾气虚寒而然，所以当与温药，温即兼言补也。 \n一、《内经》诸篇皆 以神气为言。夫神气者，元气也。元气完固，则精神 \n昌盛，无待言也。若元气微虚，则神气微去，元气大虚，则神气全去，神去则机息矣，可不 \n畏哉。《脉要精微论》曰∶夫精明者，所以视万物，别黑白，审长短。以长为短，以白为黑 \n，如是则精衰矣。言而微，终日乃复言者，此气夺也。衣被不敛，言语善恶不避亲疏，此神 \n明之乱也。仓廪不藏者，是门户不要也。水泉不止，是膀胱不藏也。得守者生，失守者死。 \n夫五脏者，身之强也；头者，精明之府，头倾视深，精神将夺矣。背者，胸中之府，背曲肩 \n垂，府将坏矣。腰者，肾之府，转摇不能，肾将惫矣。膝者，脚之府，屈伸不能，行则偻俯 \n，骨将惫矣。骨者，髓之府，不能久立，行则振掉，骨将惫矣。得强则生，失强则死。此《 \n内经》之言虚证也，当察其意。 \n一、虚者宜补，实者宜泻，此易知也。而不知实中复有虚，虚中复有实，故每以至虚之 \n病，反见盛势，大实之病，反有羸状，此不可不辨也。如病起七情，或饥饱劳倦，或酒色所 \n伤，或先天不足，及其既病，则每多身热便闭，戴阳胀满，虚狂假斑等证，似为有余之病， \n而其因实由不足，医不察因，从而泻之，必枉死矣。又如外感之邪未除，而留伏于经络，食 \n饮之滞不消，而积聚于脏腑，或郁结逆气有不可散，或顽痰瘀血有所留藏，病久致羸，似乎 \n不足，不知病本未除，还当治本。若误用补，必益其病矣。此所谓无实实，无虚虚，损不足 \n而益有余，如此死者，医杀之耳。 \n附∶华元化虚实大要论曰∶病有脏虚脏实，腑虚腑实，上虚上实，下虚下实，状各不同 \n，宜深消息。肠鸣气走，足冷手寒，食不入胃，吐逆无时，皮毛憔悴，肌肉皱皴，耳目昏塞 \n，语声破散，行步喘促，精神不收，此五脏之虚也。诊其脉，举指而滑，按之而微，看在何 \n部，以断其脏也。又按之沉小微弱短涩软濡，俱为脏虚也。饮食过多，大小便难，胸膈满闷 \n，肢节疼痛，身体沉重，头目闷眩，唇口肿胀，咽喉闭塞，肠中气急，皮肉不仁，暴生喘乏 \n，偶作寒热，疮疽并起，悲喜时来，或自痿弱，或自高强，气不舒畅，血不流通，此脏之实 \n也。诊其脉，举按俱盛者，实也。又长浮数疾洪紧弦大，俱曰实也。看在何经，而断其脏也 \n。头疼目赤，皮热骨寒，手足舒缓，血气壅塞，丹瘤更生，咽喉肿痛，轻按之痛，重按之快 \n，食饮如故，曰腑实也。诊其脉，浮而实大者是也。皮肤搔痒，肌肉 胀，食饮不化， \n大便滑而不止，诊其脉，轻手按之得滑，重手按之得平，此乃腑虚也。看在何经，而正其时 \n也。胸膈痞满，头目碎痛，饮食不下，脑项昏重，咽喉不利，涕唾稠粘，诊其脉，左右寸口 \n沉结实大者，上实也。颊赤心忪，举动颤栗，语声嘶嗄，唇焦口干，喘乏无力，面少颜色， \n颐颔肿满，诊其左右寸脉弱而微者，上虚也。大小便难，饮食如故，腰脚沉重（当作酸重）。 \n脐腹疼痛，诊其左右尺中脉伏而涩者，下实也。大小便难，饮食进退，腰脚沉重，如坐水中 \n，行步艰难，气上奔冲，梦寐危险，诊其左右尺中脉滑而涩者，下虚也。病患脉微涩短小， \n俱属下虚也。 \n一、本篇虚实证有未尽者，俱详载虚损门，当互察之。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>寒热篇（七）\n\n属性：寒热者，阴阳之化也。阴不足则阳乘之，其变为热；阳不足则阴乘之，其变为寒。故阴 \n胜则阳病，阴胜为寒也。阳胜则阴病，阳胜为热也。热极则生寒，因热之甚也；寒极则生热 \n，因寒之甚也。阳虚则外寒，寒必伤阳也；阴虚则内热，热必伤阴也。阳盛则外热，阳归阳 \n分也；阴盛则内寒，阴归阴分也。寒则伤形，形言表也；热则伤气，气言里也。故火旺之时 \n，阳有余而热病生；水旺之令，阳不足而寒病起。人事之病由于内，气交之病由于外。寒热 \n之表里当知，寒热之虚实亦不可不辨。 \n一、热在表者，为发热头痛，为丹肿斑黄，为揭去衣被，为诸痛疮疡。 \n一、热在里者，为瞀闷胀满，为烦渴喘结，或气急叫吼，或躁扰狂越。 \n一、热在上者，为头痛目赤，为喉疮牙痛，为诸逆冲上，为喜冷舌黑。 \n一、热在下者，为腰足肿痛，为二便秘涩，或热痛遗精，或溲混便赤。 \n一、寒在表者，为憎寒，为身冷，为浮肿，为容颜青惨，为四肢寒厥。 \n一、寒在里者，为冷咽肠鸣，为恶心呕吐，为心腹疼痛，为恶寒喜热。 \n一、寒在上者，为吞酸，为膈噎，为饮食不化，为嗳腐胀哕。 \n一、寒在下者，为清浊不分，为 溏痛泄，为阳痿，为遗尿，为膝寒足冷。 \n一、病患身大热，反欲得近衣者，热在皮肤，寒在骨髓也；身大寒，反不欲近衣者，寒 \n在皮肤，热在骨髓也，此表证之辨。若内热之甚者，亦每多畏寒，此当以脉证参合察之。 \n一、真寒之脉，必迟弱无神；真热之脉，必滑实有力。 \n一、阳脏之人多热，阴脏之人多寒。阳脏者，必平生喜冷畏热，即朝夕食冷，一无所病 \n，此其阳之有余也。阴脏者，一犯寒凉，则脾肾必伤，此其阳之不足也。第阳强者少，十惟 \n二三；阳弱者多，十常五六。然恃强者多反病，畏弱者多安宁。若或见彼之强而忌我之弱， \n则与侏儒观场，丑妇效颦者无异矣。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>寒热真假篇（八）\n\n属性：寒热有真假者，阴证似阳，阳证似阴也。盖阴极反能躁热，乃内寒而外热，即真寒假热 \n也。阳极反能寒厥，乃内热而外寒，即真热假寒也。假热者，最忌寒凉，假寒者，最忌温热 \n。察此之法，当专以脉之虚实强弱为主。 \n一、假热者，水极似火也。凡病伤寒，或患杂证，有其素禀虚寒，偶感邪气而然者，有 \n过于劳倦而致者，有过于酒色而致者，有过于七情而致者，有原非火证，以误服寒凉而致者 \n。凡真热本发热，而假热亦发热。其证则亦为面赤躁烦，亦为大便不通，小便赤涩，或为气 \n促，咽喉肿痛，或为发热，脉见紧数等证。昧者见之，便认为热，妄投寒凉，下咽必毙。不 \n知身虽有热，而里寒格阳，或虚阳不敛者，多有此证。但其内证，则口虽干渴，必不喜冷， \n即喜冷者，饮亦不多，或大便不实，或先硬后溏，或小水清频，或阴枯黄赤，或气短懒 \n言，或色黯神倦，或起倒如狂，而禁之则止，自与登高骂詈者不同，此虚狂也；或斑如蚊迹 \n而浅红细碎，自与紫赤热极者不同，此假斑也。凡假热之脉，必沉细迟弱，或虽浮大紧数而 \n无力无神，此乃热在皮肤，寒在脏腑，所谓恶热非热，实阴证也。凡见此内颓内困等证，而 \n但知攻邪，则无有不死。急当以四逆、八味、理阴煎、回阳饮之类，倍加附子填补真阳，以 \n引火归源，但使元气渐复，则热必退藏，而病自愈。所谓火就燥者，即此义也。故凡见身热 \n脉数，按之不鼓击者，此皆阴盛格阳，即非热也。仲景治少阴证面赤者，以四逆汤加葱白主 \n之。东垣曰∶面赤目赤，烦躁引饮，脉七八至，按之则散者，此无根之火也。以姜附汤加人 \n参主之。《外台秘要》曰∶阴盛发躁，名曰阴躁，欲坐井中，宜以热药治之。 \n一、假寒者，火极似水也。凡伤寒热甚，失于汗下，以致阳邪亢极，郁伏于内，则邪自 \n阳经传入阴分，故为身热发厥，神气昏沉，或时畏寒，状若阴证。凡真寒本畏寒，而假寒亦 \n畏寒，此热深厥亦深，热极反兼寒化也。大抵此证，必声壮气粗，形强有力，或唇焦舌黑， \n口渴饮冷，小便赤涩，大便秘结，或因多饮药水，以致下痢纯清水，而其中仍有燥粪，及矢 \n气极臭者，察其六脉必皆沉滑有力，此阳证也。凡内实者，宜三承气汤择而用之。潮热者， \n以大柴胡汤解而下之。内不实者，以白虎汤之类清之。若杂证之假寒者，亦或为畏寒，或为 \n战栗，此以热极于内而寒侵于外，则寒热之气两不相投，因而寒栗，此皆寒在皮肤，热在骨 \n髓，所谓恶寒非寒，明是热证。但察其内证，则或为喜冷，或为便结，或小水之热涩，或口 \n臭而躁烦，察其脉必滑实有力。凡见此证，即当以凉膈、芩连之属，助其阴而清其火，使内 \n热既除，则外寒自伏。所谓水流湿者，亦此义也。故凡身寒厥冷，其脉滑数，按之鼓击于指 \n下者。此阳极似阴，即非寒也。 \n一、假寒误服热药，假热误服寒药等证，但以冷水少试之。假热者，必不喜水，即有喜 \n者，或服后见呕，盒饭以温热药解之。假寒者，必多喜水，或服后反快而无所逆者，盒饭以 \n寒凉药解之。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>十问篇（九）\n\n属性：一问寒热二问汗，三问头身四问便，五问饮食六问胸，七聋八渴俱当辨，九因脉色察阴 \n阳，十从气味章神见。见定虽然事不难，也须明哲毋招怨。 \n上十问者，乃延医之要领，临证之首务也。明此十问，则六变具存，而万病形情俱在吾 \n目中矣。医之为难，难在不识病本而施误治耳。误则杀人，天道可畏，不误则济人，阴德无 \n穷。学人欲明是道，必须先察此要，以定意见，以为阶梯，然后再采群书，广其知识，又何 \n误焉？有能熟之胸中，运之掌上，非止为人，而为己不浅也，慎之宝之。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>十问篇（九）\n\n属性：问寒热者，问内外之寒热，欲以辨其在表在里也。人伤于寒则病为热，故凡病身热脉紧 \n，头疼体痛，拘急无汗，而且得于暂者，必外感也。盖寒邪在经，所以头痛身疼。邪闭皮毛 \n，所以拘急发热。若素日无疾，而忽见脉证若是者，多因外感。盖寒邪非素所有，而突然若 \n此，此表证也。若无表证而身热不解，多属内伤，然必有内证相应，合而察之，自得其真。 \n一、凡身热经旬，或至月余不解，亦有仍属表证者。盖因初感寒邪，身热头痛，医不能 \n辨，误认为火，辄用寒凉，以致邪不能散，或虽经解散而药未及病，以致留蓄在经。其病必 \n外证多而里证少，此非里也，仍当解散。 \n一、凡内证发热者，多属阴虚，或因积热，然必有内证相应，而其来也渐。盖阴虚者必 \n伤精，伤精者必连脏。故其在上而连肺者，必喘急咳嗽；在中而连脾者，或妨饮食，或生懊 \n，或为躁烦焦渴；在下而连肾者，或精血遗淋，或二便失节，然必倏热往来，时作时 \n止，或气怯声微，是皆阴虚证也。 \n一、凡怒气七情伤肝伤脏而为热者，总属真阴不足，所以邪火易炽，亦阴虚也。 \n一、凡劳倦伤脾而发热者，以脾阴不足，故易于伤，伤则热生于肌肉之分，亦阴虚也。 \n一、凡内伤积热者，在 痞必有形证，在血气必有明征，或九窍热于上下，或脏腑 \n热于三焦。若果因实热，凡火伤在形体而无涉于真元者，则其形气声色脉候自然壮丽，无弗 \n有可据而察者，此当以实火治之。 \n一、凡寒证尤属显然，或外寒者，阳亏于表，或内寒者，火衰于中，诸如前证。但热者 \n多实，而虚热者最不可误；寒者多虚，而实寒者间亦有之。此寒热之在表在里，不可不辨也。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>十问篇（九）\n\n属性：问汗者，亦以察表里也。凡表邪盛者必无汗。而有汗者，邪随汗去，已无表邪，此理之 \n自然也。故有邪尽而汗者，身凉热退，此邪去也。有邪在经而汗在皮毛者，此非真汗也。有 \n得汗后，邪虽稍减，而未得尽全者。犹有余邪，又不可因汗而必谓其无表邪也。须因脉证而详察之。 \n一、凡温暑等证，有因邪而作汗者，有虽汗而邪未去者，皆表证也。总之，表邪未除者 \n，在外则连经，故头身或有疼痛；在内则连脏，故胸膈或生躁烦。在表在里，有证可凭，或 \n紧或数，有脉可辨，须察其真假虚实，孰微孰甚而治之。 \n一、凡全非表证，则或有阳虚而汗者，须实其气；阴虚而汗者，须益其精；火盛而汗者 \n，凉之自愈；过饮而汗者，清之可宁。此汗证之有阴阳表里，不可不察也。诸汗详证载伤寒门。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>十问篇（九）\n\n属性：问其头可察上下；问其身可察表里。头痛者，邪居阳分；身痛者，邪在诸经。前后左右 \n，阴阳可辨，有热无热，内外可分，但属表邪，可散之而愈也。 \n一、凡火盛于内为头痛者，必有内应之证，或在喉口，或在耳目，别无身热恶寒在表等 \n候者，此热盛于上，病在里也。察在何经，宜清宜降，高者抑之，此之谓也。若用轻扬散剂 \n，则火必上升，而痛愈甚矣。 \n一、凡阴虚头痛者，举发无时，是因酒色过度，或遇劳苦，或逢情欲，其发则甚。此为 \n里证，或精或气，非补不可也。 \n一、凡头痛属里者，多因于火，此其常也。然亦有阴寒在上，阳虚不能上达而痛甚者， \n其证则恶寒呕恶，六脉沉微，或兼弦细，诸治不效，余以桂、附、参、熟之类而愈之，是头痛之有阳虚也。 \n一、凡云头风者，此世俗之混名，然必有所因，须求其本，辨而治之。 \n一、凡眩运者，或头重者，可因之以辨虚实。凡病中眩运，多因清阳不升，上虚而然。 \n如丹溪云∶无痰不作运。殊非真确之论，但当兼形气，分久暂以察之。观《内经》曰∶上虚 \n则眩，上盛则热痛，其义可知。至于头重，尤属上虚，经曰∶上气不足，脑为之不满，头为 \n之苦倾，此之谓也。 \n一、凡身痛之甚者，亦当察其表里以辨寒热。其若感寒作痛者，或上或下，原无定所， \n随散而愈，此表邪也。若有定处，而别无表证，乃痛痹之属，邪气虽亦在经，此当以里证视 \n之，但有寒热之异耳。若因火盛者，或肌肤灼热，或红肿不消，或内生烦渴，必有热证相应 \n，治宜以清以寒。若并无热候而疼痛不止，多属阴寒，以致血气凝滞而然。经曰∶痛者，寒 \n气多也，有寒故痛也。必温其经，使血气流通，其邪自去矣。 \n一、凡劳损病剧而忽加身痛之甚者，此阴虚之极，不能滋养筋骨而然，营气惫矣。无能为也。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>十问篇（九）\n\n属性：二便为一身之门户，无论内伤外感，皆当察此，以辨其寒热虚实。盖前阴通膀胱之道， \n而其利与不利，热与不热，可察气化之强弱，凡患伤寒而小水利者，以太阳之气未剧，即吉 \n兆也。后阴开大肠之门，而其通与不通，结与不结，可察阳明之实虚，凡大便热结而腹中坚 \n满者，方属有余，通之可也。若新近得解而不甚干结，或旬日不解而全无胀意者，便非阳明 \n实邪。观仲景曰∶大便先硬后溏者不可攻。可见后溏者，虽有先硬，已非实热， \n矧夫纯溏而连日得后者，又可知也。若非真有坚燥痞满等证，则原非实邪，其不可攻也明矣。 \n一、凡小便，人但见其黄，便谓是火，而不知人逢劳倦，小水即黄；焦思多虑，小水亦 \n黄；泻痢不期，小水亦黄；酒色伤阴，小水亦黄。使非有或淋或痛，热证相兼，不可因黄便 \n谓之火，余见逼枯汁而毙人者多矣。经曰∶中气不足，溲便为之变，义可知也。若小水清利 \n者，知里邪之未甚，而病亦不在气分，以津液由于气化，气病则小水不利也。小水渐利，则气化可知，最为吉兆。 \n一、大便通水谷之海，肠胃之门户也。小便通血气之海，冲任水道之门户也。二便皆主 \n于肾，本为元气之关，必真见实邪，方可议通议下，否则最宜详慎，不可误攻。使非真实而 \n妄逐之，导去元气，则邪之在表者反乘虚而深陷，病因内困者必由泄而愈亏。所以凡病不足 \n，慎勿强通。最喜者小便得气而自化，大便弥固者弥良。营卫既调，自将通达，即大肠秘结 \n旬余，何虑之有？若滑泄不守，乃非虚弱者所宜，当首先为之防也。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>十问篇（九）\n\n属性：问饮食者，一可察胃口之清浊，二可察脏腑之阴阳。病由外感而食不断者，知其邪未及 \n脏，而恶食不恶食者可知。病因内伤而食饮变常者，辨其味有喜恶，而爱冷爱热者可知。 \n素欲温热者，知阴脏之宜暖；素好寒冷者，知阳脏之可清。或口腹之失节以致误伤，而一时 \n之权变可因以辨。故饮食之性情所当详察，而药饵之宜否可因以推也。 \n一、凡诸病得食稍安者，必是虚证，得食更甚者，或虚或实皆有之，当辨而治也。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>十问篇（九）\n\n属性：胸即膻中，上连心肺，下通脏腑。胸腹之病极多，难以尽悉，而临证必当问者，为欲辨 \n其有邪无邪，及宜补宜泻也。夫凡胸腹胀满，则不可用补；而不胀不满，则不可用攻，此大 \n法也。然痞与满不同，当分轻重∶重者，胀塞中满，此实邪也，不得不攻。轻者，但不欲食 \n，不知饥饱，似胀非胀，中空无物，乃痞气耳，非真满也。此或以邪陷胸中者有之，或脾虚 \n不运者有之。病者不知其辨，但见胃气不开，饮食不进，问之亦曰饱闷，而实非真有胀满， \n此在疑虚疑实之间。若不察其真确，未免补泻倒施，必多致误，则为害不小。 \n一、凡今人病虚证者极多，非补不可。但用补之法，不宜造次。欲察其可补不可补之机 \n，则全在先察胸腹之宽否何如，然后以渐而进。如未及病，再为放胆用之，庶无所碍，此用补之大法也。 \n一、凡势在危急，难容稍缓，亦必先问其胸宽者乃可骤进。若元气多虚而胸腹又胀，是 \n必虚不受补之证。若强进补剂，非惟无益，适足以招谤耳。此胸腹之不可不察也。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>十问篇（九）\n\n属性：耳虽少阳之经，而实为肾脏之官，又为宗脉之所聚，问之非惟可辨虚实，亦且可知死生 \n。凡人之久聋者，此一经之闭，无足为怪。惟是因病而聋者，不可不辨。其在《热论篇》则 \n曰∶伤寒三日，少阳受之，故为耳聋。此以寒邪在经，气闭而然。然以余所验，则未有不因 \n气虚而然者。《素问》曰∶精脱者耳聋。仲景曰∶耳聋无闻者，阳气虚也。由此观之，则凡 \n病是证，其属气虚者什九，气闭者什一耳。 \n一、聋有轻重，轻者病轻，重者病重。若随治渐轻，可察其病之渐退也。进则病亦进矣 \n。若病至聋极，甚至绝然无闻者，此诚精脱之证，余经历者数人矣，皆至不治。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>十问篇（九）\n\n属性：问渴与不渴，可以察里证之寒热，而虚实之辨，亦从以见。凡内热之甚，则大渴喜冷， \n冰水不绝，而腹坚便结，脉实气壮者，此阳证也。 \n一、凡口虽渴而喜热不喜冷者，此非火证，中寒可知。既非火证，何以作渴，则水亏故耳。 \n一、凡病患问其渴否，则曰口渴。问其欲汤水否，则曰不欲。盖其内无邪火，所以不欲 \n汤，真阴内亏，所以口无津液。此口干也，非口渴也，不可以干作渴治。 \n一、凡阳邪虽盛，而真阴又虚者，不可因其火盛喜冷，便云实热。盖其内水不足，欲得 \n外水以济，水涸精亏，真阴枯也，必兼脉证细察之，此而略差，死生立判。余尝治垂危最重 \n伤寒有如此者，每以峻补之剂浸冷而服，或以冰水、参、熟等剂相间迭进，活人多矣。常人 \n见之，咸以为奇，不知理当如是，何奇之有？然必其干渴燥结之甚者，乃可以参、附、凉水 \n并进。若无实结，不可与水。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>十问篇（九）\n\n属性：脉色者，血气之影也。形正则影正，形斜则影斜，病生于内，则脉色必见于外，故凡察 \n病者，须先明脉色。但脉色之道，非数言可尽，欲得其要，则在乎阴阳虚实四者而已。四者 \n无差，尽其善矣。第脉法之辨，以洪滑者为实为阳，微弱者为虚为阴，无待言也。然仲景曰 \n∶若脉浮大者，气实血虚也。陶节庵曰∶不论脉之浮沉大小，但指下无力，重按全无，便是 \n阴证。《内经》以脉大四倍以上为关格，皆属真虚，此滑大之未必为阳也。形色之辨，以红 \n黄者为实热，青黑者为阴寒。而仲景云∶面赤戴阳者为阴不足，此红赤之未必为实也。总之 \n，求脉之道，当以有力无力辨阴阳，有神无神察虚实。和缓者，乃元气之来；强峻者，乃邪 \n气之至。病值危险之际，但以此察元气之盛衰，邪正之进退，则死生关系，全在乎此。此理 \n极微，谈非容易，姑道其要，以见凡欲诊病者，既得病因，又必须察脉色，辨声音，参合求 \n之，则阴阳虚实方有真据，否则得此失彼，以非为是，医家之病，莫此为甚，不可忽也。诸 \n所未尽，详后卷脉神章。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>十问篇（九）\n\n属性：凡制方用药，乃医家开手作用第一要着，而胸中神见，必须发泄于此。使不知气味之用 \n，必其药性未精，不能取效，何神之有？此中最有玄妙，勿谓其浅显易知，而弗加之意也。 \n余少年时，每将用药，必逐件细尝，既得其理，所益无限。 \n一、气味有阴阳∶阴者降，阳者升。阴者静，阳者动。阴者柔，阳者刚。阴者怯，阳者 \n勇。阴主精，阳主气。其于善恶喜恶，皆有妙用，不可不察。 \n一、气味之升降∶升者浮而散，散者沉而利。宜升者勿降，宜降者勿升。 \n一、气味之动静∶静者守而动者走。走者可行，守者可安。 \n一、气味之刚柔∶柔者纯而缓，刚者躁而急。纯者可和，躁者可劫。非刚不足以去暴， \n非柔不足以济刚。 \n一、气味之勇怯∶勇者直达病所，可赖出奇；怯者用以周全，藉其平妥。 \n一、气味之主气者，有能为精之母；主精者，有能为气之根。或阴中之阳者，能动血中 \n之气；或阳中之阴者，能顾气中之精。 \n一、气味有善恶∶善者赋性驯良，尽堪择用；恶者气味残野狼，何必近之。 \n一、气味有喜恶∶有素性之喜恶，有一时之喜恶。喜者相宜，取效尤易；恶者见忌，不 \n必强投。见定虽然事不难，也须明哲毋招怨。 \n明哲二字，为见机自保也。夫医患不明，明则治病何难哉？而所患者，在人情耳。人事 \n之变，莫可名状，如我有独见，岂彼所知，使彼果知，当自为矣。何藉于我？而每有病临危 \n剧，尚执浅见，从旁指示曰∶某可用，某不可用，重之曰太过，轻之言不及，倘一不合意， \n将必有后言，是当见几之一也。有杂用不专者，朝王暮李，主见不定，即药已相投，而渠不 \n之觉，忽惑人言，舍此慕彼。凡后至者，欲显己长，必谈前短，及其致败，反以嫁谗，是当 \n见几之二也。有病入膏肓，势必难疗，而怜其苦求，勉为举手，当此之际，使非破格出奇， \n何以济急？倘出奇无功，徒骇人目，事后亦招浮议，是当见几之三也。其或有是非之场，争 \n竞之所，幸灾乐祸，利害所居者，近之恐涉其患，是当见几之四也。有轻医重巫，可无可有 \n，徒用医名，以尽人事。及尚有村鄙之夫，不以彼病为恳，反云为我作兴，吁！诚可哂也。 \n此其相轻孰甚，是当见几之五也。有议论繁杂者，有亲识要功者，有内情不协者，有任性反 \n复者，皆医中所最忌，是当见几之六也。凡此六者，俱当默识，而惟于缙绅之间，尤当加意 \n。盖恐其不以为功而反以为罪，何从辨哉。此虽曰吾尽吾心，非不好生，然势有不我出者， \n不得不见几进止，此明哲之自治，所必不可少也。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>论治篇（十）\n\n属性：凡看病施治，贵乎精一。盖天下之病，变态虽多，其本则一。天下之方，活法虽多，对 \n证则一。故凡治病之道，必确知为寒，则竟散其寒，确知为热，则竟清其热，一拔其本，诸 \n证尽除矣。故《内经》曰∶治病必求其本。是以凡诊病者，必须先探病本，然后用药。若见 \n有未的，宁为少待，再加详察，既得其要，但用一味二味便可拔之，即或深固，则五六味七 \n八味亦已多矣。然虽用至七八味，亦不过帮助之，导引之，而其意则一也，方为高手。 \n今之医者，凡遇一证，便若观海望洋，茫无定见，则势有不得不为杂乱而用广络原野之 \n术。盖其意谓虚而补之，则恐补之为害，而复制之以消；意谓实而消之，又恐消之为害，而 \n复制之以补。其有最可哂者，则每以不寒不热，兼补兼泻之剂，确然投之，极称稳当，此何 \n以补其偏而救其弊乎？又有以治风、治火、治痰、治食之剂兼而用之，甚称周备，此何以从 \n其本而从其标乎？若此者，所谓以药治药尚未遑，又安望其及于病耶？即使偶愈，亦不知其补 \n之之力，攻之之功也。使其不愈，亦不知其补之为害，消之为害也。是以白头圭匕，而庸庸 \n没齿者，其咎在于无定见，而用治之不精也。使其病浅，犹无大害，若安危在举动之间，即 \n用药虽善，若无胆量勇敢而药不及病，亦犹杯水车薪，尚恐弗济，矧可以执两端而药有妄投 \n者，其害又将何如？耽误民生，皆此辈也，任医者不可不深察焉。 \n故凡施治之要，必须精一不杂，斯为至善。与其制补以消，孰若少用纯补，以渐而进之 \n为愈也。与其制攻以补，孰若微用纯攻自一而再之为愈也。故用补之法，贵乎先轻后重，务 \n在成功；用攻之法，必须先缓后峻，及病则已。若用制不精，则补不可以治虚，攻不可以去 \n实，鲜有不误人者矣。 \n余为是言，知必有以为迂阔而讥之者，曰∶古人用药每多至一二十味，何为精一？岂古 \n人之不尔若耶？是不知相制相使之妙者也，是执一不通而不知东垣之法者也。余曰∶夫相制 \n者，制其毒也。譬欲用人奇异之才，而又虑其太过之害，故必预有以防其微，总欲得其中而 \n已。然此特遇不得已之势，间一有之，初未有以显见寻常之法用得其贤，而复又自掣其肘者 \n也。至若相佐相使，则恐其独力难成，而用以助之者，亦非为欲进退牵制而自相矛盾者也。 \n观仲景之方，精简不杂，至多不过数味。圣贤之心，自可概见。若必不得已而用行中之补， \n补中之行，是亦势所当然。如《伤寒论》之小柴胡汤以人参、柴胡并用，陶氏之黄龙汤以大 \n黄、人参并用，此正精专妙处，非若今医之混用也。能悟此理，方是真见中活泼工夫。至若 \n东垣之方，有十余味及二十余味者，此其用多之道，诚自有意。学人欲效其法，必须总会其 \n一方之味，总计其一方之性。如某者多，某者少，某者为专主，某者为佐使，合其气用，自 \n成一局之性，使能会其一局之意，斯得东垣之心矣。若欲见头治头，见脚治脚，甚有执其三 \n四端而一概混用，以冀夫侥幸者，尚敢曰我学东垣者哉。虽然，东垣之法非不善也，然余则 \n宁师仲景，不敢宗东垣者，正恐未得其清，先得其隘，其失者岂止一方剂也哉，明者宜辨之。 \n一、《内经》治法。岐伯曰∶高者抑之，下者举之，温者清之，清者温之，散者收之， \n抑者散之，燥者润之，急者缓之，坚者软之，脆者坚之，衰者补之，强者泻之，佐以所利， \n和以所宜，各安其气，必清必静，则病气衰去，归其所宗，此治之大体。岐伯曰∶寒者热之 \n，热者寒之，微者逆之，甚者从之，坚者削之，客者除之，劳者温之，结者散之，留者攻之 \n，燥者濡之，急者缓之，散者收之，损者益之，溢者行之，惊者平之，上之下之，摩之浴之 \n，薄者劫之，开者发之，适事为故。帝曰∶何谓逆从？岐伯曰∶逆者正治，从者反治，从少 \n从多，观其事也。帝曰∶反治何谓？岐伯曰∶热因寒用，寒因热用，塞因塞用，通因通用， \n必伏其所主，而先其所因，其始则同，其终则异。 \n岐伯曰∶病生于内者，先治其阴，后治其阳，反者益甚。病生于阳者，先治其外，后治 \n其内，反者益甚。 \n一、治病用药，本贵精专，尤宜勇敢。凡久远之病，则当要其终始，治从乎缓，此宜然 \n也。若新暴之病，虚实既得其真，即当以峻剂直攻其本，拔之甚易。若逗留畏缩，养成深固 \n之势，则死生系之，谁其罪也。故凡真见里实，则以凉膈、承气；真见里虚，则以理中、十 \n全。表虚则 、术、建中；表实则麻黄、柴、桂之类。但用一味为君，二三味为佐使，大剂 \n进之，多多益善。夫用多之道何在？在乎必赖其力而料无害者，即放胆用之。性缓者可用数 \n两，性急者亦可数钱。若三五七分之说，亦不过点名具数，儿戏而已，解纷治剧之才，举 \n动固如是乎。 \n一、治病之则，当知邪正，当权重轻。凡治实者，譬如耘禾，禾中生稗，禾之贼也。有 \n一去一，有二去二，耘之善者也。若有一去二，伤一禾矣，有二去四，伤二禾矣。若识禾不 \n的，俱认为稗，而计图尽之，则无禾矣。此用攻之法，贵乎察得其真，不可过也。凡治虚者 \n，譬之给饷，一人一升，十人一斗，日饷足矣。若百人一斗，千人一斛，而三军之众，又岂 \n担石之粮所能活哉？一饷不继，将并前饷而弃之。而况于从中克减乎。此用补之法，贵乎轻 \n重有度，难从简也。 \n一、虚实之治，大抵实能受寒，虚能受热，所以补必兼温，泻必兼凉者，盖凉为秋气， \n阴主杀也。万物逢之，便无生长，欲补元气，故非所宜。凉且不利于补，寒者益可知矣。即 \n有火盛气虚，宜补以凉者，亦不过因火暂用，火去即止，终非治虚之法也。又或有以苦寒之 \n物谓其能补阴者，则《内经》有曰∶形不足者，温之以气，精不足者补之以味。夫气味之相 \n宜于人者，谓之曰补可也。未闻以味苦气劣而不相宜于人者，亦可谓之补也。虽《内经》有 \n曰∶水位之主，其泻以咸，其补以苦等论。然此特以五行岁气之味据理而言耳。矧其又云麦 \n、羊肉、杏、薤皆苦之类，是则苦而补者也。岂若大黄、黄柏之类，气味苦劣若此，而谓之 \n能补，无是理也。尝闻之王应震曰∶一点真阳寄坎宫，固根须用味甘温。甘温有益寒无补， \n堪笑庸医错用功。此一言蔽之也，不可不察。 \n一、补泻之法，补亦治病，泻亦治病，但当知其要也。如以新暴之病而少壮者，乃可攻 \n之泻之。攻但可用于暂，未有衰久之病，而屡攻可以无害者，故攻不可以收缓功。延久之病 \n而虚弱者，理宜温之补之。补乃可用于常，未有根本既伤，而舍补可以复元者，故补不可以 \n求速效。然犹有其要，则凡临证治病，不必论其有虚证无虚证，但无实证可据而为病者，便 \n当兼补，以调营卫精血之气；亦不必论其有火证无火证，但无热证可据而为病者，盒饭兼温 \n，以培命门脾胃之气。此吞泻之要领，苟不知此，未有不至决裂败事者。 \n一、治法有逆从，以寒热有假真也，此《内经》之旨也。经曰∶逆者正治，从者反治。 \n夫以寒治热，以热治寒，此正治也，正即逆也。以热治热，以寒治寒，此反治也，反即从也 \n。如以热药治寒病而寒不去者，是无火也，当治命门，以参、熟、桂、附之类，此王太仆所 \n谓益火之源以消阴翳，是亦正治之法也。又如热药治寒病而寒不退，反用寒凉而愈者，此正 \n假寒之病，以寒从治之法也。又如以寒药治热病而热不除者，是无水也，治当在肾，以六味 \n丸之类，此王太仆所谓壮水之主以镇阳光，是亦正治之法也。又有寒药治热病而热不愈，反 \n用参、姜、桂、附、八味丸之属而愈者，此即假热之病，以热从治之法也，亦所谓甘温除大 \n热也。第今人之虚者多，实者少，故真寒假热之病为极多，而真热假寒之病则仅见耳。 \n一、探病之法，不可不知。如当局临证，或虚实有难明，寒热有难辨，病在疑似之间， \n补泻之意未定者，即当先用此法。若疑其为虚，意欲用补而未决，则以轻浅消导之剂，纯用 \n数味，先以探之，消而不投，即知为真虚矣。疑其为实，意欲用攻而未决，则以甘温纯补之 \n剂，轻用数味，先以探之，补而觉滞，即知有实邪也。假寒者，略温之必见躁烦；假热者， \n略寒之必加呕恶，探得其情，意自定矣。经曰∶有者求之，无者求之。又曰∶假者反之，此 \n之谓也。但用探之法，极宜精简，不可杂乱。精简则真伪立辨，杂乱则是非难凭。此疑似中 \n之活法，必有不得已而用之可也。 \n一、《医诊》治法有曰∶见痰休治痰，见血休治血，无汗不发汗，有热莫攻热，喘生休 \n耗气，精遗不涩泄，明得个中趣，方是医中杰。行医不识气，治病从何据？堪笑道中人，未 \n到知音处。观其诗意，皆言不治之治，正《内经》求本之理耳，诚格言也。至于“行医不识 \n气，治病从何据”一联，亦甚有理。夫天地之道，阳主气，先天也；阴成形，后天也。故凡 \n上下之升降，寒热之往来，晦明之变易，风水之留行，无不因气以为动静，而人之于气，亦 \n由是也。凡有余之病，由气之实，不足之病，因气之虚。如风寒积滞，痰饮瘀血之属，气不 \n行则邪不除，此气之实也。虚劳遗漏，亡阳失血之属，气不固则元不复，此气之虚也。虽曰 \n泻火，实所以降气也。虽曰补阴，实所以生气也。气聚则生，气散则死，此之谓也。所以病 \n之生也，不离乎气，而医之治病也，亦不离乎气，但所贵者，在知气之虚实，及气所从生耳 \n。近见有浅辈者，凡一临证，不曰内伤外感，则曰痰逆气滞。呵！呵！此医家八字诀也。有此 \n八字，何必八阵？又何必端本澄源以求迂阔哉？第人受其害，恐不无可畏也。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>论治篇（十）\n\n属性：华元化论治疗曰∶夫病有宜汤者，宜丸者，宜散者，宜下者，宜吐者，宜汗者，宜灸者 \n，宜针者，宜补者，宜按摩者，宜导引者，宜蒸熨者，宜暖洗者，宜悦愉者，宜和缓者，宜 \n水者，宜火者，种种之法，岂唯一也。若非良善精博，难为取效。庸下浅识，每致乱投，致 \n使轻者令重，重者令死，举世皆然。且汤可以涤荡脏腑，开通经络，调品阴阳，祛分邪恶， \n润泽枯朽，悦养皮肤。养气力，助困竭，莫离于汤也。丸可以逐风冷，破坚 ，消积聚 \n，进饮食，舒营卫，定关窍。从缓以参合，无出于丸也。散者，能驱散风邪暑湿之气。摅阴 \n寒湿浊之毒，发散四肢之壅滞，除剪五脏结伏，开肠和胃，行脉通经，莫过于散也。下则疏 \n豁闭塞。补则益助虚乏。灸则起阴通阳。针则行营引卫。导引可逐客邪于关节。按摩可驱浮 \n淫于肌肉。蒸熨辟冷，暖洗生阳，悦愉爽神，和缓安气。若实而不下，则使人心腹胀满，烦 \n乱鼓肿。若虚而不补，则使人气血消散，肌肉耗亡，精神脱失，志意皆迷。当汗而不汗，则 \n使人毛孔闭塞，闷绝而终。合吐而不吐，则使人结胸上喘，水食不入而死。当灸而不灸，则 \n使人冷气重凝，阴毒内聚，厥气上冲，分坠不散，以致消减。当针不针，则使人营卫不行， \n经络不利，邪渐胜真，冒昧而昏。宜导引而不导引，则使人邪侵关节，固结难通。宜按摩而 \n不按摩，则使人淫归肌肉，久留不消。宜蒸熨而不蒸熨，则使人冷气潜伏，渐成痹厥。宜暖 \n洗而不暖洗，则使人阳气不行，阴邪相害。不当下而下，则使人开肠荡胃，洞泄不禁。不当 \n汗而汗，则使人肌肉消绝，津液枯耗。不当吐而吐，则使人心神烦乱，脏腑奔冲。不当灸而 \n灸，则使人重伤经络，内蓄火毒，反害中和，致不可救。不当针而针，则使人血气散失，机 \n关细缩。不当导引而导引，则使人真气劳败，邪气妄行。不当按摩而按摩，则使人肌肉 \n胀，筋骨舒张。不当蒸熨而蒸熨，则使人阳气偏行，阴气内聚。不当暖洗而暖洗，则使人 \n湿着皮肤，热生肌体。不当悦愉而悦愉，则使人气停意折，健忘伤志。大凡治疗，要合其宜 \n，脉状病候，少陈于后∶凡脉不紧数，则勿发其汗。脉不实数，不可以下。心胸不闭，尺脉 \n微弱，不可以吐。关节不急，营卫不壅，不可以针。阴气不盛，阳气不衰，勿灸。内无客邪 \n，勿导引。外无淫气，勿按摩。皮肤不痹，勿蒸熨。肌肉不寒，勿暖洗。神不凝迷，勿愉悦 \n。气不奔急，勿和缓。顺此者生，逆此者死耳。 \n\n\n\n<目录>卷之一入集\\传忠录（上）\n\n<篇名>气味篇（十一）\n\n属性：药物众多，各一其性，宜否万殊，难以尽识。用者不得其要，未免多误。兼之《本草》 \n所注，又皆概言其能，凡有一长，自难泯没。惟是孰为专主，孰为兼能，孰为利于此而不利 \n于彼，孰者宜于补而不宜于攻。学人昧其真性，而惟按图以索骥，所以用多不效，益见用药 \n之难矣。用药之道无他也，惟在精其气味，识其阴阳，则药味虽多，可得其要矣。凡气味之 \n辨，则诸气属阳，诸味属阴。气本乎天，气有四，曰寒热温凉是也。味本乎地，味有六，曰 \n酸苦甘辛咸淡是也。温热者，天之阳；寒凉者，天之阴也。辛甘淡者，地之阳；酸苦咸者， \n地之阴也。阳主升而浮，阴主沉而降。辛主散，其行也横，故能解表。甘主缓，其行也上， \n故能补中。苦主泻，其行也下，故可去实。酸主收，其性也敛，故可治泄。淡主渗，其性也 \n利，故可厘清。咸主软，其性也沉，故可导滞。用纯气者，用其动而能行；用纯味者，用其 \n静而能守。有气味兼用者，和合之妙，贵乎相成。有君臣相配者，宜否之机，最嫌相左。既 \n曰合宜，尤当知忌，先避其害，后用其利，一味不投，众善俱弃。故欲表散者，须远酸寒； \n欲降下者，勿兼升散。阳旺者，当知忌温；阳衰者，沉寒毋犯。上实者忌升，下实者忌秘。 \n上虚者忌降，下虚者忌泄。诸动者再动即散，诸静者再静即灭。甘勿施于中满，苦勿施于假 \n热，辛勿施于热躁，咸勿施于伤血。酸木最能克土，脾气虚者少设。阳中还有阴象，阴中复 \n有阳诀，使能烛此阴阳，则药理虽玄，岂难透彻。 \n五味所入，《内经》曰∶五味入胃，各归所喜，故酸先入肝，苦先入心，甘先入脾，辛 \n先入肺，咸先入肾。久而增气，物化之常也。气增而久，夭之由也。 \n\n\n\n<目录>卷之二入集\\传忠录（中）\n\n<篇名>神气存亡论（十二）\n\n属性：经曰∶得神者昌，失神者亡。善乎神之为义，此死生之本，不可不察也。以脉言之，则 \n脉贵有神。《脉法》曰∶脉中有力，即为有神。夫有力者，非强健之谓，谓中和之力也。大 \n抵有力中不失和缓，柔软中不失有力，此方是脉中之神。若其不及，即微弱脱绝之无力也。 \n若其太过，即弦强真藏之有力也。二者均属无神，皆危兆也。 \n以形证言之，则目光精彩，言语清亮，神思不乱，肌肉不削，气息如常，大小便不脱， \n若此者，虽其脉有可疑，尚无足虑，以其形之神在也。若目暗睛迷，形羸色败，喘急异常， \n泄泻不止，或通身大肉已脱，或两手寻衣摸床，或无邪而言语失伦，或无病而虚空见鬼，或 \n病胀满而补泻皆不可施，或病寒热而温凉皆不可用，或忽然暴病，即沉迷烦躁，昏不知人， \n或一时卒倒，即眼闭口开，手撒遗尿。若此者，虽其脉无凶候，必死无疑，以其形之神去也 \n。 \n再以治法言之，凡药食入胃，所以能胜邪者，必赖胃气施布药力，始能温吐汗下以逐其 \n邪。若邪气胜，胃气竭者，汤药纵下，胃气不能施化，虽有神丹，其将奈之何哉。所以有用 \n寒不寒，用热不热者，有发其汗而表不应，行其滞而里不应者，有虚不受补，实不可攻者， \n有药食不能下咽，或下咽即呕者。若此者，呼之不应，遣之不动，此以脏气元神尽去，无可 \n得而使也，是又在脉证之外亦死无疑者。 \n虽然，脉证之神，若尽乎此，然有脉重证轻而知其可生者，有脉轻证重而知其必死者， \n此取证不取脉也。有证重脉轻而必其可生者，有证轻脉重而谓其必死者，此取脉不取证也。 \n取舍疑似之间，自有一种玄妙。甚矣，神之难言也。能知神之缓急者，其即医之神者乎。 \n\n\n\n<目录>卷之二入集\\传忠录（中）\n\n<篇名>君火相火论（十三）\n\n属性：余向释《内经》，于君火以明，相火以位之义，说固详矣，而似犹有未尽者。及见东垣 \n云∶相火者，下焦包络之火，元气之贼也，丹溪亦述而证之。予闻此说，尝掩口而笑，而觉 \n其不察之甚也。由此兴感，因再绎之。 \n夫《内经》发明火义，而以君相明位四字为目，此四字者，个个着实，是诚至道之纲领 \n，有不可不阐扬其精义者。亦何以见之？盖君道惟神，其用在虚；相道惟力，其用在实。故 \n君之能神者，以其明也；相之能力者，以其位也。明者明于上，为化育之元主；位者位于下 \n，为神明之洪基。此君相相成之大道，而有此天不可无此地，有此君不可无此相也，明矣。 \n君相之义，岂泛言哉！ \n至若五运之分，各职其一，惟于火字独言君相，而他则不及者何也？盖两间生气，总曰 \n元气，元气惟阳为主，阳气惟火而已。第火之为用，其道最微，请以火象证之。如轻清而光 \n焰于上者，火之明也；重实而温蓄于下者，火之位也。明即位之神，无明则神用无由以着； \n位即明之本，无位则光焰何从以生。故君火之变化于无穷，总赖此相火之栽根于有地，虽分 \n之则一而二，而总之则二而一者也。此君火相火之辨。凡其为生化，为盛衰，为本末，重轻 \n攸系，从可知矣。人生所赖者惟此，故《内经》特以为言。 \n然在《内经》则但表其大义，原无分属之条，惟《刺禁论》曰∶七节之傍，中有小心。 \n此固隐然有相火所居之意。故后世诸家咸谓相火寄在命门，是固然矣。然以予之见，则见君 \n相之义，无藏不有。又何以辨之？盖总言大体，则相火当在命门，谓根 在下，为枝叶 \n之本也。析言职守，则脏腑各有君相，谓志意所出，无不从乎形质也。故凡以心之神，肺之 \n气，脾胃之仓廪，肝胆之谋勇，两肾之伎巧变化，亦总皆发见之神奇，使无其地，何以生此 \n？使地有不浓，何以蕃此？此皆从位字发生，而五脏各有位，则五脏亦各有相，相强则君强， \n此相道之关系，从可知矣。故圣人特命此名，诚重之也。而后人指之为贼，抑何异耶！此万 \n世之疑窦，故予不得不辨。 \n或曰∶是若谬矣。第彼之指为贼者，亦有深意。盖谓人之情欲多有妄动，动则俱能起火 \n，火盛致伤元气，即所谓元气之贼，亦何不可？予曰∶此固邪正之歧，最当明辨者也。夫情 \n欲之动，邪念也，邪念之火为邪气。君相之火，正气也，正气之蓄为元气。其在身家，譬之 \n产业，贤者能守之。不肖者能荡之。罪与不罪，在子孙之废与不废， 基何与焉？相火 \n之义亦犹此耳。夫既以相称之，而竟以贼名之，其失圣人之意也远矣。且凡火之贼伤人者， \n非君相之真火，无论在内在外，皆邪火耳。邪火可言贼，相火不可言贼也。矧六贼之中，火 \n惟居一，何二子独知畏火，其甚如是，而并昧邪正之大义，亦何谓耶？予闻其言，固知其错 \n认面目矣，不觉因而失笑。 \n\n\n\n<目录>卷之二入集\\传忠录（中）\n\n<篇名>先天后天论（十四）\n\n属性：人生于地，悬命于天，此人之制命于天也。栽者，培之。倾者，覆之。此天之制命于人 \n也。天本无二，而以此观之，则有天之天者，谓生我之天，生于无而由乎天也；有人之天者 \n，谓成我之天，成于有而由乎我也。生者在前，成者在后，而先天后天之义，于斯见矣。故 \n以人之禀赋言，则先天强浓者，多寿；先天薄弱者，多夭。后天培养者，寿者更寿；后天斫 \n削者，夭者更夭。 \n若夫骨骼者，先天也。肌肉者，后天也。精神者，先天也。容貌者，后天也。颜色之有 \n辨也，苍者寿而妖者夭。嫩中有苍者吉，苍中有嫩者凶。声音之有辨也，充者寿而怯者夭。 \n虽细而长者吉，虽洪而促者凶。形体之有辨也，坚者寿而脆者夭。身虽羸瘦而动作能耐者吉 \n，体虽强盛而精神易困者凶。动静有辨也，静者寿而躁者夭。性虽若急而急中有和者吉，阳 \n虽若浓而阴中蕴薄者凶。至若少长之辨，初虽绵弱而渐长渐坚者，晚成之征也。气质之辨， \n少年华丽而易盈易满者，早凋之兆也。是故两天俱得其全者，耆艾无疑也。先后俱失其守者 \n，夭促弗卜也。 \n若以人之作用言，则先天之强者不可恃，恃则并失其强矣；后天之弱者当知慎，慎则人 \n能胜天矣。所谓慎者，慎情志可以保心神，慎寒暑可以保肺气，慎酒色可以保肝肾，慎劳倦 \n饮食可以保脾胃。惟乐可以养生，欲乐者莫如为善。惟福可以保生，祈福者切勿欺天。但使 \n表里无亏，则邪疾何由而犯？而两天之权不在我乎？故广成子曰∶毋劳尔形，毋摇尔精，乃可 \n以长生。至矣哉，两言尽之矣。勿以此为易而忽之。 \n\n\n\n<目录>卷之二入集\\传忠录（中）\n\n<篇名>标本论（十五）\n\n属性：病有标本者，本为病之源，标为病之变。病本唯一，隐而难明，病变甚多，显而易见。 \n故今之治病者，多有不知本末，而惟据目前，则最为斯道之大病。且近闻时医有云∶急则治 \n其标，缓则治其本，互相传诵，奉为格言，以为得其要矣。予闻此说而详察之，则本属不经 \n而亦有可取。所谓不经者，谓其以治标治本对待为言，则或此或彼，乃可相参为用矣。若然 \n，则《内经》曰∶治病必求其本，亦何谓耶？又经曰∶夫阴阳逆从，标本之为道也。小而大 \n，浅而博，可以言一而知百病之害也。以浅而知深，察近而知远，言标与本，易而勿及。又 \n曰∶先病而后逆者治其本，先逆而后病者治其本。先寒而后生病者治其本，先病而后生寒者 \n治其本。先热而后生病者治其本，先病而后生热者治其本。先病而后泄者治其本，先泄而后 \n生他病者治其本。先热而后生中满者治其标，先病而后生中满者治其标，先中满而后生烦心 \n者治其本。小大不利治其标，小大利治其本，先小大不利而后生病者治其本。由此观之，则 \n诸病皆当治本，而惟中满与小大不利两证当治标耳。盖中满则上焦不通，小大不利则下焦不 \n通，此不得不为治标以开通道路，而为升降之所由。是则虽曰治标，而实亦所以治本也。自 \n此以外，若以标本对待为言，则治标治本当相半矣。故予谓其为不经者此也。然亦谓其可取 \n者，则在缓急二字，诚所当辨。然即中满及小大不利二证，亦各有缓急。盖急者不可从缓， \n缓者不可从急。此中亦自有标本之辨，万不可以误认而一概论也。今见时情，非但不知标本 \n，而且不知缓急。不知标本，则但见其形，不见其情。不知缓急，则所急在病，而不知所急 \n在命。故每致认标作本，认缓作急，而颠倒错乱，全失四者之大义，重命君子，不可不慎察 \n于此。 \n\n\n\n<目录>卷之二入集\\传忠录（中）\n\n<篇名>求本论（十六）\n\n属性：万事皆有本，而治病之法，尤惟求本为首务。所谓本者，唯一而无两也。盖或因外感者 \n，本于表也。或因内伤者，本于里也。或病热者，本于火也。或病冷者，本于寒也。邪有余 \n者，本于实也。正不足者，本于虚也。但察其因何而起，起病之因，便是病本，万病之本， \n只此表里寒热虚实六者而已。知此六者，则表有表证，里有里证，寒热虚实，无不皆然。六"}, {"n": 2, "text": "卷二\n\n者相为对待，则冰炭不同，辨之亦异。凡初病不即治，及有误治不愈者，必致病变日多，无 \n不皆从病本生出，最不可逐件猜摸，短觑目前。经曰∶众脉不见，众凶弗闻，外内相得，无 \n以形先。是诚求本之至要也。苟不知此，必庸流耳。故明者独知所因，而直取其本，则所生 \n诸病，无不随本皆退矣。 \n至若六者之中，多有兼见而病者，则其中亦自有源有流，无弗可察。然惟于虚实二字总 \n贯乎前之四者，尤为紧要当辨也。盖虚者本乎元气，实者由乎邪气。元气若虚，则虽有邪气 \n不可攻，而邪不能解，则又有不得不攻者，此处最难下手。但当察其能胜攻与不能胜攻，或 \n宜以攻为补，或宜以补为攻，而得其补泻于微甚可否之间，斯尽善矣。且常见有偶感微疾者 \n，病原不甚，斯时也，但知拔本，则一药可愈，而庸者值之，非痰曰痰，非火曰火，四路兜 \n拿，茫无真见，而反遗其本。多致轻者日重，重者日危，而殃人祸人，总在不知本末耳 \n。甚矣！医之贵神，神奚远哉！予故曰∶医有慧眼，眼在局外；医有慧心，心在兆前。使果能 \n洞能烛，知几知微，此而曰医，医云乎哉？他无所谓大医王矣。 \n\n\n\n<目录>卷之二入集\\传忠录（中）\n\n<篇名>治形论（十七）\n\n属性：老子曰∶吾所以有大患者，为吾有身。使吾无身，吾有何患？余则曰∶吾所以有大乐者 \n，为吾有形。使吾无形，吾有何乐？是可见人之所有者唯吾，吾之所赖者唯形耳！无形则无吾 \n矣，谓非人身之首务哉。第形之为义，其义甚微，如言动视听，非此形乎？俊丑美恶，非此 \n形乎？勇怯愚智，非此形乎？死生安否，非此形乎？人事之交，以形交也。功业之建，以形建 \n也。此形之为义，从可知也。奈人昧养形之道，不以情志伤其府舍之形，则以劳役伤其筋骨 \n之形。内形伤则神气为之消靡，外形伤则肢体为之偏废。甚至肌肉尽削，其形可知，其形既 \n败，其命可知。然则善养生者，可不先养此形，以为神明之宅，善治病者，可不先治此形， \n以为兴复之基乎。 \n虽治形之法，非止一端，而形以阴言，实惟精血二字足以尽之。所以欲祛外邪，非从精 \n血不能利而达；欲固中气，非从精血不能蓄而强。水中有真气，火中有真液，不从精血，何 \n以使之降升？脾为五脏之根本，肾为五脏之化源，不从精血，何以使之灌溉？然则精血即形也 \n。形即精血也，天一生水，水即形之祖也。故凡欲治病者，必以形体为主；欲治形者，必以 \n精血为先，此实医家之大门路也。使能知此，则变化可以无方，神明自有莫测。 \n然用此之法，无逾药饵，而药饵之最切于此者，不过数味之间，其他如性有偏用者，惟 \n堪佐使而已。亦犹饮食于人，凡可口者，孰无资益，求其纯正无损而最宜于胃气者，则惟谷 \n食，类可见矣。或问余以所宜者，果属何物？余则难以显言之。盖善吾言者，必如醴如饴， \n而不善吾言者，必反借此为射的，以资口吻之基矣。余故不能显言之，姑发明此义，以俟有 \n心者之自悟。 \n\n\n\n<目录>卷之二入集\\传忠录（中）\n\n<篇名>脏象别论（十八）\n\n属性：脏象之义，余所类于经文者不啻详矣，然经有所未及，而同中有不同，及有先同后异者 \n，俱不可以不辨也。夫人身之用，止此血气。虽五脏皆有气血，而其纲领，则肺出气也，肾 \n纳气也，故肺为气之主，肾为气之本也。血者水谷之精也，源源而来，而实生化于脾，总统 \n于心，脏受于肝，宣布于肺，施泄于肾，而灌溉一身。所谓气主嘘之，血主濡之，而血气为 \n人之橐 ，是皆人之所同也。若其同中之不同者，则脏气各有强弱，禀赋各有阴阳。脏有强 \n弱，则神志有辨也，颜色有辨也，声音有辨也，性情有辨也，筋骨有辨也，饮食有辨也，劳 \n役有辨也，精血有辨也，勇怯有辨也，刚柔有辨也。强中强者，病其太过，弱中弱者，病其 \n不及。因其外而察其内，无弗可知也。禀有阴阳，则或以阴脏喜温暖，而宜姜、桂之辛热； \n或以阳脏喜生冷，而宜芩、连之苦寒。或以平脏，热之则可阳，寒之则可阴也。有宜肥腻者 \n，非润滑不可也；有宜清素者，惟膻腥是畏也。有气实不宜滞，有气虚不宜破者。有血实 \n不宜涩，有血虚不宜泄者。有饮食之偏忌，有药饵之独碍者。有一脏之偏强，常致欺凌他脏 \n者。有一脏之偏弱，每因受制多虞者。有素挟风邪者，必因多燥，多燥由于血也。有善病湿 \n邪者，必因多寒，多寒由于气也。此固人人之有不同也。其有以一人之禀而先后之不同者， \n如以素禀阳刚而恃强无畏，纵嗜寒凉，及其久也，而阳气受伤，则阳变为阴矣。或以阴柔而 \n素耽辛热，久之则阴日以涸，而阴变为阳矣。不惟饮食，情欲皆然。病有出入，朝暮变迁， \n满而更满，无不覆矣。损而又损，无不破矣。故曰∶久而增气，物化之常也；气增而久，夭 \n之由也。此在经文固已明言之矣。 \n夫不变者，常也；不常者，变也。人之气质有常变，医之病治有常变，欲知常变，非明 \n四诊之全者不可也。设欲以一隙之偏见，而应无穷之变机，吾知其遗害于人者，多矣。故于 \n此篇之义，尤不可以不深察。 \n\n\n\n<目录>卷之二入集\\传忠录（中）\n\n<篇名>天年论（十九）\n\n属性：夫人之所受于天而得生者，本有全局，是即所谓天年也。余尝闻之岐伯曰∶上古之人， \n其知道者，法于阴阳，和于术数，食饮有节，起居有常，不妄作劳，故能形与神俱，而尽终 \n其天年，度百岁乃去。又尝闻之老子曰∶生之徒，十有三；死之徒，十有三；民之生，动之 \n死地，亦十有三。余因此言，乃知失天之畀而不得尽其全者有如是。然则后天之养，其为在 \n人，可以养生家而不以此为首务乎！故常深慨于斯，而直穷其境，则若老氏所云十中之三者 \n，盖亦言其约耳。而三之倍倍，则尤有不忍言者，兹请得而悉之。 \n夫人生于地，悬命于天，可由此而生，亦可由此而死。故凡天亦杀人，有如寒暑不时， \n灾荒荐至，或妖祥之横加，或百六之难避，是皆天刑之谓也。地亦杀人，则如旱潦无方，水 \n火突至，或阴毒最以贼人，或危险多能困毙，是皆地杀之谓也。人亦杀人，如争斗伤残，刀 \n兵屠戮，或嫁祸阴谋，或明欺强劫，是皆人祸之谓也。凡此三者，十中约去其几。再若三者 \n之外，则凡孽由自作而致不可活者，犹有六焉。何以见之？则如酒色财气，及功名之累，庸 \n医之害皆是也。故有困于酒者，但知米汁之味甘，安思曲 之性烈？能潜移祸福而人难避也 \n，能大损寿元而人不知也。及其病也，或血败为水，而肌肉为其浸渍，则鼓胀是也。或湿邪 \n侵土，而清浊苦于不分，则泻痢是也。或血不养筋，而弛纵拘挛，甚至眩晕卒倒，则中风是 \n也。或水泛为涎，而满闷不食，甚至脾败呕喘，则痰饮是也。耽而不节，则精髓胡堪久醉， \n阴血日以散亡，未及中年，多见病变百出，而危于此者不知其几何人矣。 \n有困于色者，但图娇艳可爱，而不知倾国之说为何，伐命之说为何。故有因色而病者， \n则或成劳损，或染秽恶，或相思之失心，或郁结之尽命。有因色而死者，则或以窃窥，或以 \n争夺，或以荡败无踪，或以惊吓丧胆。总之，好色之人必多淫溺，乐而忘返，安顾身家？孰 \n知实少花多，岂成瑞物，德为色胜，非薄则邪，未有贪之恋之而不招殃致败。凡受色中之害 \n者，吾又不知其几何人矣。 \n有困于财者，止知财能养命，岂识财能杀人。故鄙吝者，每以招尤。慢藏者，因多诲盗 \n。奔波不已者，多竭其力。贪得无厌者，常忘其身。顾利罔顾义，骨肉为之相残，聚敛尽膏 \n血，贾怨所以致败。盖财本通神，不容 剥，积则金精崇作，争则罄囊祸生。凡受利中 \n之害者，又不知其几何人矣。 \n有困于气者，每恃血气之强，只喜人不负我，非骄矜则好胜，人心不平，争端遂起，事 \n无大小，怨恨醉心，岂虞忿怒最损肝脾，而隔食气蛊，疼痛泄泻，厥逆暴脱等疾，犯者即危 \n。又或争竞相倾，公庭遘讼，宁趋势利以卑污，甘受丑凌于奴隶，及被他人之苛辱。既不敢 \n相抗于后，何若亲识之小忿。即涵容少逊于前，终身让路，不失一步，孰得孰失，孰知孰 \n愚？甚至破家荡产，骨肉分离之害，纤须不忍，悔时迟矣。夫气本无形，有何涯际，相谅则 \n无，偏执则有，历观往事，谁直谁非？使不能达观自策，则未免以我之躯，阴受人无申无诉 \n之蚀，而自愚自毙者，又不知其几何人矣。 \n有困于功名者，谁不有飞腾之念？谁不有功业之期？第既达者，或多鼎足之虞。未济者， \n每遭监车之厄，受灯窗寒苦之负，望眼徒穿者有之。忆荣枯今昔之异，热肠为裂者有之。甚 \n至焦思切心，奔趋竭力，荣华杳然，泉壤遽及者有之。慨古伤今，凡受斯枉而湮没无闻，浩 \n气受抑者，又不知其几何人矣。 \n有困于医者，凡疾苦之望医，犹凶荒之望岁，其恳其切，其念何如。第此中神理，微妙 \n难言，使不有天人之学，绝伦之聪，则何以能闻于无声，见于无迹，直窥乎窈冥之乡，而必 \n得其情乎？使必得其人而后可以言医，则医不易谈，盖可征矣。既难其人，则次乎此者，虽 \n未知神，犹知形迹，此即今之上医也，然此医亦不易得。而舍此之外，则昧者居其八九。庸 \n医多，则杀人亦多，每见其寒热倒施，虚实谬认，一匕之讹，吉凶随应。困者莫知其然，虽 \n死不觉，明公鉴其多误，能无恻心？顾造化大权，本非凡庸所可窥弄。而性命重托，又岂浅 \n辈所宜轻付耶！第彼非无自，盖自《原病式》以来，祖述相传，日以滋甚，醉者不醒，逝者 \n无词，而黎元阴受此害者，盖不知若干若干人矣。而闻者未知其详，犹或未之信也。 \n由是乘除，则既有前三，又有后六，凡此淘汰之余，而得尽其天年者，果剩其几？吾故 \n曰∶老氏言十之三者，盖亦言其约耳。兴言及此，诚可为人生之痛哭者也。然徒悲何益？曷 \n亦为人之计乎，则惟上知者有可晓也。虽前之三者，或多出于莫测，则有可避者，有不可避 \n者，即听之天，无不可也。然知者见于未然，而得天者天庇之，得地者地庇之，得人者人庇 \n之。得此三庇，即得生之道也；失此三庇，则失生之道也。人道于此，岂曰尽无其权乎！至 \n于六杀之防，则全由乎我矣。酒杀可避，吾能不醉也。色杀可避，吾能不迷也。财杀可避， \n吾能不贪也。气杀可避，吾能看破不认真也。功名之杀可避，吾能素其行藏也。庸医之杀可 \n避，吾能相知以豫也。夫如是而培以为善，存以无欺，守以不行险，戒以毋侥幸，则可全收 \n其效矣。孔子曰∶毋意，毋必，毋固，毋我。盖示人以无勉强也。广成子曰∶毋劳尔形，毋 \n摇尔精，乃可以长生。盖形言其外，精言其内，内外俱全，尽乎道矣。是皆古圣人垂念苍生 \n，至真至极之良方也，可不佩乎。或曰∶子言虽是，而实亦近迂，独不见有不识不知而偏跻 \n上寿者，又何人力之足恃耶？余曰∶此正所谓其知可及也，其愚不可及也。然予论诚迂矣， \n倘亦蒙知者之相顾而咀之识之，或亦可为天年之一助否？ \n\n\n\n<目录>卷之二入集\\传忠录（中）\n\n<篇名>中兴论（又十九）\n\n属性：试观天地之道，有盈有虚，有消有长，是以日中则昃，月盈则蚀，此即天运之循环，而 \n天亦不能违者，故有先天之说也。先天有定数，君子知命，固当听乎天也。若后天之道，则 \n参赞有权，人力居多矣。何以见之？第就国家之否泰，可证人身之寿夭。虽曰天步多艰，无 \n成不败，然如商周汉晋唐宋相传，国运皆有中兴，人道岂无再振？消长一理，小大皆然。尝 \n闻之康节先生云∶一万里区宇，四千年兴亡，五百主肇位，七十国开疆，则此中人事不为不 \n多也。而何以兴复仅见止此数代。是亦由知道者少，而不知道者之多耳。彼知道者，既以得 \n人，又以得天。得人即所以得天也。不知道者，既不知本，又不知末，既以失之，而终不知 \n其所以失也。至若身命之谋，则举世之人孰不爱命，而每多耽误者，其不知道者亦犹是耳。 \n欲明其道，可无言乎。然言而无证，则人多不信，故借此国运之征，用效遒人之铎。 \n试论国家之衰也，或以人心之离，或以财用之匮，或以兵戈之残伤，或以优柔之旷废。 \n而人之亨否，无非一理。夫在国曰人心，在人曰神志。故曰∶事其神者神去之，休其神者神 \n居之。知生气之主在乎心，此元神之不可不养也。又在国曰财用，在人曰血气。气为阳，阳 \n主神也；血为阴，阴主形也。血气若衰，则形神俱败，此营卫之毫厘当惜也。又在国曰兵戈 \n，在人曰克伐。夫兵者，凶器也；克伐者，危事也。未有日加剥削而不致残伤元气者，此消 \n耗之不可不慎也。又在国曰优柔，在人曰疑贰。今日云姑且，明日云将就，岂不佥云稳当， \n然致坐失机宜，变生倏忽。又焉知耽搁之大害，此死机之不可不断也。凡此数者，姑亦言其 \n大约。 \n至若人之大数，则犹有先天后天之体用，而兴亡之应变，则来培来覆，亦莫匪人之自为 \n耳。何谓先天？如《内经》曰∶人生十岁，血气始通，其气在下，故好走。二十，气血方盛 \n，肌肉方长，故好趋。三十，五脏大定，血脉盛满，故好步。四十，脏腑经脉其盛已定，腠 \n理始疏，故好坐。五十，肝气衰，故目不明。六十，心气衰，故好卧。七十，脾气衰。八十 \n，肺气虚，故言善误。九十，肾气竭。百岁，五脏六腑皆虚，神气皆去，故形骸独居而终矣 \n。此即先天之常度，是即所谓天年也。天畀之常，人人有之，其奈今时之人，自有知觉以来 \n，恃其少壮，何所不为。人生之常度有限，而情欲无穷。精气之生息有限，而耗损无穷。因 \n致戕此先天而得全我之常度者，百中果见其几？残损有因，惟人自作，是即所谓后天也。然 \n而所丧由人，而挽回之道，有不仍由人者乎？且此非逆天以强求，亦不过复吾之固有。得之 \n则国运人运，皆可中兴，不有明哲，诚难语此；失之则落花流水，逝而罔觉，一衰即已，良 \n可寒心，所以《易》重来复，正为此也。然求复之道，其道何居？盖在天在人，总在元气， \n但使元气无伤，何虞衰败？元气既损，贵在复之而已。 \n常见今人之病，亦惟元气有伤，而后邪气得以犯之。故曰∶邪之所凑，其气必虚。此客 \n主相持之理，从可知矣。凡虚邪之辨，如情志之消索，神主于心也。治节之不行，气主于肺 \n也。筋力之疲困，血主于肝也。精髓之耗减，骨主于肾也。四肢之软弱，肌肉主于脾也。损 \n其一浅，犹肤腠也；损其二深，犹经络也；损其三四，则连及脏腑矣。当其微也，使不知徙 \n薪牖户，则将为江河，将寻斧柯，恐无及于事矣。故人于中年左右，当大为修理一番，则再 \n振根基，尚余强半。敢云心得，历验已多，是固然矣。然而修理之说，亦岂易言？修国家， \n良臣不易；修身命，良医亦难。第观从古至今，数千年来，凡得医之全量者为谁？而今则曰 \n∶此医也，彼亦医也，又何良医之多也？医难言矣，其毋为良医之所惑。 \n\n\n\n<目录>卷之二入集\\传忠录（中）\n\n<篇名>逆数论（二十）\n\n属性：予尝读《易》而闻诸夫子曰∶数往者顺，知来者逆，是故《易》，逆数也。由是默会其 \n理，而知天人之道得以无穷无息者，无非赖此逆数耳。何也？盖自太极初分，两仪以判，一 \n动一静，阴阳见矣。阴阳之体为乾坤，阴阳之用为水火。乾坤定对待之交易，故一在上而一 \n在下；水火荡流行之变易，故一主降而一主升。夫如是，斯得循环无已。总之而为天道，散 \n之而为人道，而大《易》之义，所以无微不在也。姑无论其他，而但以性理明之，则总由变 \n易之数。夫变易之数，即升降之数也。变易之所以无穷者，降以升为主，是即所谓逆数也。 \n若无此逆，则有降无升，流而不返，而大道如环，何所赖乎？由是逆顺交变，则阳与阴对， \n热与寒对。升与降对，长与消对，进与退对，成与败对，勤与惰对，劳与逸对，善与恶对， \n生与死对，凡此一逆一顺，其变无穷。惟从逆者，从阳得生；从顺者，从阴得死。君如不信 \n，第详考伏羲卦气之圆图，其义昭然可见也。观其阳盛之极，自夏至一阴初 ，由五、 \n六、七、八，历巽、坎、艮、坤，天道从西右行，则阳气日降，万物日消者，此皆顺数也。 \n顺则气去，即从阴得死之道也。幸而阴剥之极，自冬至一阳得复，由四、三、二、一，历震 \n、离、兑、干，天道从东左旋，则阳气日升，万物日盛者，此皆逆数也。逆则气来，即从阳 \n得生之道也。此天道之征，固如是也。 \n若以人道言之，则人道本乎天道，天心即是人心。第天有阴霾，能蒙日月，人有愚昧， \n能胜聪明。故每多从顺者，喜其易也，喜其逸也；每多避逆者，畏其难也，畏其劳也。彼大 \n人之见则不然，如尊贵莫若帝王，可以逸矣，可以纵矣，而尧舜之惟微惟危，顾何必谆谆乎 \n在念？智能莫若圣人，可无劳矣，可无畏矣。而孔子之戒慎恐惧，又何必卷卷乎在心？此无他 \n，惟其代天功，主人极，总知夫顺不可从，从顺则流，逆不可舍，舍逆则退也。由此观之， \n乃知士而舍逆，则有屈而无伸；农而舍逆，则有种而无获；工而舍逆，则有粗而无精；商而 \n舍逆，则有散而无聚。再由此而推展之，则凡曰修身齐家，凡曰治国平天下，进一步则日以 \n就成，退一步则日以就败，有源有流，其可任其长逝而不思砥柱之良图乎！此人道之攸系， \n又如是矣。 \n然言天言人，总言乎生道也。而保生之道，莫先于医，医欲保生，其堪违阳道乎？其堪 \n倍逆数乎？然医贵圆通，安容执滞，非曰尽不从阴也，从阴正以卫阳也；非曰尽不用顺也， \n用顺亦以成逆也，性命玄关，此为第一。独念有医名丕着之辈，犹然昧此，而妄言左道，留 \n传至今，因致伤生遗害非浅者，谓非轩岐之魔不可也。嗟！嗟！有心哉其谁乎？苟得其人，可 \n与谈还悟道矣。傥亦以吾言为然不。 \n\n\n\n<目录>卷之二入集\\传忠录（中）\n\n<篇名>反佐论（二十一）\n\n属性：用药处方有反佐之道者，此轩岐之法旨，治病之微权，有不可不明者。奈何后世医家， \n每多假借以乱经常，不惟悖理于前，抑且遗害于后，是不可不辨也。观《内经》之论治曰∶ \n奇之不去则偶之，偶之不去则反佐以取之，所谓寒热温凉，反从其病也。此其义，盖言病有 \n微甚，亦有真假，先从奇偶以正治，正治不愈，然后用反佐以取之，此不得不然而然也。又 \n经曰∶微者逆之，甚者从之。又曰∶逆者正治，从者反治。此谓以寒治热，以热治寒，逆其 \n病者，谓之正治；以寒治寒，以热治热，从其病者，谓之反治。如以热治寒而寒拒热，则反 \n佐以寒而入之；以寒治热而热拒寒，则反佐以热而入之，是皆反佐之义，亦不得不然而然也 \n。又经曰∶热因寒用，寒因热用。王太仆注曰∶热因寒用者，如大寒内结，当治以热，然寒 \n甚格热，热不得前，则以热药冷服，下嗌之后，冷体既消，热性便发，情且不违，而致大益 \n，此热因寒用之法也。寒因热用者，如大热在中，以寒攻治则不入，以热攻治则病增，乃以 \n寒药热服，入腹之后，热气既消，寒性遂行，情且协和，而病以减，此寒因热用之法也。凡 \n此数者，皆《内经》反佐之义。此外，如仲景治少阴之利，初用白通汤，正治也。继因有烦 \n而用白通加猪胆汁汤，反佐也。其治霍乱吐痢，脉微欲绝者，初用四逆汤，正治也。继因汗 \n出小烦，而用通脉四逆加猪胆汁汤，反佐也。又如薛立斋治韩州同之劳热，余尝治王蓬雀之 \n喉痹，皆其法也。 \n若今诸家之所谓反佐者则不然，姑实时尚者道其一二以见之。如近代之所宗所法者，谓 \n非丹溪之书乎？观丹溪之治吞酸证，必以炒黄连为君，而以吴茱萸佐之；其治心腹痛证，谓 \n宜倍加山栀子而以炒干姜佐之。凡此之类，余不解也。夫既谓其热，寒之可也，而何以复用 \n干姜、茱萸？既谓其寒，热之可也，而何以复用黄连、栀子？使其病轻而借以行散，即或见效 \n，岂曰尽无；使其病重，人则但见何以日甚，而不知犯寒犯热，自相矛盾，一左一右，动皆 \n掣肘，能无误乎？矧作用如此，则其效与不效，必其莫知所因，而宜热宜寒，亦必从违奚辨 \n。此其见有不真，故持两可，最是医家大病，所当自反而切戒者也。 \n或曰∶以热导寒，以寒导热，此正得《内经》反佐之法。人服其善，子言其非。何其左 \n也？余曰∶此法最微，此用最妙，子亦愿闻其详乎？当为再悉之。夫反佐之法，即病治之权也 \n。儒者有经权，医者亦有经权。经者，日用之常经，用经者，理之正也；权者，制宜之权变 \n，用权者，事之暂也。此经权之用，各有所宜，诚于理势有不得不然，而难容假借者也。药 \n中反佐之法，其亦用权之道，必于正经之外，方有权宜，亦因不得不然，而但宜于暂耳，岂 \n果随病处方，即宜用乎？然则何者宜反？何者不宜反？盖正治不效者，宜反也。病能格药者， \n宜反也。火极似水者，宜反也。寒极反热者，宜反也。真以应真，假以应假，正反之道，妙 \n用有如此也。设无格拒假证，自当正治，何以反为？不当权而用权，则悖理反常，不当反而 \n佐反，则致邪失正。是乌可以混用耶？常观轩岐之反佐，为创经权之道也；后世之反佐，徒 \n开杂乱之门也。至其变也，则泾渭不分者以之，模糊疑似者以之，寒热并用者以之，攻补兼 \n施者以之，甚至广络妄投，十寒一暴，无所不谬，皆相借口，此而不辨，医乎难矣。于戏！ \n斯道失真，其来已久，安得愿闻精一者，与谈求本之道哉！是不能无望于后人也，因笔识其 \n愚昧。以上仲景治法载《伤寒论》。薛立斋治韩州同按在虚损门。余治王蓬雀按在喉痹门。 \n\n\n\n<目录>卷之二入集\\传忠录（中）\n\n<篇名>升阳散火辨（二十二）\n\n属性：凡治火之法，有曰升阳散火者，有曰滋阴降火者。夫火一也，而曰升曰降，皆堪治火。 \n然升则从阳，降则从阴，而升降混用，能无悖乎？抑何者宜升，何者宜降，而用有辨乎？此千 \n古之疑窦，亦千古之两端，而未闻有达之者。夫火之为病，有发于阴者，有发于阳者。发于 \n阴者，火自内生者也；发于阳者，火自外致者也。自内生者，为五内之火，宜清宜降者也； \n自外致者，为风热之火，宜散宜升者也。今人凡见火证，无分表里，必曰木火同气，动辄称 \n为风热，多用升阳散火之法。呜呼！此似近理，孰得非之。而不知至理所在，无容混也。 \n夫风热之义，其说有二∶有因风而生热者，有因热而生风者。因风生热者，以风寒外闭 \n而火郁于中，此外感阳分之火，风为本而火为标也。因热生风者，以热极伤阴而火达于外， \n此内伤阴分之火，火为本而风为标也。经曰∶治病必求其本。可见外感之火，当先治风，风 \n散而火自息，宜升散不宜清降。内生之火，当先治火，火灭而风自清，宜清降不宜升散。若 \n反而为之，则外感之邪得清降而闭固愈甚，内生之火得升散而燔燎何当。此其内因外因，自 \n有脉证可详辨也。 \n余阅方书，所见头目、口齿、咽喉、脏腑阴火等证，悉云风热，多以升降并用，从逆 \n兼施。独不虑升者碍降，降者碍升乎？从者忌逆，逆者忌从乎？经曰∶高者抑之，下者举之， \n寒者热之，热者寒之。又曰∶病生于内者，先治其阴，后治其阳，反者益甚。病生于阳者， \n先治其外，后治其内，反者益甚。此自不易之正理。故余之立方处治，宜抑者则直从乎降， \n宜举者则直从乎升。所以见效速而绝无耽延之患，亦不过见之真而取之捷耳。若今人之轻病 \n致重，重病致危，而经年累月，日深日甚，以致不救者，谓非两端之误之也乎？明者于此， \n最当辨也。 \n\n\n\n<目录>卷之二入集\\传忠录（中）\n\n<篇名>夏月伏阴续论（二十三）\n\n属性：夏月伏阴在内，此本天地间阴阳消长之正理。顾丹溪特为此论而反乖其义，因以致疑于 \n人。其谓何也？观其所论曰∶人与天地同一橐 ，子月一阳生，阳初动也；寅月三阳生，阳 \n初出于地也，此气之升也。巳月六阳生，阳尽出于上矣，此气之浮也。人之腹属地，气于此 \n时，浮于肌表，散于皮毛，腹中虚矣。世言夏月伏阴在内，此阴字有虚之义，若作阴凉看， \n其误甚矣。且其时阳浮地上，燔灼焚燎，流金烁石，何阴冷之有？若于夏月火令之时妄投温 \n热，宁免实实虚虚之患乎！此丹溪之言虚，是固然矣。若以阴冷二字为误，而夏月禁用温热 \n，此则余所不服也。 \n何以见之？夫天地之道，惟此阴阳，阴阳之变，惟此消长。故一来则一往，一升则一降 \n，而造化之机，正互藏为用者也。经曰∶阴主寒，阳主热。又曰∶气实者，热也；气虚者， \n寒也。此本阴阳之常性也。今既云夏月之阳尽浮于外，则阴伏于内矣，阴盛则阳衰也，非寒 \n而何？阳浮于外，则气虚于中矣。气虚即阳虚也，非寒而何？此固不易之理也。然而尤有显然 \n者，则在井泉之水，当三冬之寒冽，而井泉则温；盛夏之炎蒸，而泉源则冷。此非外寒内热 \n，外热内寒之明验乎？此又岁岁皆然，主气之常候也。至若主气之外，又有客气，而天以五 \n周，地以六备，寒暄递迁，气更应异。如伏明之纪，寒清数举；卑监之纪，风寒并兴；坚成 \n之纪，阳气随阴治化；流衍之纪，寒司物化，天地严凝；太阳司天，寒气下临，寒清时举； \n太阴司天，地乃藏阴，大寒且至等义，是无论冬夏，皆有非时之气以动为民病者也。又岂因 \n夏月之火令，遂可谓之无寒而禁用温热乎？且伏阴之义，本以阴阳对待，寒热为言，若但以 \n阴字为虚，则夏月伏阴，宜多虚证，冬月伏阳，即无虚矣。岂其然乎？又若夏月宜禁温热， \n则冬月宜禁寒凉，无待言也。今见四时之病，盛夏每多吐泻，深冬偏见疮疹，诸如此类，岂 \n非冬多内热，夏多中寒乎？总之，夏有热证，亦有寒证，冬有实证，亦有虚证，虽从时从证 \n，贵乎因病制宜，然夏月伏阴之义，此实天人之同气，疾病之玄机，有必不可不察而忽之者 \n也。今若丹溪之论，则于理反悖，而何切于用？即无此论，亦何不可？ \n近见徐东皋亦述丹溪之说云∶夏月无寒，世人不察，而用温热，为世通弊。若谓夏月伏 \n阴，宜服温热，则冬月伏夏，宜服寒凉，然则孟子冬日饮汤，夏日饮水，亦不足信欤？噫！此 \n公都子之言也，不过借喻内外，原非用析阴阳。而徐氏曲引为证，独不思经文《易》义，傥 \n相背乎？《内经》曰∶阴中有阳，阳中有阴。曰∶寒极生热，热极生寒。曰∶重阴必阳，重 \n阳必阴。曰∶相火之下，水气承之；君火之下，阴精承之。曰∶此皆阴阳表里内外雌雄相输 \n应也，故以应天之阴阳也。又如《周易》之两仪，有阴必有阳也。两仪而四象，阴阳之中复 \n有阴阳也。在泰之义，则曰内阳而外阴，君子道长，小人道消也。在否之义，则曰内阴而外 \n阳，小人道长，君子道消也。由此观之，则丹溪之论，东皋之引证，皆吾之所不信也。故复 \n为此续论。 \n\n\n\n<目录>卷之二入集\\传忠录（中）\n\n<篇名>阳不足再辨（二十四）\n\n属性：原天地阴阳之化生，实生民性命之根本，善把握补救之妙用，诚吾道代天之大权，使我 \n于此而见理不真，则加冰用汤，反成戕贼，害有不可胜言者。予自初年，尝读朱丹溪阳有余 \n阴不足论，未尝不服其高见，自吾渐立以来，则疑信相半矣。又自不惑以来，则始知其大谬 \n矣。故予于《类经·求正录》中，附有大宝论一篇，正所以救其谬也。然常恐见浅言偏，遗 \n殃后世，每怀疑惧，而望正高明者，久矣。不意付梓数载，斧削无闻，见信明贤，庶窃自慰 \n。兹于丙子之夏，始得神交一友，传训数言，询其姓氏，知为三吴之李氏也。诵其《指南》 \n，则曰∶阳常有余，阴常不足，此自丹溪之确论。而兹张子乃反谓阳常不足，阴常有余，何 \n至相反若此？而自是其是，岂矫强以自 欤？抑别有所本欤？姑无劳口吻以辨其孰是孰非，第 \n以人事证之，则是非立见矣。如人自有生以来，男必十六而精始通，女必十四而经始至；及 \n其衰也，男精竭于八八，女血净于七七。凡精血既去而人犹赖以不死者，惟此气耳。夫气为 \n阳，精血阴也，精血之来，既迟在气后，精血之去，又早在气先，可见精已无而气犹在，此 \n非阴常不足，阳常有余之明验乎？以是知先贤之金石本非谬，而后学之轻妄何容易也。予闻 \n此说，益增悲叹。悲之者，悲此言之易动人听，而无不击节称善也。紫可乱朱，莫此为甚， \n使不辨明，将令人长梦不醒，而性命所系非渺小，是可悲也。悲已而喜，喜之者，喜至道之 \n精微，不经驳正，终不昭明，幸因其说，得启此端而得解此惑，是可喜也。今即李子之言以 \n辨之。 \n如其以精为阴，以气为阳，本非诬也。第其所觑在眉睫，则未免错认面目，而呼张作李 \n矣。不知精即水也，水即阳也。若以水火言，则水诚阴也，火诚阳也；若以化生言，则万物 \n之生，其初皆水，先天后天，皆本于是，而水即阳之化也。何以见之？如水在五行则生于一 \n天，水在六气，则属乎太阳，此水之为阴否？又若精在人身，精盛则阳强，精衰则阳痿，此 \n精之为阴否？再若养生家所重者，惟曰纯阳，纯阳之阳，以精言也。精若渗漏，何阳之有。 \n此又精之为阴否？又丹书云∶分阳未尽则不死，分阴未尽则不仙，亦言仙必纯阳也。若据李 \n子之说，则但尽泄其精，便成纯阳，学仙之法岂不易乎？诚可哂也！盖李子之见，但见阴阳之 \n一窍，未见阴阳之全体。夫阴阳之道，以纲言之，则位育天地；以目言之，则缕析秋毫，至 \n大至小，无往而非其化也。若以清浊对待言，则气为阳，精为阴，此亦阴阳之一目也。若以 \n死生聚散言，则凡精血之生皆为阳，气得阳则生，失阳则死，此实性命之化源，阴阳之大纲 \n也。 \n人之生也，譬诸草木。草木之初，其生苗也，继而生枝叶，再而生花实，及其衰也，花 \n实落而枝叶存，以渐而凋也。此草木之盛衰有时，故曰生长化收藏，而候有不同也。人之生 \n也，亦犹是耳，初而生婴孩，继而生精血，再而生子女，及其衰也，精血去而形犹存，以渐 \n而终也。此人生之盛衰亦有其时，故曰生长壮老已，而年有不同也。然则自幼至老，凡在生 \n者，无非生气为之主，而一生之生气，何莫非阳气为之主，而但有国中之异耳。若以人之精 \n至为阴至，岂花果之成，亦草木之阴至耶？而枝叶未凋，即草木之阳在耶？且阳气在人，即 \n人人百岁，亦不过得分内之天年，而今见百人之中，凡尽天年而终者果得其几？此其夭而不 \n及者，皆非生气之不及耶，而何以见阳之有余也？阳强则寿，阳衰则夭，又何以见阳之有余 \n也？难得而易失者，惟此阳气，既失而难复者，亦惟此阳气，又何以见阳之有余也？观天年篇 \n曰∶“人生百岁，五脏皆虚，神气皆去，形骸独居而终矣。夫形，阴也；神气，阳也，神气 \n去而形犹存，此正阳常不足之结局也。而可谓阳常有余乎？ \n至若精气之阴阳，有可分言者，有不可分言者。可分者，如前云清浊对待之谓也；不可 \n分者，如修炼家以精气神为三宝。盖先天之气，由神以化气化精。后天之气，由精以化气化 \n神。是三者之化生，互以为根，本同一气，此所以为不可分也。故有善治精者，能使精中生 \n气，善治气者，能使气中生精。此自有可分不可分之妙用也。再若寒热之阴阳，则不可不分 \n。盖寒性如冰，热性如炭，冰炭不谋，奚堪妄用？予故曰∶精气之阴阳有不可离，寒热之阴 \n阳有不可混，此医家最切之法言也。且精血之阴阳，言禀赋之元气也；寒热之阴阳，言病治 \n之药饵也。今欲以不足之元阳，认作有余而云火，则相习以苦寒之劣物，用为补剂以滋阴， \n嗟嗟！牛山有限之生气，果能堪此无穷之阴剥否？哑子吃黄连，无容伸诉者，四百年于兹矣。 \n夫以有望之丹溪言且若此，而矧其他乎。古人云∶非圣之书不可读，此其尤甚者也。 \n然天地阴阳之道，本自和平，一有不平，则灾害至矣。而余谓阳常不足，岂亦非一偏之 \n见乎？盖以丹溪补阴之说谬，故不得不为此反言，以救万世之生气。夫人之所重者，惟此有 \n生，而何以能生，惟此阳气，无阳则无生矣。然则欲有生者，可不以此阳气为宝，即日虑其 \n亏，亦非过也。而余谓阳常不足者，盖亦惜春之杞人耳。苟诚见下，仍望明贤再驳。 \n\n\n\n<目录>卷之二入集\\传忠录（中）\n\n<篇名>小儿补肾论（二十五）\n\n属性：观王节齐曰∶小儿无补肾法。盖小儿禀父精而生，男至十六而肾始充满，既满之后，妄 \n用亏损，则可用药补之。若受胎之时，禀之不足则无可补，禀之原足，又何待于补耶？呜呼 \n，此言之谬，谬亦甚矣！夫二五之精，妙合而凝，精合而形始成，此形即精也，精即形也， \n治精即所以治形，治形即所以治精也。第时有国中，则精有衰盛，故小儿于初生之时，形体 \n虽成而精气未裕，所以女必十四，男必十六，而后天癸至。天癸既至，精之将盛也。天癸 \n未至，精之未盛也。兹以其未盛而遽谓其无精也可乎？且精以至阴之液，本于十二脏之生化 \n，不过藏之于肾，原非独出于肾也。观《上古天真论》曰∶肾者主水，受五脏六腑之精而藏 \n之。此精之所源，其不止于肾也可知矣。王节斋止知在肾而不知在五脏。若谓肾精未泄不必 \n补肾，则五脏之精，其有禀赋之亏，人事之伤者。岂因其未泄而总皆不必补耶？夫小儿之精 \n气未盛，后天之阴不足也；父母之多欲水亏，先天之阴不足也。阴虚不知治本，又何藉于人 \n为以调其元、赞其化乎？此本原之理，有当深察者如此。 \n再以小儿之病气论之。凡小儿之病最多者，惟惊风之属。而惊风之作，则必见反张戴眼 \n，斜视抽搐等证。此其为故，总由筋急而然。盖血不养筋，所以筋急。真阴亏损，所以血虚 \n，此非水衰之明验乎？夫肾主五液，而谓血不属肾，吾不信也。肝肾之病同一治，今筋病如 \n此，而欲舍肾水以滋肝木，吾亦不信也。且太阳、少阴相为表里，其经行于脊背而为目之上 \n网，今以反折戴眼之证偏多见于小儿，而谓非水脏阴虚之病，吾更不信也。矧以阳邪亢极， \n阴竭则危，脏气受伤，肾穷则死，此天根生息之基，尤于小儿为最切。然则小儿之病，其所 \n关于肾气者非眇，而顾可谓小儿无补肾法耶？决不信！决不信！ \n\n\n\n<目录>卷之三道集\\传忠录（下）\n\n<篇名>命门余义（二十六，共六条）\n\n属性：命门之义，《内经》本无，惟越人云∶肾有两者，非皆肾也。左者为肾，右者为命门。 \n命门者，诸神精之所舍，原气之所系，男子以藏精，女子以系胞也。余以其义有未尽，且有 \n可疑，故着有《三焦包络命门辨》，附梓《类经》之末，似已尽其概矣。然而犹有未尽者， \n恐不足以醒悟后人。兹因再悉其蕴，条列于下。 \n一、命门为精血之海，脾胃为水谷之海，均为五脏六腑之本。然命门为元气之根，为水 \n火之宅。五脏之阴气，非此不能滋。五脏之阳气，非此不能发。而脾胃以中州之土，非火不 \n能生，然必春气始于下，则三阳从地起，而后万物得以化生。岂非命门之阳气在下，正为脾 \n胃之母乎？吾故曰∶脾胃为灌注之本，得后天之气也；命门为化生之源，得先天之气也，此 \n其中固有本末之先后。观东垣曰∶补肾不若补脾。许知可曰∶补脾不若补肾。此二子之说， \n亦各有所谓，固不待辨而可明矣。 \n一、命门有火候，即元阳之谓也，即生物之火也。然禀赋有强弱，则元阳有盛衰；阴阳 \n有胜负，则病治有微甚，此火候之所以宜辨也。兹姑以大纲言之，则一阳之元气，必自下而 \n升，而三焦之普KT ，乃各见其候。盖下焦之候如地土，化生之本也；中焦之候如灶釜， \n水谷之炉也；上焦之候如太虚，神明之宇也。下焦如地土者，地土有肥瘠而出产异，山川有 \n浓薄而藏蓄异，聚散操权，总由阳气。人于此也，得一分即有一分之用，失一分则有一分之 \n亏。而凡寿夭生育及勇怯精血病治之基，无不由此元阳之足与不足，以为消长盈缩之主，此 \n下焦火候之谓也。中焦如灶釜者，凡饮食之滋，本于水谷，食强则体壮，食少则身衰，正以 \n胃中阳气，其热如釜，使不其然，则何以朝食午即化，午食申即化，而釜化之速不过如此。 \n观灶釜之少一炬则迟化一顷，增一炬则速化一时，火力不到，则全然不化，即其证也。故脾 \n胃之化与不化，及饮食之能与不能，亦总由阳明之气有强与不强，而阴寒之邪有犯与不犯 \n耳。及其病也，则渐痞渐胀，或隔或呕，或十化其三五，或膨聚而不消，或吞酸嗳腐而食气 \n不变，或腹疼肚痛而终日不饥，或清浊不分，或完谷不化。盖化则无不营运，不化则无不留 \n滞。营运则为气为血，留滞则为积为痰。此其故，谓非胃气之不健乎？而何以不健，谓非火 \n候之无力乎？今见治痞治胀，及治吞酸嗳腐等症，无论是热非热，动辄呼为胃火，余烬其几 \n，尚能堪否？此中焦火候之谓也。上焦如太虚者，凡变化必着于神明，而神明必根于阳气。 \n盖此火生气，则无气不至，此火化神，则无神不灵。阳之在下则温暖，故曰∶相火以位，阳 \n之在上则昭明，故曰君火以明。是以阳长则阴消，而离照当空。故五官治而万类盛，阳衰则 \n阴胜，而阳为阴抑，故聪明夺而神气减。而凡人之声色动定及智愚贤不肖之有不齐者，何非 \n阳德为之用，此上焦火候之谓也。此以三焦论火候，则各有所司，而何以皆归之命门？不知 \n水中之火，乃先天真一之气，藏于坎中，此气自下而上，与后天胃气相接而化，此实生生之 \n本也。是以花萼之荣在根柢，灶釜之用在柴薪。使真阳不发于渊源，则总属无根之火矣。火 \n而无根，即病气也，非元气也。故《易》以雷在地下而为复，可见火之标在上，而火之本则 \n在下。且火知就燥，性极畏寒。若使命门阴胜，则元阳畏避，而龙火无藏身之地，故致游 \n散不归，而为烦热格阳等病。凡善治此者，惟从其性，但使阳和之气直入坎中，据其窟宅 \n而招之诱之，则相求同气，而虚阳无不归原矣。故曰∶甘温除大热，正此之谓也。奈何昧者 \n不明此理，多以虚阳作实热，不思温养此火，而但知寒凉可以灭火，安望其尚留生意而不使 \n之速毙耶！此实医家第一活人大义，既从斯道，不可不先明斯理。倘三焦有客热邪火，皆凡 \n火耳，固不得不除。而除火何难，是本非正气火候之谓也。学人于此，当深明邪正二字，则 \n得治生之要矣。 \n一、命门有生气，即干元不息之几也。无生则息矣。盖阳主动，阴主静；阳主升，阴主 \n降。惟动惟升，所以阳得生气；惟静惟降，所以阴得死气。故干元之气，始于下而盛于上， \n升则向生也；坤元之气，始于上而盛于下，降则向死也。故阳生子中而前升后降，阴生午中 \n而前降后升。此阴阳之岐，相间不过如毛发，及其竟也，则谬以千里，而死生之柄，实惟此 \n毫厘升降之机耳。又如水暖则化气，化气则升无不生也；水寒则成冰，成冰则降无不死也。 \n故肾气独沉，则奉生者少，即此生气之理也。至若人之生气，则无所不在，亦无所不当察。 \n如脏腑有生气，颜色有生气，声音有生气，脉息有生气，七窍有生气，四肢有生气，二便有 \n生气。生气即神气，神自形生，何不可辨？衰者速培，犹恐不生，尚堪伐乎？而况其甚者乎。 \n故明师察此，必知孰者已亏，孰者犹可，孰者能益生气，孰者能损生气，孰者宜先攻病气以 \n保生气，孰者宜先固生气以御病气。务思病气虽如此，生气将如何；见在虽如此，日后将如 \n何。使不有原始要终之明，则皆寸光之流耳。 \n虽然，此徒以斯道为言也。而斯道之外，犹有说焉。夫生气者，少阳之气也。少阳之气 \n，有进无退之气也。此气何来，无非来自根本；此气何用，此中尤有玄真。盖人生所贵，惟 \n斯气耳。而出入之权在呼吸，斯气数之宝藏也。河车之济在辘轳，实转运之神机也。其进其 \n退，其得其失，总在生息之间，而彭殇之途于斯判矣。经曰∶得神者昌，失神者亡。即此生 \n气之谓也。予见遭剥于是者不可胜纪，故特明其义于此。 \n一、命门有门户，为一身巩固之关也。经曰∶仓廪不藏者，是门户不要也。水泉不止者 \n，是膀胱不藏也。得守者生，失守者死。又曰∶肾者，胃之关也。关门不利，故聚水而从其 \n类也。又曰∶北方黑色，入通于肾，开窍于二阴。是可见北门之主，总在乎肾，而肾之政令 \n，则总在乎命门。盖命门为北辰之枢，司阴阳柄，阴阳和则出入有常，阴阳病则启闭无序。 \n故有为癃闭不通者，以阴竭水枯，干涸之不行也；有为滑泄不禁者，以阳虚火败，收摄之无 \n主也。阴精既竭，非壮水则必不能行；阳气既虚，非益火则必不能固，此固其法也。然精无 \n气不行，气无水不化，此其中又有可分不可分之妙用，亦在乎慧者之神悟，有非可以笔楮尽 \n者。 \n一、命门有阴虚，以邪火之偏胜也。邪火之偏胜，缘真水之不足也。故其为病，则或为 \n烦渴，或为骨蒸，或为咳血吐血，或为淋浊遗泄。此虽明是火证，而本非邪热实热之比。盖 \n实热之火其来暴，而必有感触之故；虚热之火其来徐，而必有积损之因。此虚火实火之大有 \n不同也。凡治火者，实热之火可以寒胜，可以水折，所谓热者寒之也；虚热之火不可以寒胜 \n，所谓劳者温之也。何也？盖虚火因其无水，只当补水以配火，则阴阳得平而病自可愈。若 \n欲去火以复水，则既亏之水未必可复，而并火去之，岂不阴阳两败乎。且苦寒之物，绝无升 \n腾之生气，而欲其补虚，无是理也。故予之治此，必以甘平之剂，专补真阴，此虽未必即愈 \n，自可无害，然后察其可乘，或暂一清解，或渐加温润，必使生气渐来，庶乎脾可健则热可 \n退，肺渐润则嗽渐宁，方是渐复之佳兆，多有得生者。若但知知、柏为补阴，则愈败其肾， \n而致泄泻食减，必速其殆矣。 \n\n\n\n<目录>卷之三道集\\传忠录（下）\n\n<篇名>误谬论（二十七）\n\n属性：经曰∶揆度奇恒，道在于一，得一之精，以知死生，此即斯道中精一执中之训也。凡天 \n人之学，总无出此。矧医之为道，性命判于呼吸，祸福决自指端，此于人生关系，较之他事 \n为尤切也。以此重任，使不有此见此识，诚不可猜摸尝试以误生灵。矧立法垂训，尤难苟且 \n，倘一言失当，则遗祸无穷，一剂妄投，则害人不浅。此误谬之不容不正也。 \n宾自从斯道，常稽往古，所见轩岐之下，凡明良继出，何代无之。然必欲求其得中者， \n则舍《灵》《素》之外，似亦不多其人。盖窃见相传方论，每多失经意，背经旨，断章取义 \n。假借数语以饰一偏之诡说者，比比其然。此总属意见有不到，至理有未明，故各逞胸臆， \n用示已长。致令斯道失中，大违精一之义。此则医之于人，亦何赖焉。是岂知道本一源，理 \n无二致。自一源而万变，则万变仍归于一，自二致而错乱，则错乱遂其为两。故言外有理， \n理外亦有言。如理有在而言不能达者，此言外之理也；有可以言而不可以行者，此理外之言 \n也。然理外岂别有言乎？第以疑似之间，加之便佞，则真为伪夺，而道傍之筑，从来有矣。 \n如古之杨墨异端，今之传奇小说，谓皆非理外之言乎？言可假借，则是非乱而强辩出。由是 \n贤者固执，愚者亦固执。如择善固执，则精一之谓，君子时中，则执中之谓，此贤者之固执 \n也；其有言伪而辩，行僻而坚，必不知反，必不可移者。此愚者之固执也。执中者，见事之 \n舛，则不得不言，以利害所关，不容已也；邪僻者，见人之长，则反诋其短，以鄙陋不伸， \n不肯已也。千古来是非邪正，每为此害，矧以惟类知类，而当局者亦难其人耳。然此辈虽云 \n偏拗，犹知傍理，自非曳白者所能。其奈此中尚有全不知脉络，而止识皮毛者，亦且嚣嚣， \n偏能宜俗，是不过见热则用寒，见寒则用热，见外感则云发散，见胀满则云消导。若然者， \n谁不得而知之。设医止于是，则贱子庸夫皆堪师范，又何明哲之足贵乎？嗟！嗟！朱紫难辨， \n类多如此。 \n予因溯源稽古，即自金元以来为当世之所宗范者，无如河间、丹溪矣。而且各执偏见， \n左说盛行，遂致医道失中者，迄今四百余年矣。每一经目，殊深扼腕，使不速为救正，其流 \n弊将无穷也。兹姑撮其数条，以见倍理之谈，其有不可信者类如此，庶乎使人警悟，易辙无 \n难，倘得少补于将来，则避讳之罪，亦甘为后人而受之矣。 \n\n\n\n<目录>卷之三道集\\传忠录（下）\n\n<篇名>辨河间（二十八，共九条）\n\n属性：刘河间《原病式》所列病机，原出自《内经·至真要大论》。盖本论详言五运六气盛衰 \n胜复之理，而以病机一十九条总于篇末，且曰∶有者求之，无者求之，盛者泻之，虚者补之 \n，令其调达，而致和平。是可见所言病机，亦不过挈运气之大纲，而此中有无之求，虚实之 \n异，最当深察，总惟以和平为贵也。故《五常政大论》又详言五运三气之辨，则火之平气曰 \n升明，火之太过曰赫曦，火之不及曰伏明，此虚火实火之辨，则有如冰炭之异，而《内经》 \n不偏不倚之道，固已详明若是。奈河间不能通察本经全旨，遂单采十九条中一百七十六字， \n演为二百七十七字，不辨虚实，不察盛衰，悉以实火言病，着为《原病式》以讫于今。夫实 \n火为病故为可畏，而虚火之病犹为可畏。实火固宜寒凉，去之本不难也；虚火最忌寒凉，若 \n妄用之，无不致死。矧今人之虚火者多，实火者少，岂皆属有余之病，顾可概言为火乎？历 \n观唐宋以前，原未尝偏僻若此，继自《原病式》出，而丹溪得之定城，遂目为至宝。因续着 \n《局方发挥》，及阳常有余等论，即如东垣之明，亦因之而曰火与元气不两立。此后，如王 \n节斋、戴原礼辈，则祖述相传，遍及海内。凡今之医流，则无非刘朱之徒，动辄言火，莫可 \n解救，多致伐人生气，败人元阳，杀人于冥冥之中而莫之觉也。诚可悲矣！即间有一二特达 \n，明知其非而惜人阳气，则必有引河间之说而群吠之者矣。何从辨哉。矧病机为后学之指南 \n，既入其门，则如梦不醒，更可畏也。医道之坏，莫此为甚。此误谬之源不可不察，故直笔 \n于此，并再辨其略于下。 \n一、河间论吐酸曰∶酸者，肝木之味也，由火盛制金，不能平木，则肝木自甚，故为酸 \n也。而俗医主于温和脾胃，岂知经言人之伤于寒也，则为病热云云。 \n宾谓吐酸吞酸等证，总由停积不化而然。而停积不化，又总由脾胃不健而然。脾土既不 \n能化，非温脾健胃不可也。而尚可认为火盛耶？且妄引经文为证，其谬孰甚。本证别有详辨 \n，具载吞酸门，所当互阅。 \n一、河间论泻痢曰∶泻，白为寒，青红黄赤黑皆为热也。大法∶泻利小便。清白不涩为 \n寒，赤色者为热。又完谷不化而色不变，吐痢腥秽，澄澈清冷，小便清白不涩，身凉不渴， \n脉迟细而微者，寒证也；谷虽不化而色变非白，烦渴，小便赤黄而或涩者，热证也。凡谷消 \n化者，无问色及他证便为热也，寒泻而谷消化者，未之有也。或火主疾速，而热盛则传化失 \n常，谷不能化而飧泄者，亦有之矣。又曰痢为热，热甚于肠胃，怫热郁结而成，或言下痢白 \n为寒者，误也。若果为寒，则不能消谷，何由反化为脓也？如世之谷肉果菜，湿热甚则自然 \n腐烂化为浊水，故食于腹中。感人湿热邪气，则自然溃发，化为脓血也。 \n据河间此说，似是而非，误人不浅。夫泻白为寒，人皆知也，而青挟肝邪，脾虚者有之 \n，岂热证乎？红因损脏，阴络伤者有之，岂尽热乎？正黄色浅，食半化者有之，岂热证乎？黑 \n为水色，元阳衰者有之，岂热证乎？若此者皆谓之热，大不通矣。且凡泻痢者，水走大肠， \n小水多涩，水枯液涸，便尿多黄，此黄涩之证未必皆由热也。亡液者渴，亡阴者烦，此烦渴 \n之证未必尽为热也。至如完谷不化，澄澈清冷，诚大寒矣。然人偶有寒邪伤脏，或偶以生冷 \n犯脾，稍失温和即病泻痢者，此本受寒，然未必即大寒证也。且凡脾胃初伤，阳气犹在，何 \n能卒至清冷，遂成完谷不化？若必待清冷不化始云为寒，则阳已大败。又岂无渐寒而遽至若 \n是哉？夫渐寒者，即寒证也。此等证候，犯者极多。若作热治，必用寒凉。夫既以生冷伤于 \n前，复以寒凉败于后，乃至冰坚于霜而遭其厄者，皆此论之杀之也。再观其前条，则犹云泻 \n白为寒也；观其后条，则又云或言下痢白为寒者误也。然则凡治此者，舍清凉之外，则必无寒 \n证矣，谬甚！谬甚！又若寒则不能消谷，及谷化为脓之说，则尤为不妥。夫饮食有时，本当速 \n化，此自胃气之常，人皆赖之以为生也。若化觉稍迟，便是阳虚之病，又何待不能消谷而始 \n为寒乎？矧以所下脓垢，原非谷之所化。盖饮食入胃，凡其神化而归于营卫者，乃为膏血； \n其不能化而留于肠胃者，惟糟粕耳。此其为精为秽，本自殊途，是以糟粕不能化脓，从可知 \n矣。且垢亦非脓，而实肠脏之脂膏也。何以知之？近有偶病而服硝黄等药者，随泻而下，必 \n有如脓之垢，又或偶患泄泻者，于一二日间，即有此垢，岂热化之脓，其速有如此乎？又如 \n久痢不已，或经年累月不能痊可，而每日所下皆有脓垢者，岂热化之脓，可以久延如此乎？ \n此其非脓也，明矣。既知非脓，安得皆云为热？此盖以肠脏受伤，而致膏脂不固，随剥随下 \n，所以如此。若不为之安养脏气，而再用寒凉以治其热，则未有不藏气日败，而必至于死。 \n故今之治痢多危者，率受此害，最当察也。 \n一、河间曰∶假如下痢赤白，俗言寒热相兼。其说尤误。岂知水火阴阳寒热者，犹权衡 \n也，一高必一下，一盛必一衰。岂能寒热俱甚于肠胃而同为痢乎？如热生疮疡而出白脓者， \n岂可以白为寒欤？由其在皮肤之分，属肺金，故色白也。在血脉之分，属心火，故为血疖 \n也。在肌肉，属脾土，故作黄脓。在筋部，属肝木，故脓色带苍。深至骨，属肾水，故紫 \n黑血出也。各随五脏之部而见五色，是谓标也。本则一出于热，但分深浅而已。大法下迫窘 \n痛，后重里急，小便赤涩，皆属燥热，而下痢白者必多有之，然则为热明矣。 \n据此说，以五色分五脏，其理颇通。若谓本则一出于热，则大不通矣。且五脏之分五色 \n之证，则犹有精义，余因其说，并为悉之。夫泻出于脏，无不本于脾胃，脾胃之伤，以五气 \n皆能犯之。故凡其兼赤者，则脾心证也；兼青者，脾肝证也；兼白者，脾肺证也；兼黑者， \n脾肾证也；正黄者，本脏证也。若以脾兼心，火乘土也，其土多热，言火可也。以脾兼肝， \n土受克也，其土多败，非火也。以脾兼肾，水反克也，其土多寒，非火也。以脾兼肺，母气 \n泄也，其土多虚，非火也。本脏自病，脾受伤也，其土多湿，非火也。此兼证之盛衰，其逆 \n顺有如此。且凡脾肾之强者有实热，脾肾之弱者皆虚寒，此脏气之可辨也。矧火本热，而尚 \n有虚火实火之异；风本阳也，而亦有风热风寒之异；土本乎中气也，而亦有湿热寒湿之异。 \n至于金之寒，水之冷，同归西北之化，则其寒多热少，理所必致。岂可谓五脏之痢，本则一 \n出于热乎？因致寒证之衔冤者，此言之不得辞其责也。又赤白义详后丹溪条中。 \n一、河间曰∶夫治诸痢者，莫若于辛苦寒药治之，或微加辛热佐之则可。盖辛热能发散 \n开通郁结，苦能燥湿，寒能胜热，使气宣平而已。如钱氏香连丸之类是也。故治诸痢者，黄 \n连、黄柏为君，以至苦大寒，正主湿热之病。 \n据河间此说，最为治痢之害。又观其所着药性，则曰诸苦寒药多泄。惟黄连、黄柏，性 \n冷而燥。故自丹溪而后，相传至今。凡治痢者，举世悉用寒凉，皆此说之误也。毋论其他， \n姑以苦能燥湿一言辨之，则河间之见大左矣。夫五味之理，悉出《内经》，《内经》有曰∶ \n以苦燥之者，盖言苦之燥者也。河间不能详察，便谓是苦皆燥，而不知《内经》之言苦者， \n其性有二，其用有六。如曰∶火生苦。曰∶其类火，其味苦。曰∶少阳在泉为苦化，少阴在 \n泉为苦化。曰∶湿淫于内，治以苦热；燥淫于内，治以苦温。是皆言苦之阳也。曰∶酸苦涌 \n泄为阴。曰∶湿司于地，热反胜之，治以苦冷。曰∶湿化于天，热反胜之，治以苦寒。是皆 \n言苦之阴也。此其言性之二也。又曰以苦发之，以苦燥之，以苦温之，以苦坚之，以苦泄之 \n，以苦下之，此其言用之六也。盖苦之发者，麻黄、白芷、升麻、柴胡之属也。苦之燥者， \n苍术、白术、木香、补骨脂之属也。苦之温者，人参、附子、干姜、肉桂、吴茱萸、肉豆蔻 \n、秦椒之属也。苦之坚者，续断、地榆、五味、诃子之属也。苦之泄者，栀、柏、芩、连、 \n木通、胆草之属也。苦之下者，大黄、芒硝之属也。夫气化之道，惟阳则燥，惟阴则湿，此 \n不易之理也。岂以沉阴下降有如黄连、黄柏之属者，以至苦大寒之性而犹谓其能燥，有是理 \n乎？是但知苦燥之一言，而不察苦发、苦温、苦坚、苦泄、苦下之五者，抑又何也？凡医中之 \n讹，每有云其然而不知其所以然者，类如此。因致后人治痢，多不分寒热虚实，动以河间之 \n法，及其将危，犹云血色如此，何敢用温？腹痛如此，何敢用补？死而无悟，深可哀也。谁之 \n咎与？谁之咎与？ \n一、河间肿胀条云∶肿胀者，热胜则 肿。如六月湿热太甚而庶物隆盛，则水肿之 \n义明可见矣。 \n据此说，岂其然乎？夫肿胀之病，因热者固有之，而因寒者尤不少。盖因热者，以湿热 \n之壅，而阴道有不利也；因寒者，以寒湿之滞，而阳气有不化也。故经曰∶脏寒生满病。又 \n曰∶胃中寒则胀满。是皆轩岐之言也。由此观之，岂胀皆热病耶？且庶物隆盛，乃太和之阳 \n化，以此拟形质之强壮则可，以此拟 肿之病象，拟亦下矣。 \n一、河间曰∶战栗动摇，火之象也。栗，寒栗也。或言寒战为脾寒者，未明变化之道也 \n。此由心火热甚，亢极而战，反兼水化制之，故寒栗也。然寒栗者，由火甚似水，实非兼以 \n寒气也。 \n据此说，则凡见寒战皆为火证，而何以经曰阴胜则为寒。又曰阳虚畏外寒。又曰阳虚而 \n阴盛，外无气，故先寒栗也。又曰阳明虚则寒栗鼓颔也？凡此者皆属经言，而河间悉言为火 \n，其然否可知也。 \n一、河间曰∶惊者，心卒动而不宁也。所谓恐则喜惊者，恐则伤肾而水衰，心火自甚， \n故喜惊也。 \n据此所云∶恐则喜惊，恐则伤肾。然经曰∶肝气虚则恐，又曰∶恐则气下，惊则气乱。 \n夫肝气既虚，肾气既伤，而复见气下气乱，无非阳气受伤之病。阳气既伤，则何由心火遽甚 \n而惊则皆由火也。即曰恐则伤肾，不能滋养肝木，而肝虚则惊，又何不可？且肾水独衰者有 \n之，岂必水衰即火盛也？今常见惊恐之人，必阳痿遗溺，其虚可知。然因火入心而惊者，固 \n亦有之，未有因恐而惊者，皆可指为火证，则倍理甚矣。 \n一、河间曰∶虚妄者，以心火热甚，则肾水衰而志不精一，故神志失常，如见鬼神。或 \n以鬼神为阴，而见之则为阴极脱阳而无阳气者，此妄意之言也。 \n据此一说，则凡以神魂失守而妄见妄言者，俱是火证，亦不然也。夫邪火盛而阳狂见鬼 \n者，固然有之。又岂无阳气太虚而阴邪为鬼者乎？《难经》曰∶脱阴者，目盲。脱阳者，见 \n鬼。华元化曰∶得其阳者生，得其阴者死。岂皆妄意之言乎？何自信之如此也。 \n\n\n\n<目录>卷之三道集\\传忠录（下）\n\n<篇名>辨丹溪（二十九，共九条）\n\n属性：尝见朱丹溪阳常有余、阴常不足论，谓人生之气常有余，血常不足，而专以抑火为言。 \n且妄引《内经》阳道实，阴道虚，及至阴虚，天气绝，至阳盛，地气不足等文，强以为证。 \n此诚大倍经旨，大伐生机之谬谈也。何也？盖人得天地之气以有生，而有生之气，即阳气也 \n，无阳则无生矣。故凡自生而长，自长而壮，无非阳气为之主，而精血皆其化生也。是以阳 \n盛则精血盛，生气盛也；阳衰则精血衰，生气衰也。故经曰∶中焦受气取汁，变化而赤，是 \n谓血。是岂非血生于气乎？丹溪但知精血皆属阴，故曰阴常不足，而不知所以生精血者先由 \n此阳气，倘精血之不足，又安能阳气之有余？由此虑之，何不曰难成易亏之阳气，而反曰难 \n成易亏之阴气，是何异但知有母而不知有父者乎？故其所立补阴等方，谓其能补阴也，然知 \n、柏止堪降火，安能补阴？若任用之，则戕伐生气而阴以愈亡，以此补阴，谬亦甚矣。及察 \n其引证经文，则何其谬诞。若经曰∶阳者，天气也，主外；阴者，地气也，主内，故阳道实 \n，阴道虚。此“太阴阳明论”言脾之与胃生病有异，以阳明主表，太阴主里。凡犯贼风虚邪 \n者，阳受之，阳受之则入六腑，而外邪在表，邪必有余，故曰阳道实也。食饮不节，起居不 \n时者，阴受之，阴受之则入五脏，而内伤脏气，脏必受亏，故曰阴道虚也。此本经以阳主外 \n阴主内，而言阳病多实、阴病多虚有如此，岂以天地和平之阴阳而谓其阳常有余、阴常不足 \n乎？勉强引证，此一谬也。又经曰∶至阴虚，天气绝；至阳盛，地气不足。此方盛衰论言阴 \n阳痞隔之为病。谓阴虚于下则不升，下不升则上亦不降，是至阴虚，天气绝也；阳亢于上则 \n不降，上不降则下亦不升，是至阳盛，地气不足也。此本以上下不交者为言，亦非阳常有余 \n、阴常不足之谓也。且下二句犹或似之，而上二句云至阴虚，天气绝，则何以为解？此更谬 \n也。以丹溪之通博，而胡为妄引若此，抑为偏执所囿而忘其矫强乎？余陋不自觉，而念切在 \n道，故不能为丹溪讳而摘正于此，犹俟高明之评教。 \n一、丹溪相火论曰∶五行各一其性，惟火有二∶曰君火，人火也；曰相火，天火也。火 \n内阴而外阳，主乎动者也。故凡动皆属火。天主生物，故恒于动，人有此生，亦恒于动，其 \n所以恒于动者，皆相火之所为也。故人自有知之后，五志之火为物所感，不能不动，为之动 \n者，即《内经》五火也。相火易起，五性厥阳之火相扇而妄动矣。火起于妄，变化莫测，无 \n时不有，煎熬真阴。阴虚则病，阴绝则死。 \n据丹溪此论，则无非阐扬火病而崇其补阴之说也。第于此而浅视之，则若或近理，故易 \n动人；于此而深味之，则意识皆幻，大是误人，余请精绎其义，用解后人之惑何如？盖自一 \n元初肇，两仪继之，则动静于斯乎见。而阳主动，阴主静也。自两仪奠位，而五行布之，则 \n气质各有所主，而火主热，水主寒也。此两仪动静，为五行之先天。先天者，性道也；五行 \n寒热，为两仪之后天。后天者，变体也。先后之理，有可混言者，有不可混言者。其可混者 \n，如火本属阳，即言火为动，若为不可也。其不可混者，以阳为元气之大主，火为病气之变 \n见，而动乃阳之性道，安得以性道为病变，而言凡动皆属火也。即自天人论之，则曰天行健 \n，岂天动即火乎？又曰君子以自强不息，岂人动即火乎？使天无此动则生机息，人无此动则性 \n命去，又何可以火言动乎？若谓之火，则火必宜去，而性亦可去乎？若谓凡动皆属火，则岂必 \n其不动而后可乎？夫以阳作火，词若相似，而理则大倍矣。故在丹溪则曰阴虚则病，阴绝则 \n死；余则曰阳虚则病，阳脱则死，此机微疑似中，有毫厘千里之异，临岐者不可不详察也。 \n或曰∶子言虽是，第未达丹溪之意耳。如曰五脏各有火，五志激之，其火随起，以致真阴受 \n伤，阴绝则死者。岂非因动生火乎？予曰∶此或因情欲之思动火者，止有一证，如欲念不遂 \n，或纵欲太过，致动相火而为劳为瘵者，诚有之也。此外而五志之动皆能生火，则不然也。 \n夫所谓五志者，喜怒思忧恐也。经曰∶喜伤心，怒伤肝，思伤脾，忧伤肺，恐伤肾。五脏既 \n受此伤，则五火何由而起？又曰∶喜则气散，怒则气逆，忧则气闭，思则气结，恐则气下。 \n此五者之性为物所感，不能不动，动则耗伤元气，元气既耗如此，则火又何由而起？故经曰 \n∶五脏者，主藏精者也。不可伤，伤则失守而阴虚，阴虚则无气，无气则死矣。是可见脏不 \n可伤，气亦不可伤，未闻伤即为火也。即云为火，必有火证，使无火证，而但以动字敷衍其 \n说，是何异捉影为形，而天下事又何不可马鹿其间乎。且常见五志所伤之人，伤极必生战栗 \n。是盖以元阳不固，神气失守而然。倘遇河间为之和，则又必谓战栗皆生于火矣。孰是孰非 \n，其几如此，能不为生民痛哉！ \n一、丹溪《局方发挥》曰∶相火之外，又有脏腑厥阳之火，五志之动，各有火起。相火 \n者，此经所谓一水不胜二火之火，出于天造。厥阳者，此经所谓一水不胜五火之火，出于人 \n欲。气之升也，随火炎上，升而不降，孰能御之？ \n原经文五火之说，乃解精微论中言厥病之目无所见也。谓其阳并于上，阴并于下，阴阳 \n不交，所以为厥。厥者，逆也。由其阳逆于上则火不降，阴逆于下则水不升，水既不升，火 \n又不降，而目以一阴之微精，不胜五脏之阳逆，此单言厥逆之为病也如此，岂言火有五而水 \n止一乎？又按二火之说，乃逆调论言∶人有身寒之甚而反不战栗者，名为骨痹。谓其人肾气 \n素胜，以水为事，则肾脂枯而髓不能满，故寒甚至骨也。又以肝为一阳，心为二阳，二藏皆 \n有伏火，则一水不胜二火，所以身虽寒而不冻栗，此单言骨痹之为病也如此。又岂阳常有余 \n之谓乎？若以五火、二火尽可引为火证，则如示从容论中有云二火不胜三水者，又将何以解 \n之，而何独不引为言耶？试以此问丹溪，其将何以答乎？ \n一、丹溪曰∶气有余便是火。又曰∶五脏各有火，五志激之，其火随起。若诸寒为病， \n必须身犯寒气，口得寒物，乃为病寒。非若诸火，病自内作。所以气之病寒者，十无一二。 \n予味丹溪此言，不能不掩卷叹息。岂必气之病寒者十无一二耶？夫气本属阳，阳实者固 \n能热，阳虚者独不能寒乎？故经曰∶气实者，热也。气虚者，寒也。又经曰∶血气者，喜温 \n而恶寒，寒则泣不能流，温则消而去之，则其义有可知矣。且今人之气实与气虚者，孰为多 \n寡？则寒热又可知矣。然而何以证之？如心气虚则神有不明，肺气虚则治节有不行，脾气虚则 \n食饮不能健，肝气虚则魂怯而不宁，肾气虚则阳道衰而精少志屈，胃气虚则仓廪匮而并及诸 \n经，三焦虚则上中下俱失其职，命门虚则精气神总属无根。凡此者，何非气虚之类？气虚即 \n阳虚，阳虚则五内不暖而无寒生寒，所以多阳衰羸败之病。若必待寒气寒食而始为寒证，则 \n将置此辈于何地？夫病之所贵于医者，贵其能识生气，是诚医家最大关系，而丹溪全不之察 \n。故无怪其曰∶气有余便是火。而余反之曰∶气不足便是寒。使其闻余之说，尚不知以为然 \n否。 \n一、丹溪《格致余论》曰∶六气之中，湿热为病，十居八九。 \n据此说，湿热为病十居八九，则无怪乎寒凉之药，亦宜八九矣，此亦大谬之言也。夫阴 \n阳之道，本若权衡，寒往暑来，无胜不复。若偏热如此，则气候乱而天道乖矣。故轩辕帝曰 \n∶其德化政令之动静损益皆何如？岐伯曰∶夫德化政令灾变，不能相加也。胜复盛衰，不能 \n相多也。往来大小，不能相过也。用之升降，不能相无也。各从其动而复之耳。此气交变大 \n论之文，岂亦其不足信乎？ \n一、丹溪夏月伏阴论曰∶若于夏月火令之时，妄投温热，宁免实实虚虚之患乎？或曰∶ \n巳月纯阳，于理或通。五月一阴，六月二阴，非阴冷而何？答曰∶此阴之初动于地下也。四 \n阳浮于地上，燔灼焚燎，流金烁石，何阴冷之有？ \n据此一说，则夏月止宜寒凉矣。而何以帝曰∶服寒而反热，服热而反寒，其故何也？岐 \n伯曰∶治其旺气，是以反也。然则丹溪止知治旺气。而旺气有不可治者，何以不知也？矧春 \n夏之温热，秋冬有寒凉，此四时之主气也；而风寒暑湿火燥，此六周之客气也。故春夏有阴 \n寒之令，秋冬有温热之时，所谓主气不足，客气胜也。所谓必先岁气，无伐天和，亦此谓也 \n。岂丹溪止知有主气，而客气之循环胜复，又何以不知也？然此犹以气令言也。若人之血气 \n阴阳，本自不同，病之表里寒热，岂皆如一？设以夏月得阴证而忌用温热，冬月得阳证而忌 \n用寒凉，则其人能生乎？是丹溪止知时热宜凉，而舍时从证。又何以不知也？观其所论，止言 \n夏月忌温热，不言冬月忌寒凉，何其畏火之见，主火之言，一至于此。 \n一、丹溪《局方发挥》曰∶经云暴注下迫，皆属于热。又曰∶暴注属于火。又曰∶下痢 \n清白属于寒。夫热为君火之气，火为相火之气，寒为寒水之气，属火热者二，属水寒者一， \n故泻痢一证。似乎属热者多，属寒者少。详玩《局方》专以热涩为用，若用于下痢清白而属 \n寒者，斯可矣。经所谓下迫者，即里急后重之谓也，其病属火。相火所为，其毒甚于热也， \n投以涩热，非杀之而何？ \n据此说，以二火一水言泻痢之由，殊未当也。夫经言暴注下迫皆属于热者，谓暴泻如注 \n之下迫，非肠 下痢之谓也。观《太阴阳明论》曰∶阴受之则入五脏，下为飧泄，久为 \n肠。然肠 言久，岂同暴注而皆为热乎？且《内经》所言泻痢之证，寒者极多。 \n今于泄泻门详列可考，何丹溪俱不引证，而独引二火之说，亦勉强矣。及遍考《内经》，则 \n止有暴注下迫皆属于热一句，并无暴注属于火之文，即或以属火之年有言暴注者，然木金土 \n水之年皆有此证，又何以独言火也？盖其意专在火，故借引经文以证其说，而不知经言二火 \n者，本言六气之理也，岂以泻痢一证为二火乎？观之经曰∶长夏善病洞泄寒中，何不曰洞泄 \n热中，其义可知，而丹溪何不察也。夫以泻痢为火者，本出河间，而丹溪宗之，故变为此说 \n。戴原礼又宗丹溪，故云∶痢虽有赤白二色，终无寒热之分，通作湿热治。自此说相传，遂 \n致诸家方论，无不皆言湿热，而不知复有寒湿矣，其害孰甚。至若《局方》一书，虽云多用 \n热涩，然于实热新邪，岂云皆用此法。观其所载太平丸、戊己丸、香连丸、薷苓汤之类，岂 \n非以寒治热者耶？又若真人养脏汤、大已寒丸、胡椒理中汤之类，皆有可用之法，其中随证 \n酌宜，顾在用之者何如耳？岂《局方》专以热涩为用，而可斥其非耶。且是书之行，乃宋神 \n宗诏天下高医各以效方奏进而成者。此其中或过于粉饰者，料不能无，而真效之方必亦不少 \n。第在丹溪之言火多者，谓热药能杀人，而余察其为寒多者，则但见寒药之杀人耳。明者其 \n深察之。 \n一、丹溪曰∶痢赤属血，自小肠来；白属气，自大肠来，皆湿热为本。初得一二日间， \n元气未虚，必推荡之，此通因通用之法。大承气汤、调胃承气汤。下后看其气病血病而用药 \n，气用参、术，血用四物。痢五日后不可下，脾胃气虚故也。壮实者亦可下。 \n据此说，以赤白言血气，而分属大肠小肠，其于五行之说则然。而于病情之真则凿矣。 \n盖小肠为心之腑，宜其主血，大肠为肺之腑，宜其主气。然水谷气化于小肠，岂小肠之非气 \n乎？或于粪前而见血，岂大肠之无血乎？观之经曰∶血者，神气也。此非赤化于气乎？又曰∶ \n白血出者死。此非白亦为血乎？盖白者赤者，无不关乎血气，但其来浅者白，而来深者则赤 \n也。故经曰∶阳络伤则血外溢，血外溢则衄血；阴络伤则血内溢，血内溢则后血。此自至理 \n，何其明显，而顾可以小肠大肠分血气哉！然此犹无碍，亦不必深为之辨也。至若初得一二 \n日间，元气未虚，必推荡之，为通因通用法，则此说不可概言矣。盖此证有不宜下者，有必 \n不可下者。岂以一二日间必可推荡耶？若病之可泻者，必其元气本强，积聚多实，则无论寒 \n邪热邪，但得一推，则邪从泻去，而气本无伤，故可泻也。使无此元气，无此胀实，则无可 \n言泻者矣。则强盛之人，随食随化，故饮食不易伤，泻痢不易犯，即有所犯，亦无不随病而 \n随愈也。其有易病者，必其易伤者也。易伤者，必其本弱者也。所以凡患泻痢而有久延难愈 \n者，必其弱者多，而强者少也。是以治宜推荡者，亦不过数十中之一二耳。且体弱之证，亦 \n有不同，有微弱者，有次弱者，有大弱者，此其形气脉息，病因证候，是实是虚，自可明辨 \n。凡见脾肾不足而致泻痢者，则始终皆不可下。若妄用之，则微者必甚，甚者必死，莫可解 \n救，此推荡之不可轻用也。诚见其致误者不少矣。即在丹溪亦曰∶余近年涉历，亦有大虚大 \n寒者，不可不知。此丹溪晚年之一隙耳。而亦知前言之过否。 \n一、丹溪痢疾门附录曰∶诸有积者，以肚热缠痛推之。诸有气者，以肚如蟹渤验之。究 \n其受病之源，决之对病之剂。大要以散风邪，行滞气，开胃脘为先。不可遽用肉豆蔻、诃子 \n、白术辈以补住寒邪。不可投米壳、龙骨辈以闭涩肠胃。邪得补而愈盛，故变证作，所以日 \n夕淹延而不已也。 \n据此散风邪，行滞气，开胃脘三法，亦不过言其大概，固未尽也。至若补住寒邪之说， \n则大有不通，而且最易惑人，为害不浅。夫既受寒邪，即当辨其虚实，然实者必有实证，本 \n不宜补，不宜补而补之，则随补随甚，即显见也。又何待乎变证？若因脏气受伤者，则无非 \n虚证，即宜温补。盖温可以逐寒邪，补可以健脾肾，脾肾既健，寒邪既去，则无不速愈。何 \n反有补住之理？又何有变证之说？且温补之法，原不在米壳、龙骨之属。又岂止豆蔻、白术而 \n已乎。若执补住之说而禁用之，则必致虚者日虚，而变证百出矣。余所见者，惟寒凉变证之 \n害，不可胜纪，或近则旬日，远则累月经年，终于殒命而后已。未闻有以温补变证而日夕淹 \n延不已者。兹余年出古稀，涉历不少。凡遇人言，率多不分虚实，无不曰补住寒邪，无不曰 \n邪得补而愈盛。正以信之者多，所以害之者甚。因致抱疾之辈，宁受寒凉而死，不愿温补而 \n生。究其所由，实由乎此。嗟，嗟，一言关系，有如是乎！余切悲之。今但反其说曰∶以寒 \n遇寒，则留住寒邪，邪得寒而愈甚，理所必然。遭此害者多矣，因特表其义，谨以告诸惑者 \n。 \n又总原刘、朱二家之说，无非偏执言火。故但见经文有火字，则必引以为证。凡如前列 \n诸条，果亦有一言合经意者否？彼二子者既曰读经，何以罔顾上下文，而单扯一句，便可着 \n书妄言，岂谓后世之人都无目耶？抑举世可欺耶？抑性体之有未明耶？谬已甚矣。吾不得为之 \n解也。自二子之说行，而轩岐之受诬亦久矣。何也？以后人之遭毒于亡阳者，必谓轩岐之诲 \n之也。使轩岐再起而见之，能无 裂而发竖乎。此时医受病之源，实河间创之，而丹溪成之 \n。予为此论，盖一则为后人保生命，一则为轩岐正道统，一则为后生浅学，知识未广。凡初 \n见彼书者，无不信为经训，多致终生受误，害可胜言！欲清其流，必澄其源，故单采二家之 \n略，辨正于此，而有余未尽，诚难悉也。 \n\n\n\n<目录>卷之三道集\\传忠录（下）\n\n<篇名>论时医（三十，共三十一条）\n\n属性：一、时医治病，但知察标，不知察本，且常以标本借口。曰∶急则治其标，缓则治其本 \n。是岂知《内经》必求其本之意。故但见其所急在病，而全不知所急在命，此其孰可缓也？ \n孰当急也？孰为今日之当急，孰为明日之更当急也？缓急既不知，则每致彼此误认，尚何标本 \n为言乎！ \n一、中风证悉由内伤，本无外感。既无外感，必不可散。若过用治风等药，则轻者必重 \n，重者必速死。 \n一、伤寒关系全在虚实二字。实者易治，虚者难治。以其元气本虚，故邪不易解。若治 \n挟虚伤寒，不知托散，而但知攻邪，愈攻则愈虚，愈虚则无有不死。若甚虚者，即微补且无 \n益，而但以治标为主者必死。 \n一、伤寒阳经与阳证不同。阳经者，邪在表也；阳证者，热在里也。若内无实热脉候， \n而以阳经作阳证，妄用寒凉治其火，因致外内合邪而不可解者必死。 \n一、痢疾之作，惟脾肾薄弱之人极易犯之。夫因热贪凉，致伤脏气，此人事之病，非天 \n时之病也。今之治痢者，止知治天时之热，不知治人事之寒何也？矧痢证多在秋深。斯时 \n也，炎暑既消，固不可执言热毒。秋凉日至，又何堪妄用寒凉？凡若此者，既不知人事，又 \n不知天时，失之远矣。害莫甚矣。当因予言而熟思之矣。 \n一、小儿血气未充，亦如苗萼之柔嫩。一或伤残，无不凋谢。故平时最宜培植，不可妄 \n行消导。其或果有食滞胀痛，则宜暂消。果有风寒发热，则宜暂散。果有实热痰火，则宜暂 \n清。此不得不治其标也。舍此之外，如无暴急标病，而时见青黄羸瘦，或腹膨微热，溏泄困 \n倦等证，则悉由脾肾不足，血气薄弱而然。而时医见此，无非曰食积痰火，而但知消导，尤 \n尚清凉，日消日剥，则元气日损，再逢他疾，则无能支矣。此幼科时俗之大病，有不可不察 \n者也。 \n一、小儿痘疹发热，此其正候。盖不热则毒不能透。凡其蒸热之力，即元气之力，故自 \n起至化，自收至靥，无不赖此热力为之主，是诚痘疹之用神，必不可少，亦不必疑者也。惟 \n是热甚而毒甚者，则不得不清火以解其毒。然必有内热真火脉证，方可治以清凉，此不过数 \n十中之一二耳。如无内热，而但有外热，此自痘家正候，必不可攻热以拔元气之力，以伤脾 \n肾之源。奈近代痘科全不知此，但见发热，则无论虚实，开口止知解毒，动手只知寒凉，多 \n致伤脾而饮食日减，及靥时泄泻而毙者，皆其类也。此误最多，不可不察。 \n一、痘疮不起，如毒盛而不可起者，此自不救之证，不必治也。若别无危证而痘不起者 \n，总由元气无力，但培气血，则无有不起。近见痘科凡逢此证，则多用毒药，如桑蚕、穿山 \n甲之类，逼而出之，见者以为奇效，而不知起发非由根本，元气为毒所残，发泄太过，内必 \n匮竭，以此误人，所当切省。 \n一、妇人经脉滞逆，或过期不至，总由冲任不足而然。若不培养血气，而止知通经逐瘀 \n，则血以日涸，而崩漏血枯等证，无所不至矣。 \n一、凡情欲致伤，多为吐血失血，及或时发热，此真阴受伤之病。若但知治火，而不知 \n治阴，则阴日消亡，而劳瘵反成矣。 \n一、痰证必有所因，是痰本不能生病，而皆因病生痰也。若止知治痰，而不知所以生痰 \n，则痰必愈甚，未有可消而去者也。 \n一、膨满总由脾胃，脾胃虽虚，未必即胀。若但知消导，则中气愈虚，而胀必日甚矣。 \n一、气滞隔塞，总属脾虚不运，故为留滞。若不养脾而但知破气，则气道日亏，而渐成噎 \n隔等病。 \n一、小水短赤，惟劳倦气虚及阴虚之人多有之。若以此类通作火治，而专用寒凉，则变 \n病有不可测矣。 \n一、脉虚证热，本非真火。若作热治，而肆用寒凉，则轻者必重，重者必死。 \n一、病本大虚而治以微补，药不及病，本无济益。若疑为误而改用消伐则死。 \n一、病有缓急，效有迟速。若以迟病而求速效，则未免易医，易医多则高明本少，庸浅 \n极多，少不胜多，事必败矣。"}, {"n": 3, "text": "卷三\n\n一、任医须择贤者，而于危急之际，尤不可苟。若彼宵小之辈，惟妄 已长，好翻人按 \n，不幸遇之，多致淆惑是非，生命所系不浅。 \n一、经曰∶人迎盛坚者伤于寒，气口坚盛者伤于食。此本以阳明太阴之脉分言表里，而 \n王叔和以左为人迎，右为气口，因致后人每以左脉辨外感，右脉辨内伤。岂左无内伤，而右 \n无外感乎？谬甚！谬甚！ \n一、经曰∶病生于内者，先治其阴，后治其阳，反者益甚。病生于阳者，先治其外，后 \n治其内，反者益甚。 \n一、病患善服药者，闻其气，尝其味，便可觉宜否之优劣，固无待入腹而始知也。独悯 \n乎无识无知者，但知见药服药，而不知药之为药；但知见医求医，而不知医之为医，亦可悲矣。 \n\n\n\n<目录>卷之三道集\\传忠录（下）\n\n<篇名>京师水火说（三十一）\n\n属性：水火者，养生之本。日用之物，用水火而不察其利病，则适足以伤人，而实人所不知也 \n。故水品分差等，火性言优劣，固非欺我者也。姑无论其他，试以燕京之水火言之。凡水之 \n佳者，得阳之气，流清而源远，气香而味甘；水之劣者，得阴之性，源近而流浊，气秽而味 \n苦。而京师之水则有两种，曰甜水，曰苦水是也。即其甜者亦未甚佳，而其苦者乃为最劣。 \n盖水之味苦者，以其多碱。试取墙间白霜，火之皆燃，水中所有，即此物也。即朴硝也。其 \n性则五金八石皆能消化，因而命名曰硝。故善于推荡积滞，攻破 坚。凡脾弱之人服之 \n多泄，是所验也。使无其实，而朝夕用之以养生。吾恐人之脏腑，有更非五金八石之可比， \n其为潜消暗耗，剥人元气于罔觉之中，大有可畏者。或曰∶未必然，果若所云，则吾未见斯 \n地之乏人，亦未见斯地之皆病，何子之过虑也？予曰∶噫，此正所谓罔觉也。请以寿夭而纪 \n其验，则水土清甘之处，人必多寿，而黄发儿齿者，比比皆然；水土苦劣之乡，暗折天年， \n而耄耋期颐者，目不多见。虽曰寿乡未必全寿，夭乡未必皆夭。若以强者而滋养得宜，岂不 \n更寿？弱者而饮食不佳，岂不更夭？远者不能概知，第以京师较之吾乡，则其寿夭之殊，不无 \n大有径庭矣。职此之由，谓非水土之使然与？ \n又若火之良否，原自不同，故先王取用，四时有异。惟是京师用煤，必不可易。虽用煤 \n之处颇多，而惟京师之煤，气性尤烈，故每熏人至死，岁岁有之，而人不能避者无他，亦以 \n用之不得其法耳。夫京师地寒，房室用纸密糊，人睡火炕，煤多热于室内。惟其房之最小而 \n最密者，最善害人。其故何也？盖以水性流下，下而不泄，则自下满而上；火性炎上，上而 \n不泄，则自上满而下。故凡煤毒中人者，多在夜半之后，其气渐满，下及人鼻，则闭绝呼吸 \n，昧然长逝，良可慨悯。凡欲避其毒者，惟看房室最密之所，极为可虑。但于顶格开留一窍 \n，或于窗纸揭开数楞，则其气自透去，不能下满，乃可无虑矣。然总之窗隙不如顶核，为其 \n透气之速也。设有中其毒者，必气闭声挣，不能自醒，速当呼之，饮以凉水，立可解救。或 \n速令仆地，使其鼻吸地气，亦可解救。然待其急而救疗，恐有迟误而无济于事。孰若预有以 \n防之为愈也。此京师水火之害，举京师而言，则他处可以类推矣。凡宦游京国及客处异地者 \n，不可不知此二说，以为自珍之本。 \n\n\n\n<目录>卷之三道集\\传忠录（下）\n\n<篇名>医非小道记（三十二）\n\n属性：予出中年，尝游东藩之野，遇异人焉。偶相问曰∶子亦学医道耶？医道，难矣。子其慎 \n之。予曰∶医虽小道，而性命是关，敢不知慎，敬当闻命。异人怒而叱曰∶子非知医者也。 \n既称性命是关。医岂小道云哉？夫性命之道，本乎太极，散于万殊。有性命然后三教立，有 \n性命然后五伦生。故造化者，性命之炉冶也。道学人，性命之绳墨也。医药者，性命之赞育 \n也。然而其义深，其旨博，故不有出人之智，不足以造达微妙。不有执中之明，不足以辨正 \n毫厘。使能明医理之纲目，则治平之道如斯而已。能明医理之得失，则兴亡之机如斯而已。 \n能明医理之缓急，则战守之法如斯而已。能明医理之趋舍，则出处之义如斯而已。洞理气于 \n胸中，则变化可以指计，运阴阳于掌上，则隔垣可以目窥。修身心于至诚，实儒家之自治； \n洗业障于持戒，诚释道之自医。身心人己，理通于一，明于此者，必明于彼。善乎彼者，必 \n善于斯。故曰∶必有真人，而后有真知，必有真知，而后有真医。医之为道，岂易言哉。若 \n夫寻方逐迹，龊龊庸庸，椒、硫杀疥，葱、薤散风，谁曰非医也？而缁衣黄冠，总称释道； \n矫言伪行，何非儒流？是泰山之与丘垤，河海之与行潦，固不可以同日语矣。又若阴阳不识 \n，虚实误攻，心粗胆大，执拗偏庸，非徒无益而反害之之徒。殆又椒、硫、葱、薤之不若。 \n小道之称，且不可当。又乌足与言医道哉！医道，难矣。医道，大矣。是诚神圣之首传，民 \n命之先务矣。吾子其毋以草木相渺，必期进于精神相贯之区，玄冥相通之际，照终始之后先 \n，会结果之根蒂，斯于斯道也。其庶乎为有得矣。子其勉之！予闻是教，惭悚应诺，退而皇 \n皇者数月，恐失其训，因笔记焉。 \n\n\n\n<目录>卷之三道集\\传忠录（下）\n\n<篇名>病家两要说\n\n属性：（三十三，一、忌浮言，二、知真医） \n医不贵能愈病，而贵于能愈难病；病不贵于能延医，而贵于能延真医。夫天下事，我能 \n之，人亦能之，非难事也；天下病，我能愈之，人亦能愈之，非难病也。惟其事之难也，斯 \n非常人之可知；病之难也，斯非常医所能疗。故必有非常之人，而后可为非常之事，必有非 \n常之医，而后可疗非常之病。第以医之高下，殊有相悬。譬之升高者，上一层有一层之见， \n而下一层者不得而知之；行远者，进一步有一步之闻，而近一步者不得而知之。是以错节盘 \n根，必求利器；阳春白雪，和者为谁？夫如是，是医之于医尚不能知，而矧夫非医者。昧真 \n中之有假，执似是而实非；鼓事外之口吻，发言非难，挠反掌之安危，惑乱最易。使其言而 \n是，则智者所见略同。精切者已算无遗策，固无待其言矣。言而非，则大隳任事之心，见几 \n者宁袖手自珍，其为害岂小哉！斯时也，使主者不有定见，能无不被其惑而致误事者，鲜矣 \n。此浮言之当忌也。又若病家之要，虽在择医，然而择医非难也，而难于任医；任医，非 \n难也。而难于临事不惑，确有主持。而不致朱紫混淆者之为更难也。倘不知此而偏听浮议， \n广簇医，则骐骥不多得，何非冀北驽群？帷幄有神筹，几见圯桥杰竖？危急之际，奚堪庸妄 \n之误投；疑似之秋，岂可纷纭之错乱，一着之谬，此生付之矣。以故议多者无成，医多者必 \n败。多何以败之？君子不多也。欲辨此多，诚非易也，然而尤有不易者，则正在知医一节耳 \n。夫任医如任将，皆安危之所关。察之之方，岂无其道？第欲以慎重与否观其仁，而怯懦者 \n实似之；颖悟与否观其智，而狡诈者实似之；果敢与否观其勇，而猛浪者实似之；浅深与否 \n观其博，而强辩者实似之。执拗者，若有定见。夸大者，若有奇谋。熟读几篇，便见滔滔不 \n竭；道闻数语，谓非凿凿有凭。不反者，临涯已晚；自是者，到老无能。执两端者，冀自然 \n之天功；废四诊者，犹瞑行之瞎马。得稳当之名者，有耽阁之误；昧经权之妙者，无格致之 \n明。有曰专门，决非通达。不明理性，何物圣神？又若以己之心，度人之心者，诚接物之要 \n道，其于医也，则不可谓人己气血之难符；三人有疑，从其二同者，为决断之妙方。其于医 \n也，亦不可谓愚智寡多之非类。凡此之法，何非征医之道，而征医之难，于斯益见。然必有 \n小大方圆全其才，仁圣工巧全其用，能会精神于相与之际，烛幽隐于玄冥之间者，斯足谓之 \n真医。而可以当性命之任矣。惟是皮质之难窥，心口之难辨，守中者无言，怀玉者不 ，此 \n知医之所以为难也。故非熟察于平时，不足以识其蕴蓄；不倾信于临事，不足以尽其所长。 \n使必待渴而穿井，斗而铸兵，则仓卒之间，何所趋赖？一旦有急，不得已而付之庸劣之手， \n最非计之得者。子之所慎斋战疾。凡吾侪同有性命之虑者，其毋忽于是焉。噫，惟是伯牙常 \n有也，而钟期不常有；夷吾常有也，而鲍叔不常有。此所以相知之难，自古苦之，诚不足为 \n今日怪。倘亦有因余言而留意于未然者，又孰非不治已病治未病，不治已乱治未乱之明哲乎 \n。惟好生者略察之。 \n\n\n\n<目录>卷之三道集\\传忠录（下）\n\n<篇名>保天吟（三十四）\n\n属性：一气先天名太极，太极生生是为易。易中造化分阴阳，分出阴阳运不息。刚柔相荡立干 \n坤，剥复 群生植，禀得先天成后天，气血原来是真的。阴阳气固可长生，龙虎 \n飞腾失家宅。造化钟人果几多？谁道些须亦当惜。顾惜天真有两端，人己机关宜辨格，自治 \n但存毋勉强，庄生最乐无心得。为人须慎保天和，岐伯深明无伐克，伐克从来性命仇，勉强 \n分明元气贼。肤切根源未了然，养气修真亦何益？漫将斯语等浮云，道在路旁人不识，余今 \n着此保天吟，愿效痴东奉佳客。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：（一部位解见后章） \n脉要精微论曰∶尺内两傍，则季胁也，尺外以候肾，尺里以候腹。中附上，左外以候肝，内以 \n候膈；右外以候胃，内以候脾。上附上，右外以候肺，内以候胸中，左外以候心，内以候膻中。前 \n以候前，后以候后。上竟上者，胸喉中事也；下竟下者，少腹腰股膝胫中事也。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：五十营篇曰∶天周二十八宿，人经二十八脉，周身十六丈二尺，以应二十八宿。漏水下百刻以 \n分昼夜。故人一呼，脉再动，气行三寸，一吸，脉亦再动，气行三寸，呼吸定息，气行六寸，十息 \n，气行六尺；二百七十息，气行十六丈二尺，一周于身；五百四十息，气行再周于身，二千七百息， \n气行十周于身；一万三千五百息，气行五十周于身，水下百刻，日行二十八宿，漏水皆尽，脉终矣 \n。故五十营备，得尽天地之寿，凡行八百一十丈也。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：三部九候论帝曰∶愿闻天地之至数，合于人形血气，通决死生，为之奈何？岐伯曰∶天地之至 \n数，始于一，终于九焉。一者天，二者地，三者人，因而三之，三三为九，以应九野。故人有三部， \n部有三候，以决死生，以处百病，以调虚实，而除邪疾。帝曰∶何谓二部？曰∶有下部，有中部，有 \n上部。部各有三候，三候者，有天，有地，有人也。上部天，两额之动脉；上部地，两颊之动脉； \n上部人，耳前之动脉。中部天，手太阴也；中部地，手阳明也；中部人，手少阴也。下部天，足厥 \n阴也；下部地，足少阴也；下部人，足太阴也。故下部之候，天以候肝，地以候肾，人以候脾胃之 \n气。中部之候，天以候肺，地以候胸中之气，人以候心。上部之候，天以候头角之气，地以候口齿之 \n气，人以候耳目之气。帝曰∶以候奈何？岐伯曰∶必先度其形之肥瘦，以调其气之虚实，实则泻之， \n虚则补之。 \n按∶寸口脉亦有三部九候。三部者，寸关尺也；九候者，三部中各有浮中沉也。察三部可知病 \n之高下，如寸为阳，为上部，主头项以至心胸之分也；关为阴阳之中，为中部，主脐腹 胁之分也； \n尺为阴，为下部，主腰足胫股之分也。三部中各有三候，三而三之，是为九候。如浮主皮肤，候表 \n及府；中主肌肉，以候胃气；沉主筋骨，候里及脏。此皆诊家之枢要，当与本篇互相求察也。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：三部九候论帝曰∶何以知病之所在？岐伯曰∶察九候独小者病，独大者病，独疾者病，独迟者 \n病，独热者病，独寒者病，独陷下者病。 \n详此独字，即医中精一之义，诊家纲领，莫切于此。今见诸家言脉，悉以六部浮沉，凿分虚实， \n顾不知病 \n本何在，既无独见，焉得确真？故宝命全角论曰∶众脉不见，众凶弗闻，外内相得，无以形先。是 \n诚察病之秘旨，必知此义，方可言诊。外有独论在后中卷，当参阅之。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：平人气象论曰∶太阳脉至，洪大以长。少阳脉至，乍疏乍数、乍短乍长。阳明脉至，浮大而短。 \n至真要大论曰∶厥阴之至，其脉钩。少阴之至，其脉钧。太阴之至，其脉沉。少阳之至，大而 \n浮。阳明之至，短而涩。太阳之至，大而长。 \n按此二篇之论，盖前言阴阳之盛衰，后分六气之专主，辞若稍异，义实相符。详具《类经·脉 \n色类第十四》篇，所当兼阅。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：玉机真藏论岐伯曰∶春脉如弦。春脉者，肝也，东方木也，万物之所以始生也，故其气来，软 \n弱轻虚而滑，端直以长，故曰弦，反此者病。帝曰∶何如而反？岐伯曰∶其气来实而强，此谓太过， \n病在外；其气来不实而微，此谓不及，病在中。夏脉如钩。夏脉者，心也，南方火也，万物之所以 \n盛长也，故其气来盛去衰，故曰钩，反此者病。何如而反？曰∶其气来盛去亦盛，此谓太过，病在 \n外；其气来不盛，去反盛，此谓不及，病在中。秋脉如浮。秋脉者，肺也，西方金也，万物之所以 \n收成也，故其气来，轻虚以浮，来急去散，故曰浮，反此者病。何如而反？曰∶其气来毛而中央坚， \n两傍虚，此谓太过，病在外；其气来毛而微，此谓不及，病在中。冬脉如营。冬脉者，肾也，北方 \n水也，万物之所以合藏也，故其气来沉以搏，故曰营，反此者病。何如而反？曰∶其气来如弹石者， \n此谓太过，病在外；其去如数者，此谓不及，病在中。帝曰∶四时之序，脾脉独何主？岐伯曰∶ \n脾脉者土也，孤藏以灌四傍者也。帝曰∶脾之善恶可得见乎？曰∶善者不可得见，恶者可见。其来 \n如水之流者，此谓太过，病在外；如鸟之喙者，此谓不及，病在中。 \n按∶本篇中外二字，乃指邪正为言也。盖邪气来于外，元气见于中，邪气之来皆有余，故太过， \n则病在外；元气之伤惟不足，故不及，则病在中也。又凡脾家有病，必有形见，故恶 \n者可见，若其无病，则阴行灌濡，五脏攸赖，而莫知其然，故善者不可得见，是即所谓胃气也。 \n玉机真脏论曰∶所谓逆四时者，春得肺脉，夏得肾脉，秋得心脉，冬得脾脉，甚至皆悬绝沉涩者，命 \n曰逆四时。未有藏形，于春夏而脉沉涩，秋冬而脉浮大，名曰逆四时也。 \n宣明五气篇曰∶春得秋脉，夏得冬脉，长夏得春脉，秋得夏脉，冬得长夏脉，是谓五邪，皆同命，死不治。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：玉机真藏论曰∶脉弱以滑，是有胃气，命曰易治。终始篇曰∶邪气来也紧而疾，谷气来也徐而和。 \n平人气象论曰∶平人之常气禀于胃，胃者，平人之常气也。人无胃气曰逆，逆者死。春胃微弦曰平， \n弦多胃少曰肝病，但弦无胃曰死；胃而有石曰冬病，毛甚曰今病，脏真散于肝，肝藏筋膜之气也。夏胃微钩曰平， \n钩多胃少曰心病，但钩无胃曰死；胃而有毛曰秋病，石甚曰今病，脏真通于心，心脏血脉之气也。长夏胃微软弱曰 \n平，弱多胃少曰脾病，但代无胃曰死，软弱有石曰冬病，弱甚曰今病，脏真濡于脾，脾藏肌肉之气也。秋 \n胃微毛曰平，毛多胃少曰肺病，但毛无胃曰死；毛而有弦曰春病，弦甚曰今病，脏真高于肺，以行营卫阴阳也。冬胃微 \n石曰平，石多胃少曰肾病，但石无胃曰死；石而有钩曰夏病，钩甚曰今病，脏真下于肾，肾藏骨髓之气也。胃 \n之大络，名曰虚里，贯膈络肺，出于左乳下，其动应长，脉宗气也。盛喘数绝者，则病在中；结而横，有积矣； \n绝不至曰死。乳之下，其动应衣，宗气泄也。 \n详代脉之义，本以更代为言，如宣明五气篇曰∶脾脉代者，谓胃气随时而更，此四时之代也。根结篇曰∶五十动 \n而不一代者，谓五脏受气之盛衰，此至数之代也。本篇曰∶但代无胃曰死者，谓代无真脏不死也。由此 \n观之，则凡见忽大忽小、乍迟乍数、倏而更变不常者，均谓之代。自王叔和云∶代脉来数中止，不 \n能自还，脉代者死。自后以此相传，遂失代之真义。 \n平人气象论曰∶人以水谷为本，故人绝水谷则死，脉无胃气亦死。所谓无胃气者，但得真脏脉， \n不得胃气也。所谓脉不得胃气者，肝不弦，肾不石也。 \n凡肝脉但弦，肾脉但石，名为真脏者，以其无胃气也。若肝当弦而不弦，肾当石而不石，总由 \n谷气不至，亦以其无胃气也。此举肝肾而言，则五脏皆然。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：邪气脏腑病形篇曰∶诸急者多寒，缓者多热，大者多气少血，小者气血皆少，滑者阳气盛，微 \n有热，涩者少血少气，微有寒。诸小者，阴阳形气俱不足，勿取以针，而调以甘药也。 \n按∶本篇正文曰∶涩者多血少气，微有寒。多血二字，乃传写之误也。观本篇下文曰∶刺涩者， \n无令其血出。其为少血可知。仲景曰∶涩者，营气不足，是亦少血之谓。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：脉要精微论曰∶推而外之，内而不外，有心腹积也。推而内之，外而不内，身有热也。推而上 \n之，上而不下，腰足清也。推而下之，下而不上，头项痛也。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：邪气脏腑病形篇曰∶见其色，知其病，命曰明；按其脉，知其病，命曰神；问其病，知其处， \n命曰工。夫 \n色脉与尺之相应也，如桴鼓影响之不得相失也，此亦本末根叶之出候也，根死则叶枯矣。故知一则 \n为工，知二则为神，知三则神且明矣。色青者，其脉弦也、赤者，其脉钩也；黄者，其脉代也；白 \n者，其脉毛；黑者，其脉石。见其色而不得其脉，反得其相胜之脉，则死矣。得其相生之脉，则病 \n已矣。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：五色篇雷公曰∶病之益甚，与其方衰如何？黄帝曰∶外内皆在焉。切其脉口，滑小紧以沉者， \n病益甚，在中；人迎气大紧以浮者，其病益甚，在外。其脉口浮滑者，病日进；人迎沉而滑者，病 \n日损。其脉口滑以沉者，病日进，在内；其人迎脉滑盛以浮者，其病日进，在外。人迎盛坚者，伤 \n于寒；气口盛坚者，伤于食。 \n详人迎本足阳明之经脉，在结喉两傍；气口乃手太阴之经脉，在两手寸口。人迎为腑脉，所以 \n候表；气口为脏脉，所以候里。故曰∶气口独为五脏主，此《内经》之旨也，所以后世但诊气口， \n不诊人迎。盖以脉气流经，经气归于肺，而肺朝百脉，故寸口为脉之大会，可决死生，而凡在表在 \n里之病，但于寸口诸部皆可察也。自王叔和误以左手为人迎，右手为气口，且云左以候表，右以候 \n里，岂左无里而右无表乎？讹传至今，其误甚矣。详义见后十六卷劳倦内伤门，及《类经·脏象类 \n第十一》篇。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：至真要大论帝曰∶脉从而病反者，其诊何如？岐伯曰∶脉至而从，按之不鼓，诸阳皆然。帝曰∶ \n诸阴之反，其脉何如？曰∶脉至而从，按之鼓甚而盛也。 \n脉至而从者，如阳证见阳脉，阴证见阴脉，是皆谓之从也。若阳证虽见阳脉，但按之不鼓，而 \n指下无力，则脉虽浮大，便非真阳之候，不可误认为阳证，凡诸脉之似阳非阳者皆然也。或阴证虽 \n见阴脉，但按之鼓甚而盛者，亦不得认为阴证。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：脉要精微论曰∶心脉搏坚而长，当病舌卷不能言；其软而散者，当消环自已。肺脉搏坚而长， \n色不青，当病坠若搏，因血在胁下，令人喘逆；其软而散，色泽者，当病溢饮。溢饮者，渴暴多饮， \n而易入肌皮肠胃之外也。胃脉搏坚而长，其色赤，当病折髀；其软而散者，当病食痹。脾脉搏坚而 \n长，其色黄，当病少气；其软而散，色不泽者，当病足 肿，若水状也。肾脉搏坚而长，其色黄而 \n赤者，当病折腰；其软而散者，当病少血，至令不复也。帝曰∶诊得心脉而急，此为何病？岐伯曰∶ \n病名心疝，心为牡脏，小肠为之使，故少腹当有形也。帝曰∶诊得胃脉何如？曰∶胃脉实则胀，虚 \n则泄。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：平人气象论曰∶寸口之脉中手短者，曰头痛。寸口脉中手长者，曰足胫痛。寸口脉中手促上击 \n者，曰肩背痛。寸口脉沉而坚者，曰病在中。寸口脉浮而盛者，曰病在外。寸口脉沉而弱，曰寒热 \n及疝瘕、少腹痛。寸口脉沉而横，曰胁下有积，腹中有横积痛。寸口脉沉而喘，曰寒热。脉盛滑坚 \n者，病在外。脉小实而坚者，病在内。脉小弱以涩，谓之久病。脉滑浮而疾者，谓之新病。脉急者 \n，曰疝瘕少腹痛。脉滑曰风。脉涩曰痹。缓而滑曰热中。盛而紧曰胀。臂多青脉曰脱血。尺脉缓涩， \n谓之解 。安卧脉盛，谓之脱血。尺涩脉滑，谓之多汗。尺寒脉细，谓之后泄。脉尺粗常热者，谓 \n之热中。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：脉要精微论曰∶夫脉者，血之府也。长则气治，短则气病，数则烦心，大则病进，上盛则气高， \n下盛则气 \n胀，代则气衰，细则气少，涩则心痛，浑浑革至如涌泉，病进而色弊，绵绵其去如弦绝者死。粗大 \n者，阴不足，阳有余，为热中也。来疾去徐，上实下虚，为厥巅疾；来徐去疾，上虚下实，为恶风也 \n。故中恶风者，阳受气也。有脉俱沉细数者，少阴厥也。沉细数散者，寒热也。浮而散者，为 仆 \n。诸浮不躁者，皆在阳，则为热；其有躁者在手。诸细而沉者，皆在阴，则为骨痛；其有静者在足 \n。数动一代者，病在阳之脉也，泄及便脓血。涩者，阳气有余也；滑者，阴气有余也。阳气有余， \n为身热无汗；阴气有余，为多汗身寒；阴阳有余，则无汗而寒。按之至骨，脉气少者，腰脊痛而身 \n有痹也。 \n阴阳别论曰∶阴阳虚，肠辟死。阳加于阴谓之汗。阴虚阳搏谓之崩。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：平人气象论曰∶风热而脉静，泄而脱血脉实，病在中脉虚，病在外脉涩坚者，皆难治，命曰反 \n四时也。 \n玉机真藏论曰∶凡治病，察其形气色泽，脉之盛衰，病之新故，乃治之，无后其时。形气相得 \n，谓之可治；色泽以浮，谓之易已；脉从四时，谓之可治；脉弱以滑，是有胃气，命曰易治；形气 \n相失，谓之难治。色夭不泽，谓之难已；脉实以坚，谓之益甚；脉逆四时，为不可治。必察四难而 \n明告之。病热脉静，泄而脉大，脱血而脉实，病在中脉实坚，病在外脉不实坚者，皆难治。 \n按∶此二篇之义，如前篇言病在中脉虚者为难治，后篇言病在中脉实坚者为难治；前言病在外 \n脉涩坚者为难治，后言病在外脉不实坚者为难治，前后若乎相反，何也？盖实邪在中者，脉不宜虚 \n；虚邪在中者，脉不宜实也。阳邪在表者，宜滑而软，不宜涩而坚；外邪方盛者，宜实而大，不宜 \n虚而小也。此中各有精义，或者以其为误，是不达耳。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：阴阳别论曰∶脉有阴阳，知阳者知阴，知阴者知阳。凡阳有五，五五二十五阳。所谓阴者，真 \n藏也，见则为败，败必死也。所谓阳者，胃脘之阳也。别于阳者，知病处也；别于阴者，知死生之 \n期。 \n玉机真藏论曰∶真肝脉至，中外坚，如循刀刃责责然，如按琴瑟弦，色青白不泽，毛折乃死。 \n真心脉至，坚而搏，如循薏苡子累累然，色赤黑不泽，毛折乃死。真肺脉至，大而虚，如以毛羽中 \n人肤，色白赤不泽，毛折乃死。真肾脉至，搏而绝，如指弹石辟辟然，色黑黄不泽，毛折乃死。真 \n脾脉至，弱而乍数乍疏，色黄青不泽，毛折乃死。诸真脏脉见者，皆死不治也。黄帝问曰∶见真脏 \n者死，何也？岐伯曰∶五脏者，皆禀气于胃，胃者，五脏之本也；藏气者，不能自致于手太阴，必 \n因于胃气，乃至于手太阴也。故邪气胜者，精气衰也；病甚者，胃气不能与之俱至于手太阴，故真 \n脏之气独见，独见者，病胜脏也，故曰死。 \n按∶此胃气即人之阳气，阳气衰则胃气弱，阳气败则胃气绝矣，此即死生之大本也。所谓凡阳 \n有五者，即五脏之阳也，凡五脏之气，必互相灌濡，故五脏之中，必各兼五气，此所谓二十五阳也 \n。是可见无往而非阳气，亦无往而非胃气，无胃气即真脏独见也，故曰死。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：六节藏家论曰∶人迎一盛，病在少阳，二盛病在太阳，三盛病在阳明，四盛以上为格阳。寸口 \n一盛，病在厥阴，二盛病在少阴，三盛病在太阴，四盛以上为关阴。人迎与寸口俱盛四倍以上为关 \n格，关格之脉羸，不能极于天地之精气则死矣。本篇脉证具载关格门，当详察之。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：平人气象论曰∶妇人手少阴脉动甚者，任子也。 \n阴阳别论曰∶阴搏阳别，谓之有子。 \n腹中论帝曰∶何以知怀子之且生也？岐伯曰∶身有病而无邪脉也。本篇诸义，具详妇人门胎孕 \n条中。 \n\n\n\n<目录>卷之四道集\\脉神章（上）\n\n<篇名>《内经》脉义\n\n属性：通评虚实论帝曰∶乳子而病热，脉悬小者何如？岐伯曰∶手足温则生，寒则死。帝曰∶乳子中 \n风热，喘鸣肩息者，脉何如？曰∶喘鸣肩息者，脉实大也，缓则生，急则死。此条详义，具载小儿 \n本门。 \n\n\n\n<目录>卷之五道集\\脉神章（中）\n\n<篇名>通一子脉义\n\n属性：脉者，血气之神，邪正之鉴也。有诸中必形诸外，故血气盛者脉必盛，血气衰者脉必衰，无病者 \n脉必正，有病者脉必乖。矧人之疾病，无过表里寒热虚实，只此六字，业已尽之。然六者之中，又 \n惟虚实二字为最要。盖凡以表证、里证、寒证、热证，无不皆有虚实，既能知表里寒热，而复能以 \n虚实二字决之，则千病万病，可以一贯矣。且治病之法，无逾攻补。用攻用补，无逾虚实。欲察虚 \n实，无逾脉息。虽脉有二十四名主病各异，然一脉能兼诸病，一病亦能兼诸脉，其中隐微，大有玄 \n秘，正以诸脉中亦皆有虚实之变耳。言脉至此，有神存矣。倘不知要而泛焉求迹，则毫厘千里，必 \n多迷误，故予特表此义。有如洪涛巨浪中，则在乎牢执柁杆，而病值危难处，则在乎专辨虚实，虚 \n实得真，则标本阴阳，万无一失。其或脉有疑似，又必兼证兼理，以察其孰客孰主，孰缓孰急。能 \n知本末先后，是即神之至也矣。 \n\n\n\n<目录>卷之五道集\\脉神章（中）\n\n<篇名>通一子脉义\n\n属性：左寸心部也，其候在心与心包络。得南方君火之气，脾土受生，肺金受制，其主神明清浊。 \n右寸肺部也，其候在肺与膻中。得西方燥金之气，肾水受生，肝木受制，其主情志善恶。 \n右二部，所谓上以候上也，故凡头面、咽喉、口齿、颈项、肩背之疾，皆候于此。 \n左关肝部也，其候在肝胆。得东方风木之气，心火受生，脾土受制，其主官禄贵贱。 \n右关脾部也，其候在脾胃。得中央湿土之气，肺金受生，肾水受制，其主财帛浓薄。 \n右二部居中，所以候中焦也，故凡于胁肋腹背之疾，皆候于此。 \n左尺肾部也，其候在肾与膀胱、大肠。得北方寒水之气，肝木受生，心火受制，其主阴气之寿 \n元。 \n右尺三焦部也，其候在肾与三焦、命门、小肠。得北方天一相火之气，脾土受生，肺金受制， \n其主阳气之寿元。 \n右二部，所谓下以候下也，故凡于腰腹、阴道及脚膝之病，皆候于此。按∶本经曰∶上竟上者 \n，胸喉中事；下竟下者，少腹腰股膝胫中事。所以脉之形见上者候上，下者候下，此自然之理也。 \n自王叔和云∶心与小肠合于左寸，肺与大肠合于右寸，以至后人遂有左心小肠，右肺大肠之说，其 \n谬甚矣。夫小肠、大肠皆下部之腑，自当应于两尺。然脉之两尺，左为水位，乃真阴之舍也；右为 \n火位，乃元阳之本也。小肠属火，而火居火位，故当配于下之右；大肠属金，而金水相从，故当配 \n于下之左，此亦其当然也。但二肠连胃，气本一贯，故在《内经》亦不言其定处，而但曰大肠、小 \n肠皆属于胃，是又于胃气中，总可察二肠之气也。然凡在下焦脏腑，无不各具阴阳，若欲察下部之阳 \n者，当总在右尺；察下部之阴者，当总在左尺，则尽其要矣。或问曰∶何以右尺为阳而属火？曰尺 \n为蛇武之乡，而地之刚居西北，所以手足之右强于左，是即左阴右阳之义也。此篇尚有详论，具载 \n《类经，求正录》中，所当参阅。 \n正脉十六部（三 浮、沉、迟、数、洪、微、滑、涩、弦、芤、紧、缓、结、伏、虚、实） \n浮脉 举 \n之有余，按之不足。浮脉为阳，凡洪大芤革之属，皆其类也。为中气虚，为阴不足，为风，为暑， \n为胀满，为不食，为表热，为喘急。浮大为伤风，浮紧为伤寒，浮滑为宿食，浮缓为湿滞，浮芤为 \n失血，浮数为风热，浮洪为狂躁。虽曰浮为在表，然真正风寒外感者，脉反不浮，但其紧数而略兼 \n浮者，便是表邪，其证必发热无汗，或身有酸疼，是其候也。若浮而兼缓，则非表邪矣。大都浮而 \n有力有神者，为阳有余，阳有余则火必随之，或痰见于中，或气壅于上，可类推也。若浮而无力空 \n豁者，为阴不足，阴不足则水亏之候，或血不营心，或精不化气，中虚可知也。若以此等为表证， \n则害莫大矣。其有浮大弦硬之极，甚至四倍以上者，《内经》谓之关格，此非有神之谓，乃真阴虚 \n极而阳亢无根，大凶之兆也。凡脉见何部，当随其部而察其证，诸脉皆然。 \n沉脉 轻手不见，重取乃得。沉脉为阴，凡细小、隐伏、反关之属，皆其类也，为阳郁之候。为 \n寒，为水，为气，为郁，为停饮，为 瘕，为胀实，为厥逆，为洞泄。沉细为少气，为寒欲，为胃 \n中冷，为腰脚痛，为 癖。沉迟为痼冷，为精寒。沉滑为宿食，为伏痰。沉伏为霍乱，为胸腹痛。 \n沉数为内热。沉弦、沉紧为心腹、小肠疼痛。沉虽属里，然必察其有力无力，以辨虚实。沉而实者 \n，多滞多气，故曰下手脉沉，便知是气。气停积滞者，宜消宜攻。沉而虚者，因阳不达，因气不舒 \n。阳虚气陷者，宜温宜补。其有寒邪外感，阳为阴蔽，脉见沉紧而数，及有头疼身热等证者，正属 \n邪表，不得以沉为里也。 \n迟脉 不及四至者皆是也。迟为阴脉，凡代缓结涩之属，皆其相类，乃阴盛阳亏之候。为寒，马 \n虚。浮而迟者内气虚，沉而迟者表气虚。迟在上，则气不化精，迟在下，则精不化气。气寒则不行 \n，血寒则凝滞。若迟兼滑大者，多风痰顽痹之候，迟兼细小者，必真阳亏弱而然。或阴寒留蓄于中， \n则为泄为痛；或元气不荣于表，则寒栗拘挛。大都脉来迟慢者，总由元气不充，不可妄施攻击。 \n数脉 五至六至以上，凡急疾紧促之属，皆其类也。为寒热，为虚劳，为外邪，为痈疡。滑数、 \n洪数者多热，涩数、细数者多寒。暴数者多外邪，久数者必虚损。数脉有阴有阳。今后世相传，皆 \n以数为热脉，及详考 \n《内经》则但曰∶诸急者多寒，缓者多热，滑者阳气盛，微有热。曰∶粗大者，阴不足，阳有余， \n为热中也。曰∶缓而滑者曰热中。舍此之外，则并无以数言热者。而迟冷数热之说，乃始自《难经 \n》云数则为热，迟则为寒，今举世所宗，皆此说也。不知数热之说，大有谬误。何以见之？盖自余 \n历验以来，凡见内热伏火等证，脉反不数，而惟洪滑有力，如经文所言者是也。至如数脉之辨，大 \n约有七，此义失真，以至相传遗害者，弗胜纪矣。兹列其要者如左，诸所未尽，可以类推。一、外 \n邪有数脉。凡寒邪外感，脉必暴见紧数。然初感便数者，原未传经，热自何来？所以只宜温散。即 \n或传经日久，但其数而滑实，方可言热；若数而无力者，到底仍是阴证，只宜温中。此外感之数， \n不可尽以为热也。若概用寒凉，无不杀人。一、虚损有数脉。凡患阳虚而数者，脉必数而无力，或 \n兼细小，而证见虚寒，此则温之且不暇，尚堪作热治乎？又有阴虚之数者，脉必数而弦滑，虽有烦 \n热诸证，亦宜慎用寒凉，若但清火，必至脾泄而败。且凡患虚损者，脉无不数，数脉之病，惟损最 \n多，愈虚则愈数，愈数则愈危，岂数皆热病乎？若以虚数作热数，则万无不败者矣。一、疟疾有数 \n脉。凡疟作之时，脉必紧数，疟止之时，脉必和缓，岂作即有火，而止则无火乎？且火在人身，无 \n则无矣，有则无止时也。能作能止者，惟寒邪之进退耳，真火真热，则不然也。此疟疾之数，故不 \n可尽以为热。一、痢疾有数脉。凡痢疾之作，率由寒湿内伤，脾肾俱损，所以脉数但兼弦涩细弱者 \n，总皆虚数，非热数也，悉宜温补命门，百不失一。其有形证多火，年力强壮者，方可以热数论治 \n。然必见洪滑实数之脉，方是其证。一、痈疡有数脉。凡脉数身无热而反恶寒，饮食如常者，或身 \n有热而得汗不解者，即痈疽之候也。然疮疡之发，有阴有阳，可攻可补，亦不得尽以脉数者为热证 \n。一、痘疹有数脉，以邪毒未达也，达则不数矣。此当以虚实大小分阴阳，亦不得以数为热脉。一 \n、癖有数脉。凡胁腹之下有块如盘者，以积滞不行，脉必见数。若积久成疳，阳明壅滞，而致口 \n臭、牙疳、发热等证者，乃宜清胃清火。如无火证，而脉见细数者，亦不得认以为热。一、胎孕有 \n数脉。以冲任气阻，所以脉数，本非火也。此当以强弱分寒热，不可因其脉数，而执以黄芩为圣药 \n。按∶以上数脉诸证，凡邪盛者多数脉，虚甚者尤多数脉，则其是热非热，从可知矣。 \n洪脉 大而实也，举按皆有余。洪脉为阳，凡浮芤实大之属，皆其类也，为血气燔灼，大热之 \n候。浮洪为表热，沉洪为里热。为胀满，为烦渴，为狂躁，为斑疹，为头疼面热，为咽干喉痛，为 \n口疮痈肿，为大小便不通，为动血，此阳实阴虚，气实血虚之候。若洪大至极，甚至四倍以上者， \n是即阴阳离绝，关格之脉也，不可治。 \n微脉 纤细无神，柔弱之极，是为阴脉。凡细小虚濡之属，皆其类也，乃血气俱虚之候。为畏寒 \n，为恐惧，为怯弱，为少气，为中寒，为胀满，为呕哕，为泄泻，为虚汗，为食不化，为腰腹疼痛 \n，为伤精失血，为眩运厥逆。此虽气血俱虚，而尤为元阳亏损，最是阴寒之候。 \n滑脉 往来流利，如盘走珠。凡洪大芤实之属，皆其类也，乃气实血壅之候。为痰逆，为食滞， \n为呕吐，为满闷。滑大、滑数为内热，上为心肺、头目、咽喉之热，下为小肠、膀胱、二便之热。 \n妇人脉滑数而经断者为有孕。若平人脉滑而和缓，此自营卫充实之佳兆；若过于滑大，则为邪热之 \n病。又凡病虚损者，多有弦滑之脉，此阴虚然也；泻痢者，亦多弦滑之脉，此脾肾受伤也，不得通 \n以火论。 \n涩脉 往来艰涩，动不流利，如雨 沙，如刀刮竹，言其象也。涩为阴脉，凡虚细微迟之属，皆 \n其类也，为血气俱虚之候。为少气，为忧烦，为痹痛，为拘挛，为麻木，为无汗，为脾寒少食，为 \n胃寒多呕，为二便违和，为四肢厥冷。男子为伤精，女子为失血，为不孕，为经脉不调。凡脉见涩 \n滞者，多由七情不遂，营卫耗伤，血无以充，气无以畅。其在上，则有上焦之不舒，在下则有下焦 \n之不运，在表则有筋骨之疲劳，在里则有精神之短少，凡此总属阳虚。诸家言气多血少，岂以脉之 \n不利，犹有气多者乎？ \n弦脉 按之不移，硬如弓弦。凡滑大坚搏之属，皆其类也。为阳中伏阴，为血气不和，为气逆， \n为邪胜，为肝强，为脾弱，为寒热，为痰饮，为宿食，为积聚，为胀满，为虚劳，为疼痛，为拘急 \n，为疟痢，为疝痹，为胸胁痛。《疮疽论》曰∶弦洪相搏，外紧内热，欲发疮疽也。弦从木化，气 \n通乎肝，可以阴，亦可以阳。但其弦大兼滑者，便是阳邪；弦紧兼细者，便是阴邪。凡脏腑间胃气 \n所及，则五脏俱安，肝邪所侵，则五脏俱病。何也？盖木之滋生在水，培养在土。若木气过强，则 \n水因食耗，土为克伤；水耗则肾亏，土伤则胃损；肾为精 \n血之本，胃为水谷之本，根本受伤，生气败矣，所以木不宜强也。矧人无胃气曰死，故脉见和缓者 \n吉，指下弦强者凶。盖肝邪与胃气不和，缓与弦强相左，弦甚者土必败，诸病见此，总非佳兆。 \n芤脉 浮大中空，按如葱管。芤为阳脉，凡浮豁弦洪之属，皆相类也，为孤阳脱阴之候。为失血 \n脱血，为气无所归，为阳无所附，为阴虚发热，为头晕目眩，为惊悸怔忡，为喘急盗汗。芤虽阳脉， \n而阳实无根，总属大虚之候。 \n紧脉 急疾有力，坚搏抗指，有转索之状，凡弦数之属，皆相类也。紧脉阴多阳少，乃阴邪激搏 \n之候，主为痛为寒。紧数在表，为伤寒发热，为浑身筋骨疼痛，为头痛项强，为咳嗽鼻塞，为瘴为 \n疟。沉紧在里，为心胁疼痛，为胸腹胀满，为中寒逆冷，为吐逆出食，为风痫反张，为 癖，为泻 \n痢，为阴疝。在妇人为气逆经滞，在小儿为惊风抽搐。 \n缓脉 和缓不紧也。缓脉有阴有阳，其义有三∶凡从容和缓，浮沉得中者，此自平人之正脉；若 \n缓而滑大者多实热，如《内经》所言者是也；缓而迟细者多虚寒，即诸家所言者是也。然实热者， \n必缓大有力，多为烦热，为口臭，为腹满，为痈疡，为二便不利，或伤寒温疟初愈，而余热未清者 \n，多有此脉。若虚寒者，必缓而迟细，为阳虚，为畏寒，为气怯，为疼痛，为眩晕，为痹弱，为痿 \n厥，为怔忡健忘，为食饮不化，为惊溏飧泄，为精寒肾冷，为小便频数。女人为经迟血少，为失血 \n下血。凡诸疮毒外证，及中风产后，但得脉缓者皆易愈。 \n结脉 脉来忽止，止而复起，总谓之结。旧以数来一止为促，促者为热，为阳极；缓来一止为结 \n，结者为寒，为阴极。通谓其为气为血，为食为痰，为积聚，为 瘕，为七情郁结。浮结为寒邪在 \n经，沉结为积聚在内，此固结促之旧说矣。然以予之验，则促类数也，未必热；结类缓也，未必寒 \n，但见中止者，总是结脉。多由血气渐衰，精力不继，所以断而复续，续而复断，常见久病者多有 \n之，虚劳者多有之，或误用攻击消伐者亦有之。但缓而结者为阳虚，数而结者为阴虚。缓者犹可， \n数者更剧。此可以结之微甚，察元气之消长，最显最切者也。 \n至如留滞郁结等病，本亦此脉之证应，然必其形强气实，而举接有力，此多因郁滞者也。又有无病 \n而一生脉结者，此其素禀之异常，无足怪也。舍此之外，凡病有不退，而渐见脉结者，此必气血衰 \n残，首尾不继之候，速宜培本，不得妄认为留滞。 \n伏脉 如有如无，附骨乃见。此阴阳潜伏，阻隔闭塞之候。或火闭而伏，或寒闭而伏，或气闭而 \n伏。为痛极，为霍乱，为疝瘕，为闭结，为气逆，为食滞，为忿怒，为厥逆、水气。 \n凡伏脉之见，虽与沉微细脱者相类，而实有不同也。盖脉之伏者，以其本有如无，而一时隐蔽 \n不见耳。此有胸腹痛剧而伏者，有气逆于经，脉道不通而伏者，有偶因气脱不相接续而伏者，然此 \n必暴病暴逆者乃有之，调其气而脉自复矣。若此数种之外，其有积困延绵，脉本细微而渐至隐伏者 \n，此自残烬将绝之兆，安得尚有所伏？常见庸人诊此，无论久暂虚实，动称伏脉，而破气导痰等剂 \n，犹然任意，此恐其就道稽迟，而复行催牒耳。闻见略具，谅不至此。 \n虚脉 正气虚也，无力也，无神也。有阴有阳。浮而无力为血虚，沉而无力为气虚，数而无力为 \n阴虚，迟而无力为阳虚。虽曰微濡迟涩之属，皆为虚类，然而无论诸脉，但见指下无神者，总是虚 \n脉。《内经》曰∶按之不鼓，诸阳皆然，即此谓也。故凡洪大无神者，即阴虚也；细小无神者，即 \n阳虚也。阴虚则金水亏残，龙雷易炽，而五液神魂之病生焉。或盗汗遗精，或上下失血，或惊忡不 \n宁，或咳喘劳热。阳虚则火土受伤，真气日损，而君相化源之病生焉。或头目昏眩，或膈塞胀满， \n或呕恶亡阳，或泻痢疼痛。救阴者，壮水之主；救阳者，益火之源。渐长则生，渐消则死，虚而不 \n补，元气将何以复？此实死生之关也。医不识此，尚何望其他焉？ \n实脉 邪气实也，举按皆强，鼓动有力。实脉有阴有阳，凡弦洪紧滑之属，皆相类也，为三焦壅 \n滞之候。表邪实者，浮大有力，以风寒暑湿外感于经，为伤寒瘴疟，为发热头痛、鼻塞头肿，为筋 \n骨肢体酸疼、痈毒等证。里邪实者，沉实有力，因饮食七情内伤于脏，为胀满，为闭结，为 瘕， \n为瘀血，为痰饮，为腹痛，为喘 \n呕咳逆等证。火邪实者，洪滑有力，为诸实热等证。寒邪实者，沉弦有力，为诸痛滞等证。凡其在 \n气在血，脉有兼见者，当以类求。然实脉有真假，真实者易知，假实者易误。故必问其所因，而兼 \n察形证，必得其神，方是高手。 \n\n\n\n<目录>卷之五道集\\脉神章（中）\n\n<篇名>通一子脉义\n\n属性：持脉之道，须明常变。凡众人之脉，有素大素小，素阴素阳者，此其赋自先天，各成一局也。 \n邪变之脉，有倏缓倏疾，乍进乍退者，此其病之骤至，脉随气见也。故凡诊脉者，必须先识脏脉， \n而后可以察病脉；先识常脉，而后可以察变脉。于常脉中可察人之器局寿夭，于变脉中可察人之疾 \n病吉凶，诊家大要，当先识此。 \n\n\n\n<目录>卷之五道集\\脉神章（中）\n\n<篇名>通一子脉义\n\n属性：凡诊病之法，固莫妙于脉，然有病脉相符者，有脉病相左者，此中大有玄理。故凡值疑似难明 \n处，必须用四诊之法，详问其病由，兼辨其声色，但于本末先后中，正之以理，斯得其真。若不察 \n此，而但谓一诊可凭，信手乱治，亦岂知脉证最多真假，见有不确，安能无误？且常诊者，知之犹 \n易，初诊者，决之甚难，此四诊之所以不可忽也。故《难经》以切居四诊之末，其意深矣。陶节庵 \n亦曰∶问病以知其外，察脉以知其内，全在活法二字，乃临证切脉之要诀也。此义惟汪石山言之最 \n详，并附于后卷。 \n\n\n\n<目录>卷之五道集\\脉神章（中）\n\n<篇名>通一子脉义\n\n属性：脉义之见于诸家者，六经有序也，脏象有位也，三部九候有则也，昭然若此，非不既详且备矣 \n。及临证用之，则犹如望洋，莫测其孰为要津，孰为彼岸，予于初年，亦尝为此所迷者盖屡屡矣。 \n今而熟察其故，乃知临 \n岐忘羊，患在不得其独耳。兹姑以部位言之，则无不曰心肝肾居左之三部，肺脾命居右之三部，而 \n按部以索脏，按脏以索病，咸谓病无遁情矣。故索部位者，审之寸，则似乎病在心肺也；审之关， \n则似乎病在肝脾也；审之尺，又似乎病在两肾也。既无无脉之部，又无无病之脉，而病果安在哉？ \n孰是孰非，此难言也。再察其病情，则有如头痛者，一证耳，病本在上，两寸其应也。若以经脏言 \n之，则少阳、阳明之痛，不应在两关乎？太阳之痛，不应在左尺乎？上下无分，此难言也。又如淋 \n遗，一证耳，病本在下，尺中所主也。若气有不摄，病在右寸矣；神有不固，病在左寸矣，源流无 \n辨，此难言也。诸如此类，百病皆燃，使必欲以部位言，则上下相关，有不可泥也。使必欲以经脏 \n言，则承制相移，有不可执也。言难尽意，绘难尽神，无弗然矣。是可见诸家之所胪列者，亦不过 \n描摸影响，言此失彼，而十不得一，第觉其愈多愈繁，愈繁愈失，而迷津愈甚矣。故善为脉者，贵在 \n察神，不在察形。察形者，形千形万，不得其要；察神者，唯一惟精，独见其真也。 \n独之为义，有部位之独也，有脏气之独也，有脉体之独也。部位之独者，谓诸部无恙，惟此稍 \n乖，乖处藏奸，此其独也。脏气之独者，不得以部位为拘也，如诸见洪者，皆是心脉，诸见弦者， \n皆是肝脉，肺之浮，脾之缓，肾之石；五脏之中，各有五脉，五脉互见，独乖者病，乖而强者，即 \n本脏之有余；乖而弱者，即本脏之不足，此脏气之独也。脉体之独者，如经所云独小者病，独大者 \n病，独疾者病，独迟者病，独热者病，独寒者病，独陷下者病，此脉体之独也。总此三者，独义见 \n矣。夫既谓之独，何以有三？而不知三者之独，亦总归于独小、独大、独疾、独迟之类，但得其一 \n，而即见病之本矣。故经曰∶得一之精，以知死生。又曰∶知其要者、一言而终，不知其要，则流 \n散无穷。正此之谓也。 \n虽然，然独不易言也，亦不难言也。独之为德，为群疑之主也，为万象之源也。其体至圆，其 \n用至活也。欲得之者，犹纵目于泰山之顶，则显者显，隐者隐，固若易中有难也；犹认针于沧海之 \n中，则左之左，右之右， \n还觉难中有易也。然不有无岐之目，无二之心，诚不足以因彼之独，而成我之独也。故曰独不难知 \n也，而惟恐知独者之难其人也。独自有真也，而又恐伪辩者假借以文其僻也。真独者，兼善成于独 \n善；伪独者，毒己由于独人。独之与毒，音虽若同，而利害则天渊矣。故并及之，以识防于此。 \n\n\n\n<目录>卷之五道集\\脉神章（中）\n\n<篇名>通一子脉义\n\n属性：上下来去至止，此六字者，深得诊家之要，乃滑伯仁所创言者。第滑氏之说，未尽其蕴，此中 \n犹有精义，余并续而悉之。盖此六字之中，具有三候之法。如初诊之先，即当详审上下，上下之义 \n，有升降焉，有阴阳焉，有脏象焉，有补泻焉；上下昭然，则证治条分而经济自见，此初候之不可 \n不明也。及延医之后，即当详察来去，来去之义，或指下之和气未来，形证之乖气未去，此进退可 \n别矣。或何者为邪气渐去，何者为生气渐来，此消长有征矣。来去若明，则吉凶可辨，而权衡在我 \n此中候之不可不察也。再统国中之全局，犹当详见至止。至止之义，即凡一举一动，当料其势所必 \n至，一闻一见，当思其何所底止，知始知终，庶乎近神矣，此未候之不可不察也。凡此六字之义， \n其真诊家之纲领乎。故余续之如此，并附滑氏原论于后。滑氏曰∶察脉须识上下来去至止六字，不 \n明此六字，则阴阳虚实不别也。上者为阳，来者为阳，至者为阳；下者为阴，去者为阴，止者为阴 \n也。上者，自尺部上于寸口，阳生于阴也。下者，自寸口下于尺部，阴生于阳也。来者，自骨肉之 \n分而出于皮肤之际，气之升也。去者，自皮肤之际而还于骨肉之分，气之降也。应曰至，息曰止也 \n。 \n\n\n\n<目录>卷之五道集\\脉神章（中）\n\n<篇名>通一子脉义\n\n属性：凡诊脉须知胃气，如经曰∶人以水谷为本，故人绝水谷则死，脉无胃气亦死。又曰∶脉弱以滑 \n，是有胃气。又曰∶邪气来也紧而疾，谷气来也徐而和。又曰∶五味入口，藏于胃，以养五脏气。 \n是以五脏六腑之气味，皆 \n出于胃，而变见于气口。是可见谷气即胃气，胃气即元气也。夫元气之来，力和而缓；邪气之至， \n力强而峻。 \n高阳生曰∶阿阿软若春杨柳，此是脾家脉四季。即胃气之谓也。故凡诊脉者，无论浮沉迟数， \n虽值诸病叠见，而但于邪脉中，得兼软滑徐和之象者，便是五脏中俱有胃气，病必无害也。何也？ \n盖胃气者，正气也，病气者，邪气也，夫邪正不两立，一胜则一负，凡邪气胜则正气败，正气至 \n则邪气退矣。若欲察病之进退吉凶者，但当以胃气为主。 \n察之之法，如今日尚和缓，明日更弦急，知邪气之愈进，邪愈进则病愈甚矣；今日甚弦急，明 \n日稍和缓，知胃气之渐至，胃气至则病渐轻矣。即如顷刻之间，初急后缓者，胃气之来也；初缓后 \n急者，胃气之去也。此察邪正进退之法也。至于死生之兆，亦惟以胃气为主。夫胃气中和，旺于四 \n季，故春脉微弦而和缓，夏脉微钩而和缓，秋脉微毛而和缓，冬脉微石而和缓，此胃气之常，即平 \n人之脉也。若脉无胃气，即名真脏。脉见真脏，何以当死？盖人有元气，出自先天，即天气也，为 \n精神之父。人有胃气，出乎后天，即地气也，为血气之母。其在后天，必本先天为主持；在先天， \n必赖后天为滋养，无所本者死，无所养者亦死。何从验之？如但弦、但钩、但毛、但石之类，皆真 \n脏也，此以孤脏之气独见，而胃气不能相及，故当死也。且脾胃属土，脉本和缓，士惟畏木，脉则 \n弦强。凡脉见弦急者，此为土败木贼，大非佳兆。若弦急之微者，尚可救疗，弦急之甚者，胃气其 \n穷矣。 \n\n\n\n<目录>卷之五道集\\脉神章（中）\n\n<篇名>通一子脉义\n\n属性：据脉法所言，凡浮为在表，沉为在里，数为多热，迟为多寒，弦强为实，微细为虚，是固然矣 \n。然疑似中尤有真辨，此其关系非小，不可不察也。如浮虽属表，而凡阴虚血少，中气亏损者，必 \n浮而无力，是浮不可以概言表。沉虽属里，而凡表邪初感之深者，寒束皮毛，脉不能达，其必沉紧 \n，是沉不可以概言里。数为热，而 \n真热者未必数，凡虚损之证，阴阳俱困，气血张皇，虚甚者数必甚，是数不可以概言热。迟虽为寒 \n，凡伤寒初退，余热未清，脉多迟滑，是迟不可以概言寒。弦强类实，而真阴胃气大亏，及阴阳关 \n格等证，脉必豁大而弦健，是强不可以概言实。微细类虚，而凡痛极气闭，营卫壅滞不通者，脉必 \n伏匿，是伏不可以概言虚。由此推之，则不止是也，凡诸脉中皆有疑似，皆有真辨。诊能及此，其 \n必得鸢鱼之学人乎。不易言也！不易言也！ \n\n\n\n<目录>卷之五道集\\脉神章（中）\n\n<篇名>通一子脉义\n\n属性：凡治病之法，有当舍证从脉者，有当舍脉从证者，何也？盖证有真假，脉亦有真假，凡见脉证 \n有不相合者，则必有一真一假隐乎其中矣。故有以阳证见阴脉者，有以阴证见阳脉者，有以虚证见 \n实脉者，有以实证见虚脉者，此阴彼阳，此虚彼实，将何从乎？病而遇此，最难下手，最易差错， \n不有真见，必致杀人。矧今人只知见在，不识隐微，凡遇证之实而脉之虚者，必直攻其证，而忘其 \n脉之真虚也；或遇脉之弦大而证之虚者，亦必直攻其脉，而忘其证之无实也。此其故，正以似虚似 \n实，疑本难明，当舍当从，孰知其要。医有迷途，莫此为甚，余尝熟察之矣，大都证实脉虚者，必 \n其证为假实也；脉实证虚者，必其脉为假实也。何以见之？如外虽烦热，而脉见微弱者，必火虚也 \n；腹虽胀满，而脉见微弱者，必胃虚也，虚火虚胀，其堪攻乎？此宜从脉之虚，不从证之实也。其 \n有本无烦热，而脉见洪数者，非火邪也；本无胀滞，而脉见弦强者，非内实也，无热无胀，其堪 \n泻乎？此宜从证之虚，不从脉之实也。凡此之类，但言假实，不言假虚，果何意也？盖实有假实， \n虚无假虚。 \n假实者，病多变幻，此其所以有假也；假虚者，亏损既露，此其所以无假也。大凡脉证不合者 \n，中必有奸，必先察其虚以求根本，庶乎无误，此诚不易之要法也。 \n一、真实假虚之候，非曰必无，如寒邪内伤，或食停气滞，而心腹急痛，以致脉道沉伏，或促或结 \n一证，此以邪闭经络而然，脉虽若虚，而必有痛胀等证可据者，是诚假虚之脉，本非虚也。又若四 \n肢厥逆，或恶风怯寒，而脉见滑数一证，此由热极生寒，外虽若虚，而内有烦热便结等证可据者， \n是诚假虚之病，本非虚也。大抵假虚之证，只此二条，若有是实脉，而无是实证，即假实脉也；有 \n是实证，而无是实脉，即假实证也，知假知真，即知所从舍矣。近见有治伤寒者，每以阴脉作伏 \n脉，不知伏脉之体，虽细虽微，亦必隐隐有力，亦必明明有证，岂容任意胡猜，以草菅人命哉！仁 \n者必不然也。 \n一、又有从脉从证之法，乃以病有轻重为言也。如病本轻浅，别无危候者，但因见在以治其标， \n自无不可，此从证也。若病关脏气，稍见疑难，则必须详辨虚实，凭脉下药，方为切当。所以轻者 \n从证，十唯一二；重者从脉，十当八九，此脉之关系非浅也。虽曰脉有真假，而实由人见之不真耳 \n，脉亦何从假哉！ \n\n\n\n<目录>卷之五道集\\脉神章（中）\n\n<篇名>通一子脉义\n\n属性：凡内出不足之证，忌见阳脉，如浮洪紧数之类是也。外人有余之病，忌见阴脉，如沉细微弱之 \n类是也。如此之脉，最不易治。 \n一、凡有余之病，脉宜有力有神，如微涩细弱而不应手者，逆之兆也。凡不足之病，脉宜和缓 \n柔软，若洪大搏击者，亦为逆也。 \n一、凡暴病脉来浮洪数实者为顺，久病脉来微缓软弱者为顺。若新病而沉微细弱，久病而浮洪 \n数实者，皆为逆也。凡脉证贵乎相合，设若证有余而脉不足，脉有余而证不足，轻者亦必延绵，重 \n者即危亡之兆。 \n一、经曰∶脉小以涩，谓之久病，脉浮而滑，谓之新病。故有余之病，忌见阴脉；不足之病， \n忌见阳脉。久病忌见数脉，新暴之病而见形脱脉脱者死。 \n一、凡元气虚败之证，脉有微极欲绝者，若用回阳救本等药，脉气徐徐渐出渐复者，乃为佳兆； \n若陡然暴出，忽如复元者，此假复也，必于周日之后，复脱如故，是必不治之证。若全无渐复生意 \n者，自不必治。若各部皆脱，而惟胃脉独存者，犹可冀其万一。 \n\n\n\n<目录>卷之五道集\\脉神章（中）\n\n<篇名>通一子脉义\n\n属性：脉有三部，部有三候，逐部先寻，次宜总究。左寸心经火位，脉宜流利洪强；左关肝胆，弦而 \n且长；尺部膀胱，沉静弥良。右寸肺金之主，轻浮充畅为宗；脾胃居于关部，和缓胃气常充；右尺 \n三焦连命，沉滑而实则隆。四时相代，脉状靡同。秋微毛而冬石，春则弦而夏洪。滑而微浮者肺恙 \n，弦中兼细者脾殃。心病则血衰脉小，肝证则脉弦且长。大而兼紧，肾疾奚康？寸口多弦，头面何 \n曾舒泰？关前若紧，胸中定是症殃。急则风上攻而头痛，缓则皮顽痹而不昌。微是厥逆之阴，数为 \n亏损之阳。滑则痰涎而胸膈气壅，涩缘血少而背膊疼伤。沉是背心之气，洪乃胸胁之妨。若夫关中 \n，缓则饮食必少，滑实胃火煎熬，小弱胃寒逆冷，细微食少膨胀。卫之虚者涩候，气之滞者沉当。 \n左关微涩兮血少，右关弦急兮过劳。洪实者血结之瘀，迟紧者脾冷之殃。至如尺内，洪大则阴虚可 \n凭，或微或涩，便浊遗精。弦者腹痛，伏者食停。滑兮小腹急胀，妇则病在月经。涩兮呕逆翻胃， \n弦强阴疝血崩。紧兮小腹作痛，沉微必主腰疼。紧促形于寸，此气满于心胸；紧弦见于关，斯痛攻 \n乎腹胁。两寸滑数兮，呕逆上奔；两关滑数兮，蛔虫内啮。心胸留饮，寸口沉潜；脐腹成 ，关中 \n促结。左关弦紧兮，缘筋脉之拘挛；右关沉滑兮，因食积之作孽。 \n脉有浮沉迟数，诊有提纲大端。浮而无力为虚，有力为邪所搏。浮大伤风兮浮紧伤寒，浮数虚 \n热兮浮缓风涎。沉缓滑大兮多热，沉迟紧细兮多寒。沉健须知积滞，沉弦气病淹淹。沉迟有力，疼 \n痛使然。迟弦数弦兮，疟寒疟热之辨；迟滑洪滑兮，胃冷胃温之愆。数而有痛，恐发疮疡；若兼洪 \n滑，热甚宜凉。阴数阴虚必发热， \n阳数阳强多汗黄。 \n脉有七情之伤，而为九气之列。怒伤于肝者，其脉促而气上冲；惊伤于胆者，其气乱而脉动掣 \n。过于喜者伤于心，故脉散而气缓；过于思者伤于脾，故脉短而气结。忧伤于肺兮，脉必涩而气沉； \n恐伤于肾兮，脉当沉而气怯。若脉促而人气消，因悲伤而心系挈。伤于寒者脉迟，其为人也气收； \n伤于热者脉数，其为人也气泄。 \n脉体须明，脉证须彻。浮为虚而表显，沉乃实而里决。滑是多痰，芤因失血。濡散总因虚而冷 \n汗，弦紧其为寒而痛切。洪则躁烦，迟为冷别。缓则风而顽木，实则胀而秘结。涩兮血少而寒，长 \n兮痫而又热。短小元阳必病，坚强患乎满急。伏因痛痹伏藏，细弱真元内伤。结促惟虚断续，代云 \n变易不常。紧急或缘泻痢，紧弦 痞相妨。数则心烦，大则病进。上盛则气高，下盛则气胀。大是 \n血虚之候，细为气少之恙。浮洪则外证推测，沉弦为内疾斟量。阳芤兮吐衄立至，阴芤兮下血须防。 \n盛滑则外疼可别，实紧则内痛多伤。弱小涩弦为久病，滑浮数疾是新殃。沉而弦紧， 癖内痛；脉 \n来缓滑，胃热宜凉。长而滑大者酒病，浮而缓豁者湿伤。坚而疾者为癫，迟而伏者必厥。洪大而疾 \n则发狂，紧滑而细为呕哕。脉洪而疾兮，因热结以成痈；脉微而涩兮，必崩中而脱血。阴阳皆涩数 \n，知溲屎之艰难；尺寸俱虚微，晓精血之耗竭。 \n脉见危机者死，只因指下无神。不问何候，有力为神。按之则隐，可见无根。盖元气之来，力 \n和而缓；邪气之至，力强而峻。弹石硬来即去，解索散乱无绪，屋漏半日而落，雀啄三五而住，鱼 \n翔似有如无，虾游进退难遇。更有鬼贼，虽如平类，土败于木，真弦可畏，是亦危机，因无胃气。 \n诸逢此者，见几当避。 \n\n\n\n<目录>卷之五道集\\脉神章（中）\n\n<篇名>通一子脉义\n\n属性：伤寒病热兮，洪大易治而沉细难医；伤风咳嗽兮，浮濡可攻而沉牢当避。肿胀宜浮大，颠狂忌 \n虚细。下血下痢兮，浮洪可恶；消渴消中兮，实大者利。霍乱喜浮大而畏微迟，头疼爱浮滑而嫌短 \n涩。肠 脏毒兮，不怕 \n沉微；风痹足痿兮，偏嫌数急。身体中风，缓滑则生；腹心作痛，沉细则良。喘急浮洪者危，咳血 \n沉弱者康。脉细软而不弦洪，知不死于中恶；脉微小而不数急，料无忧于金疮。吐血鼻衄兮，吾不 \n喜其实大；跌扑损伤兮，吾则畏其坚强。痢疾身热而脉洪，其灾可恶；湿病体烦而脉细，此患难当。 \n水泻脉大者可怪，亡血脉实者不祥。病在中兮脉虚为害，病在外兮脉涩为殃。腹中积久而脉虚者死 \n，身表热甚而脉静者亡。 \n\n\n\n<目录>卷之五道集\\脉神章（中）\n\n<篇名>通一子脉义\n\n属性：雀啄连来三五啄，屋漏半日一点落，鱼翔似有又如无，虾游静中忽一跃，弹石硬来寻即散，搭 \n指散乱为解索。寄语医家仔细看，六脉一见休下药。 \n\n\n\n<目录>卷之六道集\\脉神章（下）\n\n<篇名>《难经》脉义\n\n属性：一难曰∶十二经皆有动脉，独取寸口以决五脏六腑死生吉凶之法，何谓也？然∶寸口者，脉之 \n大会，手太阴之脉动也。二难曰∶脉有尺寸，何谓也？从关至尺是尺内，阴之所治也；从关至鱼际 \n是寸口内，阳之所治也。故分寸为尺，分尺为寸。 \n\n\n\n<目录>卷之六道集\\脉神章（下）\n\n<篇名>《难经》脉义\n\n属性：五难曰∶脉有轻重，何谓也？然∶初持脉如三菽之重，与皮毛相得者，肺部也。如六菽之重， \n与血脉相得者，心部也。如九菽之重，与肌肉相得者，脾部也。如十二菽之重，与筋平者，肝部也 \n。按之至骨，举指来疾者，肾部也。故曰轻重也。 \n\n\n\n<目录>卷之六道集\\脉神章（下）\n\n<篇名>《难经》脉义\n\n属性：四难曰∶脉有阴阳之法，何谓也？然∶呼出心与肺，吸入肾与肝，呼吸之间，脾受谷味也，其 \n脉在中。浮者阳也，沉者阴也，故曰阴阳也。心肺俱浮，何以别之？然∶浮而大散者心也，浮而短 \n涩者肺也。肾肝俱沉， \n何以别之？然∶牢而长者肝也，按之濡、举指来实者肾也。脾者中州，故其脉在中，是阴阳之法也。 \n\n\n\n<目录>卷之六道集\\脉神章（下）\n\n<篇名>《难经》脉义\n\n属性：六难曰∶脉有阴盛阳虚，阳盛阴虚，何谓也？然∶浮之损小，沉之实大，故曰阴盛阳虚；沉之 \n损小，浮之实大，故曰阳盛阴虚，是阴阳虚实之意也。 \n\n\n\n<目录>卷之六道集\\脉神章（下）\n\n<篇名>《难经》脉义\n\n属性：九难曰∶何以别知脏腑之病耶？然∶数者腑也，迟者脏也。数则为热，迟则为寒。诸阳为热， \n诸阴为寒，故以别知脏腑之病也。 \n\n\n\n<目录>卷之六道集\\脉神章（下）\n\n<篇名>《难经》脉义\n\n属性：十四难曰∶上部有脉，下部无脉，其人当吐，不吐者死。上部无脉，下部有脉，虽困无能为害 \n。所以然者，人之有尺，譬如树之有根，枝叶虽枯槁，根本将自生。脉有根本，人有元气，故知不 \n死。 \n\n\n\n<目录>卷之六道集\\脉神章（下）\n\n<篇名>仲景脉义\n\n属性：问曰∶脉有阴阳，何谓也？答曰∶凡脉浮大数动滑，此名阳也；沉涩弱弦微，此名阴也。阴病 \n见阳脉者生，阳病见阴脉者死。 \n寸口脉微，名曰阳不足，阴气上入阳中，则洒淅恶寒也。尺脉弱，名曰阴不足，阳气下陷入阴 \n中，则发热 \n也。阳脉浮、阴脉弱者，则血虚，血虚则筋急也。 \n其脉沉者，荣气之微也。其脉浮而汗出如流珠者，卫气之衰也。寸口脉浮为在表，沉为在里， \n数为在腑，迟为在脏。若脉浮大者，气实血虚也。 \n寸口脉浮而紧，浮则为风，紧则为寒，风则伤卫，寒则伤荣，荣卫俱病，骨节烦疼，当发其 \n汗也。 \n夏月盛热，欲着复衣，冬月盛寒，欲裸其身，所以然者，阳微则恶寒，阴弱则发热。 \n寸口脉浮大，而医反下之，此为大逆。浮则无血，大则为寒，寒气相搏，则为肠鸣。医乃不知 \n而反饮冷水，令汗大出，水得寒气，冷必相搏，其人即KT 。 \n诸脉浮数，当发热而反洒淅恶寒，若有痛处，饮食如常者，当发其痈。脉数不时，则生恶疮也。 \n\n\n\n<目录>卷之六道集\\脉神章（下）\n\n<篇名>仲景脉义\n\n属性：师曰∶脉有三部，道之根源，荣卫流行，不失衡铨。肾沉心洪，肺浮肝弦，此自经常，不失铢 \n分。出入升降，刻漏周旋，水下二刻，一周循环，当复寸口，虚实见焉。变化相乘，阴阳相干。风 \n则浮虚，寒则牢坚，沉潜水 ，支饮急弦，动则为痛，数则热烦，设有不应，知变所缘。三部不同， \n病各异端，太过可怪，不及亦然。邪不空见，中必有奸，审察表里，三焦别焉。知其所舍，消息诊 \n看，料度脏腑，独见若神。为子条记，传与贤人。 \n师曰∶呼吸者，脉之头也。初持脉，来疾去迟，此出疾入迟，名曰内虚外实也。初持脉，来迟 \n去疾，此出迟入疾，名曰内实外虚也。 \n师持脉，病患欠者，无病也。脉之呻者，病也。言迟者，风也。摇头言者，里痛也。行迟者， \n表强也。坐而伏者，短气也。坐而下一脚者，腰痛也。里实护腹，如怀卵物者，心痛也。 \n问曰∶人病恐怖者，其脉何状？曰∶脉形如循丝累累然，其面白脱色也。人愧者，其脉何类？ \n曰∶脉浮而面色乍白乍赤也。 \n问曰∶脉有残贼，何谓也？曰∶脉有弦紧浮滑沉涩，此六者名为残贼，能为诸脉作病也。 \n问曰∶脉有灾怪，何谓也？曰∶假令人病，脉得太阳，与形证相应，因为作汤，比还服汤如食 \n顷，病患乃大吐，若下痢，腹中痛。师曰∶我前来不见此证，今乃变异，是名灾怪。又问曰∶何缘 \n作此吐痢？答曰∶或有旧时服药，今乃发作，故名灾怪耳。 \n肥人责浮，瘦人责沉。肥人当沉今反浮，瘦人当浮今反沉，故责之。 \n寸脉下不至关为阳绝，尺脉上不至关为阴绝，此皆不治，决死也。若计其余命死生之期，期以 \n月节克之也。 \n脉病患不病，号曰行尸，以无生气，卒眩仆不识人者，短命则死。人病脉不病，名曰内虚，以 \n无谷神，虽困无苦。 \n问曰∶紧脉从何而来？曰∶假令亡汗若吐，以肺里寒，故令脉紧也。假令咳者，坐饮冷水，故 \n令脉紧也。假令下痢，以胃中虚冷，故令脉紧也。 \n寸口脉缓而迟，缓则阳气长，其色鲜，其颜光，其声商，毛发长；迟则阴气盛，骨髓生，血满 \n，肌肉紧薄鲜硬。阴阳相抱，营卫俱行，刚柔相搏，名曰强也。 \n寸口脉浮而大，浮为虚，大为实，在尺为关，在寸为格，关则不得小便，格则吐逆。 \n寸口脉弱而迟，弱者卫气微，迟者营中寒。营为血，血寒则发热；卫为气，气微者心内饥，饥 \n而虚满，不能食也。 \n寸口脉弱而缓，弱者阳气不足，缓者胃气有余，噫而吞酸，食卒不下，气填于膈上也。 \n寸口脉微而涩，微者卫气不行，涩者营气不足。营卫不能相将，三焦无所仰，身体痹不仁。营 \n气不足，则烦疼，口难言。卫气虚，则恶寒数欠。三焦不归其部，上焦不归者，噫而酢吞；中焦不 \n归者，不能消谷引食；下焦不归者，则遗溲。（酢，古醋字。） \n寸口脉微而涩，微者卫气衰，涩者营气不足。卫气衰，面色黄，荣气不足，面色青。营为根， \n卫为叶，营卫俱微，则根叶枯槁，而寒栗、咳逆、吐腥、吐涎沫也。 \n寸口脉微，尺脉紧，其人虚损多汗，知阴常在，绝不见阳也。 \n寸口诸微亡阳，诸濡亡血，诸弱发热，诸紧为寒。诸乘寒者则为厥，郁冒不仁，以胃无谷气， \n脾涩不通，口急不能言，战而栗也。 \n问曰∶何以知乘腑？何以知乘脏？曰∶诸阳浮数为乘腑，诸阴迟涩为乘脏。 \n\n\n\n<目录>卷之六道集\\脉神章（下）\n\n<篇名>仲景脉义\n\n属性：问曰∶寸口脉沉大而滑，沉则为实，滑则为气，实气相搏，气血入脏即死，入腑即愈，此谓卒 \n厥，何谓也？ \n师曰∶唇口青，身冷，为入脏，即死；身和，汗自出，为入腑，即愈。 \n问曰∶脉脱入脏即死，入腑即愈，何谓也？师曰∶非为一病，百病皆然。譬如浸淫疮，从口起流向 \n四肢者可治，从四肢流来入口者不可治。病在外者可治，入里者即死。 \n五邪中人，各有法度，风中于前，寒中于暮，湿伤于下，雾伤于上。风令脉浮，寒令脉急。雾 \n伤皮腠，湿流关节，食伤脾胃，极寒伤经，极热伤络。 \n夫男子平人，脉大为劳，极虚亦为劳。男子脉浮弱而涩为无子，精气清冷。脉得诸芤动微紧， \n男子失精，女子梦交。 \n男子平人，脉虚弱细微者，喜盗汗也。脉沉小迟名脱气，其人疾行则喘喝，手足逆寒，腹满， \n甚则溏泄，食不消化也。脉弦而大，弦则为减，大则为芤，减则为寒，芤则为虚，虚寒相搏，此名 \n为革，妇人则半产漏下，男子则亡血失精。 \n\n\n\n<目录>卷之六道集\\脉神章（下）\n\n<篇名>滑氏脉义\n\n属性：凡诊脉，先须识时脉、胃脉与脏腑平脉，然后及于病脉。时脉谓春三月六部中俱带弦，夏三月 \n俱带洪，秋三月俱带浮，冬三月俱带沉。胃脉谓中按得之，脉见和缓。凡人脏腑胃脉既平，又应时 \n脉，乃无病者也，反此为病。 \n持脉之要有三，曰举，曰按，曰寻。轻手循之曰举，重手取之曰按，不轻不重，委曲求之曰寻。 \n初持脉，轻手候之，脉见皮肤之间者，阳也，腑也，亦心肺之应也。重手得之，脉附于肉下者，阴 \n也，脏也，亦肝肾之应也。不轻不重，中而取之，其脉应于血肉之间者，阴阳相适，中和之应，脾 \n胃之候也。若委曲寻之而若隐若 \n见，则阴阳伏匿之脉也。 \n\n\n\n<目录>卷之六道集\\脉神章（下）\n\n<篇名>滑氏脉义\n\n属性：明脉须辨表里虚实四字。表，阳也，腑也，凡六淫之邪袭于经络，而未入胃腑及脏者，皆属于 \n表也。里，阴也，脏也，凡七情之气郁于心腹之内，不能散越，及饮食之伤留于腑脏之间，不能通 \n泄，皆属于里也。虚者，元气之自虚，精神耗散，气力衰竭也。实者，邪气之实，由正气之本虚， \n邪得乘之，非元气之自实也。故虚者补其正气，实者泻其邪气。经曰∶邪气盛则实，精气夺则虚， \n此大法也。 \n\n\n\n<目录>卷之六道集\\脉神章（下）\n\n<篇名>滑氏脉义\n\n属性：东垣曰∶不病之脉，不求其神而神无不在也。有病之脉，则当求其神之有无，谓如六数七极， \n热也，脉中有力，即有神矣，当泄其热；三迟二败，寒也，脉中有力，即有神矣，当去其寒。若数 \n极迟败中不复有力，为无神也，将何所恃耶？苟不知此而泄之去之，神将何以根据而为主？故经曰∶ \n脉者，血气之先，气血者，人之神也。善夫！ \n\n\n\n<目录>卷之六道集\\脉神章（下）\n\n<篇名>附诸家脉义\n\n属性：夫脉者，本乎营与卫也，而营行脉之中，卫行于脉之外，苟脏腑和平，营卫调畅，则脉无形状 \n之可议矣。或者六淫外袭，七情内伤，则脏腑不和，营卫乖谬，而二十四脉之名状，层出而叠见矣 \n。是故风寒暑湿燥火，此六淫也，外伤六淫之脉，则浮为风，紧为寒，虚为暑，细为湿，数为燥， \n洪为火，此皆可以脉而别其外感之 \n邪也。喜怒忧思悲恐惊者，此七情也，内伤七情之脉，喜则伤心而脉缓，怒则伤肝而脉急，恐则伤 \n肾而脉沉，悲则气消而脉短，惊则气乱而脉动，此皆可以脉而辨其内伤之病也。然此特举其常，而 \n以脉病相应者为言也。 \n若论其变，则有脉不应病，病不应脉，变出百端，而难一一尽凭乎脉者矣。试举一二言之，如 \n张仲景云∶脉浮大，邪在表，为可汗。若脉浮大，心下硬，有热属脏者，攻之，不令发汗，此又非 \n浮为表邪可汗之脉也。又云∶促脉为阳盛，宜用葛根黄芩黄连汤。若脉促厥冷为虚脱，非灸作温不 \n可，此又非促为阳盛之脉也。又曰∶迟脉为寒，沉脉为里。若阳明脉迟，不恶寒，身体 汗出， \n则用大承气，此又非诸迟为寒之脉矣；少阴病始得之，反发热而脉沉，宜麻黄细辛汤汗之，此又非 \n沉为在里之脉矣。凡此皆脉难尽凭之明验也。若只凭脉而不问证，未免以寒为热，以表为里，以阴 \n为阳，颠倒错乱，而夭人寿者多矣。是以古人治病，不专于脉，而必兼于审证，良有以也。 \n奈何世人不明乎此，往往有病讳而不言，惟以诊脉而试医之能否，脉之而所言偶中，便视为良 \n医而倾心付托，其于病之根源，一无所告，药之宜否，亦无所审，惟束手听命于医，因循遂至于死 \n，尚亦不悟，深可悲矣。彼庸俗之人，素不嗜学，固无足怪，奈近世士大夫家，亦未免狃于此习， \n是又大可笑也。夫定静安虑，格物致知，乃《大学》首章第一义，而虑者谓虑事精详，格物者谓穷 \n致事物之理，致知者谓推极吾之所知，凡此数事，学人必当究心于此矣。先正又言，为人子者，不 \n可不知医，病卧于床，委之庸医，比之不慈不孝。夫望闻问切，医家大节目也，苟于临病之际，惟 \n以切而知之为能，其余三事，一切置而不讲，岂得谓知医乎？岂得为处事精详乎？岂得为穷致事物 \n之理而推极吾之所知乎？ \n且医之良，亦不专于善诊一节，凡动静有常，举止不妄，存心忠浓，发言纯笃，察病详审，处 \n方精专，兼此数者，庶可谓之良矣。虽据脉言证，或有少瘥，然一脉所主非一病，故所言未必尽中 \n也。若以此而遂弃之， \n所谓以二卵而弃干城之将，乌可与智者道哉。姑以浮脉言之，《脉经》云，浮为风，为虚，为气， \n为呕，为厥，为痞，为胀，为满不食，为热，为内结等类，所主不下数十余病，假使诊得浮脉，彼 \n将断其为何病耶？苟不兼之以望闻问，而欲的知其为何病，吾为戛戛乎其难矣。古人以切居望闻问 \n之后，则于望闻问之间，已得其病情矣，不过再诊其脉，看病应与不应也。若脉与病应，则吉而易 \n医，脉与病反，则凶而难治，以脉参病，意盖如此，曷以诊脉知病为贵哉？夫《脉经》一书，拳拳 \n示人以诊法，而开卷入首便言观形察色，彼此参伍以决死生，可见望闻问切，医之不可缺一也。噫 \n！世称善脉莫过叔和，尚有待于彼此参伍，况下于叔和者乎！故专以切脉言病，必不能不致于误也。 \n安得为医之良？ \n抑不特此，世人又有以《太素脉》而言人贵贱穷通者，此又妄之甚也。予尝考其义矣，夫太者 \n，始也，初也，如太极、太乙之太；素者，质也，本也，如绘事后素之素，此盖言始初本质之脉也。 \n此果何脉耶？则必指元气而言也。东垣曰∶元气者，胃气之别名。胃气之脉，蔡西山所谓不长不短 \n，不疏不数，不大不小，应手中和，意思欣欣，难以名状者是也。无病之人，皆得此脉，以此脉而 \n察人之有病无病则可，以此脉而察人之富贵贫贱则不可。何也？胃气之脉，难以形容，莫能名状， \n将何以为贵贱穷通之诊乎？窃观其书，名虽太素，而其中论述，略无一言及于太素之义，所作歌括 \n，率多俚语，全无理趣。原其初意，不过托此以为徼利之媒，后世不察，遂相传习，莫有能辨其非 \n者。又或为之语曰∶太素云者，指贵贱穷通禀于有生之初而言也，然脉可以察而知之，非谓脉名太 \n素也。予曰∶固也，然则太素之所诊者，必不出于二十四脉之外矣。夫二十四脉皆主病，言一脉见 \n则主一病，贫贱富贵何从而察之哉？假如浮脉，其诊为风，使太素家诊之，将言其为风耶？抑言其 \n为贵贱穷通耶？二者不可得兼，若言其为风，则其所知亦不过病也；若遗其病而言其为贵贱穷通， \n则是 \n近而病诸身者尚不能知，安得谓之太素，则远而违诸身者必不能知之也。盖贵贱穷通，身外之事， \n与身之血气了不相干，安得以脉而知之乎？况脉之变见无常，而天之寒暑不一，故四时各异其脉， \n必不能久而不变，是以今日诊得是脉，明日诊之而或非，春间诊得是脉，至夏按之而或否。彼太素 \n者，以片时之寻按，而断一生之休咎，殆必无是理，然纵使亿则屡中，亦是捕风捉影，仿佛形容， \n安有一定之见哉。噫！以脉察病，尚不知病之的，而犹待乎望闻问，况能知其他乎。且脉兆于岐黄 \n，演于秦越，而详于叔和，遍考《素》、《难》、《脉经》，并无一字言及此者，非隐之也，殆必 \n有不可诬者耳。巢氏曰∶太素者，善于相法，特假太素以神其术耳。诚哉言也，足以破天下后世之 \n惑矣。又有善伺察者，以言 人，阴得其实，故于诊按之际，肆言而为欺妄，是又下此一等，无足 \n论也。 \n虽然，人禀天地之气以生，不能无清浊纯驳之殊，禀之清者，血气清而脉来亦清，清则脉形圆 \n净，至数分明。吾诊乎此，但知其主富贵而已，若曰何年登科，何年升授，何年招财，何年得子， \n吾皆不得而知矣。禀之浊者，血气浊而脉来亦浊，浊则脉形不清，至数混乱。吾诊乎此，但知其主 \n贫贱而已，若曰某时招悔，某时破财，某时损妻，某时克子，吾亦莫得而知矣。又有形浊而脉清者 \n，此谓浊中之清；质清而脉浊者，此谓清中之浊。又有形不甚清，脉不甚浊，但浮沉各得其位，大 \n小不失其等，亦主平稳而无大得丧也。其他言有所未尽，义有所未备，学人可以类推，是则吾之所 \n谓知人者，十本于理而已矣，岂敢妄为之说以欺人哉。噫，予所以着为是论者，盖以世之有言太素 \n脉者，靡不翕然称美，不惟不能以理析，又从而延誉于人，纵使其言有谬，又必阴与之委曲影射， \n此所谓误己而误人者也，果何益之有哉？又有迎医服药者，不惟不先言其所苦，甚至再三询叩，终 \n于默默，至有隐疾而困医者，医固为其所困，不思身亦为医所困矣。此皆世之通患，人所共有， \n故予不得不详论之，以致夫丁宁之意，俾聋瞽者或有所开发焉。孟子曰∶予岂好辨哉，予不得已也 \n。 \n\n\n\n<目录>卷之六道集\\脉神章（下）\n\n<篇名>附诸家脉义\n\n属性：太素之说，固为不经，然其间亦有可采者。如曰∶脉形圆净，至数分明，谓之清；脉形散涩， \n至数模糊，谓之浊。质清脉清，富贵而多喜，质浊脉浊，贫贱而多忧。质清脉浊，此为清中之浊， \n外富贵而内贫贱，失意处多，得意处少也。质浊脉清，此谓浊中之清，外贫贱而内富贵，得意处多 \n，失意处少也。若清不甚清，浊不甚浊，其得失相半，而无大得丧也。富贵而寿，脉清而长；贫贱"}, {"n": 4, "text": "卷四\n\n而夭，脉浊而促。清而促者，富贵而夭；浊而长者，贫贱而寿。此皆太素可采之句也，然亦不能外 \n乎风鉴，故业太素者，不必师太素，但师风鉴，风鉴精而太素之说自神矣。至其甚者，索隐行怪，无 \n所不至，是又巫家之教耳。孔子曰∶攻乎异端，斯害也已矣，正士岂为之。 \n\n\n\n<目录>卷之六道集\\脉神章（下）\n\n<篇名>附诸家脉义\n\n属性：论贵贱，切脉之清浊，论穷通，切脉之滑涩，论寿夭以浮沉，论时运以衰旺，论吉凶以缓急，亦 \n皆仿佛《灵枢》虚实攻补，法天法地法人之奥旨。凡人两手清微如无脉者，此纯阴脉，主贵；有两 \n手俱洪大者，此纯阳脉，主贵。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>经义（一）\n\n属性：水热穴论帝曰∶人伤于寒而传为热，何也？岐伯曰∶夫寒盛则生热也。 \n《内经》伤寒诸义及诸治法之未备者，俱补载瘟疫门，所当参阅。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>伤寒总名（二）\n\n属性：黄帝曰∶今夫热病者，皆伤寒之类也。又曰∶凡病伤寒而成温者，先夏至日为病温，后夏至日 \n为病暑。此皆《内经》之明言也。故凡病温病热而因于外感者，皆本于寒，即今医家皆谓之为伤寒 \n，理宜然也。近或有以温病热病谓非真伤寒者，在未达其义耳。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>初诊伤寒法（三）\n\n属性：凡初诊伤寒者，以其寒从外入，伤于表也。寒邪自外而入，必由浅渐深，故先自皮毛，次入经 \n络，又次入筋骨，而后及于脏腑，则病日甚矣。故凡病伤寒者，初必发热，憎寒无汗，以邪闭皮毛， \n病在卫也。渐至筋脉拘急，头背骨节疼痛，以邪入经络，病在营也。夫人之卫行脉外，营行脉中， \n今以寒邪居之，则血气混淆，经络壅滞，故外证若此，此即所谓伤寒证也。自此而渐至呕吐、不食 \n、胀满等证，则由外入内，由经入腑，皆可 \n因证而察其表里矣。若或肌表无热，亦不憎寒，身无疼痛，脉不紧数者，此其邪不在表，病必属里 \n。凡察伤寒，此其法也。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>论脉（四）\n\n属性：伤寒之邪，实无定体，或入阳经气分，则太阳为首，或入阴经精分，则少阴为先。其脉以浮紧 \n而有力无力，可知表之虚实；沉紧而有力无力，可知里之虚实；中而有力无力，可知阴阳之凶吉。 \n诊之之法，当问证以知其外，察脉以知其内，先病为本，后病为标。能参合脉证，而知缓急先后者 \n，乃为上工。 \n一、诊法曰∶浮脉为在表。故凡脉见浮紧而数者，即表邪也。再加以头项痛，腰脊强等证，此 \n即太阳经病，当求本经轻重而解散之。 \n一、脉见洪长有力，而外兼阳明证者，即阳明在经之邪也，宜求本经之寒热以散之。 \n一、脉见弦数，而兼少阳之证者，即少阳经半表半里之病，宜和解而散之。 \n一、沉脉为在里，病属三阴，详具后六经证辨中。但沉数有力，是即热邪传里也，若表证深入， \n而内见大满大实，阳邪热结等证，治当从下也。 \n一、沉紧无力，而外无大热，内无烦渴等病，此阴证也。若或畏寒厥冷，及呕吐、腹痛、泻痢者 \n，此即阴寒直中，治宜温中也。 \n一、脉大者为病进，大因邪气胜，病日甚也。脉渐缓者为邪退，缓则胃气至，病将愈也。此以 \n大为病进，固其然也，然亦有宜大不宜大者，又当详辨。如脉体本大，再加洪数，此则病进之脉， \n不可当也。如脉体本小，因服药后而渐见滑大有力者，此自阴转阳，必将汗解，乃为吉兆。盖脉至 \n不鼓者，由气虚而然，无阳岂能作汗也。后论汗条中有按，当并阅之。 \n仲景《伤寒论》曰∶脉有阴阳者，何谓也？曰∶凡脉浮大数动滑，皆阳也；沉涩弱弦微，皆阴 \n也。诸脉浮数，而发热恶寒，身痛不欲饮食者，伤寒也。若洒淅恶寒，饮食如常，而痛偏一处者， \n必血气壅遏不通，成痈脓也。寸口脉浮为在表，沉为在里，数为在腑，迟为在脏。寸关尺三部，浮 \n沉、大小、迟数同等，虽有寒热不解者，此脉阴阳为和平，虽剧必愈。其脉浮而汗出如流珠者，阳 \n气衰也。脉瞥瞥如羹上珠者，阳气微也。脉萦萦如蜘蛛丝者，阳气衰也。脉绵绵如泻漆之绝者，亡 \n其血也。其脉沉者，荣气微也。若脉浮大者，气实血虚也。脉微缓者，为欲愈也。阳脉浮，阴脉弱 \n者，为血虚，血虚则筋急也。脉微弱而恶寒者，此阴阳俱虚，不可更发汗、更吐、更下也。阴证无 \n脉，温之而脉微续者生，暴出者死。阴病见阳脉者生，阳病见阴脉者死。 \n《论》曰∶寸脉微，名曰阳不足，阴气上入于阳中，则洒淅恶寒也。尺脉微，名曰阴不足，阳 \n气下陷入阴中，则发热也。寸口脉微而涩，微者卫气不行，涩者荣气不足。卫气衰，面色黄，荣气 \n不足，面色青。荣为根，卫为叶，荣卫俱微，则根叶枯槁，而寒栗、咳逆、唾腥、吐涎沫也。 \n《论》曰∶紧脉从何而来？曰∶假令亡汗若吐，以肺里寒，故令脉紧也。假令咳者，坐饮冷水 \n，故令脉紧也。假令下痢，以胃中虚冷，故令脉紧也。按此言紧者，即弦搏不软之谓，盖单言其紧 \n，而无滑数之意， \n乃阳明胃气受伤之脉，故主为阴寒之证。若紧而兼数，则必以外邪所致。 \n愚按∶浮为在表，沉为在里，此古今相传之法也。然沉脉亦有表证，此阴实阳虚，寒胜者然也 \n。浮脉亦有里证，此阳实阴虚，水亏者然也。故凡欲察表邪者，不宜单据浮沉，只当以紧数与否为 \n辨，方为的确。盖寒邪在表，脉皆紧数，紧数甚者邪亦甚，紧数微者邪亦微，紧数浮洪有力者，邪 \n在阳分，即阳证也，紧数浮沉无力者，邪在阴分，即阴证也。以紧数之脉而兼见表证者，其为外感 \n无疑，即当治从解散。然内伤之脉，亦有紧数者，但内伤之紧，其来有渐，外感之紧，发于陡然， \n以此辨之，最为切当。其有似紧非紧，但较之平昔，稍见滑疾而不甚者，亦有外感之证，此其邪之 \n轻者，或以初感而未甚者，亦多见此脉，是又不可不兼证而察之也。若其和缓而全无紧疾之意，则 \n脉虽浮大，自非外邪之证。 \n按陶节庵曰∶夫脉浮当汗，脉沉当下，固其宜也。然其脉虽浮，亦有可下者，谓邪热入腑，大 \n便难也，设使大便不难，岂敢下乎？其脉虽沉，亦有可汗者，谓少阴病，身有热也，设使身不发热 \n，岂敢汗乎？若此之说，可见沉有表，而浮亦有里也。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>风寒辨（五）\n\n属性：凡病伤寒者，本由寒气所伤，而风即寒之帅也。第以风寒分气令，则风主春而东，寒主冬而北 \n；以风寒分微甚，则风属阳而浅，寒属阴而深。然风送寒来，寒随风入，透骨侵肌，本为同气，故 \n凡寒之浅者，即为伤风，风之深者，即为伤寒；而不浅不深，半正半邪之间者，即为疟疾∶其有留 \n于经络，而肢体疼痛者，则为风痹。然则伤风也，伤寒也，疟疾、风痹也，皆风寒之所为也。观《灵 \n枢·九宫八风篇》及岁露论所载，俱甚言虚邪贼风之为害，口问篇言风成为寒热，此皆指风为寒邪 \n也。即如冬伤于寒者，宜乎其为伤寒也，若春夏秋三时之感冒，则孰非因寒，亦孰非因风而入之。 \n故仲景曰∶凡伤寒之病，多从风寒得之，始因表中风寒，入里则 \n不消矣，未有温覆而当，不消散者，岂非风寒本为同气乎。《内经》曰∶谨候虚风而避之。故圣人 \n日避虚邪之道，如避矢石然，邪弗能害，此之谓也，此杜渐防微之道也。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>伤寒三证（六）\n\n属性：夫伤寒为病，盖由冬令严寒，以水冰地裂之时，最多杀厉之气，人触犯之而实时病者，是为正 \n伤寒，此即阴寒直中之证也。然惟流离穷困之世多有之，若时当治平，民安饱暖，则直中之病少见， \n此伤寒之一也。其有冬时感寒，不即病者，寒毒藏于营卫之间，至春夏时，又遇风寒，则邪气应时 \n而动，故在春则为温病，在夏则为暑病。是以辛苦之人，春夏多温热病者，皆由冬时触寒所伤，故 \n随气传变，本非即病正伤寒之属，所当因其寒热而随证调治之，此伤寒之二也。又有时行之气者， \n如春时应暖而反寒，夏时应热而反凉，秋时应凉而反热，冬时应寒而反温，此非其时而有其气，是 \n以一岁之中，长幼之病多相似者，是实时行之病，感冒虚风不正之气，随感随发，凡禀弱而不慎起 \n居多劳倦者多犯之，此伤寒之三也。凡此三者，皆伤寒之属，第其病有不同，治有深浅，苟不能辨 \n，则必致误人。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>六经证（七）\n\n属性：太阳经病，头项痛，腰脊强，发热恶寒，身体痛，无汗，脉浮紧。以太阳经脉由脊背连风府， \n故为此证，此三阳之表也。 \n阳明经病，为身热，目疼，鼻干，不眠，脉洪而长。以阳明主肌肉，其脉挟鼻络于目，故为此 \n证，此三阳之里也。 \n少阳经病，为胸胁痛，耳聋，寒热，呕而口苦，咽干目眩，脉弦而数。以少阳之脉循胁肋，终 \n于耳，故为此证。此二阳三阴之间也。由此渐入三阴，故为半表半里之经。 \n太阴经病，为腹满而吐，食不下，嗌干，手足自温，或自利腹痛不渴，脉沉而细。以太阴之脉 \n布胃中；络于嗌，故为此证。 \n少阴经病，为舌干口燥，或自利而渴，或欲吐不吐，或引衣蜷卧，心烦，但欲寐，其脉沉。以 \n少阴之脉贯肾络于肺，系舌本，故为此证。 \n厥阴经病，为烦满囊缩，或气上撞心，心中疼热，消渴，饥而不欲食，食即吐蛔，下之利不止， \n脉沉而弦。以厥阴之脉循阴器而络于肝，故为此证。 \n成无己曰∶热邪自太阳传至太阴，则腹满而嗌干，未成渴也。传至少阴，则口燥舌干而渴，未 \n成消也。传至厥阴而成消渴者，热甚能消水故也。凡饮水多而小便少者，谓之消渴。肝居下部，而 \n邪居之，则木火相犯，所以邪上撞心。木邪乘土，则脾气受伤，所以饥不欲食，食即吐蛔。脾土既 \n伤，而复下之，则脾气愈虚，所以痢不止。 \n正阳明腑病者，由表而传里，由经而入腑也。邪气既深，故为潮热自汗，谵语发渴，不恶寒， \n反恶热，揭去衣被，扬手掷足，或发斑黄狂乱，五六日不大便，脉滑而实。此实热已传于内，乃可 \n下之。若其脉弱无神，或内无痞满实坚等证，又不可妄行攻下。 \n仲景曰∶尺寸俱浮者，太阳受病也，当一二日发。尺寸俱长者，阳明受病也，当二三日发。尺 \n寸俱弦者，少阳受病也，当三四日发。此三阳皆受病，未入于腑者，可汗而已。尺寸俱沉细者，太 \n阴受病也，当四五日发。尺寸俱沉者，少阴受病也，当五六日发。尺寸俱微缓者，厥阴受病也，当 \n六七日发。此三阴俱受病，已入于腑者，可下而已。 \n成无己注曰∶三阳受邪，为病在表，法当汗解，然三阳亦有便入腑者，入腑则宜下，故云未入 \n于腑者，可汗而已。三阴受邪，为病在里，于法当下，然三阴亦有在经者，在经则宜汗，故云已入 \n于腑者，可下而已。 \n太阳证似少阴者，以其发热恶寒，而脉反沉也。少阴证似太阳者，以其恶寒脉沉，而反发热也 \n。仲景曰∶ \n太阳病，发热头痛，脉反沉，身体疼痛，若不瘥者，当救其里，宜四逆汤。少阴病，始得之，反发 \n热，脉沉者，宜麻黄附子细辛汤。 \n按此二证，谓病在太阳，其脉当浮，而反沉者，因正气衰弱，里虚而然，故当用四逆汤，此里 \n虚不得不救也。病在少阴，证当无热，而反热者，因寒邪在表，犹未传里，故当用麻黄附子细辛汤 \n，此表邪不得不散也。此二证者，均属脉沉发热，但其有头疼，故为太阳病，无头疼，故为少阴病。 \n第在少阴而反发热者，以表邪浮浅，可以汗解，其反犹轻；在太阳而反脉沉者，以正气衰微，难施 \n汗下，其反为重。由此观之，可见阳经有当温里者，故以生附配干姜，补中自有散意；阴经有当发 \n表者，故以熟附配麻黄，发中亦有补焉。此仲景求本之治，其他从可知矣。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>传经辨（八附合病并病义）\n\n属性：伤寒传变，不可以日数为拘，亦不可以次序为拘。如《内经》言一日太阳，二日阳明，三日少 \n阳之类，盖言传经之大概，非谓凡患伤寒者，必皆如此也。盖寒邪中人，本无定体，观陶节庵曰∶ \n风寒之国中人也无常，或入于阴，或入于阳，非但始太阳、终厥阴也。或自太阳始，日传一经，六 \n日至厥阴，邪气衰不传而愈者，亦有不罢再传者，或有间经而傅者，或有传至二三经而止者，或有 \n始终只在一经者，或有越经而传者，或有自少阳、阳明而入者，或有初入太阳，不作郁热，便入少 \n阴而成真阴证者。所以凡治伤寒，不可拘泥，但见太阳证，便治太阳，但见少阴证，便治少阴，但 \n见少阳、阳明证，便治少阳、阳明，此活法也。又有合病、并病之证。曰合病者，两经或三经齐病 \n，不传者为合病。并病者，一经先病未尽，又过一经者，为并病。所以有太阳阳明合病，有太阳少 \n阳合病，有阳明少阳合病，有三阳合病。三阳若与三阴合病，即是两感，所以三阴无合并例也。即 \n仲景亦曰∶日数虽多，但见表证而脉浮紧者，犹宜汗之；日数虽少，但见里证而脉沉实者，犹宜下 \n之，诚为不易之论。故不可执定日数，谓一二日宜发表，三四日宜和解，五六日即宜下，若或不知 \n通变，因致误人者多 \n矣。故必真知其表邪未解，则当汗之，真知其胃邪已实，方可下之，真知其阴寒邪胜，自宜温之， \n真知其邪实正虚，客主不敌，必须补之。但能因机察变，原始要终而纤悉无遗者，方是活人高手。 \n仲景曰∶伤寒一日，太阳受之，脉若静者为不传；颇欲吐，若躁烦，脉数急者，为传也。伤寒 \n六七日，无大热，其人躁烦者，此为阳去入阴故也。伤寒二三日，阳明、少阳证不见者，为不传 \n也。伤寒三日，三阳为尽，三阴当受邪，其人反能食而不呕，此为三阴不受邪也。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>阳证阴证辨（九）\n\n属性：凡治伤寒，须先辨阳证阴证。若病自三阳不能解散，而传入三阴，则寒郁为热，因成阳证。盖 \n其初病，必发热头痛，脉浮紧，无汗，以渐而深，乃入阴经。此邪自阳分传来，愈深则愈热，虽在 \n阴经，亦阳证也。其脉必沉实有力，其证必烦热炽盛，此当攻里，或消或下，随宜而用。若内不有 \n热，安得谓之阳证乎？若初起本无发热头痛等证，原不由阳经所传，而径入阴分者，其证或厥冷， \n或呕吐，或腹痛泻利，或畏寒不渴，或脉来沉弱无力，此皆元阳元气之不足，乃为真正阴证。经曰 \n∶发热恶寒发于阳，无热恶寒发于阴。此以传经不传经而论阴阳也。阴阳之治，又当辨其虚实如下∶ \n一、治伤寒，凡阳证宜凉宜泻，阴证宜补宜温，此大法也。第以经脏言阴阳，则阴中本有阳证， \n此传经之热邪也。以脉证言阴阳，则阳中最多阴证，此似阳之虚邪也。惟阴中之阳者易辨，而阳中 \n之阴者为难知耳。如发热狂躁，口渴心烦，喜冷，饮水无度，大便硬，小便赤，喉痛口疮，声粗气 \n急，脉来滑实有力者，此真阳证也。其有身虽热，而脉来微弱无力者，此虽外证似阳，实非阳证。 \n观陶节庵曰∶凡发热面赤烦躁，揭去衣被，唇口赤裂，言语善恶不避亲疏，虚狂假斑，脉大者，人 \n皆不识，认作阳证，殊不知阴证不分热与不热，须凭脉下药、至为切当。不问脉之浮沉、大小，但 \n指下无力，重按全无，便是阴脉，不可与凉药，服之必死，急与五积散，通解表里之寒，甚者必须 \n加姜附以温之。又曰∶病自阳分传入三阴者，俱是脉沉，妙在指下有力无力中 \n分，有力者为阳，为实为热，无力者为阴，为虚为寒，此节庵出人之见也。然以余观之，大都似阳 \n非阳之证，不必谓其外热、烦躁、微渴、戴阳之类，即皆为阴证也，但见其元阳不足，而气虚于中 \n，虽有外热，即假热耳，设用清凉消耗，则中气愈败，中气既败，则邪气愈强，其能生乎？故凡遇 \n此等证候，必当先其所急。人知所急在病，而不知所急在命，元气忽去，疾如绝弦，呼吸变生， \n挽无及矣。治例另列后卷。 \n一、伤寒纲领，惟阴阳为最，此而有误，必致杀人。然有纯阳证，有纯阴证，是当定见分治也 \n。又有阴阳相半证，如寒之即阴胜，热之即阳胜，或今日见阴，而明日见阳者有之，今日见阳，而 \n明日变阴者亦有之，其在常人最多此证，盘珠胶柱，惟明哲者之能辨也。然以阴变阳者多吉，以阳 \n变阴者多凶，是又不可不察。 \n凡病患开目喜明，欲见人，多谈者属阳；闭目喜暗，不欲见人，懒言者属阴。 \n《论》曰∶夫阳盛阴虚，汗之则死，下之则愈；阳虚阴盛，汗之则愈，下之则死。又曰∶桂枝 \n下咽，阳盛则毙，承气入胃，阴盛以亡。按∶此阴阳二字，乃以寒热为言也。阳盛阴虚，言内热有 \n余，而外寒不甚也。夫邪必入腑，然后作热，热实于内，即阳盛也，故再用温热以汗之，则死矣。 \n阳虚阴盛，言寒邪有余，而蓄热未深也。夫邪中于表，必因风寒，寒束于外，即阴盛也，故妄用沉 \n寒以下之，则死矣。所以阳盛者用桂枝则毙，阴盛者用承气则亡。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>三阳阳明证（十）\n\n属性：仲景曰∶病有太阳阳明，有正阳阳明，有少阳阳明，何谓也？答曰∶太阳阳明者，脾约是也。 \n正阳阳明者，胃家实也。少阳阳明者，发汗、利小便，胃中躁烦实，大便难是也。问曰∶何缘得阳 \n明病？答曰∶太阳病发汗，若下，若利小便，此亡津液，胃中干燥，因转属阳明，内实，大便难， \n此名阳明也。问曰∶阳明病外证云何？ \n答曰∶身热汗自出，不恶寒反恶热也。 \n按∶此三阳阳明之证，皆自经传腑，胃家之实证也。曰太阳阳明者，邪自太阳传入于胃，其名 \n脾约，以其小便数，大便硬也。正阳阳明者，邪自阳明本经传入于腑，而邪实于胃也。少阳阳明者 \n，邪自少阳传入于胃也。胃为腑者，犹府库之府，府之为言聚也。以胃本属土，为万物所归，邪入 \n于胃，则无所复传，郁而为热，此由耗亡津液，胃中干燥，或三阳热邪不解，自经而腑，热结所成 \n，故邪入阳明胃腑者，谓之实邪。土气为邪，旺于未申，所以日晡潮热者，属阳明也。《论》曰∶ \n潮热者实也，是为可下之证。又曰∶潮热者，此外欲解也，可攻其里焉。又曰∶其热不潮，不可与 \n承气。此潮热属胃可知也。然潮热虽为可攻，若脉浮而紧，或小便难，大便溏，身热无汗，此热邪 \n未全入腑，犹属表证，仍当和解。若邪热在表而妄攻之，则祸不旋踵矣。 \n成无己曰∶胃为水谷之海，主养四傍，故四傍有病，皆能传入于胃，入胃则更不复传。如太阳 \n病传之入胃，则不更传阳明；阳明病传之入胃，则不更传少阳；少阳病传之入胃，则不更传三阴也。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>两感（十一）\n\n属性：病两感于寒者，一日则太阳与少阴表里俱病，凡头痛发热恶寒者邪在表，口干而渴者邪在里。 \n二日则阳明与太阴表里俱病，身热目痛、鼻干不眠者邪在表，腹满不欲食者邪在里。三日则少阳与 \n厥阴表里俱病，耳聋胁痛、寒热而呕者邪在表，烦满、囊缩而厥、水浆不入邪在里。凡两感者，或 \n三日，或六日，营卫不行，脏腑不通，昏不知人，胃气乃尽，故当死也。若此两感，虽为危证，然 \n不忍坐视，其于拯溺救焚之计所不可免，但当细察其证，亦自有缓急可辨。若三阳之头痛身热，耳 \n聋胁痛，恶寒而呕，此在表者，不得不解于外。其三阴之腹满口渴，囊缩谵语，此在里者，不得不 \n和其中。若其邪自外入，而外甚于里者，必当以外为主治，而兼调其内。若其邪因虚袭，而元气不 \n支者，速宜单顾根本，不可攻邪，但使元阳不败，则强敌亦将自解，其庶几乎有，可望也。此证变 \n态非常，故不可凿言方治。 \n按∶门人钱祯曰∶两感者，本表里之同病，似若皆以外感为言也，而实有未必尽然者，正以外 \n内俱伤，便是两感。今见有少阴先溃于内，而太阳继之于外者，即纵情肆欲之两感也。太阴受伤于 \n里，而阳明重感于表者，即劳倦竭力，饮食不调之两感也。厥阴气逆于脏，少阳复病于腑者，即七 \n情不慎，疲筋败血之两感也。人知两感为伤寒，而不知伤寒之两感，内外俱困，病斯剧矣。但伤有 \n重轻，医有知不知，则死生系之。或谓两感证之不多见者，盖亦见之不广，而义有未达耳。其于治 \n法，亦在乎知其由而救其本也。此言最切此病，诚发人之未发，深足指迷，不可不录。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>表里辨（十二）\n\n属性：阳邪在表则表热，阴邪在表则表寒。阳邪在里则里热，阴邪在里则里寒。邪在半表半里之间而 \n无定处，则往来寒热。邪在表则心腹不满，邪在里则心腹胀痛。邪在表则呻吟不安，邪在里则躁烦 \n闷乱。邪在表则能食，邪在里则不能食。不欲食者，邪在于表里之间，未至于不能食也。邪在表则 \n不烦不呕，邪在里则烦满而呕。凡初见心烦喜呕，及胸膈渐生痞闷者，邪在表方传里也，不可攻下 \n。凡病本在表，外证悉具，而脉反沉微者，以元阳不足，不能外达也，但当救里，以助阳散寒为上 \n策。前卷传忠录中有辨，当互阅之。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>寒热辨（十三）\n\n属性：邪气在表发热者，表热里不热也，宜温散之。邪气在里发热者，里热甚而达于外也，宜清之。 \n阳不足，则阴气上入阳中而为恶寒，阴胜则寒也，宜温之。阴不足，则阳气陷入阴中而为发热 \n，阳胜则热也，宜清之。 \n寒热往来者，阴阳相争，阴胜则寒，阳胜则热也。盖热为阳，寒为阴，表为阳，里为阴，邪之 \n客于表者为寒，邪与阳相争则为寒栗；邪之传于里者为热，邪与阴相争则为热躁；其邪在半表半里 \n之间者，外与阳争则为 \n寒，内与阴争则为热，或表或里，或出或入，是以寒热往来，此半表里之证也。故凡寒胜者必多寒， \n热胜者必多热，但审其寒热之势，则可知邪气之浅深也。 \n经曰∶阳微则恶寒，阴弱则发热。 \n仲景曰∶发热恶寒者，发于阳也。无热恶寒者，发于阴也。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>论汗（十四）\n\n属性：仲景《论》曰∶寸口脉浮而紧，浮则为风，紧则为寒，风则伤卫，寒则伤荣，荣卫俱病，骨节 \n烦疼，当发其汗也。 \n曰∶三阳皆受病，未入于府者，可汗而已。详见前六经证中。 \n曰∶太阳病，脉浮紧，无汗发热，身疼痛，八九日不解，表证仍在者，此当发其汗。按此一证， \n虽以太阳经为言，然阳明、少阳日久不解者，亦仍当汗散，但太阳为三阳之表，而主通身之外证，故特举 \n太阳为言也。 \n曰∶太阳病，头痛发热，身疼腰痛，骨节疼痛，恶风无汗而喘者，麻黄汤主之。 \n曰∶脉浮而数者，可发汗，宜麻黄汤主之。 \n曰∶太阳与阳明合病，喘而胸满者，邪在表也，不可下，宜麻黄汤主之。 \n曰∶阳明病，脉浮，无汗而喘者，发汗则愈，宜麻黄汤主之。 \n曰，太阳病，项背强几几，无汗恶风者，宜葛根汤主之。 \n曰∶太阳与阳明合病者，必自下痢，葛根汤主之。 \n曰∶太阳中风，脉浮紧，发热恶寒，身疼痛，不汗出而烦躁者，大青龙汤主之。 \n曰∶太阳病，发热汗出，恶风脉缓者，名为中风。太阳病，头痛发热，汗出恶风者，桂枝汤主 \n之。 \n曰∶太阳病，外证未解，脉浮弱者，当以汗解，宜桂枝汤。 \n曰∶太阳病，脉迟，汗出多，微恶寒者，表证未解也，可发汗，宜桂枝汤。 \n曰∶病如疟状，日晡所发热者，属阳明也。脉浮虚者，当发汗，宜桂枝汤。 \n曰∶太阴病，脉浮者，可发汗，宜桂枝汤。 \n曰∶厥阴证，有下痢，腹胀满，身体疼痛者，先温其里，乃攻其表，温里四逆汤，攻表桂枝汤。 \n曰∶下痢后，身疼痛，清便自调者，急当救表，宜桂枝汤发汗。按此以身疼痛者为表证，故当 \n散之。 \n曰∶伤寒发汗解，半日许复烦，脉浮数者，可更发汗，宜桂枝汤主之。 \n曰∶少阴病，始得之，反发热，脉沉者，麻黄附子细辛汤主之。按∶此证脉虽沉而身反热者， \n正乃阴经之表证也，故宜用此温散。 \n曰∶太阳病不解，转入少阳，胁下硬满，干呕不能食，往来寒热，脉沉紧者，与小柴胡汤。 \n曰∶呕而发热者，小柴胡汤主之。 \n曰∶阳明病，发潮热，大便溏，小便自可，胸胁满者，小柴胡汤主之。 \n曰∶阴证不得有汗，今头汗出，故知非少阴也，可与小柴胡汤。 \n曰∶二阳并病，太阳初得病时，发其汗，汗出不彻，因转属阳明，续自微汗出，不恶寒。若太 \n阳病证不罢者，不可下，下之为逆，如此可小发汗。 \n按∶仲景表汗之条，缕悉尚多，今但述其切要者，凡二十四证，以见其宜否之法，而大意可得 \n也。第其所用汗剂，不曰麻黄，则曰桂枝，此寒邪初感，温散之妙法也。今后人以麻黄、桂枝为异 \n物而不敢用，而复有强为之释者，谓此在仲景乃为隆冬直中阴寒者设耳，而不知四时阴胜之邪，皆 \n最宜者也。呜呼，仲景之下，再无仲景，可见医中之品矣。 \n一、各经表证，凡有汗出不彻者，皆未足言汗。盖邪未尽去，其人必身热不退，而仍觉躁烦，或 \n四体酸疼， \n坐卧有不安者，以汗出不彻故也。何从知之？但诊其脉紧不退，及热时干燥无汗者，即其证也，仍 \n宜汗之。如果汗透而热仍不退，或汗后身热愈甚者，是即所谓阴阳交，魂魄离，大凶之兆也。 \n一、凡汗之不彻者，其故有三∶如邪在经络筋骨，而汗出皮毛者，此邪深汗浅，卫解而营不解， \n一不彻也；或以十分之邪，而去五分之汗，此邪重汗轻，二不彻也；或寒邪方去，犹未清楚，遽起 \n露风，而因虚复感，此新旧相踵，三不彻也。凡遇此者，当辨其详，而因微甚以再汗之。 \n一、凡既愈复热者，其故有四∶或以邪气方散，胃气未清，因而过食者，是为食复，此其一也； \n或以表邪方解，原不甚虚，有过慎者，辄加温补，是误补而复，此其二也。若此二者，所谓食入于 \n阴，长气于阳，以致胃气复闭，阳邪复聚而然，表邪既复，仍宜汗也。又或有以新病方瘳，不能调 \n摄，或劳伤脾阴，因而复热者，是名劳复，此其三也；或不慎房室，因而再感者，是名女劳复，此 \n其四也。若此二者，所谓阴虚者阳必凑之而然，此则或从补，或从汗，当因变制宜，权其缓急，而 \n治分虚实也。 \n《论》曰∶伤寒瘥后，更发热者，小柴胡汤主之。脉浮者，宜汗解之。脉沉实者，宜下解之。 \n一、取汗之法，当取于自然，不宜急暴，但服以汤剂，盖令温暖，使得津津微汗，稍令久之，则 \n手足俱周，遍身通达，邪无不散矣。若一时逼之，致使如淋如洗，则急遽间卫气已达，而营气未周 \n，反有不到之处，且恐大伤元气，非善法也。余尝见有子病者，其父母爱惜之甚，欲其速愈，且当 \n温暖之令，覆以重被，犹恐不足，而以身压其上，子因热极呼叫，其父母曰∶犹未也，须再出些方 \n好。及许久放起，竟致亡阳而毙之。是但知汗出何妨，而不知汗之杀人，此强发之鉴也。又有邪本 \n不甚，或挟虚、年衰感邪等证，医不能察，但知表证宜解，而发散太过；或误散无效，而屡散不已 \n，因而即被其害者有之；或邪气虽去，遂致胃气大伤，不能饮食，而羸惫不振者有之，此过汗之戒 \n也。凡发汗太过，一时将致亡阳，或身寒而栗，或气脱昏沉等候，速宜煎独参汤一两许饮之，或甚 \n者以四味回阳饮速为挽回，庶可保全，否则恐致不救。 \n一、脉有忌汗者，如《伤寒论》曰∶太阳病，发热恶寒，热多寒少，脉微弱者，此无阳也，不 \n可发汗。弦为阳运，微为阴寒，上实下虚，意欲得温。微弦为虚，不可发汗，发汗则寒栗，不能自 \n还。伤寒四五日，脉沉而喘满，沉为在里，不可汗。汗亡津液，必大便难而谵语。少阴病，脉微， \n不可发汗，以亡阳故也。伤寒，脉微而恶寒者，此阴阳俱虚，不可更发汗，更吐下也。尺脉弱而无 \n力者，切不可汗下。尺中迟者，不可发汗，以荣气不足，血少故也。 \n景岳子曰∶按以上忌汗诸脉，可见仲景大意，故凡治伤寒，但见脉息微弱，及沉细无力者，皆 \n不可任意发汗。然欲去外邪，非汗不可，而仲景云脉微弱者不可发汗，夫脉弱非阳，既不可用寒凉 \n，而寒邪在表，又不可用攻下，然则舍汗之外，又将何法以治此表邪乎？不知温中即可以散寒，而 \n强主即可以逐寇，此仲景之意，岂不尽露于言表，而明悟者当心会之矣。且凡病外感而脉见微弱者 \n，其汗最不易出，其邪最不易解，何也？正以元气不能托送，即发亦无汗，邪不能解，则愈发愈虚 \n，而危亡立至矣。夫汗本乎血，由乎营也，营本乎气，由乎中也，未有中气虚而营能盛者，未有营 \n气虚而汗能达者。脉即营之外候，脉既微弱，元气可知，元气愈虚，邪愈不解，所以阳证最嫌 \n阴脉，正为此也。故治此者，但遇脉息微弱，正不胜邪等证，必须速固根本，以杜深入，专助中气 \n，以托外邪，必使真元渐充，则脉必渐盛，自微细而至滑大，自无力而至有神，务令阴脉转为阳 \n脉，阴证转为阳证。斯时也，元气渐充，方是正复邪退，将汗将解之佳兆。故凡治表邪之法，有 \n宜发散者，有宜和解者，有宜调补营卫者。如果邪实而无汗，则发散为宜；有汗而热不除，则和解 \n为宜；元气虚而邪不能退，则专救根本，以待其自解自汗为宜。此逐邪三昧，万全之法也。今有庸 \n流，但见其外，不见其内，每不论证之阴阳，脉之虚实，但知寒凉可以退热，但知发散可以解表， \n不知元阳一败，则土崩瓦解，立见溃矣。反掌杀人，而终身不悟，是真下愚不移者也。若而人者， \n亦可谓之医乎？ \n证有忌汗者，如《伤寒论》曰∶当汗者，下之为逆；当下者，汗之为逆。下痢清谷，不可攻表 \n，汗出 \n必胀满，以重亡津液故也。汗家不可发汗。阳虚不得重发汗。衄家不可发汗。亡血家不可发汗。淋 \n家不可发汗，发汗必便血。咽喉干燥者，不可发汗。咽中闭塞，不可发汗，发汗则吐血，气欲绝。 \n身重心悸者，不可发汗。疮家虽身疼痛，不可发汗，发汗则痉。咳而小便利，若失小便者，不可发 \n汗，汗出则四肢厥逆冷。诸动气不可发汗。（动气义详后论下。） \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>论吐（十五）\n\n属性：仲景曰∶病患手足厥冷，脉乍紧者，邪结在胸中，心中满而烦，饥不能食者，病在胸中，当吐 \n之，宜瓜蒂散。病患手足厥冷，脉乍结，以客气在胸中，心下满而烦，饮食不能入者，病在胸中， \n当吐之。 \n曰∶病如桂枝证，头不痛，项不强，寸脉微浮，胸中痞硬，气上冲咽喉，不得息者，此为胸有 \n寒也，当吐之，宜瓜蒂散。少阴病，饮食入口则吐，心中温温欲吐，复不能吐，始得之，手足寒， \n脉弦迟者，此胸中实，不可下也，当吐之。若膈上有寒饮，干呕者，不可吐也，急温之，宜四逆汤 \n。按∶此二节，前节言胸有寒者，谓寒邪也，所以当吐；后节言膈上有寒饮，干呕者，谓中寒也， \n所以宜温。然则前节之言寒者，言寒邪之实，后节之言寒者，言胃气之虚，均谓之寒，而有虚实之 \n异。实者宜吐，吐则散也；虚而吐之，则胃气愈虚，病必更甚矣。此等要处，最当详察。 \n曰∶病胸上诸实，胸中郁郁而痛，不能食，欲使人按之，而反有涎唾，下痢日十余行，其脉反 \n迟，而寸脉微滑，此可吐之，吐之痢则止。 \n曰∶太阳病，吐之，但太阳病当恶寒，今反不恶寒，不欲近衣者，此为吐之内烦也。按∶此以 \n太阳证有不当吐而吐者，必邪热乘虚入胃，故致内烦也。 \n一、宿食在上脘者，当吐之。 \n一、凡用吐药，中病即止，不必尽剂也。 \n一、寸脉弱而无力者，切忌用吐。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>论下（十六）\n\n属性：《论》曰∶三阴皆受病，已入于府者，可下而已。此详义见前六经证。 \n曰∶脉浮而大，心下反硬，有热属脏者，攻之，不令发汗。按∶此以心下硬而热在脏，即脉虽 \n浮大者，病亦属里，故不宜发汗，而当攻内也。 \n曰∶伤寒不大便六七日，头痛有热者，与承气汤。按∶此以阳明内热而为头痛也，故可攻之。 \n曰∶阳明病，外已解而潮热者，可攻里也，手足 然而汗出者，此大便已硬也，大承气汤主之 \n。若汗虽多，而微发热恶寒者，表未解也，其热不潮，未可与承气。 \n曰∶阳明病，胃中有燥屎者，可攻之。病患不大便五六日，绕脐痛，烦躁，发作有时者，此有 \n燥屎也。 \n曰∶汗出谵语者，以有燥屎在胃中，此为风也，须下之，宜大承气汤。 \n曰∶阳明病，发热汗多者，热在里也，急下之，宜大承气汤。 \n曰∶阳明病，发汗不解，腹满痛者，邪在里也，急下之，宜大承气汤。 \n曰∶病腹中满痛者，此为实也，当下之。 \n曰∶腹满不减，减不足言，当下之，宜大承气汤。 \n曰∶伤寒六七日，结胸热实，脉沉而紧，心下痛，按之石硬者，或心下至少腹硬满而痛不可近 \n者，大陷胸汤主之。 \n曰∶阳明少阳合病，脉滑而数者，有宿食也，当下之，宜大承气汤。按∶此一条必须兼脉证而 \n察之，盖伤寒之脉滑数者多，若无胀痛等证，未必即为宿食，故不可单据滑数之脉，便认作可攻之 \n证。 \n曰∶若表已解而内不消，非大满，犹生寒热，则病不除也。按此一条言若非大满，而犹生寒热 \n者，是表 \n病犹不除也，尚不可下。 \n曰∶若表已解而内不消，大满大实坚，有燥屎，自可徐下之，虽四五日不能为祸也。若不宜下 \n而便攻之，内虚热入，协热遂利，烦躁诸变，不可胜数，轻者困笃，重者必死矣。按∶此一条言 \n外无表证，内有坚满，然后可下，正以见下不宜轻。轻下者，为祸不小也。 \n曰∶太阳病，热结耪胱，其人如狂，血自下，下者愈。若表未解者，不可攻，当先解表。表已 \n解，但少腹急结者，乃可攻之，宜桃仁承气汤。 \n一、凡伤寒当下者，不宜用丸药，以丸药不能涤荡热邪，而但能损正气也。又凡治伤寒热邪传里 \n者，服下药后，仍用盐炒麸皮一升许，将绢包于病患腹上，款款熨之，使药气得热则行，大便必易 \n通也。 \n一、脉有忌下者，如《伤寒论》曰∶伤寒脉微而恶寒者，此阴阳俱虚，不可更发汗，更吐，更下 \n也。寸口脉浮大，而医反下之，此为大逆。关脉弱，胃气虚有热，不可大攻之，热去则寒起。尺脉 \n涩弱无力者，不可下。大便硬者当下之，设脉迟缓者不可下，里气不实也。脉虚细者不可下。脉浮 \n者不可下。脉濡而弱，弱反在关，濡反在巅，弦反在上，微反在下。弦为阳运，微为阴寒，上实下 \n虚，意欲得温。微弦为虚，虚者不宜下也。脉浮而大，浮为气实，大为血虚，血虚为无阴，孤阳独 \n下阴部者，医以为热，而复用毒药攻其胃，此为重虚，客阳去有期，必下如污泥而死。脉濡而紧， \n濡则阳气微，紧则荣中寒，阳微卫中风，发热而恶寒，荣紧胃气冷，微呕心内烦。医谓有大热， \n解肌而发汗，亡阳虚烦躁，心下苦痞坚，表里俱虚竭，卒起而头眩，客热在皮肤，胀怏不得眠。不 \n知胃气冷，紧寒在关元，当温反下之，安可复追还。脉久数者，非外邪也，不可下之。脉细数者， \n非实邪也；不可下。结胸证，其脉浮大者，邪未入府也，不可下，下之则死。大抵伤寒最宜慎下， \n若 \n脉息无力，及表证未罢者，不可乱投汤剂，下之为逆。 \n一、证有忌下者，如太阳病外证未解，不可下，下之为逆。太阳与阳明合病，喘而胸满者，邪 \n在表也，不可下。阳明病，若微发热恶寒者，表未解也，不可下。阳明病，潮热，大便初硬后溏者 \n，不可攻。阳明病，腹微满，初头硬，后必溏者，非实热也，不可攻之。阳明病，其热不潮者，未 \n可与承气汤。阳明病，虽有潮热，而大便不硬者，不可与承气汤。不转失气者，其内不坚，慎不可 \n攻也。阳明病，心下硬满者，不可攻，攻之利遂不止者死。硬在心下者，其邪在胸膈，犹未入腑也 \n，故不可攻。脏结无阳证，不往来寒热，其人反静，舌上苔滑者，不可攻也。病欲吐者，不可下。 \n呕多，虽有阳明证，不可攻之。此呕多者，病在上焦，病在上而攻其下，取败之道也。阳明病，若 \n汗多，微发热恶寒者，外未解也，其热不潮，未可与承气汤。湿家下之，额上汗出，微喘，小便不 \n利者死，下痢不止亦死。阳明病，不能食，攻其热必哕，所以然者，胃中虚冷故也。以其人本虚， \n故攻其热必哕。阴强无阳者，虽其大便坚硬，亦不可下，下之则清谷腹满。阴阳俱虚，恶水者。若 \n下之，则里冷，不嗜食，大便完谷出。阳微者不可下，下之则心下痞硬。恶寒者，不可下。小便清 \n利者，火不盛也，不可下。诸四逆厥者，不可下。咽中闭塞者不可下。发汗多，亡阳谵语者不可下 \n。诸虚者不可下，下之则阳虚而生寒。仲景曰∶极寒反汗出，身必冷如冰，其有眼睛不慧，语言不 \n休，口虽欲言，舌不得前者皆死。阴虚水亏，虚烦虚躁者不可下，重亡其阴，万无生理矣。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>看目（十七）\n\n属性：夫治伤寒须观两目，或赤或黄，赤者为阳证，若兼六脉洪大有力，或躁而渴者，其热必甚，轻 \n则三黄石膏汤，重则大承气之类主之。 \n一、凡目色清白，而无昏冒闪烁之意者，多非火证，不可轻用寒凉。 \n一、眼眵多结者，必因有火。盖凡有火之候，目必多液，液干而凝，所以为眵，即如肺热甚则鼻 \n涕出，是 \n亦目液之类也。 \n一、目睛上视者，谓之戴眼，此属足太阳经之证。盖太阳为目之上网，而与少阴为表里，少阴之 \n肾气大亏，则太阳之阴虚血少，故其筋脉燥急，牵引而上。若直视不转者，尤为凶候。欲治此者， \n速当以培阴养血为主。今人不知，皆云为风，若用风药，则阴愈虚，血愈燥矣，其有不颠覆者，未 \n之有也。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>舌色辨（十八）\n\n属性：舌为心之官，本红而泽，凡伤寒三四日以后，舌上有苔，必自润而燥，自滑而涩，由白而黄， \n由黄而黑，甚至焦干，或生芒刺，是皆邪热内传，由浅入深之证也。故凡邪气在表，舌则无苔，及 \n其传里，则津液干燥而舌苔生矣。若邪犹未深，其在半表半里之间，或邪气客于胸中者，其苔不黑 \n不涩，止宜小柴胡之属以和之。若阳邪传里，胃中有热，则舌苔不滑而涩，宜栀子豉汤之属以清之 \n。若烦躁，欲饮水数升者，白虎加人参汤之类主之。大都舌上黄苔而焦涩者，胃腑有邪热也，或清 \n之，或微下之。《金匮要略》曰∶舌黄未下者，下之黄自去。然必大便燥实，脉沉有力而大渴者， \n方可下之。若微渴而脉不实，便不坚，苔不干燥芒刺者，不可下也。其有舌上黑苔而生芒刺者，则 \n热更深矣，宜凉膈散、承气汤、大柴胡之属，酌宜下之。若苔色虽黑滑而不涩者，便非实邪，亦非 \n火证，非惟不可下，且不可清也。此辨舌之概，虽云若此，然犹有不可概论者，仍宜详察如下。 \n按∶伤寒诸书皆云∶心为君主之官，开窍于舌。心主火，肾主水，黑为水色，而见于心部，是 \n为鬼贼相刑，故知必死。此虽据理之谈，然实有未然者。夫五行相制，难免无克，此其所以为病， \n岂因克为病，便为必死？第当察其根本何如也。如黑色连地，而灰黯无神，此其本原已败，死无疑 \n矣。若舌心焦黑，而质地红活，未必皆为死证。阳实者清其胃火，火退自愈，何虑之有。其有元气 \n大损，而阴邪独见者，其色亦黄黑，真水涸竭者，其舌亦干焦，此肾中水火俱亏，原非实热之证。 \n欲辨此者，但察其形气脉色，自有虚实可辨，而从 \n补从清，反如冰炭矣。故凡以焦黑干涩者，尚有非实非火之证。再若青黑少神而润滑不燥者，则无 \n非水乘火位，虚寒证也。若认此为火，而苦寒一投，则余烬随灭矣。故凡见此者，但当详求脉证， \n以虚实为主，不可因其焦黑，而执言清火也。伤寒固尔，诸证亦然。 \n新按∶余在燕都，尝治一王生，患阴虚伤寒，年出三旬，而舌黑之甚，其芒刺干裂，焦黑如炭 \n，身热便结，大渴喜冷，而脉则无力，神则昏沉。群医谓阳证阴脉，必死无疑。余察其形气未脱， \n遂以甘温壮水等药，大剂进之，以救其本，仍问用凉水以滋其标。盖水为天一之精，凉能解热，甘 \n可助阴，非若苦寒伤气者之比，故于津液干燥，阴虚便结，而热渴火盛之证，亦所不忌。由是水药 \n并进，前后凡用人参、熟地辈各一、二斤，附子、肉桂各数两，冷水亦一、二斗，然后诸证渐退， \n饮食渐进，神气俱复矣。但察其舌黑，则分毫不减，余甚疑之，莫得其解。再后数日，忽舌上脱一 \n黑壳，而内则新肉灿然，始知其肤腠焦枯，死而复活，使非大为滋补，安望再生。若此一证，特举 \n其甚者纪之，此外，凡舌黑用补而得以保全者，盖不可枚举矣。所以凡诊伤寒者，当以舌色辨表里 \n，以舌色辨寒热，皆不可不知也。若以舌色辨虚实，则不能无误，盖实固能黑，以火盛而焦也，虚 \n亦能黑，以水亏而枯也。若以舌黄、舌黑，悉认为实热，则阴虚之证，万无一生矣。 \n古按∶《金镜录》曰∶舌见全黑色，水克火明矣，患此者百无一治，治者审之。薛立斋曰，余 \n在留都时，地官主事郑汝东妹婿患伤寒得此舌，院内医士曾禧曰∶当用附子理中汤，人咸惊骇而止 \n。及其困甚治棺，曾与其邻复往视之，谓用前药犹有生意。其家既待以死，拼而从之，数剂而愈。 \n大抵舌黑之证，有火极似水者，即杜学士所谓薪为黑炭之意也，宜凉膈散之类以泻其阳；有水来克 \n火者，即曾医士所疗者是也，宜理中汤以消阴翳。又须以老生姜切平，擦其舌，色稍退者可治，坚 \n不退者不可治。 \n又按∶弘治辛酉，金台姜梦辉患伤寒，亦得此舌，手足厥冷，呃逆不止，众医犹作火治，几致 \n危殆，判院吴仁斋用附子理中汤而愈。夫医之为道，有是病必用是药，附子疗寒，其效可数，奈何 \n世皆以为必不可用之药， \n宁视人之死而不救，不亦哀哉！凡用药得宜，效应不异，不可便谓为百无一治而弃之也。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>饮水（十九）\n\n属性：凡伤寒饮水，因内水消竭，欲得外水自救，若大渴欲饮一升，止可与一碗，常令不足，不可太 \n过。若恣饮过量，使水停心下，则为水结胸，留于胃则为噎、为哕，溢于皮肤则为肿，蓄于下焦则 \n为癃，渗于肠间则为痢下，皆饮水太多之过也。又不可不与，又不可强与，故曰∶若还不与非其治 \n，强饮须教别病生也。 \n凡阳明病口燥，但欲 水而不欲咽者，以热在经，而里无热也，必将为衄，不可与凉药。 \n按∶饮水一证，本以内热极而阳毒甚者最其相宜，若似乎止宜实邪，不宜于虚邪也，而不知虚 \n证亦有不同。如阳虚无火者，其不宜水无待言也，其有阴虚火盛者，元气既弱，精血又枯，多见舌 \n裂唇焦，大渴喜冷，三焦如焚，二便闭结等证，使非藉天一之精，何以济然眉之急？故先宜以冰水 \n解其标，而继以甘温培其本，水药兼进，无不可也。其有内真寒，外假热，阴盛格阳等证，察其元 \n气，则非用甘温必不足以挽回，察其喉舌，则些微辛热又不可以近口。有如是者，则但将甘温大补 \n之剂，或单用人参煎成汤液，用水浸极冷而饮之，此以假冷之味，解上焦之假热，而真温之性，复 \n下焦之真阳，是非用水而实亦用水之意，余用此活人多矣，诚妙之甚者也。惟是假热之证，则证虽 \n热而脉则微，口虽渴而便则不闭者，此而欲水，必不可与，若误犯之，则其败泄元阳，为害不小， \n有不可不慎也。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>三阳阴证辨（二十）\n\n属性：足太阳膀胱经病，凡发热头痛，腰脊强，肩背痛，脉浮紧者，是皆太阳证也。若肩背畏寒，恶 \n心欲呕，或眼目无神，不欲见人，喜暗畏明，眼眶酸涩，或喜向壁卧，或戴眼上视，或头倾身痛， \n甚或颜色清白，隐见青 \n黑，或丹田无力，息短声微，气促而喘，或咽中闭塞，或角弓发痉，或小水清白，或失小便，或小 \n便短赤而内不喜冷，凡脉见浮空无力，或沉紧细弱者，皆太阳合少阴之阴证也。足阳明胃经之病， \n凡发热，头目痛，不得眠，脉长而数者，本皆阳明证也。若面鼻恶寒，面色清白，或鼻尖冷，口气 \n不热，或唇口青白微黑，或气短声微，鼻息不长，懒于言语，或戴阳面赤，昏沉困倦多眠，或烦躁 \n，面赤身热，虚狂假斑，脉反微细无力，或身虽发热，反欲得衣，或口渴不欲饮水，并水浆不入， \n或恶寒寒栗，恶心呕逆，或肉 心悸，或动气见于胸腹，或四肢无力，身重懒于举动，或手足自冷 \n，或肌肉之间以手按之，殊无大热，或大便不实，自利腹痛，凡脉见浮长无力，或短细结促者，皆 \n阳明合太阴之阴证也。足少阳胆经之病，凡发热，头耳牵痛，胁肋痛，往来寒热，脉见弦数者，本 \n皆少阳证也。若身虽微热，而时作时止，时多畏寒，或耳聋，或头运，或眼目羞涩，或多惊怯恐畏 \n，或呕苦吐酸，或恶心喜暖，或爪青筋急囊缩，或厥逆下痢，肠鸣小腹痛，凡脉见弦数无力，而沉 \n细微弱者，皆少阳合厥阴之阴证也。以上乃三阳经之阴证。阴证者，即阳虚之证也，皆大忌寒凉克 \n伐之药，妄用即死。余恐将来复有如李子建之流者，故特揭而出之，用为提醒后人之鉴云。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>再论阴证阳证及李子建《伤寒十劝》之害（二十一）\n\n属性：天地间死生消长之道，惟阴阳二气尽之，而人力挽回之权，亦惟阴阳二字尽之，至于伤寒一证 \n，则尤切于此，不可忽也。第伤寒之阴证阳证，其义有二，所谓二者，曰经有阴阳，证有阴阳也。 \n经有阴阳，则三阳为阳证，三阴为阴证。证有阴阳，则实热为阳证，虚寒为阴证。凡经之阴阳，则 \n有寒有热，故阳经亦有阴证，阴经亦有阳证。证之阴阳，则有假有真，故发热亦有阴证，厥逆亦有 \n阳证。此经自经，而证自证，乃伤寒中最要之纲领，不可混也。而今之医流，多不明此，故每致混 \n指阴阳，肆行克伐，杀人于反掌之间，而终身不悟，深为可慨。原其由然，非无所本，盖本于李子 \n建之《伤寒十劝》。《十劝》之中，惟八劝曰∶病已在里，不可发汗；九劝曰∶饮水不可过多；十 \n劝曰∶病后当忌饮食房劳；凡此三者，皆为得理，然亦人皆知之，无待其为劝矣。 \n此外七劝，则悉忌温补。 \n如一劝云∶伤寒头痛及身热，便是阳证，不可服热药。若此一说，乃悉以阳经之表病，认为内 \n热之阳证，治以寒凉，必杀人矣。观仲景治太阳经伤寒，头痛发热无汗者，用麻黄汤；头痛发热， \n汗出恶风者，用桂枝汤；太阳病，发热头痛，脉反沉，身体疼痛者，当救其里，用四逆汤；阳明病 \n，脉浮，无汗而喘者，出汗则愈，宜麻黄汤。凡此之类，岂非皆用热药，以治阳经之疼痛发热乎？ \n且凡寒邪之感人，必先入三阳之表，所以为头疼发热等证，使于此时，能用温散，则浅而且易。故 \n岐伯曰∶发表不远热，是诚神圣传心之旨，惟仲景知之，故能用温散如此，是岂果阳经之病，便是 \n阳证耶？经证不明，而戒用温热，最妄之谈，此其一也。 \n又二劝曰∶伤寒必须直攻毒瓦斯，不可补益。若据此说，则凡是伤寒，尽皆实证，而必无虚证矣 \n，何岐伯曰∶邪之所凑，其气必虚。又曰∶寒则真气去，去则虚，虚则寒搏于皮肤之间。又观仲景 \n论伤寒之虚证虚脉，及不可汗吐下者，凡百十余条，此外如东垣、丹溪、陶节庵辈，所用补中益气 \n，回阳返本，温经益元等汤，则其宜否温补，概可知矣。矧今之人，凡以劳倦七情，色欲过度，及 \n天禀薄弱之流，十居七八。使以此辈一旦因虚感邪，若但知直攻毒瓦斯，而罔顾元阳，则寇未逐而主 \n先伤，鼠未投而器先破，顾可直攻无忌乎？凡受斯害，死者多矣，妄谈之甚，此其二也。 \n又三劝曰∶伤寒不思饮食，不可服温脾药。据此一说，则凡见伤寒不食者，皆是实热证，而何 \n以仲景有曰∶阳明病，不能食，攻其热必哕，所以然者，胃中虚冷故也。又曰∶病患脉数，数为热 \n，当消谷引饮，而反吐者，以其发汗，令阳气微，膈气虚，脉乃数也。数为客热，不能消谷，以胃 \n中虚冷故也。又曰∶食谷欲呕者。属阳明也，吴茱萸汤主之。若此之类，岂非皆寒证之宜温者耶？ \n但伤寒之热证固不能食，而寒证之不食者尤多，以中寒而不温脾，则元阳必脱而死矣。此妄谈之三 \n也。 \n又四劝曰∶伤寒腹痛，亦有热证，不可轻服温暖药。据所云亦有热证，则寒证居多矣，寒痛既 \n多，则何不曰不可轻服寒凉药，而特以温暖为禁者何也？独不见仲景之治腹痛，有用真武汤者，有 \n用通脉四逆汤者，有用 \n四逆散加附子者。有曰手足厥冷，小腹满，按之痛者，此冷结膀胱关元也。使以此证而亦忌温暖， \n则寒在阴分，能无毙乎？此妄谈之四也。 \n再如五劝之伤寒自利，不可例服补药、暖药、止泻药，六劝之禁用艾火，七劝之手足厥冷，不 \n可例作阴证等说，总属禁热之谈，余亦不屑与之多辨，第拓取圣贤成法，明哲格言，再悉于此，用 \n救将来，是诚今日之急务也。因详考仲景《伤寒论》，见其所列三百九十七法，而脉证之虚寒者， \n一百有余；一百一十三方，而用人参者二十，用桂附者五十有余。又东垣曰∶实火宜泻，虚火宜补 \n。又薛立斋曰∶大凡元气虚弱而发热者，皆内真寒而外假热也。凡若此者，岂皆余之杜撰耶？岂子 \n建诸人一无所见耶？若无所见，胡可妄言？若有所见，胡敢妄言？今观彼十劝之中，凡禁用温补者 \n，居其八九，而绝无一言戒及寒凉，果何意哉。因致未学认为圣经，遂悉以阴证作阳证，悉以虚证 \n作实证，但知凉泻之一长，尽忘虚寒之大害。夫生民元气足者其几，能堪此潜消暗剥之大盗乎？嗟 \n！嗟！，何物匪才，敢言十劝，既不能搜罗训典，明析阴阳，又不能揣摩实虚，原终要始，总弗求 \n阳德之亨，全不识冰霜之至。后学人多被所愚，致造终身之孽，无辜者阴受其戮，讵思冤魄可怜。 \n余言及此，能不转慈悲为愤怒，借笔削为箴规，独思深诋先辈，岂出本心，亦以目击多艰，难胜呜 \n咽，实亦有为而云然。盖以久感之余，复有所触，适一契姻，向以中年过劳，因患劳倦发热，余为 \n速救其本，已将复元，忽遭子建之徒，坚执十劝以相抗，昧者见其发热，反为左袒，不数剂而遂以 \n有生之徒，置之死地。因并往日见闻，倍加伤惨，诚可痛可恨也。子建、子建，吾知多冤之积于尔 \n者久矣，故悉此论，以解尔此后之冤孽，尔若有知，尚知感否。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>论伤寒古治法（二十二）\n\n属性：凡伤寒治法，必当先知经络次序，如一日在太阳，则为发寒、头痛等证；二日在阳明，则为目 \n痛、鼻 \n干、不眠等证；三日在少阳，则为耳聋、胁痛、寒热、口苦等证；四日在太阴，则为腹满自利等证 \n；五日在少阴，则为舌干口燥等证；六日在厥阴，则为烦满囊缩等证，此伤寒传经之大概也。然病 \n有不同，证有多变，故不可以一定之法，凿凿为拘。今人有不知察变者，每按日按经，执方求治， \n则证多不合，益见其难矣。即如发热，无汗，头痛者，宜于发汗，本太阳经之证治也，然仲景曰∶ \n阳明病，外证云何？曰∶身热，汗自出，不恶寒，反恶热，此阳明之发热也；曰∶阳明病，反无汗 \n，而小便利，呕而咳，手足厥者，必苦头痛，此阳明之无汗头痛也；曰∶伤寒，脉弦细，头痛发热 \n者，属少阳，此少阳之头痛发热也。凡三阳皆为表证，而惟少阳则曰半表半里，不可发汗。然法曰 \n∶尺寸俱浮者，太阳受病也；尺寸俱长者，阳明受病也；尺寸俱弦者，少阳受病也，此三经皆受病 \n，未入于府者，可汗而已，岂非少阳亦所当汗乎？此三阳之治，宜乎若此。至于三阴，则亦有若此 \n者，如曰∶太阴病，脉浮者，可发汗，宜桂枝汤；曰∶少阴病，始得之，反发热，脉沉者，宜麻黄 \n附子细辛汤；曰∶厥阴证，下痢，腹胀满，身体疼痛者，先温其里，乃攻其表，温里四逆汤，攻表 \n桂枝汤，凡此皆三阴之发热，三阴之当汗者也。至于下证，则惟独少阳为半表半里之经，若不之， \n恐邪气乘虚内陷，故不可攻，其他五经，皆有下证。由此观之，则三阳何尝无里证，三阴何尝无表 \n证。故善治者，但见表邪未解，即当解表，若表证未解，不可攻里也；但见里证已具，即当攻里， \n若里证未实，尚宜和解也。或汗、或和、或下，但当随证缓急，而用得其宜，即古今画一之法也。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>论古法通变（二十三）\n\n属性：凡用药处方，最宜通变，不可执滞。观仲景以麻黄汤治太阳经发热头痛，脉浮无汗之伤寒，而 \n阳明病脉浮无汗而喘者亦用之；太阳与阳明合病，喘而胸满者亦用之，此麻黄汤之通变也。又如桂 \n枝汤，本治太阳经发热 \n汗出之中风，而阳明病如疟状，日晡发热，脉浮虚，宜发汗者亦用之；太阳病外证未解，脉浮弱， \n当以汗解者亦用之；太阴病，脉浮，可发汗者亦用之；厥阴证下痢，腹胀满，身疼痛，宜攻表者亦 \n用之，此桂枝汤之通变也。又如小柴胡汤，本治少阳经胁痛干呕，往来寒热之伤寒，而阳明病潮热 \n胸胁满者亦用之；阳明中风，脉弦浮大，腹满胁痛，不得汗，身面悉黄，潮热等证亦用之；妇人中 \n风，续得寒热，经水适断，热入血室，如疟状者亦用之，此小柴胡之通变也。由此观之，可见仲景 \n之意，初未尝逐经执方，而立方之意，多有言不能悉者，正神不可以言传也。所以有此法，未必有 \n此证，有此证，未必有此方。即仲景再生，而欲尽踵其成法，吾知其未必皆相合，即仲景复言，而 \n欲尽吐其新方，吾知其未必无短长。于戏！方乌足以尽变，变胡可以定方，但使学人能会仲景之意 \n，则亦今之仲景也，又何必以仲景之方为拘泥哉。余故曰∶用药处方，最宜通变，不当执滞也。虽 \n然，此通变二字，盖为不能通变者设，而不知斯道之理，又自有一定不易之要焉。苟不知要，而强 \n借通变为谈柄，则胡猜乱道，何匪经权，反大失通变之旨矣。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>麻黄桂枝辨（二十四）\n\n属性：按∶《伤寒论》曰∶太阳病，头痛，发热，恶寒，体痛，呕逆，脉阴阳俱紧，无汗而喘者，名 \n为伤寒，麻黄汤主之。曰∶太阳病，头痛，发热，汗出，恶风，脉缓者，名为中风，桂枝汤主之。 \n此以无汗脉紧者为伤寒，故用麻黄汤；有汗脉缓者为中风，故用桂枝汤，是其辨也。又《论》曰∶ \n桂枝本为解肌，若其人脉浮紧，发热汗不出者，不可与也，常须识此，勿令误也。然何以又曰∶太 \n阳病外证未解，脉浮弱者，当以汗解，宜桂枝汤。阳明病，日晡所发热，脉虚浮者，宜发汗，发汗 \n宜桂枝汤，是岂桂枝为止汗者耶？但麻黄汤无芍药，而用麻黄，桂枝汤无麻黄，而用芍药，盖桂枝 \n性散，芍药性敛，以芍药从桂枝，则桂枝不峻，以桂枝从芍药，则芍药不寒。然以芍药之懦，终不 \n胜桂枝之勇，且芍药能滋调营气，适足为桂枝取汗之助，故桂枝汤亦是散剂，但麻黄汤峻， \n而桂枝汤缓耳。故凡寒邪深固者，恐服桂枝不能解表，则反以助热，所以脉紧无汗者，宜麻黄不宜 \n桂枝；若脉浮缓有汗，或浮弱者，以其风邪尚浅，宜桂枝不宜麻黄也。此麻黄汤为发表之第一，而 \n桂枝汤则解表之次者也。今时医不能察此，但闻汗不出者，不可与桂枝，便谓桂枝能止汗，误亦甚 \n矣，而不知止汗在芍药，不在桂枝也。但桂枝性温，能强卫气，如《内经》曰∶阴气有余，为多汗 \n身寒。仲景曰∶极寒反汗出者，此亡阳而汗也，助阳乃可以止汗，则正宜用桂枝矣。又《伤寒论》 \n以太阳病无汗脉紧者为伤寒，汗出脉缓者为中风，此风寒之辨也。然大青龙汤证治曰∶太阳中风， \n脉浮紧，发热恶寒，身疼痛，不汗出而烦躁者，大青龙汤主之。是岂非太阳中风亦有脉紧无汗者耶 \n？可见风之与寒，本不相远，但风邪浅而寒邪深耳，浅属阳而深属阴耳。且近见外感寒邪者，率 \n皆伤寒发热脉紧无汗等证，至于中风一证，谓其脉缓有汗，而复发热者，其病本不多见，即有之， \n亦必外因者少，而内因者多也。倘学人以风寒二字，及麻黄桂枝二汤，必欲分其阴阳同异，而执以 \n为辞，则失之远矣。本门前卷有风寒辨，宜并察之。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>论今时皆合病并病（二十五）\n\n属性：余究心伤寒已久，初见合病并病之说，殊有不明，而今始悉之。夫所谓合病者，乃二阳、三阳 \n同病，病之相合者也。并病者，如太阳先病不解，又并入阳明、少阳之类也。观仲景曰∶二阳并病 \n，太阳初得病时，发其汗，汗先出不彻，因转属阳明。若太阳病证不罢者，不可下。按此云转属阳 \n明，则自太阳而来可知也，云太阳病证不罢，则二经皆病可知也。凡并病者，由浅而深，由此而彼 \n，势使之必然也。此合病并病之义，而不知者皆以此为罕见之证，又岂知今时之病，则皆合病并病 \n耳。何以见之？盖自余临证以来，凡诊伤寒，初未见有单经挨次相传者，亦未见有表证悉罢，止存 \n里证者，若欲根据经如式求证，则未见有如式之病，而方治可相符者，所以令人致疑，愈难下手，是 \n不知合病并病之义耳。今列其大略如下∶ \n一、合病者，乃两经三经同病也。如初起发热恶寒头痛者，此太阳之证，而更兼不眠，即太阳 \n阳明合病也； \n若兼呕恶，即太阳少阳合病也。若发热不眠，呕恶者，即阳明少阳合病也。若三者俱全，便是三阳 \n合病。三阳合病者，其病必甚。 \n一、三阳与三阴本无合病，盖三阳为表，三阴为里，若表里同病，即两感也。故凡有阴阳俱病者 \n，必以渐相传而至，皆并病耳，此亦势所必至，非合病、两感之谓。 \n一、并病与合病不同，合病者，彼此齐病也；并病者，一经先病，然后渐及他经而皆病也。如太 \n阳先病，发热头痛，而后见目痛、鼻干不眠等证者，此太阳并于阳明也∶或后见耳聋胁痛，呕而口 \n苦等证者，此太阳并于少阳也；或后见腹满嗌干等证者，此太阳并于太阴也；或后见舌干口燥等证 \n者，此太阳并于少阴也；或后见烦满囊缩等证者，此太阳并于厥阴也。若阳明并于三阴者，必鼻干 \n不眠，而兼三阴之证。少阳并于三阴者，必耳聋呕苦，而兼三阴之证。阴证虽见于里，而阳证仍留 \n于表，故谓之并。凡患伤寒，而始终热有不退者，皆表邪之未解耳，但得正汗一透，则表里皆愈， \n岂非阴阳相并之病乎。今之伤寒率多并病，若明此理，则自有头绪矣。治此之法，凡并病在三阳者 \n，自当解三阳之表，如邪在太阳者，当知为阳中之表，治宜轻清；邪在阳明者，当知为阳中之里， \n治宜浓重；邪在少阳者，当知为阳中之枢，治宜和解。此虽解表之大法，然余仍有心法，详载《新 \n方八略》中。故或宜温散，或宜凉散，或宜平散，或宜补中而散，是又于阴阳交错之理，有不可不 \n参合而酌用者，皆治表之法也。至于病入三阴，本为在里，如太阴为阴中之阳，治宜微温；少阴为 \n阴中之枢，治宜半温；厥阴为阴中之阴，治宜大温，此阴证之治略也。然病虽在阴，而有兼三阳之 \n并病者，或其邪热已甚，则自宜清火；或其表尚未解，则仍当散邪，盖邪自外入，则外为病本，拔 \n去其本，则里病自无不愈者，此所以解表即能和中也。若表邪不甚，而里证为急，又当先救其里， \n盖表里之气，本自相关，惟表不解，所以里病日增，惟里不和，所以表邪不散，此所以治里亦能解 \n表也。但宜表宜里，或此或彼之间，则自有缓急先后一定不易之道，而非可以疑似出入者，要在乎 \n知病之薮，而独见其必胜之机耳，此又阴阳并病之治略也。惟是病既在阴，必关于脏，脏气为人之 \n根本，而死生系之。故凡诊阴证者，必当细察其虚实，而补泻寒热，弗至倒施，则今时 \n之治要，莫切乎此矣。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>治法（二十六）\n\n属性：凡治伤寒，不必拘于日数，但见表证，即当治表，但见里证，即当治里，因证辨经，随经施治 \n，乃为良法。若表邪未解，即日数虽多，但有表证而脉见紧数者，仍当解散，不可攻里也。若表邪 \n已轻，即日数虽少，但有里证而脉见沉实者，即当攻里，不可发表也。然此二者，一曰发表，一曰 \n攻里，皆以邪实者为言也。其有脉气不足，形气不足者，则不可言发言攻，而当从乎补矣。但补有 \n轻重，或宜兼补，或宜全补，则在乎明而慧者之用之如法耳。 \n一、伤寒但见发热恶寒，脉紧数，无汗，头项痛，腰脊强，或肢体酸软者，便是表证，不拘日 \n数多寡，即当解散，但于阴阳虚实，不可不预辨也，而于后开汗散方中择宜用之。 \n一、伤寒但见往来寒热，胁痛，口苦而呕，或渐觉耳聋，脉见弦数者，即少阳经半表半里之证 \n，治宜和解，以新方诸柴胡饮，及小柴胡汤之类，酌宜用之。然少阳之治有三禁，曰不可汗、吐、 \n下也。 \n一、伤寒如头痛、发热、恶寒表证之类悉除，反见怕热，躁渴谵语，揭去衣被，扬手掷足，斑 \n黄发狂，或潮热自汗，大便不通，小便短赤，或胸腹胀满疼痛，或上气喘促，脉实有力者，即是传 \n里之热证，不拘日数多少，即当清里。如果实邪内结，不得宣通，此必大为涤荡，庶使里通而表亦 \n通也。然必其胸腹胀满，肠胃燥结，而大满大实坚者，乃可攻之。故法曰∶痞满燥实坚，五者具而 \n后可下。又曰∶下不嫌迟。盖恐内不实而误攻之，则必致不救矣。 \n一、凡治伤寒，如时寒火衰，内无热邪而表不解者，宜以辛温热剂散之；时热火盛而表不解者 \n，宜以辛甘凉剂散之；时气皆平而表不解者，宜以辛甘平剂散之，此解散之要法也。盖人在气交之 \n中，随气而化，天地之气寒，则宜辛热，天地之气热，则宜辛凉，经文既以冬为伤寒，春为温病， \n夏为暑病，名既因时而易，则方亦不容不随时而更也。第以凉散之法，当知所辨，必其表里俱有热 \n证，方可兼用清凉，若身 \n表虽热，而内无热证者，此以表邪未解，因寒而为热也，不可妄用凉药、盖恐表寒未除， \n而内寒复至，以寒遇寒，则凝结不解，必将愈甚，经曰∶发表不远热，正此之谓也。且舍 \n时从证，尤为治伤寒紧要之法，此又不可不知常变。 \n一、凡暑热盛行，瘟疫大起，焦渴斑黄，脏腑如火，此则或用寒肃，以清其里，或用 \n寒散，以救其表，但当察表里而酌缓急之宜也。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>论虚邪治法（二十七）\n\n属性：凡伤寒治法，在表者宜散，在里者宜攻，此大则也。然伤寒死生之机，则全在虚实 \n二字，夫邪之所凑，其气必虚，故伤寒为患，多系乘虚而入者。时医不察虚实，但见伤寒， \n则动曰伤寒无补法，任意攻邪。殊不知可攻而愈者，原非虚证，正既不虚，邪自不能害之，及 \n其经尽气复，自然病退，故治之亦愈，不治亦愈，此实邪之无足卢也。惟是挟虚伤寒，则 \n最为可畏，使不知固本御侮之策，而肆意攻邪，但施孤注，则凡攻散之剂，未有不先入于 \n胃，而后达于经，邪气未相及，而胃气先被伤矣，即不尽脱，能无更虚？元气更虚，邪 \n将更入，虚而再攻，不死何待？是以凡患伤寒而死者，必由元气之先败，此则举世之通弊 \n也。故凡临证者，但见脉弱无神，耳聋手颤，神倦气怯，畏寒喜暗，言语轻微，颜色青白， \n诸形证不足等候，盒饭思顾元气。若形气本虚，而过散其表，必至亡阳；脏气本虚，而误 \n攻其内，必至亡阴，犯者必死。即如元气半虚，而邪方盛者，亦当权其轻重，而兼补以散， \n庶得其宜。若元气大虚，则邪气虽盛，亦不可攻，必当详察阴阳，峻补中气。如平居偶感阴 \n寒，邪未深入，但见发热身痛，脉数不洪，内无火证，素禀不足者，即当用理阴煎加柴 \n胡，或加麻黄，连进一二服，其效如神，此常用第一方也。此外诸证，如虚在阳分，则当 \n以四柴胡饮、补中益气汤，或八珍汤、理中汤、温胃饮之类，此温中自能发散之治也。若虚 \n在阴分，而液涸水亏，不能作汗，则当用补阴益气煎、三柴胡饮，或三阴煎、左归饮之类， \n此壮水制阳，精化为气之治也。若阴盛格阳，真寒假热者，则当以大补元煎、右 \n归饮、崔氏八味丸料之类，此引火归原之治也。其有阴盛阳衰之证，身虽发热，而畏寒不已 \n，或呕 \n恶，或泄泻，或背凉如冰，或手足厥冷，是皆阳虚之极，必用大温中饮，或理阴煎，不可疑也。若 \n果邪火热甚，而水枯干涸者，或用凉水渐解其热。表未解而固闭者，或兼微解，渐去其寒。若邪实 \n正虚，原有主客不敌之势，使但能保定根本，不令决裂，则邪将不战而自解。此中大有玄妙，余常 \n藉此而存活者，五十年来若干人矣，谨书之以为普济者之则。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>补中亦能散表（二十八）\n\n属性：夫补者所以补中，何以亦能散表？盖阳虚者，即气虚也，气虚于中，安能达表，非补其气，肌 \n能解乎？凡脉之微弱无力，或两寸短小而多寒者，即其证也，此阳虚伤寒也。阴虚者，即血虚也， \n血虚于里，安能化液，非补其精，汗能生乎？凡脉之浮芤不实，或两尺无根而多热者，即其证也， \n此阴虚伤寒也。然补则补矣，仍当酌其剂量，譬之饮酒者，能饮一勺，而与一升，宜乎其至于困也； \n使能饮一斗，而与一合，其真蚍蜉之撼大树耳。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>寒中亦能散表（二十九）\n\n属性：夫寒中者所以清火，何以亦能散表？盖阳亢阴衰者，即水亏火盛也，水涸于经，安能作汗？譬 \n之干锅赤裂，润自何来？但加以水，则郁蒸沛然，而气化四达。夫汗自水生，亦犹是也，如前论言 \n补阳补阴者，宜助精气也； \n此论言以水济火者，宜用寒凉也。盖补者，补中之不足；济者，制火之有余，凡此均能解表， \n其功若一，而宜寒宜暖，其用不侔，是有不可不辨。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>伤寒三表法（三十）\n\n属性：伤寒者，危病也。治伤寒者，难事也。所以难者，亦惟其理有不明，而不得其要耳。所谓要者 \n，亦惟正气、 \n邪气二者之辨而已，使能知正气之虚实，邪气之浅深，则尽之矣。夫寒邪外感，无非由表而入里， \n由表而入者，亦必由表而出之，故凡患伤寒者，必须得汗而后解。但正胜邪者，邪入必浅，此元气 \n之强者也。邪胜正者，其入必深，此元气之弱者也。邪有浅深，则表散有异，正有虚实，则攻补有 \n异，此三表之法所不容不道也。何为三表？盖邪浅者，逐之于藩篱，散在皮毛也；渐深者，逐之于 \n户牖，散在筋骨也；深入者，逐之于堂室，散在脏腑也。故浅而实者宜直散，直散者，直逐之无难 \n也。虚而深者宜托散，托散者，但强其主，而邪无不散也，今姑举其略∶如麻黄汤、桂枝汤、参苏 \n饮、羌活汤、麻桂饮之类，皆单逐外邪，肌表之散剂也。又如小柴胡汤、补中益气汤、三柴胡饮、 \n四柴胡饮之类，皆兼顾邪正，经络之散剂也。再如理阴煎、大温中饮、六味回阳饮、十全大补汤之 \n类，皆建中逐邪，脏腑之散剂也。呜呼！以散药而散于肌表经络者，谁不知之，惟散于脏腑则知者 \n少矣。以散为散者，谁不知之，惟不散之散，则玄之又玄矣。余因古人之未及，故特吐其散邪之精 \n义有如此。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>伤寒无补法辨（三十一）\n\n属性：按伤寒一证，惟元气虚者为最重，虚而不补，何以挽回？奈何近代医流，咸谓伤寒无补法。此 \n一言者，古无是说，而今之庸辈，动以为言，遂致老幼相传，确然深信，其为害也，不可胜纪。兹 \n第以一岁之事言之，如万历乙巳岁，都下瘟疫盛行，凡涉年衰及内伤不足者，余即用大温大补兼散 \n之剂，得以全活者数十余人，使此辈不幸而遭庸手，则万无一免者矣。即余一人，于一年之中，所 \n遇若此，其如岁月之长，海宇之广，凡为无补所杀者，固可胜量哉！ \n余痛夫枉者之非命，因遍求经传，则并无伤寒无补法之例。必求其由，则惟陶节庵有云∶伤寒 \n汗、吐、下后，不可便用参 大补，使邪气得补，而热愈盛，所谓治伤寒无补法也。此一说者，盖 \n亦本于孙真人之言，云服承气汤得痢瘥，慎不中补也。此其意谓因攻而愈者，本为实邪，故不宜妄 \n用补药，复助其邪耳，初非谓 \n虚证亦不宜补也。此外则有最庸最拙，为万世之害者，莫如李子建之《伤寒十劝》，今后世谬传， \n实基于此，故余于前论直叱其非，并详考仲景《伤寒论》，及诸贤之成法，以申明其义焉。矧今人 \n之患伤寒者，惟劳倦内伤，七情挟虚之类，十居七八，传诵伤寒无补者，十有八九，以挟虚之七八 \n，当无补之八九，果能堪乎！而不知以直攻而死者，皆挟虚之辈也。此在众人，则以传闻之讹，无 \n怪其生疑畏。至若名列医家，而亦曰伤寒无补法，何其庸妄无知，毫不自反，误人非浅，诚可丑可 \n恨者也。其有尤甚者，则本来无术，偏能惑人，但逢时病，则必曰∶寒邪未散，何可用补？若将邪 \n气补住，譬之关门赶贼。若此一言，又不知出自何典，乱道异端，尤可恨也。此外又有一辈，曰若 \n据此脉证，诚然虚矣，本当从补，但其邪气未净，犹宜缓之，姑俟清楚方可用也。是岂知正不能复 \n，则邪必日深，焉能清楚？元阳不支，则变生呼吸，安可再迟？此不知死活之流也。又有一辈，曰 \n此本虚证，如何不补，速当用人参七八分，但以青陈之类，监制用之，自然无害。是岂知有补之名 \n，无补之实，些须儿戏，何济安危，而尚可以一消一补，自掣其肘乎？此不知轻重之徒也。即或有 \n出奇言补者，亦必见势在垂危，然后曰∶快补快补。夫马到临涯，收缰已晚，补而无济，必又曰∶ \n伤寒用参者无不死。是伤寒无补之说益坚，而众人之惑益不可破，虽有仪秦不能辩也。余目睹其受 \n害于此者，盖不可胜纪矣，心切悲之，不得不辩。 \n夫伤寒之邪，本皆自外而入，而病有浅深轻重之不同者，亦总由主气之有强弱耳。故凡主强者 \n，虽感亦轻，以邪气不能深入也。主弱者，虽轻必重，以中虚不能自固也。此其一表一里，邪正相 \n为胜负，正胜则生，邪胜则死。倘以邪实正虚而不知固本，将何以望其不败乎？矧治虚治实，本自 \n不同，补以治虚，非以治实，何为补住寒邪？补以补中，非以补外，何谓关门赶贼？即曰强寇登堂 \n矣，凡主弱者，避之且不暇，尚敢关门乎？既能关门，主尚强也，贼闻主强，必然退遁，不遁即成 \n禽矣，谓之捉贼，又何不可？夫病情人事，理则相同，未有正胜而邪不却者。故主进一分，则贼退 \n一步，谓之内托，谓之逐邪，又何不可，而顾谓之关门耶？矧如仲 \n景之用小柴胡汤，以人参柴胡并用，东垣之用补中益气汤，以参术升柴并用，盖一以散邪，一以固 \n本，此自逐中有固，固中有逐，又岂皆补住、关门之谓乎？甚矣，一言之害，杀命无穷，庸医之庸 \n，莫此为甚。余不能以口遍传，故特为此辩，使有能广余之说，以活人一命者，必胜念弥陀经多多 \n矣。 \n徐东皋曰∶汉张仲景着《伤寒论》，专以外伤为法，其中顾盼脾胃元气之秘，世医鲜有知之者 \n。观其少阳证，小柴胡汤用人参，则防邪气之入三阴，或恐脾胃稍虚，邪乘而入，必用人参甘草， \n固脾胃以充中气，是外伤未尝不内因也。即如理中汤、附子汤、黄连汤、炙甘草汤、吴茱萸汤、茯 \n苓四逆汤、桂枝人参汤、人参败毒散、人参白虎汤、阳毒升麻汤、大建中汤等，未尝不用参术以治 \n外感，可见仲景公之立方，神化莫测。或者谓外伤是其所长，而内伤非所知也，此诚不知公者也。 \n何今世之医，不识元气之旨，惟见王纶《杂着》戒用人参之谬说，执泥不移，乐用苦寒，攻病之标 \n，致误苍生，死于非命，抑何限耶。间有病家疑信相半，两弗之从，但不速其死耳，直以因循，俟 \n其元气自尽，终莫之救而毙者，可谓知乎？况斯世斯时，人物剧繁，禀气益薄，兼之劳役名利之场 \n，甚至蹈水火而不知恤，就酒色以竭其真，不谓内伤元气，吾弗信也。观其杂病，稍用攻击而脾胃 \n遂伤，甚则绝谷而死者，可以类推矣。 \n\n\n\n<目录>卷之七须集\\伤寒典（上）\n\n<篇名>病宜速治（三十二）\n\n属性：凡人有感冒外邪者，当不时即治，速为调理，若犹豫隐忍，数日乃说，致使邪气入深，则难为 \n力矣。惟小儿女子，则为尤甚。凡伤寒之病，皆自风寒得之，邪气在表，未有温覆而不消散者，若 \n待入里，必致延久。一人不愈，而亲属之切近者，日就其气，气从鼻入，必将传染，此其病之微甚 \n，亦在乎治之迟早耳。故凡作汤液，不可避晨夜，觉病须臾，即宜速治，则易愈矣。仲景曰∶凡发 \n汗温服汤药，其方虽言日三服，若病剧不解，当促之，可半日中尽三服，即速治之意也。其或药病 \n稍见不投，但有所觉，便可改易。若其势重，当一日一夜， \n时观之，一剂未退，即当复进一剂。最难者不过三剂，必当汗解。其有汗不得出者，即凶候也。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>温病暑病（三十三）\n\n属性：温病暑病之作，本由冬时寒毒内藏，故至春发为温病，至夏发为暑病，此以寒毒所化，故总谓 \n之伤寒。仲景曰∶发热，不恶寒而渴者，温病也。暑病则尤甚矣。盖暑病者，即热病也，是虽与寒 \n证不同，然亦因时而名，非谓其病必皆热也。此外如夏月中暑者，亦谓之暑病，则又非寒毒蓄留之 \n证，在仲景则名之为中 。义详暑证门，所当参阅。 \n一、温病暑病之治，宜从凉散，固其然也，然必表里俱有热证，方可治用清凉。若值四时寒邪 \n客胜，感冒不正之气，表邪未解，虽外热如火，而内无热证可据者，不得以温暑之名，执以为热， \n而概用凉药。 \n一、冬有非时之暖，或君相客热之令而病热者，名曰冬温。此与冬月正伤寒大异，法宜凉解，此 \n舍时从证也。若夏月有寒者，其宜温亦然。 \n《素问·刺志论》曰∶气盛身寒，得之伤寒，气虚身热，得之伤暑。《伤寒论》曰∶脉盛身寒 \n，得之伤寒；脉虚身热，得之伤暑。此二论之言伤寒伤暑者，非即温病暑病之谓，盖单指夏月感触 \n时气者，所当辨其为寒为暑，而寒则宜温，暑则宜清也。身寒者，言受寒憎寒；身热者，言受热发 \n热，非曰身冷者方是伤寒，身热者乃是伤暑也。但此二论，则一曰气盛气虚，一曰脉盛脉虚，词若 \n异而理则一也。故凡察气者，当在形色，察脉者，当在本元，合而观之，则见理精矣。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>发斑（三十四）\n\n属性：发斑证，轻则如疹子，重则如锦纹。其致此之由，虽分数种，然总由寒毒不解而然。如当汗不 \n汗，则表邪不解；当下不下，则里邪不解；当清不清，则火盛不解；当补不补，则无力不解；或下 \n之太早，则邪陷不解；或以阳证误用温补，则阳亢不解；或以阴证误用寒凉，则阴凝不解。凡邪毒"}, {"n": 5, "text": "卷五\n\n不解，则直入阴分，郁而成热，乃致液涸血枯，斑见肌表，此实毒邪固结，营卫俱剧之证也。但斑 \n有微甚，势有重轻，轻者细如蚊迹，或先红而后黄；重者成粒成片，或先红而后赤。轻者只在四肢 \n，重者乃见胸腹。轻者色淡而隐，重者色紫而显。若见黑斑，或大便自利，或短气，或二便不通， \n则十死九矣。凡病伤寒，而汗、下、温、清俱不能解，及足冷耳聋，烦闷咳呕者，便是发斑之候。 \n一、成无己曰∶大热则伤血，热不散，里实表虚，热邪乘虚出于皮肤而为斑也，慎不可发汗，若 \n汗之，重令开泄，更增斑烂也。自后诸家所述，皆同此说，予则以为不然。盖凡伤寒之邪，本自 \n外而入，深入不解，则又自内而出，此其表里相乘，势所必至，原非表虚证也，但使内外通达，则 \n邪必由表而解矣。即如犀角地黄汤，乃治斑之要药，人知此汤但能凉血清毒，而不知此汤善于解表 \n散邪，若用之得宜，则必通身大汗，热邪顿解，何为不可汗耶？由此言之，则凡脉数无汗，表证俱 \n在者，必须仍从解散。 \n一、凡治发斑，须察表里。如瘟疫不解，热入血室，舌焦，烦热发斑者，犀角地黄汤。内外俱 \n热，阳明狂躁，大渴发斑者，白虎汤，或加人参。阳毒赤斑，狂言见血者，阳毒升麻汤。疫疠发斑 \n，大热而燥者，三黄石膏汤。火郁于经，寒邪不解，脉仍滑数而发斑者，一柴胡饮。阳明外邪，阳 \n毒不解者，升麻汤。脾肾本虚，外邪不解而发斑者，五柴胡饮。阳明表邪不解，温热发斑者，柴胡 \n白虎煎。温热毒盛，咽痛发斑者，玄参升麻汤。阴虚水亏，血热发斑者，玉女煎。阴虚血燥，大热 \n大渴发斑者，归葛饮。内虚外实，阴盛格阳发斑者，大温中饮。太阳阳明恶热，大便秘结，邪毒在 \n腑发斑者，调胃承气汤。 \n一、凡本非阳证，妄用寒凉者，每令泄泻，邪陷不解，予常用大温中饮、理阴煎之类，解寒托 \n邪，始得大汗，汗后邪达，多有见赤斑风饼随汗而出，随出随没，顷刻即愈，活者多人矣。凡寒毒 \n为斑，即此可见，使内托无力，则此毒终无出期，日深日甚，难乎免矣。此理甚微，不可不察。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>发黄（三十五）\n\n属性：凡发黄黄胆等证，多由湿热。如小水不利，或黄或赤，或小腹胀满不痛，或大便实而渴甚，脉 \n来沉实有力，皆湿热之证。轻则茵陈五苓散，重则茵陈汤，分利小便，清血泻火，则黄自退矣。然 \n黄有阴证及诸治法，俱详黄胆门，宜参用之。 \n仲景曰∶太阳病，脉浮而动数，头痛发热，微盗汗出，而反恶寒者，表未解也，医反下之，则 \n为结胸；若不结胸，但头汗出，小便不利，身必发黄也。曰∶阳明病，无汗，小便不利，心中懊 \n者，身必发黄。阳明病，发热汗出者，此为热越，不能发黄也。但头汗出，身无汗，际颈而还，小 \n便不利，渴饮水浆者，此为瘀热在里，身必发黄，茵陈蒿汤主之。曰∶伤寒，脉浮而缓，手足自温 \n者，系在太阴，身当发黄。若小便自利者，不能发黄，至七八日大便硬者，为阳明病也。曰∶伤寒 \n，发汗已，身目为黄，所以然者，以寒湿在里，不解故也。以为不可下也，于寒湿中求之。伤寒身 \n黄发热者，栀子柏皮汤主之。 \n孙真人曰∶黄胆脉浮者，当以汗解之，宜桂枝加黄 汤。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>发狂（三十六）\n\n属性：伤寒发狂，本阳明实热之病，然复有如狂证者，虽似狂而实非狂，此中虚实相反，最宜详辨， \n不可忽也。凡实热之狂，本属阳明，盖阳明为多气多血之经，阳邪传入胃腑，热结不解，因而发狂 \n。《内经·阳明脉解篇》 \n曰∶胃者土也，故闻木音而惊者，土恶木也。其恶火者，热甚则恶火也。其恶人者，以阳明厥则喘 \n而惋，惋则恶人也。其病甚则弃衣而走，登高而歌，或数日不食，或逾垣上屋者，以四肢为诸阳之 \n本，阳盛则四肢实，实则能登高也。其弃衣而走者，以热盛于身也。其妄言骂詈，不避亲疏而歌者 \n，以阳盛为邪也。又曰∶阴不胜其阳，则脉流薄疾，并乃狂。又曰∶邪入于阳则狂。是皆以阳明热 \n邪上乘心肺，故令神志昏乱若此，此阳狂也。然伤寒病至发狂，是为邪热已极，使非峻逐火邪，则 \n不能已。故但察其大便硬结，或腹满而坚，有可攻之证，则宜以大小承气，或凉膈散、六一顺气汤 \n之类，下之可也。如无胀满实坚等证，而惟胃火致然者，则但以白虎汤、抽薪饮之类，泄去火邪， \n其病自愈。 \n一、如狂证本非实热发狂，其证亦有轻重。如仲景曰∶太阳病不解，热结膀胱，其人如狂。其外 \n证不解者，尚未可攻，当先解外。外已解，但少腹急结者，乃可攻之，宜桃仁承气汤。又曰∶太阳 \n病，六七日，表证仍在，脉微而沉，反不结胸，其人如狂者，以热在下焦，少腹当硬满。小便自利 \n者，下其血乃愈，抵当汤主之。按此二条，以太阳热邪不解，随经入腑，但未至发狂，故曰如狂。 \n此以热搏血分，蓄聚下焦，故宜下也。 \n一、近见伤寒家则别有如狂之证，古人所未及言者，盖或由失志而病，其病在心也；或由悲忧 \n而病，其病在肺也；或由失精而病，其病在肾也；或由劳倦思虑而病，其病在肝脾也。此其本病已 \n伤于内，而寒邪复感于外，则病必随邪而起矣。其证如狂，亦所谓虚狂也。而虚狂之证，必外无黄 \n赤之色，刚暴之气，内无胸腹之结，滑实之脉，虽或不时躁扰，而禁之则止，口多妄诞，而声息不 \n壮，或眼见虚空，或惊惶不定，察其上则口无焦渴，察其下则便无硬结，是皆精气受伤，神魂不守 \n之证。此与阳极为狂者，反如冰炭，而时医不能察，但见错乱，便谓阳狂，妄行攻泻，必致杀人。 \n凡治此者，须辨阴阳。其有虚而挟邪者，邪在阳分，则宜补中益气汤之类；邪在阴分，则宜补阴益 \n气煎之类。虚而无邪者，在阳分，则宜四君、八珍、十全大补汤、大补元煎之类； \n在阴分，则宜四物、六味、左归饮、一阴煎之类。阴虚挟火者，宜加减一阴煎、二阴煎之类。阳虚 \n挟寒者，宜理中汤、回阳饮、八味汤、右归饮之类。此方治之宜，大略如此，而变证之异，则有言 \n不能传者，能知意在言表，则知所未言矣。 \n一、凡身有微热，或面赤戴阳，或烦躁不宁，欲坐卧于泥水中，然脉则微弱无力，此阴证似阳 \n也，名为阴躁。盖以阳虚于下，则气不归原，故浮散于上，而发躁如狂。速当温补其下，命门暖则 \n火有所归，而病当自愈。若医不识此，而误用寒凉者必死。 \n一、发狂，下痢谵语者不治。狂言，反目直视者，为肾绝，死。汗出后辄复热，狂言不食者死。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>风湿（三十七）\n\n属性：仲景《论》曰∶太阳病，关节疼痛而烦，脉沉而细者，此名湿痹。其人小便不利，大便反快， \n但当利其小便。曰∶湿家之为病，一身尽痛，发热，身色如熏黄。湿家，其人但头汗出，背强，欲 \n得被覆向火。若下之早则哕，胸满，小便不利，舌上如苔者，以丹田有热，胸中有寒，渴欲得水而 \n不能饮，口燥烦也。湿家下之，额上汗出，微喘，小便不利者死，利下不止者亦死。 \n《论》曰∶风湿相搏，一身尽疼痛，法当汗出而解，值天阴雨不止，医云此可发汗，汗之病不 \n愈者，何也？曰∶发其汗，汗大出者，但风气去，湿气在，是故不愈也。若治风湿者，发其汗，但 \n微微似欲汗出者，风湿俱去也。湿家，病身上疼痛，发热面黄而喘，头痛鼻塞而烦，其脉大，自能 \n饮食，腹中和无病，病在头中寒湿，故鼻塞，纳药鼻中则愈。病者一身尽疼，发热日晡所剧者，此 \n名风湿，此病伤于汗出当风，或久伤取冷所致也。 \n《论》曰∶伤寒八九日，风湿相搏，身体疼烦，不能自转侧，不呕不渴，脉浮虚而涩者，桂枝 \n附子汤主之。若其人大便硬，小便自利者，桂枝汤去桂加白术主之。风湿相搏，骨节烦疼，掣痛不 \n得屈伸，近之则痛剧，汗出短气，小便不利，恶风不欲去衣，或身微肿者，甘草附子汤主之。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>结胸（三十八）\n\n属性：仲景曰∶病有结胸，其状何如？答曰。按之痛，寸脉浮，关脉沉，名曰结胸也。曰∶病发于阳 \n而反下之，热入因作结胸。病发于阴而反下之，因作痞。所以成结胸者，以下之太早故也。曰∶结 \n胸，脉浮大者不可下，下之即死。曰∶结胸证悉具，烦躁者亦死。 \n《论》曰∶太阳病，脉浮而动数，头痛发热，微盗汗出，而反恶寒者，表未解也，医反下之， \n胃中空虚，阳气内陷，心下因硬，而为结胸，大陷胸汤主之。曰∶太阳病，重发汗而复下之，不大 \n便五六日，舌上燥而渴，日晡所小有潮热，从心下至少腹硬满而痛不可近者，大陷胸汤主之。按此 \n二条，皆言太阳表证未解，因误下之而成结胸也。 \n《论》曰∶伤寒五六日，呕而发热者，此柴胡汤证具，而以他药下之，其柴胡证仍在者，当复 \n与柴胡汤，必蒸蒸而振，却发热汗出而解。若心下满而硬痛者，此为结胸也，大陷胸汤主之。但满 \n而不痛者，此为痞，柴胡不中与之，宜半夏泻心汤。按此一条以少阳表证未解，因误下之而为结胸 \n也。 \n《论》曰∶太阳少阳并病，而反下之，成结胸，心下硬，下痢不止，水浆不入，其人烦心。按 \n此一条，以太阳少阳并病，二经表邪未解，亦因误下而成结胸也。 \n《论》曰∶阳明病，心下硬满者，不可攻之，攻之利遂不止者死，利止者愈。按此一条，谓阳 \n明邪气入腑者，必腹满便结，今惟心下硬，以邪气尚浅，未全入腑，故不可攻。此虽非结胸，而实 \n亦结胸之类，盖不由误下，而因阳明之邪渐深也。 \n《论》曰∶伤寒六七日，结胸热实，脉沉而紧，心下痛，按之石硬者，大陷胸汤主之。按此一 \n条，不云下早，而云热实，其于六七日，脉沉紧而心下硬痛者，此伤寒传里之实邪，有不因误下而 \n成结胸者，乃伤寒之本病也。 \n愚按∶结胸一证，观《伤寒论》所载，如前数条，凡太阳表邪未解而误下者，成结胸，少阳证 \n亦然，太阳少阳并病者亦然，此不当下而误下之，以致脏气空虚，外邪乘虚内陷，结于胸膈之间， \n是皆因下而结者也。又曰∶伤寒六七日，结胸热实，脉沉而紧，心下痛，按之石硬者，此不因下而 \n邪实渐深，结聚于胸者也。然则结胸一证，有因误下而成者，有不因下而由于本病者。观近代伤寒 \n诸书，云未经下者，非结胸也，岂不谬哉。 \n一、结胸证，观仲景所言，惟太阳、少阳二经误下者有之，而阳明一经独无言及者，何也？盖凡 \n病入阳明，胃腑已实，故可下之而无害也。然又曰∶阳明病，心下硬满者，不可攻之，攻之痢不止 \n者死。此岂非阳明在经表证，邪未入腑者，亦为不可下乎？不惟三阳为然，即三阴之证，其有发热 \n恶寒，表邪未解者，切不可下，最当慎也。 \n一、结胸证治之辨，凡心腹胀满硬痛，而手不可近者，方是结胸，若但满不痛者，此为痞满，非 \n结胸也。凡痞满之证，乃表邪传至胸中，未入于腑，此其将入未入，犹兼乎表。是即半表半里之证 \n，只宜小柴胡之属，加入枳壳之类治之，或以本方对小陷胸汤亦妙。今余新方制有柴陈煎，及一柴 \n胡饮之类，皆可择而用之也。至于结胸之治，则仲景俱用大陷胸汤主之。然余之见，则惟伤寒本病 \n，其有不因误下，而实邪传里，心下硬满，痛连小腹而不可近，或燥渴谵妄，大便硬，脉来沉实有 \n力者，此皆大陷胸汤所正宜也。其于太阳少阳表邪未解，因下早而致结胸者，此其表邪犹在，若再 \n用大陷胸汤，是既因误下而复下之，此则余所未敢。不若以痞满门诸法，酌其轻重，而从乎双解， \n以缓治之；或外用罨法，以解散胸中实邪，此余之屡用获效，而最稳最捷者也。罨法见新方因类第 \n三十。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>阴厥阳厥（三十九附脏厥蛔厥）\n\n属性：厥有二证，曰阳厥，曰阴厥也。阳厥者，热厥也，必其先自三阳传入阴分，故其初起，必因头 \n疼发热，自 \n浅入深，然后及于三阴，变为四肢逆冷，或时乍温，其证必便结躁烦，谵语发渴，不恶寒，反恶热 \n，脉沉有力。此以传经热证所化，外虽手足厥冷，内则因于热邪，阳证发厥，故为阳厥，乃阳极似 \n阴也。其证由邪热内结，或伏阳失下之所致也。凡厥微则热亦微，宜四逆散之类；厥甚则热亦甚， \n宜承气汤之类也。阴厥者，寒厥也，初无三阳传经实热等证，而真寒直入三阴，则畏寒厥冷，腹痛 \n吐泻，战栗不渴，脉沉无力者，此阴寒厥逆，独阴无阳也，故为阴厥。轻则理中汤，重则四逆、回 \n阳等汤主之。 \n成无己曰∶四逆者，四肢不温也。伤寒邪在三阳，则手足必热，传到太阴，手足自温，至少阴 \n则邪热渐深，故四肢逆而不温也。及至厥阴，则手足厥冷，是又甚于逆，故用四逆散，以散其传阴 \n之热证。 \n《论》曰∶诸四逆厥者，不可下之，虚家亦然。成无己注曰∶四逆者，四肢不温也；厥者，手 \n足冷也，甚于四逆也。皆阳气少而阴气多，故不可下，虚家亦然。《金匮玉函》曰∶虚者十补，勿 \n一泻之。 \n《论》曰∶凡厥者，阴阳气不相顺接，便为厥。厥者，手足逆冷是也。病者手足厥冷，言我不 \n结胸，小腹满，按之痛者，此冷结在膀胱关元也。伤寒发热四日，厥反三日，复热四日，厥少热多 \n，其病当愈。伤寒，厥四日，热反三日，复厥五日，其病为进。寒多热少，阳气退，故为进也。若 \n厥而呕，胸胁烦满者，其后必便血。 \n《论》曰∶少阴病，下痢清谷，里寒外热，手足厥逆，脉微欲绝，身反不恶寒，其人面赤色， \n或腹痛，或干呕，或咽痛，或痢止脉不出者，通脉四逆汤主之。伤寒脉促，手足厥逆者，可灸之。 \n伤寒脉滑而厥者，里有热也，白虎汤主之。手足厥寒，脉细欲绝者，当归四逆汤主之。若其人内有 \n久寒者，宜当归四逆加吴茱萸生姜汤主之。大汗出，热不去，内拘急，四肢疼、又下痢厥逆而恶寒 \n者，四逆汤主之。大汗，若大下痢，而厥逆者，四逆汤主之。病患手足厥冷，脉乍紧者，邪结在胸 \n中，心中满而烦，饥不能食者，病在胸中，当须吐之，宜瓜蒂散。伤寒厥而心下悸者，宜先治水， \n当服茯苓甘草汤，却治其厥。不尔，水渍入胃，必作痢也。下痢清谷，里寒外热，汗出而厥者，通 \n脉四逆汤主之。呕而脉弱，小便复痢，身有微热，见厥者难治，四逆汤主之。 \n按∶阳厥阴厥，其辨如前，此先哲之大法也。然愚则犹有所辨，如阴厥一证，既无阳证阳脉， \n而病寒若此，明是阴证，今人但曰中寒者，即其病也。然犯此者无几，知此者无难，治宜温中，无 \n待辨也。惟是阳厥一证，则有不得不辨者。夫厥由三阳所传，是为阳厥，此固然矣，即以传经者 \n言之，又岂尽无阴证乎？故凡病真阳不足者，即阳中之阴厥也；脉弱无神者，即阳中之阴厥也；攻 \n伐清凉太过者，即阳中之阴厥也。四肢为诸阳之本，使非有热结、烦渴、胀实等证，而见厥逆者， \n皆由阳气不足也。成无己曰∶大抵厥逆为阴所主，寒者多矣。又曰∶厥为阴之盛也。故凡属挟虚伤 \n寒，则虽自阳经传入者，是亦阳中之阴厥也。阴中之阴者宜温，阳中之阴者，果宜凉乎？学人勿谓 \n其先有头疼发热，但自三阳传至者，便为阳厥，而寒因热用之，则为害不小矣。 \n一、脏厥证。仲景曰∶伤寒脉微而厥，至七八日肤冷，其人躁无暂安时者，此为脏厥。脏厥者 \n死，阳气绝也。 \n一、蛔厥证。仲景曰∶蛔厥者，其人当吐蛔，今病者静，而复时烦，此为脏寒，蛔上入膈，故 \n烦，须臾复止，得食而呕，又烦者，蛔闻食臭出，其人当自吐蛔。蛔厥者，乌梅丸主之。成无己曰 \n∶脏厥者死，阳气绝也。蛔厥虽厥而烦，吐蛔已则静，不若脏厥而躁无暂安时也。病患脏寒胃虚， \n故宜与乌梅九温脏安虫。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>谵语郑声（四十）\n\n属性：《论》曰∶实则谵语，虚则郑声，此虚实之有不同也。夫谵语郑声，总由神魂昏乱而语言不正 \n，又何以分其虚实？但谵语者，狂妄之语也；郑声者，不正之声也。谵语为实，实者邪实也。如伤 \n寒阳明实热，上乘于心，心为热冒，则神魂昏乱而谵妄不休者，此实邪也。实邪为病，其声必高， \n其气必壮，其脉必强，其色必厉，凡登高骂詈，狂呼躁扰之类皆是也。此之为病，有燥粪在胃而然 \n者，有瘀血在脏而然者，有火盛热极而然者，有腹胀便秘、口疮咽烂而然者。察其果实，即当以三 \n承气，或白虎汤、凉膈散之类治之。郑声为虚，虚者神虚也。如伤寒元神失守，为邪所乘，神志昏 \n沉而错乱不正者，此虚邪也。虚邪为病，其声必低，其气必短，其脉必无 \n力，其色必萎悴，凡其自言自语，喃喃不全，或见鬼怪，或惊恐不休，或问之不应、答之不知之类 \n皆是也。此之为病，有因汗亡阳，因下亡阴而然者；有焦思抑郁，竭尽心气而然者；有劳力内伤， \n致损脾肾而然者；有日用消耗，暗残中气而然者。凡其或虽起倒，而遏之即止，终不若实邪之难制 \n者，即虚邪也。察其果虚，最忌妄行攻伐，少有差谬，无不即死。治此者，速宜察其精气，辨其阴 \n阳，舍其外证，救其根本，稍迟犹恐不及，而况于误治乎。甚至有自利身寒，或寻衣撮空，面壁啐 \n啐者，尤为逆候。盖谵妄一证，最于虚损者不宜有之，故凡身有微热，脉见洪滑者生，心多烦躁， \n脉见微弱细急而逆冷者死。所以证逢虚损，而见有谵妄者，即大危之兆，不可不加之意也。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>衄血（四十一）\n\n属性：杂病衄血，责热在里；伤寒衄血，责热在表。《论》曰∶伤寒小便清者，知不在里，仍在表也 \n，当发其汗；若头痛者，必衄，宜桂枝汤。曰∶伤寒脉浮紧，不发汗，因致衄者，麻黄汤主之。此 \n以伤寒之衄，为其热不在里，在表而然也。然又《论》曰∶衄家不可发汗。而何以复用桂枝、麻黄 \n等汤？盖衄由乎阴者，以阴虚火动也，故不宜再汗以亡阴；衄由乎阳者，以表邪未解也，故当用桂 \n枝、麻黄以发散。又《论》曰∶太阳病，脉浮紧，发热，身无汗，自衄者愈。此以表邪欲解，不从 \n汗而从血，俗人谓之红汗，所以衄后当愈也。由此观之，则有因衄而愈者，以经通而邪散也；有治 \n衄仍当发散者，以邪之将解未解，而因散其余邪也。治衄之法，于斯可见。若寒气不甚，而用麻黄 \n、桂枝，似属太刚，或易以柴葛之类，自无不可，用者其酌之。 \n《论》曰∶阳明病，口燥但欲漱水，不欲咽者，此必衄。盖阳明之脉络于口鼻，今其漱水不欲 \n咽者，以热在经而里无热，故当鼻衄也。 \n一、有动阴血者，又非衄血之谓。《论》曰∶少阴病，但厥无汗，而强发之，必动其血，未知 \n从何道出，故或从口鼻，或从目出者，是名下厥上竭。此阴血也，乃为危证。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>蓄血（四十二）\n\n属性：伤寒蓄血者，以热结在里，搏于血分，留瘀下焦而不行也。《论》曰∶伤寒有热，少腹满，应 \n小便不利，今反利者，为有血也。又曰∶太阳病，身黄脉沉结，少腹硬，小便不利者，为无血也。 \n小便自利，其人如狂者，血证谛也。大抵热蓄血分，留结下焦则生狂躁，《论》曰∶热结膀胱，其 \n人如狂者是也。然又有阳明证，其人喜忘，屎虽硬，而大便反快，其色黑者，是亦蓄血之证。故凡 \n诊伤寒，但其少腹硬满而痛，盒饭问其小便，若小水自利者，知为蓄血之证，盖小水由于气化，病 \n在血而不在气，故小便利而无恙也。血瘀于下者，血去则愈，其在仲景之法，则以抵当汤、抵当丸 \n主之。愚谓但以承气之类，加桃仁、红花以逐之，或其兼虚者，以玉烛散之类下之，则蓄血自去， \n而病无不除矣。 \n成无己曰∶伤寒衄者，以邪气不得发散，壅盛于经，逼迫于血，因而致衄也。蓄血者，下焦结 \n聚，而不行不散也。血菀于上而吐血者，谓之薄厥，留瘀于下者，谓之蓄血。此由太阳经瘀热在里 \n，搏蓄下焦所致。 \n《经》曰∶太阳病七八日，表证仍在，脉沉而微，反不结胸，其人如狂者，以热在下焦，少腹 \n当硬满，小便自利者，下血乃愈。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>热入血室（四十三）\n\n属性：《论》曰∶阳明病，下血谵语者，此为热入血室，是兼男女而言也。曰∶妇人中风，七八日， \n续得寒热，发作有时，经水适断者，此为热入血室，其血必结，故使如疟状，发作有时，小柴胡汤 \n主之。曰∶妇人中风，脉 \n迟身凉，而证如结胸者，当刺期门。曰∶妇人伤寒，经水适来，昼日了了，暮则谵语者，无犯胃气 \n及上二焦，必自愈。 \n按:血室者，即冲任血海也，亦血分也。凡血分之病，有蓄血者，以血因热结而留蓄不行也； \n有热入血室者，以邪入血分而血乱不调也。故血蓄者，去之则愈；血乱者，调之则安。调之之法， \n则热者宜凉，陷者宜举，虚者宜滋，瘀者宜行，邪未散者宜解也。然此皆病在下焦，故曰无犯胃气 \n及上二焦。必自愈，是又不可不察。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>胸胁腹满（四十四）\n\n属性：凡邪气自表传里，必先入胸膈，以次渐从胁肋而后入胃，邪气入胃，乃为入腑，是以胸满者犹 \n属表证，胁满则半表半里也。大抵胸胁满者，以邪气初入于里，气郁不行，所以生满，尚未停聚为 \n实，故但从和解，以小柴胡之属则可愈矣。若果实邪在上，留滞不能散者，乃可吐之。华元化曰∶ \n四日在胸，吐之则愈。是因邪已收聚而未及散漫者，乃可吐也。在仲景用栀子豉汤，或瓜蒂散之属 \n，栀子豉汤可吐客热，瓜蒂散可吐实痰。其或一时药有不便，余有吐法在新方攻阵中，可以代之， \n或即以和解之药探而吐之，无不可也。 \n一、腹满证，按华元化曰∶伤寒一日在皮，二日在肤，三日在肌，四日在胸，五日在腹，六日在 \n胃，入胃即为入腑，入腑即在腹也。若腹虽满而未甚者，犹是未全入腑，不可攻也。然腹满之证， \n有虚实也，有寒热也，不可一概皆以实论。观《金匮要略》曰∶腹满不减，减不足言，当下之。是 \n不减者为实满也。又曰∶腹满时减，复如故，此虚寒从下上也，当以温药和之。是或进或退，时或 \n减而时复如故者，本非结聚实邪，此虚满也。大抵腹满之证，本属太阴，若是阳邪，则必咽干烦热 \n，脉实有力；若是阴邪，则必腹满吐食，畏寒自利，脉息无神，可以辨之。实热者可清可攻，虚寒 \n者宜温宜补也。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>呕吐哕证（四十五）\n\n属性：呕者，有声无物；吐者，吐出食物也。呕者有寒有热，吐则皆因胃寒也。凡呕而发热烦闷者， \n邪热为呕也。 \n呕而吞酸冷咽，涎沫FS FS 一者，寒邪为呕也。大抵伤寒表邪将传入里，里气相逆则为呕，是以半表 \n半里之邪，其证多呕，若邪全在表，无是证也。凡邪在半表半里者，和之散之，气逆者顺之，有痰 \n者降之，热者清之，寒者温之。《千金》云∶呕家多服生姜，此是呕家圣药。然呕家虽有阳明证， \n不可攻之，盖其气逆在上，而邪未入腑，本非胃实证也。气逆于上而攻其下，下虚则逆气乘之，势 \n必大危，若脉微弱者，乃为尤甚。 \n凡伤寒三阳传毕，三阴当受邪矣，若其人反能食而不呕，此为邪不入阴，是知邪之传里者，乃 \n致为呕也。观干姜附子汤证治云∶不呕不渴者，为里无热。十枣汤证治云∶干呕，短气，汗出，不 \n恶寒者，此表解里未和也。即此观之，则凡呕者，知为里证，而兼烦渴者，方为内热也。 \n仲景《论》曰∶食谷欲呕者，属阳明也，吴茱萸汤主之。得汤反剧者，属上焦也。曰∶少阴病 \n，吐痢，手足厥冷，烦躁欲死者，吴茱萸汤主之。 \n《论》曰∶病患脉数，数为热，当消谷引饮，而反吐者，此以发汗，令阳气微，膈气虚，脉乃 \n数也。数为客热，不能消谷，以胃中虚冷，故吐也。东垣曰；邪热不杀谷，故热邪在胃则不食。 \n《论》曰∶阳明病不能食，攻其热必哕，所以然者，胃中虚冷故也。以其人本虚，故攻其热必 \n哕。若胃中虚冷不能食者，饮水则哕。若膈上有寒饮，干呕者，不可吐也，急温之，宜四逆汤。 \n《论》曰∶伤寒哕而腹满，视其前后，知何部不利，利之则愈。治哕诸法，详呃逆门。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>劳力感寒（四十六）\n\n属性：凡因辛苦劳倦而病者，多有患头痛发热恶寒，或骨腿酸疼，或微渴，或无汗，或自汗，脉虽浮 \n大而无力，亦多紧数，此劳力感寒之证，即东垣云内伤证也。宜补中益气汤，或补阴益气煎，及五 \n福饮等剂为良，所谓温 \n能除大热，即此类也。若或邪盛无汗，脉见洪数，而当和解者，即当用新方散阵诸柴胡饮之类主之。 \n一、凡劳力感寒一证，人皆以服役辛苦之人为言，而不知凡为名利所牵，有不自揣，以致竭尽 \n心力而患伤寒者，皆其类也。故凡有形劳而神不劳者，劳之轻者也，若既劳其神，又劳其形，内外 \n俱劳，则形神俱困，斯其甚矣。今人之病伤寒者，率多此类，轻者和解，治宜如前，重者速宜救本 \n，当于后开培补诸方，择而用之，庶乎有济。倘不知其所致之由，而概施混治，但知攻邪，则未有 \n不误人者矣。此即劳倦内伤之类，诸义俱详本门。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>虚证（四十七）\n\n属性：仲景曰∶阳微则恶寒，阴弱则发热，是寒热之有虚也。曰∶其人本虚，是以发战，是战汗之皆 \n因虚也。曰∶耳聋无闻者，阳气虚也。曰∶面赤戴阳者，阴不足也。曰∶无阳不能作汗，必身冷而 \n脉迟也。曰∶客热不能杀谷，胃中虚冷也。曰∶病患脉数，数为热，当消谷引食，而反吐者，此以 \n发汗，令阳气微，膈气虚，脉乃数也。数为客热，不能消谷，以胃中虚冷，故吐也。曰∶虚则郑声 \n，以言语乱而不正也。曰∶身蜷恶寒而利，因冷气而为厥逆也。曰∶尺中脉微，此里虚，须表里实 \n，津液自和，便自汗出愈。曰∶脉促厥冷者宜灸，以促脉有非因热也。曰∶头疼呕吐之宜温，以头 \n疼之有属阴也。曰∶不利而利，发热汗出者，有阴无阳也。曰∶少阴脉沉者，汗后热不去，而厥利 \n恶寒者，皆宜急温也。曰∶旧有微溏者，不可与栀子汤，以里虚而寒在下也。曰∶阳明病，不能食 \n，攻其热必哕，所以然者，胃中虚冷故也。饮之水亦哕也。曰∶小便色白者，以下焦之虚寒也。曰 \n∶自利不渴者，以脏中之无火也。曰∶邪中于阴者，必生内栗，因表气虚而里气不守也。曰∶发汗 \n过多，其人叉手自冒心，心下悸而欲得按者，亡其阳也。曰∶发汗病不解，而反恶寒者，虚故也。 \n曰∶脉阴阳俱紧，反汗出者，亡其阳也。 \n一、诸脉有虚证，见前卷。 \n一、忌汗下各有虚证，见前卷。 \n一、表里五脏各有虚实，详一卷《传忠录·虚实辨》中，俱当互阅。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>动气（四十八）\n\n属性：《论》曰∶诸动气者，不可发汗，亦不可下。按∶此动气一证，即筑筑然动于脐傍，及左乳之 \n下曰虚里者，皆其联系者也。考之《难经》，则以脐之上下左右，分心肾肝肺四脏，而各列其证。 \n在《伤寒论》所载亦详。成无己曰∶动气者，脏气不治，正气内虚也。虽诸说如此，然皆未尽其要 \n，所以今之医家，多不识此为何证，而且疑为未见此证也。余尝留心察此，所见极多。盖动气之在 \n脐傍者，皆本于下焦之阴分，凡病关格劳损者，多有此证，而尤于瘦薄者易见之。其动之微者，则 \n止于脐傍上下，其动之甚者，则连及虚里心胁，真若舂舂连续，而混身皆振动者。此以天一无根， \n故气不蓄脏，而鼓动于下，诚真阴不守，大虚之候也。何以验之？但察于呼吸饥饱之顷，可得其征。 \n凡病此者，馁时则动甚，饱时则稍缓，呼出则动甚，吸入则稍缓，但虚甚者动必甚，虚微者动亦微 \n，岂非虚实之明证乎。即在病者，虽常觉其振动，而无疼无痒，尚不知为何故，医家多不以为意， \n弗能详察，故不知为何病，此动气之不明也久矣。此动气之见于虚损者极多，而见于伤寒者亦不少 \n也。精虚者既不可汗，阴虚者又不可下，仲景但言其禁，而不言其治，然则动气之治，岂无法乎？ \n独于霍乱条中云∶脐上筑者，肾气动也，用理中丸去术加桂四两以治之，此其意在脾肾，概可知也 \n。然余之治此，则惟直救真阴，以培根本，使其气有所归，无不获效。欲察虚实者，最不可忽此一 \n证，《类经》虚里穴下有详注，当并考之。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>战汗（四十九）\n\n属性：论曰∶脉浮而紧，按之反芤，此为本虚，故当战而汗出也。其人本虚，是以发战，以其脉浮， \n故当汗出而解。若脉浮大而数，按之不芤，此本不虚，故其欲解，则但汗出而不发战也。 \n一、战与栗异，战由乎外，栗由乎内也。凡伤寒欲解将汗之时，若其正气内实，邪不能与之争， \n则但汗出自不作战，所谓不战，应知体不虚也。若其人本虚，邪与正争，微者为振，甚则为战，正 \n胜则战而汗解矣。故凡邪正之争于外者则为战，战其愈者也；邪正之争于内者则为栗，栗其甚者也 \n。《论》曰∶阴中于邪，必内栗也。夫战为正气将复，栗则邪气肆强，故伤寒六七日，有但栗不战 \n，竟成寒逆者，多不可救。此以正气中虚，阴邪内盛，正不胜邪，而反为邪气所胜。凡遇此证，使 \n非用大补温热之剂，及艾灼回阳等法，其他焉得而御之。 \n余尝治一衰翁，年逾七旬，陡患伤寒，初起即用温补，调理至十日之外，正气将复，忽尔作战， \n自旦至辰，不能得汗，寒栗危甚，告急于余。余用六味回阳饮，入人参一两，姜附各三钱，使之煎 \n服。下咽少顷，即大汗如浴，时将及午，而浸汗不收，身冷如脱，鼻息几无，复以告余。余令以前 \n药复煎与之。告者曰∶先服此药，已大汗不堪，今又服此，尚堪再汗乎？余笑谓曰∶此中有神，非 \n尔所知也。急令再进，遂汗收神复，不旬日而起矣。呜呼！发汗用此，而收汗复用此，无怪乎人之 \n疑之也。而不知汗之出与汗之收，皆元气为之枢机耳。故余纪此，欲人知合辟之权，不在乎能放能 \n收，而在乎所以主之者。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>头汗（五十）\n\n属性：头汗之证有二，一为邪热上壅，一为阳气内脱也。盖头为诸阳之会，凡伤寒遍身得汗者，谓之 \n热越，若身无汗，则热不得越而上蒸阳分，故但头汗出也，治热蒸者，可清可散，甚者可下，在去 \n其热而病自愈。至若气脱一证，则多以妄下伤阴，或克伐太过，或泄泻不止，以致阴竭于下，则阳 \n脱于上，小水不通，而上见头汗， \n则大危矣。 \n《论》曰∶伤寒五六日，头出汗，微恶寒，手足冷，心下满，口不欲食，大便难，脉细者，此 \n为阳微结，乃半在里半在外也。脉虽沉紧，不得为少阴病，所以然者，阴不得有汗，今头汗出，故 \n知非少阴也，可与小柴胡汤，得屎而解。曰∶伤寒五六日，已发汗而复下之，胸胁满微结，小便不 \n利，渴而不呕，但头汗出，往来寒热，心烦者，此为未解也，柴胡桂枝干姜汤主之。 \n《论》曰∶伤寒十余日，但结胸无大热者，此为水结在胸胁也，但头汗出者，大陷胸汤主之。 \n曰∶阳明病，下血谵语者，此为热入血室，但头汗出者，刺期门，随其实而泻之， 然汗出则愈。 \n《论》曰∶太阳病，医反下之，若不结胸，但头汗出，余处无汗，际颈而还，小便不利，身必 \n发黄也。曰∶阳明病，但头汗出，小便不利，必发黄。 \n《论》曰∶湿家下之，额上汗出，微喘，小便不利者死，若下痢不止者亦死。 \n《脉经》曰∶阳气上出，汗见于头者，盖阳脱也。 \n一、头汗，脉紧数，有表邪当散者，宜小柴胡汤，或柴胡桂枝干姜汤，及新方诸柴胡饮，俱可 \n酌用。若有火邪，脉洪滑，内多烦热，头汗，当清者，宜人参白虎汤、益元散之类主之。若水结胸 \n，心下满，头汗出者，或大陷胸汤，或小半夏茯苓汤。若便结，腹胀疼痛，头汗者，宜承气汤。若 \n诸虚泄泻，阳脱头汗者，宜速用独参汤，或大补元煎、六味回阳饮等，作急救之，庶可保全。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>吐蛔（五十一）\n\n属性：凡治伤寒，若见吐蛔者，虽有大热，忌用凉药，犯之必死。盖胃中有寒，阳气弱极，则蛔逆而 \n上，此大凶之兆也。急用炮姜理中汤一服，加乌梅二个，花椒一、二十粒，服后待蛔定，然后以小 \n柴胡或补中益气等剂， \n渐治其余。盖蛔闻酸则静，见苦则安也。仲景曰∶病患有寒，复发汗，胃中冷，必吐蛔。蛔厥证见 \n前三十九。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>腹痛（五十二）\n\n属性：陶节庵曰∶伤寒腹痛有四，若绕脐硬痛，大便结实，烦渴者，皆属燥屎痛，急用寒药下之。因 \n食积而痛者，治亦同。 \n一、若小腹硬痛，小水自利，大便黑，身目黄者，属蓄血痛，亦用寒剂加行血药，下尽黑物自 \n愈。 \n一、凡伤寒腹中痛甚，但将凉水一盏，与病者饮而试之，若饮水后痛稍可者属热痛，当用凉药清 \n之。以上三条，皆实热痛也，必脉来沉实有力，方是此证，若微弱者，仍当详审，从缓治之。 \n一、若饮水愈加作痛，此为寒痛，当用温药和之。和之不已，而或四肢厥冷，呕吐泻利者，急 \n用热药救之。但须详脉之有力无力，方为良法。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>下痢（五十三）\n\n属性：凡杂证下痢，多责于寒，伤寒下痢，有寒有热。盖热邪传里，则亦有下痢之证，但寒痢最多， \n热痢则仅见耳。治者当辨寒热，若误用之，则为害最大。 \n仲景《论》曰∶自利不渴者，属太阴，以其脏有寒故也，当温之，宜服四逆辈。少阴病二三日 \n，至四五日，腹痛，小便不痢，下痢不止，便脓血者，桃花汤主之。少阴病，吐痢，手足厥冷，烦 \n躁欲死者，吴茱萸汤主之。少阴病，下痢，白通汤主之。少阴病，二三日不已，至四五日，腹痛， \n小便不痢，四肢沉重疼痛，自下痢者，此为有水气，其人或咳，或小便痢，或下痢，或呕者，真武 \n汤主之。少阴病，下痢清谷，里寒外热，手足厥逆，脉微欲绝，身反不恶寒，其人面色赤，或腹痛 \n，或干呕，或咽痛，或痢止脉不出者，四逆汤主之。大汗出， \n热不去，内拘急，四肢疼，下痢厥逆而恶寒者，四逆汤主之。下痢清谷，不可攻表，汗出必胀满。 \n按∶此诸论，乃皆言寒痢之当温也。如所云手足厥逆，恶寒腹痛，脉微欲绝，下痢清谷之类， \n此固阴寒之甚者也。其于疑似之间，则犹有真辨∶凡伤寒下痢由热邪者，必有烦躁大热，酷欲冷水 \n等证，亦必有洪滑强盛数实等脉，如果表里俱热，方可作火证论治。若其脉虽数而无力，外虽身 \n热而不恶热，内虽渴而不喜冷，此其内本不热，而病为下痢者，悉属虚寒，治宜四逆汤、理中汤、 \n温胃饮、胃关煎、五苓散之类，酌用可也。或表里寒邪俱甚，则当以麻桂饮相兼用之为最妥。若以 \n寒痢作热痢，妄用寒凉，再损胃气，则无有不死。 \n《论》曰∶下痢，腹胀满，身体疼痛者，先温其里，乃攻其表，温里四逆汤，攻表桂枝汤。 \n按∶此一条，乃言表里俱病而下痢者，虽有表证，所急在里，盖里有不实，则表邪愈陷，即欲 \n表之，而中气无力，亦不能散。故凡见下痢中虚者，速当先温其里，里实气强，则表邪自解，温中 \n可以散寒，即此谓也。 \n《论》曰∶热痢下重者，白头翁汤主之。下痢，脉数，欲饮水者，以有热故也，白头翁汤主之 \n。少阴病，下痢，六七日，咳而呕渴，心烦不得眠者，猪苓汤主之。 \n按∶此三条，乃言热痢之当清也。但既云脉数，又欲饮水，是诚热矣，然寒邪在表，脉无不数 \n，但数而有力者为阳证，数而无力者，即阴证矣。泻痢亡津，无有不渴，但渴欲饮水，愈多愈快者 \n为阳证，若口虽欲水，而腹不欲咽者，即非阳证矣。此外，如渴欲茶汤者，乃泻渴之当然也，不得 \n悉认为热证。一、凡伤寒表邪未解，脉实滑数，喜冷气壮，内外俱热而下痢者，宜柴芩煎主之。 \n《论》曰∶少阴病，自痢清水，色纯青，心下必痛，口干燥者，急下之，宜大承气汤。下痢， \n三部脉皆平，按之心下硬者，急下之，宜大承气汤。下痢谵语者，有燥屎也，宜小承气汤。 \n按∶此三条，乃言下痢之当攻者也。凡伤寒下痢者，本非阳明实邪，不当谵语，今既谵语，故 \n知有燥屎当去也。又若少阴下痢，心下有痛有硬者，必有所积，故亦当下。 \n一、凡自痢家，身凉脉小者为顺，身热脉大者为逆。此以外无表证，而病之左脏者言也。下痢 \n，日十余行。脉反实者死。发热，下痢至甚，厥不止者死。直视谵语，下痢者死。下痢无脉，手足 \n厥冷，灸之不温，脉不远者死。少阴病，自痢，烦躁不得卧寐者死。大抵下痢一证，为脱气至急， \n五夺之中，惟此为甚。《金匮要略》曰∶六腑气绝于外者，手足寒，五脏气绝于内者，痢下不禁， \n脏气既脱，不能治也。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>协热下痢（五十四）\n\n属性：仲景曰∶若不宜下而便攻之，内虚热入，协热遂痢，烦躁，诸变不可胜数，轻者困笃，重者必 \n死矣。太阳病二三日，不能卧，反下之，若痢止，必作结胸。未止者，四日复下之，此作协热痢也 \n。太阳病，外证未除，而数下之，遂协热而痢，痢下不止，心下痞硬，表里不解者，桂枝人参汤主 \n之。阳明少阳合病，若脉数不解，而下不止，必协热而便脓血也。 \n按∶此四条乃皆言表证未除而误下之，因致外热未退，内复作痢，故云协热下痢，此一热字， \n乃言表热也，非言内热也。夫协者，协同之协，非挟藏之挟，即表里俱病之谓，故治此者，止有桂 \n枝人参汤一方，其义显然可见。即如成无己《明理论》曰∶表邪传里，里虚协热则痢，乃亦以表邪 \n为言也。奈何后学不明此义，止因协热二字，每每以表作里，以寒作热，但见作痢者，无论表里虚 \n实，即认为内热，便云协热下痢。且近有不必误下，而妄用芩连治表热者，表证得寒，热愈不退， \n乃致下痢，或脾胃素弱，逢寒即泄者，皆是此证。既见下痢，益云协热，其谬孰甚，独不观仲景桂 \n枝人参汤，岂治内热之剂乎？寒热倒施，杀人多矣，予因特表于此。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>小便（五十五）\n\n属性：凡伤寒小便清者，病不在里，仍在表也，当解表发汗。小便利者，病不在气分，而在血分，以 \n小水由于气 \n化也。 \n阳盛则欲衄，阴虚小便难。 \n凡病伤寒而小水利者多吉，以内邪不甚也。 \n仲景曰∶阳明病，汗出多而渴者，不可与猪苓汤，以汗多必胃燥，故不可复利小水也。 \n《论》曰∶湿家之为病，一身尽痛，发热，身色如熏黄，其人但头汗出，背强，欲得被覆向火 \n，舌上如苔者，以丹田有热，胸中有寒，渴欲得水，而不能饮，此湿痹之候。其人小便不利，大便 \n反快者，但当利其小便。 \n凡伤寒表证未除，病在阳分者，不可即利小便。盖走其津液，取汗愈难，且恐大便干结也。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>死证（五十六）\n\n属性：陶节庵曰∶凡看伤寒，极要识各经中死证死脉，须一一理会过，免致临病疑惑。但见死证，便 \n当以脉参之，如果有疑，切莫下药，虽至亲俯恳，亦不可治，倘有差失，咎将归于己矣。 \n一、脉浮而洪，身汗如油，喘而不休，水浆不入，形体不仁，乍静乍乱，此命绝也。汗出发润， \n喘而不休，此肺绝也。形如烟煤，直视摇头，此心绝也。唇吻色青，四肢振动，此肝绝也。环口黎 \n黑，冷汗发黄，此脾绝也。溲便遗失，狂言，反目直视，此肾绝也。 \n一、少阴病，恶寒身蜷而利，手足逆冷者，不治。少阴病，吐痢躁烦，四逆者死。少阴病，四逆 \n身蜷，脉不至，不烦而躁者死。少阴病，六七日，息高者死。少阴病，至五六日，自利，烦躁不得 \n卧寐者死。少阴病，下痢，厥逆无脉，服药后，脉微续者生，脉暴出者死。少阴病，但厥无汗，而 \n强发之，必动其血，未知从何道出，或从口鼻，或从目出，是名下厥上竭，为难治。 \n一、阴病见阳脉者生，阳病见阴脉者死。脉纯弦者死。脉阴阳俱虚，热不止者死。脉阴阳俱盛， \n大汗出， \n热不解者死。手足逆冷，脉沉细，谵言妄语者死。脉证俱虚，而见谵妄者死。伤寒六七日，脉微， \n手足厥冷，烦躁，灸厥阴，厥不还者死。寸脉上不至关为阳绝，尺脉下不至关为阴绝，此皆不治， \n决死也。伤寒下痢，日十余行，脉反实者死。 \n一、伤寒，病胁下素有痞气，连于脐傍，痛引少腹入阴筋者，此名脏结，死。发热，下痢厥逆， \n躁不得卧者死。发热，下痢至甚，厥不止者死。直视谵语，喘满者死，下痢者，亦死。下痢发热者 \n亦死。发热而厥，七日，下痢者难治。伤寒六七日，发热而利，汗出不止者死，有阴无阳故也。阳 \n气前绝，阴气后绝者，阴证也，其人死后，身色必青。阴气前绝，阳气后绝者，阳证也，其人死后 \n，身色必赤，腋下温，心下热也。 \n《金匮要略》曰∶六腑气绝于外者，手足寒，五脏气绝于内者，利下不禁。盖伤寒发热，为邪 \n气独甚，若下痢至甚，厥不止，此以邪未解，而腑脏之气先绝，故死。 \n《灵枢·热病篇》曰∶热病不可刺者有九∶一曰汗不出，大颧发赤，哕者死。二曰泄而腹满甚 \n者死。三曰目不明，热不已者死。四曰老人婴儿，热而腹满者死。五曰汗不出，呕下血者死。六曰 \n舌本烂，热不已者死。七曰咳而衄，汗不出，出不至足者死。八曰髓热者死。九曰热而痉者死，腰 \n折螈 齿噤 也。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>伤寒逆证赋（五十七）\n\n属性：伤寒难疗，逆证须知。阳病怕逢阴脉，谵语阴证非宜。乍疏乍数脉之忌，口张目陷舌如煤。干 \n呕出气，骨节痛而呃逆弗已；发斑发黄，大便利而先赤后灰。霍乱躁烦，心下闷而喘胀；腹膨呃逆 \n，下泄利而难溲。四肢厥逆，眼定腹疼如石；内外关格，头汗阳脱溲迟。头连胸痛四肢冷，声哑唇 \n疮狐惑悲。七日已过复大热，喘逆上气脉散危。阴阳易，脉离经而外肾肿，手足挛拳加腹痛。阴阳 \n交，大汗后而热愈甚，躁急狂言食更稀。厥利无脉，灸而不至者肾殆；唇青舌卷，耳聋囊缩者肝离 \n。赤斑黑斑，救五而救一；寻衣撮空，两感者何疑。凡诸 \n汗证，仍当备言∶只在头面不遍身，鼻衄不止；口噤肉战多喘促，如油汗圆。当汗无汗，麻黄数剂 \n不能通，尤嫌脉躁；汗后呕吐，水药不入证反剧，言乱目眩。湿家大汗必成痉，风湿与疸皆谵言。 \n犯湿温，则身青面变，耳聋不语名重 ；发少阴，必九窍出血，下厥上竭奚能痊。动气脉迟弱皆忌 \n，风湿和中湿不堪。其诸下痢，尤宜细参∶热厥利而汗难止，冷厥利而躁不眠；少阳阳明合病，脉 \n弦者负；少阴吐泻无脉，拳厥躁烦。谵语直视而喘满，下痢频数而脉坚。脏结者脐痛引阴，白胎下 \n利；除中则厥逆而利，反能食焉。误下湿家之头汗，溲难便利喘加添。体如熏而摇头直视，心神已 \n绝；唇吻青而四肢多汗，肝气不全。肾绝者，直视狂言而遗尿反目；肺绝者，喘无休歇而汗润发颠 \n。虚汗发黄环口黑，非脾经之吉兆；孤阳偏胜脉暴出，知阴绝之在先。此伤寒之逆候，勿侥幸以图全 \n。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>伤寒治例（五十八）\n\n属性：\\x温散诸方\\x \n麻黄汤（散一） 大温 凡太阳阳明伤寒，而阴邪甚者宜此。 \n桂枝汤（散九） 大温 凡太阳中风兼寒有汗者宜此。 \n麻桂饮（新散七） 大温 凡伤寒初感，邪盛气实者，无论诸经四季，先宜用此。 \n二柴胡饮（新散二） 微温 凡邪感三阳，及三阳并病，寒胜者宜此主之。三阴初感者亦可用 \n。 \n葛根汤（散二九） 大温 治冬月太阳经伤寒，项背强，无汗恶风者宜此。 \n五积散（散三九） 微温 凡感寒邪而阴胜于阳，外有表证，内有呕吐腹痛，及寒湿客于经络，筋 \n骨酸疼等证宜此。 \n十神汤（散四十） 微温 凡时气、风寒、瘟疫，发热憎寒，头疼咳嗽无汗，当温散者宜此。 \n麻黄附子细辛汤（散三） 大温 少阴伤寒，脉沉发热者宜此。 \n小青龙汤（散八） 大温 凡伤寒阴胜，表邪不解，及心下有水气，呕哕，咳嗽，发热，小腹 \n满者宜此。 \n消风百解散（散四六） 微温 凡四时伤寒，头疼发热，及风寒咳嗽，鼻塞声重者宜此。 \n柴胡桂枝干姜汤（散百十四） 微温伤寒汗下后，但头汗出，寒热往来，邪不解者宜此。 \n桂枝加黄 汤（散十） 大温 黄疽脉浮，当以汗解者宜此。 \n\\x凉散诸方\\x \n一柴胡饮（新散一） 微凉 凡六经初感，内外俱有热者宜此。 \n小柴胡汤（散十九） 微凉 凡邪在少阳，及三阳并病，但属半表半里，往来寒热兼呕者宜此。 \n九味羌活汤（散四四） 微凉 凡四时不正之气，风寒感冒，憎寒壮热，头疼身痛者宜此。 \n柴葛解肌汤（散三一） 微凉 凡足阳明证，发热脉洪者宜此。 \n升麻葛根汤（散三十） 微凉 阳明证具，及小儿疫疠疮疹等证宜此。 \n归葛饮（新散十三） 次凉 凡阳明温暑，大热大渴，津枯不能作汗者宜此， \n六神通解散（寒十五） 大凉 凡发热头痛，脉洪无汗，三阳伏火，而表邪不解者宜此。 \n柴胡白虎煎（新散十二） 大寒 凡温病热极，表里不解者宜此。 \n柴平汤（和二三三） 微凉 凡温疟身痛，手足沉重，寒热者宜此。 \n柴芩煎（新散十） 大凉 凡表邪未解，内外俱热，泄泻不止者宜此。 \n大青龙汤（散七） 微寒 凡太阳中风，发热无汗而躁烦者宜此。 \n升麻汤（散百十三） 大寒 凡无汗而喘，烦渴发斑者宜此。 \n四逆散（散二八） 微凉 凡阳邪亢极，四肢厥逆者宜此。 \n\\x平散诸方\\x \n三柴胡饮（新散三） 凡肝脾阴虚血少，而偶感风寒者宜此。 \n正柴胡饮（新散六） 凡气血本无亏损，而感冒寒邪者宜此。 \n柴陈煎（新散九） 凡感冒风寒，发热而兼咳嗽、呕恶者宜此。 \n参苏饮（散三四） 凡四时感冒伤寒，头疼发热无汗，及咳嗽声重，往来潮热者宜此。 \n败毒散（散三六） 凡四时瘟疫、寒热，身体疼痛，及烟瘴之气，或处卑湿香港脚者宜此。 \n升阳散火汤（散四一） 凡胃虚血虚，因寒邪冷物抑遏阳气，以致发热者，宜此发之。 \n加减小柴胡汤（散二二） 凡少阳经寒热往来，脉弦腹痛者宜此。 \n\\x兼补兼散诸方\\x \n补中益气汤（补三十） 凡劳倦伤脾，中气不足，以致外感发热者宜此。 \n补阴益气煎（新补十六） 凡邪陷阴中，阴虚不能作汗，身热不退，或往来寒热者宜此。 \n三柴胡饮（新散三） 凡肝脾血分微虚，而感外邪者宜此。 \n四柴胡饮（新散四） 凡脾肺气虚，或劳倦感寒发热者宜此。 \n五柴胡饮（新散五） 凡睥肾血气不足，而感外邪发热者宜此。 \n理阴煎（新热三） 大温 凡真阴不足，或因劳倦感寒，阴虚假热，寒邪不解者，速宜用此。 \n大温中饮（新散八） 大温 凡中气虚寒感邪，发热无汗，表不能解者，速宜用此。 \n调中益气汤（补三一） 凡风寒湿热所伤，食少体重者宜此。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>温中和中类\n\n属性：\\x大温兼补诸方\\x \n人参理中汤（热一） 大温 治太阴即病自利，阴寒腹痛呕吐，中气虚寒，胀满厥逆，疟痢等证。 \n四逆汤（热十四） 大温 治伤寒阴证，自利脉沉，身痛而厥。 \n胃关煎（新热九） 大温 凡脾肾虚寒，泻痢不止者宜此。 \n桂枝人参汤（散十三） 大温 伤寒表里不解，协热下痢者宜此。 \n白通汤（热一四五） 大热 少阴下痢者宜此。 \n桃花汤（热一四六） 微温 少阴下痢脓血者宜此。 \n真武汤（热一四二） 大温 少阴伤寒腹痛，或呕、或痢者宜此。 \n回阳返本汤（热四五） 大温 伤寒阴盛格阳，阴极发躁，脉弱无力者宜此。 \n四味回阳饮（新热一） 大温 阳脱气虚者宜此。 \n暖肝煎（新热十五） 大温 凡肝肾阴寒，小腹疼痛者宜此。 \n吴茱萸汤（热一三七） 大热 呕而胸满，吐涎头痛者宜此。 \n当归四逆汤（热二十） 微温 伤寒厥逆脉细，下痢肠鸣者宜此。 \n茯苓甘草汤（热七五） 大温 水停心下，作悸作利者宜此。 \n甘草附子汤（热三一） 大热 风湿相搏者宜此。 \n桂枝附子汤（热三十） 大热 风湿相搏，筋骨疼痛者宜此。 \n干姜附子汤（热三四） 大热 瘴毒阴证，厥逆呕吐，自利汗出者宜此。 \n华佗救阳脱方（热六三） 治阴寒直中三阴证。 \n\\x微温和中诸方\\x \n二陈汤（和一） 微温 凡风寒咳嗽，痰饮呕恶，脾胃不和者宜此。 \n六君子汤（补五） 微温 凡脾胃虚弱，或久患疟痢，或呕吐吞酸者宜此。 \n金水六君煎（新和一） 微温 凡阴虚受寒，咳呕喘促，吞酸痞满等证宜此。 \n平胃散（和十七） 微温 凡寒伤脾胃，心腹胀满，呕恶不思饮食，身体疼痛，泻痢者宜此。 \n藿香正气散（和二十） 微温 凡外感风寒，内停饮食，头疼寒热，吐泻胀满者宜此。 \n乌梅丸（和三二三） 微温 吐蛔、蛔厥者宜此。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>清理类\n\n属性：\\x清火诸方\\x \n抽薪饮（新寒三） 大寒 凡热邪内蓄之甚者宜此。 \n徙薪饮（新寒四） 次寒 凡热邪内蓄，将甚未甚者宜此。 \n黄连解毒汤（寒三） 大寒 凡热邪内盛，烦躁狂斑，口渴舌焦，喘满脉洪，热甚者宜此。 \n白虎汤（寒二） 大寒 凡脉洪大渴，阳明热甚，或中暑虚烦等证宜此。 \n人参白虎汤（寒三） 大凉 凡赤斑口燥，烦躁暑热，脉洪大浮虚者宜此。 \n三黄石膏汤（寒十一） 大寒 凡疫瘟大热而躁者宜此。 \n一六甘露散（新寒十五） 大寒 阳明实热，烦躁斑黄等证宜此。 \n益元散（寒百十二） 次寒 凡中暑身热烦渴，小水不利者宜此。 \n玉女煎（新寒十二） 大寒 凡阴虚水亏，阳明火盛，烦渴内热者宜此。 \n阳毒升麻汤（散百六） 大凉 凡阳毒赤斑，狂言失血者宜此。 \n竹叶石膏汤（寒五） 微寒 阳明汗多而渴，鼻衄喜水，暑热烦躁者宜此。 \n桂苓甘露饮（寒八） 微寒 凡伏暑发热烦躁，水道不利者宜此。 \n黄芩清肺饮（寒三八） 次寒 肺热小水不利，或便血者宜此。 \n大连翘饮（寒七八） 次寒 凡风热热毒，大小便不利，及疮毒丹瘤等证宜此。 \n普济消毒饮（寒十三） 大寒 凡疫疠大行，憎寒壮热，头肿目闭，喘渴，咽喉不利，俗名大 \n头瘟、热毒等证宜此。 \n栀子柏皮汤（寒二三） 大寒 伤寒身黄，内外俱热者宜此。 \n白头翁汤（寒一 八四） 大寒 治伤寒热痢。 \n玄参升麻汤（外四八） 次寒 瘟疫颊腮肿痛，发斑、咽痛者宜此。 \n小陷胸汤（寒十六） 微凉 凡小结胸热邪胀满者宜此。 \n八正散（寒百十五） 大寒 凡心经蕴热，脏腑秘结，小便赤涩、血淋等证宜此。 \n解瘟疫热毒法（寒二四） \n\\x清血清便滋阴诸方\\x \n犀角地黄汤（寒七九） 微凉 凡热入血分，吐衄斑黄，及血热血燥，不能作汗，表不解者宜 \n此。 \n二阴煎（新补十） 大凉 心经有热，狂笑、烦热、失血者宜此。 \n加减一阴煎（新补九） 大凉 凡水亏火盛，烦热动血者宜此。 \n五苓散（和一八二） 微温 凡暑热霍乱泄泻，小水不利，湿肿胀满者宜此。 \n导赤散（寒一二二） 微凉 心火小肠热秘，小水不利者宜此。 \n大厘清饮（新寒五） 微寒 凡积热闭结，小水不通，热泻等证宜此。 \n小厘清饮（新和十） 性平 凡小水不利，湿滞肿胀，泄泻者宜此。 \n猪苓汤（和一八八） 微凉 伤寒下后，发热，小便不利者宜此。 \n\\x清胃诸方\\x \n大和中饮（新和七） 性平 凡邪结胃脘，气逆食滞者宜此。 \n小和中饮（新和八） 性平 胸膈胀满，呕恶气滞者宜此。 \n小半夏茯苓汤（和九） 微温 膈间有水，呕吐，心下痞者宜此。 \n半夏泻心汤（寒二八） 微凉 呕而肠鸣，心下痞者宜此。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>吐涌类\n\n属性：独圣散（攻百六） 凡邪实上焦，及痰涎积蓄者宜此。 \n茶调散（攻百七）治同前。 \n吐剂（新攻一）此有二法，便而且易，可随宜用之。 \n栀子豉汤（寒二十）伤寒烦热懊 ，当吐者宜此。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>攻下类\n\n属性：\\x峻下诸方\\x \n大承气汤（攻一） 凡阳明、太阴伤寒，及各经实热内结者宜此。 \n小承气汤（攻二） 凡病在太阴，无表证，潮热脉实，狂言腹胀者宜此。 \n调胃承气汤（攻三） 凡太阳、阳明，不恶寒，反恶热、潮热，邪入腑者宜此。 \n桃仁承气汤（攻四） 凡伤寒蓄血证，小腹急痛，大便不通而黑者宜此。 \n大柴胡汤（攻七） 凡伤寒表证未除，里证又急，当汗下兼行者宜此。 \n大陷胸汤（攻九） 凡结胸胀痛连腹，手足不可近者宜此。 \n六一顺气汤（攻八） 凡伤寒热邪传里，便实口燥，狂斑潮热，腹胀硬痛等证，宜用此以代三 \n承气汤。 \n凉膈散（攻十九） 凡三焦六经火邪内结不通者宜此。 \n百顺丸（新攻六） 凡三焦热秘，邪不解者宜此。 \n茵陈蒿汤（攻三一） 谷疸，发热身黄，便结者宜此。 \n罨结胸法（新因三十） \n\\x攻补兼用诸方\\x \n黄龙汤（攻二一） 凡伤寒热邪传里，当下而气血兼虚者宜此。 \n玉烛散（攻二四） 凡血虚有滞，而热邪传里，腹胀作痛者宜此。 \n\n\n\n<目录>卷之八须集\\伤寒典（下）\n\n<篇名>培补类\n\n属性：\\x峻补诸方\\x \n大补元煎（新补一）凡元气大虚者，虽有寒邪，亦不可攻，必单培根本，正复邪将自散，或真寒假 \n热等证皆宜用此。 \n大营煎（新补十四）此大补元煎之次者也，酌宜用之。 \n三阴煎（新补十一） 凡三阴不足，及风疟多汗，而正气不复，寒热不止者宜此。 \n六味回阳饮（新热二） 凡阴阳大虚，元气将脱者，非此不可。 \n八珍汤（补十九） 气血两虚者宜此。 \n十全大补汤（补二十） 凡气血两虚，恶寒发热，倦卧眩运，自汗诸虚者宜此。 \n大建中汤（补二三） 凡中气不足，厥逆呕吐，虚斑虚火，筋骨疼痛等证宜此。 \n独参汤（补三五） 凡气虚气脱，畏闻诸药气味，及反胃呕吐垂危者，惟此为宜。 \n参附汤（补三七） 凡真阳不足，喘呕呃逆，腹痛厥冷气短者宜此。 \n参归汤（补三八） 凡心虚、血虚、盗汗等证宜此。 \n\\x补阴诸方\\x \n阴煎（新补八） 凡肾水真阴不足，而虚火为邪者宜此。 \n小营煎（新补十五） 凡血少阴虚而无火者宜此。 \n左归饮（新补二） 凡命门真阴亏损，虽有寒邪不可攻者宜此。 \n右归饮（新补三） 凡命门阳衰，或阴盛格阳，感邪不可攻者宜此。 \n四物汤（补八） 凡阴虚营弱，病在血分者宜此。 \n生脉散（补五六） 凡热伤元气，口渴气短，烦躁倦怠汗出者宜此。 \n六味地黄丸（补百二十） 阴虚水亏发热等证宜此。 \n崔氏八味丸（补一二一） 凡阴盛格阳，火不归原，及真阳虚败等证宜此。 \n\\x补中诸方\\x \n四君子汤（补一） 凡脾胃虚弱，食少体瘦，疟痢劳倦等证宜此。 \n五君子煎（新热六） 凡脾胃气分虚弱，而微寒当温者宜此。 \n五味异功散（补四） 凡脾胃虚寒，饮食少思，气逆腹满者宜此。 \n五福饮（新补六） 凡五脏气血俱虚者宜此为主。 \n温胃饮（新热五） 凡中寒呕吐吞酸者宜此。 \n养中煎（新热四） 凡中气虚寒，为呕为泄者宜此。 \n归脾汤（补三二） 凡脾虚健忘怔忡，少食困倦，疟痢等证宜此。 \n参苓白术散（补五四） 凡脾胃虚弱，吐泻食少等证宜此。 \n参术汤（补四十） 凡气虚颤掉，泄泻呕吐者宜此。 \n\n\n\n<目录>卷之十从集·杂证谟\\诸风\n\n<篇名>经义\n\n属性：《九宫八风篇》曰∶太一常以冬至之日，居叶蛰之宫四十六日，明日居天留四十六日， \n明日居仓门四十六日，明日居阴洛四十五日，明日居天宫四十六日，明日居玄委四十六日， \n明日居仓果四十六日，明日居新洛四十五日，明日复居叶蛰之宫，日冬至矣。常如是无已， \n终而复始。太一移日，天必应之以风雨，以其日风雨则吉，岁美民安少病矣。先之则多雨， \n后之则多旱。太一在冬至之日有变，占在君；太一在春分之日有变，占在相；太一在中宫之 \n日有变，占在吏；太一在秋分之日有变，占在将；太一在夏至之日有变，占在百姓。所谓有 \n变者，太一居五宫之日，病风折树木，扬砂石，各以其所主占贵贱。因视风所从来而占之。 \n风从其所居之乡来为实风，主生，长养万物。从其冲后来为虚风，伤人者也，主杀主害者。 \n谨候虚风而避之，故圣人日避虚邪之道，如避矢石然，邪弗能害，此之谓也。是故太一入徙 \n立于中宫，乃朝八风，以占吉凶也。风从南方来，名曰大弱风。其伤人也，内舍于心，外在 \n于脉，气主热。风从西南方来，名曰谋风。其伤人也，内舍于脾，外在于肌，其气主为弱。 \n风从西方来，名曰刚风，其伤人也，内舍于肺，外在于皮肤，其气主为燥。风从西北方来， \n名曰折风。其伤人也，内舍于小肠，外在于手太阳脉，脉绝则溢，脉闭则结不通，善暴死。 \n风从北方来，名曰大刚风。其伤人也，内舍于肾，外在于骨与肩背之膂筋，其气主为寒也。 \n风从东北方来，名曰凶风。其伤人也，内舍于大肠，外在于两肋腋骨下及肢节。风从东方来 \n，名曰婴儿风。其伤人也，内舍于肝，外在于筋纽，其气主为身湿。风从东南方来，名曰弱 \n风。其伤人也，内舍于胃，外在肌肉，其气主体重。此八风皆从其虚之乡来，乃能病患。三 \n虚相搏，则为暴病卒死。两实一虚，病则为淋露寒热。犯其雨湿之地，则为痿。故圣人避风 \n，如避矢石焉。其有三虚而偏中于邪风，则为击仆偏枯矣。 \n《岁露论》∶黄帝问于少师曰∶余闻四时八风之中人也。故有寒暑，寒则皮肤急而腠理 \n闭，暑则皮肤缓而腠理开。贼风邪气因得以入乎？将必须八正虚邪，乃能伤人乎？少师答曰∶ \n不然。贼风邪气之中人也，不得以时。然必因其开也，其入深，其内极病，其病患也卒暴； \n因其闭也，其入浅以留，其病也徐以迟。帝曰∶有寒温和适，腠理不开，然有卒病者，其故 \n何也？少师曰∶虽平居，其腠理开闭缓急，其故常有时也。人与天地相参也，与日月相应也 \n。故月满则海水西盛，人血气积，肌肉充，皮肤致，毛发坚，腠理 ，烟垢着。当是之时， \n虽遇贼风，其入浅不深。至其月郭空，则海水东盛。人气血虚，其卫气去，形独居，肌肉减 \n，皮肤纵，腠理开，毛发残， 理薄，烟垢落。当是之时，遇贼风则其入深，其病患也 \n卒暴。帝曰∶其有卒然暴死暴病者何也？少师曰∶三虚者，其死暴疾也；得三实者，邪不能 \n伤人也。帝曰∶愿闻三虚。曰∶乘年之衰，逢月之空，失时之和，因为贼风所伤，是谓三虚 \n。故论不知三虚，工反为粗。帝曰∶愿闻三实。少师曰∶逢年之盛，遇月之满，得时之和， \n虽有贼风邪气，不能危之也。帝曰∶愿闻岁之所以皆同病者，何因而然？少师曰∶此八正之 \n候也。候此者，常以冬至之日，太一立于叶蛰之宫，其至也。天必应之以风雨者矣。风雨从 \n南方来者，为虚风，贼伤人者也。其以夜半至也。万民皆卧而弗犯也，故其岁民少病。其以 \n昼至者，万民懈惰而皆中于虚风，故万民多病。虚邪入客于骨而不发于外，至其立春，阳气 \n大发，腠理开。因立春之日，风从西方来，万民又皆中于虚风，此两邪相搏，经气结代者矣 \n。故逢其风而遇其雨者，命曰遇岁露焉。因岁之和，而少贼风者，民少病而少死；岁多贼风 \n邪气，寒温不和，则民多病而死矣。 \n《八正神明论》帝曰∶星辰八正何候？岐伯曰∶星辰者，所以制日月之行也；八正者 \n，所以候八风之虚邪，以时至者也。四时者，所以分春秋冬夏之气所在，以时调之也。八正 \n之虚邪，而避之勿犯也。以身之虚，而逢天之虚，两虚相感，其气至骨，入则伤五脏。工候 \n救之，弗能伤也。故曰∶天忌不可不知也。虚邪者，八正之虚邪气也。正邪者，身形若用力 \n汗出，腠理开，逢虚风，其中人也微。故莫知其情，莫见其形。 \n《阴阳应象大论》曰∶风胜则动，热胜则肿，燥胜则干，寒胜则浮，湿胜则濡泻。冬伤 \n于寒，春必温病；春伤于风，夏生飧泄。天气通于肺，地气通于嗌，风气通于肝，雷气通于 \n心，谷气通于脾，雨气通于肾。阳之汗，以天地之雨名之；阳之气，以天地之疾风名之。邪 \n风之至，疾如风雨。故善治者，治皮毛，其次治肌肤，其次治筋脉，其次治六腑，其次治五 \n脏。治五脏者，半死半生也。故天之邪气，感则害人五脏；水谷之寒热，感则害于六腑；地 \n之湿气，感则害皮肉筋脉。东方生风，风生木，木生酸，酸生肝，肝生筋，筋生心。神在 \n天为风，在地为木，在体为筋，在脏为肝，在色为苍，在音为角，在声为呼，在变动为握， \n在窍为目，在味为酸，在志为怒。风伤筋，燥胜风，风胜湿。 \n《风论》∶黄帝问曰∶风之伤人也，或为寒热，或为热中，或为寒中，或为疠风，或为 \n偏枯，或为风也，其病各异，其名不同。或内至五脏六腑，不知其解，愿闻其说。岐伯对曰 \n∶风气藏于皮肤之间，内不得通，外不得泄。风者善行而数变，腠理开则洒然寒，闭则热而 \n闷。其寒也则衰食饮。其热也则消肌肉。故使人 栗而不能食，名曰寒热。风气与阳明 \n入胃，循脉而上至目内 ，其人肥则风气不得外泄，则为热中而目黄；人瘦则外泄而寒，则 \n为寒中而泣出。风气与太阳俱入，行诸脉俞，散于分肉之间，与卫气相干，其道不利，故使 \n肌肉愤 而有疡，卫气有所凝而不行，故其肉有不仁也。疠者，有营气热 ，其气 \n不清，故使鼻柱坏而色败，皮肤疡溃，风寒客于脉而不去，名曰疠风，或名曰寒热。以春甲 \n乙伤于风者为肝风，以夏丙丁伤于风者为心风，以季夏戊己伤于邪者为脾风，以秋庚辛中于 \n邪者为肺风，以冬壬癸中于邪者为肾风。风中五脏六腑之俞，亦为脏腑之风，各入其门户所 \n中，皆为偏风。风气循风府而上，则为脑风。风入系头，则为目风、眼寒。饮酒中风，则为 \n漏风。入房汗出中风，则为内风。新沐中风，则为首风。久风入中，则为肠风飧泄。外在腠 \n理，则为泄风。故风者百病之长也，至其变化，乃为他病也，无常方，然致有风气也。帝曰 \n∶五脏风之形状不同者何？愿闻其诊及其病能。岐伯曰∶肺风之状，多汗恶风，色 然 \n白，时咳短气，昼日则瘥，暮则甚，诊在眉上，其色白。心风之状，多汗恶风，焦绝，善怒 \n吓，赤色，病甚则言不可快，诊在口，其色赤。肝风之状，多汗恶风，善悲，色微苍，嗌干 \n善怒，时憎女子，诊在目下，其色青。脾风之状，多汗恶风，身体怠惰，四支不欲动，色薄 \n微黄，不嗜食，诊在鼻上，其色黄。肾风之状，多汗恶风，面 然浮肿，脊痛不能正立 \n，其色 ，隐曲不利，诊在肌上，其色黑。胃风之状，颈多汗恶风，食饮不下，鬲塞不 \n通，腹善满，失衣则 胀，食寒则泄，诊形瘦而腹大。首风之状，头面多汗恶风，当先 \n风一日则病甚，头痛不可以出内，至其风日，则病少愈。漏风之状，或多汗，常不可单衣， \n食则汗出，甚则身汗，喘息恶风，衣常濡，口干善渴，不能劳事。泄风之状，多汗，汗出泄 \n衣上，口中干上渍，其风不能劳事，身体尽痛则寒。 \n《玉机真藏论》曰∶风者百病之长也，今风寒客于人，使人毫毛毕直，皮肤闭而为热， \n当是之时，可汗而发也。或痹不仁肿痛，当是之时，可汤熨及火灸刺而去之。弗治，病入舍 \n于肺，名曰肺痹，发咳上气。弗治，肺即传而行之肝，名曰肝痹，一名曰厥，胁痛出食，当 \n是之时，可按若刺耳。弗治，肝传之脾，病名曰脾风，发瘅，腹中热，烦心出黄，当此之时 \n，可按可药可浴。弗治，脾传之肾，病名曰疝瘕，少腹冤热而痛，出白，一名曰蛊，当此之 \n时，可按可药。弗治，肾传之心，病筋脉相引而急，病名曰螈，当此之时，可灸可药。弗治 \n，满十日，法当死。肾因传之心，心即复反传而行之肺，发寒热，病当三岁死。此病之次也 \n。 \n《金匮真言论》帝曰∶天有八风，经有五风，何谓？岐伯曰∶八风发邪，以为经风， \n触五脏，邪气发病。所谓得四时之胜者，春胜长夏，长夏胜冬，冬胜夏，夏胜秋，秋胜春， \n所谓四时之胜也。东风生于春，病在肝，俞在颈项；南风生于夏，病在心，俞在胸胁；西风 \n生于秋，病在肺，俞在肩背；北风生于冬，病在肾，俞在腰股；中央为土，病在脾，俞在脊 \n。故春气者病在头，夏气者病在脏，秋气者病在肩背，冬气者病在四肢。故春善病鼽衄，仲 \n夏善病胸胁，长夏善病洞泄寒中，秋善病风疟，冬善病痹厥。夏暑汗不出者，秋成风疟。 \n《调经论》曰∶风雨之伤人也，先客于皮肤，传入于孙脉，孙脉满则传入于络脉，络脉 \n满则输于大经脉，血气与邪并客于分腠之间，其脉坚大，故曰实。实者外坚充满，不可按之 \n，按之则痛。寒湿之伤人也，皮肤不收，肌肉坚紧，荣血泣，卫气去，故曰虚。虚者聂辟气 \n不足，按之则气足以温之，故快然而不痛。 \n《太阴阳明论》曰∶故犯贼风虚邪者，阳受之。阳受之则入六腑，入六腑则身热不时卧 \n，上为喘呼。故阳受风气，阴受湿气。故伤于风者，上先受之。伤于湿者，下先受之。 \n《生气通天论》曰∶风者，百病之始也，清静则肉腠闭拒，虽有大风苛毒，弗之能害， \n此因时之序也。因于露风，乃生寒热。是以春伤于风，邪气留连，乃为洞泄。夏伤于暑，秋 \n为咳疟。秋伤于湿，上逆而咳，发为痿厥。冬伤于寒，春必温病。四时之气，更伤五脏。 \n《百病始生篇》帝曰∶夫百病之始生也，皆生于风雨寒暑，清湿喜怒。三部之气，所 \n伤异类，愿闻其会。岐伯曰∶三部之气各不同，或起于阴，或起于阳，请言其方。喜怒不节 \n则伤脏，伤脏则病起于阴也，清湿袭虚则病起于下，风寒袭虚则病起于上，是谓三部。至其 \n淫，不可胜数。岐伯曰∶风雨寒热，不得虚，邪不能独伤人。卒然逢疾风豪雨而不病 \n者，盖无虚故邪不能独伤人，此必因虚邪之风，与其身形，两虚相得，乃客其形。其中于 \n虚邪也，因与天时，与其身形，参以虚实，大病乃成，气有定舍，因处为名，上下中外，分 \n为三员。是故虚邪之中人也，始于皮肤，皮肤缓则腠理开，开则邪从毛发入，入则抵深，深 \n则毛发立，毛发立则淅然，故皮肤痛。留而不去，则传舍于络脉，在络之时，痛于肌肉，其 \n痛之时息，大经乃代。留而不去，传舍于经，在经之时，洒淅喜惊。留而不去，传舍于输， \n在输之时，六经不通，四肢则肢节痛，腰脊乃强。留而不去，传舍于伏冲之脉，在伏冲之时 \n，体重身痛。留而不去，传舍于肠胃，在肠胃之时，贲响腹胀，多寒则肠鸣飧泄，食不化， \n多热则溏出糜。留而不去，传舍于肠胃之外，募原之间，留着于脉，稽留而不去，息而成积 \n。邪气淫 ，不可胜论。帝曰∶治之奈何？岐伯曰∶察其所痛，以知其应，有余不足， \n当补则补，当泻则泻，毋逆天时，是谓至治。 \n《邪气脏腑病形篇》曰∶诸阳之会，皆在于面。中人也方乘虚时，及新用力。若饮食汗 \n出，腠理开，而中于邪。中于面则下阳明，中于项则下太阳，中于颊则下少阳，其中于膺背 \n两胁，亦中其经。虚邪之中身也，洒淅动形。正邪之中人也微，先见于色，不知于身。若有 \n若无，若亡若存，有形无形，莫知其情。 \n《刺节真邪论》曰∶虚邪之中于人也，洒淅动形，起毫毛而发腠理。其入深，内搏于骨 \n，则为骨痹。搏于筋，则为筋挛。搏于脉中，血闭不通，则为痈。搏于肉，与卫气相搏，阳 \n胜者则为热，阴胜者则为寒，寒则真气去，去则虚，虚则寒。搏于皮肤之间，其气外发，腠 \n理开，毫毛摇，气往来行，则为痒。留而不去则痹。卫气不行，则为不仁。虚邪偏客于身半 \n，其入深，内居营卫，营卫稍衰，则真气去，邪气独留，发为偏枯。其邪气浅者，脉偏痛。 \n虚邪之入于身也深。寒与热相搏，久留而内着。寒胜其热，则骨疼肉枯。热胜其寒，则烂肉 \n腐肌为脓。内伤骨，内伤骨为骨蚀。 \n《脉要精微论》曰∶风成为寒热，久风为飧泄，脉风成为疠，来徐去疾，上虚下实，为 \n恶风也。故中恶风者，阳受气也。 \n《寿夭刚柔篇》曰∶病在阳者，命曰风。病在阴者，命曰痹。阴阳俱病，命曰风痹。风 \n寒伤形，忧、恐、忿、怒伤气。 \n《通评虚实论》曰∶不从内外中风之病，故瘦留着也。 跛，风寒湿之病也。 \n《平人气象论》曰∶面肿曰风。人一呼脉三动，一吸脉三动而躁。尺热曰病温；尺不热 \n脉滑曰病风。脉涩曰痹。 \n《刺志论》曰∶脉大血少者，脉有风气，水浆不入，此之谓也。 \n《阴阳别论》曰∶二阳之病发心脾，其传为风消，其传为息贲者，死不治。二阳一阴发 \n病，主惊骇，背痛，善噫，善欠，名曰风厥。三阳三阴发病，为偏枯痿易，四肢不举。 \n《五色篇》曰∶黄赤为风，青黑为痛，白为寒，黄而膏润为脓，赤甚者为血，痛甚为挛 \n，寒甚为皮不仁。 \n《评热病论》帝曰∶有病身热汗出烦满，烦满不为汗解，此为何病？岐伯曰∶汗出而 \n身热者，风也 \n。汗出而烦满不解者，厥也。病名曰风厥。巨阳主气，故先受邪；少阴与其为表里也，得热 \n则上从之，从之则厥也。帝曰∶治之奈何？曰∶表里刺之，饮之服汤。帝曰∶劳风为病何如？ \n岐伯曰∶劳风法在肺下，其为病也，使人强上冥视，唾出若涕，恶风而振寒，此为劳风之病 \n。帝曰∶治之奈何？曰∶以救俯仰。巨阳引精者三日，中年者五日，不精者七日。咳出青黄 \n涕，其状如脓，大如弹丸，从口中若鼻中出，不出则伤肺，伤肺则死矣。 \n《病能论》帝曰∶有病身热懈惰，汗出如浴，恶风少气，此为何病？岐伯曰∶病名曰 \n酒风。治之以泽泻、术各十分，麋衔五分，合以三指撮，为后饭。 \n《骨空论》曰∶风从外入，令人振寒，汗出头痛，身重恶寒，治其风府，调其阴阳，不 \n足则补，有余则泻。大风颈项痛，刺风府，风府在上椎。大风汗出，灸噫嘻，噫嘻 \n在背下侠脊傍三寸所。 \n《四时气篇》曰∶疠风者，素刺其肿上，已刺，以锐针针其处，按出其恶气，肿尽乃止 \n。常食方食，无食他食。 \n《热病篇》曰∶偏枯，身偏不用而痛，言不变，志不乱，病在分腠之间，巨针取之。益 \n其不足，损其有余，乃可复也。痱之为病也，身无痛者，四肢不收，智乱不甚，其言微知。 \n可治，甚则不能言，不可治也。病先起于阳，后起于阴者。先取其阳，后取其阴，浮而取之 \n。风痉身反折，先取足太阳及 中及血络出血；中有寒，取三里。 \n《至真要大论》曰∶厥阴司天，其化以风。风气大来，木之胜也。土湿受邪，脾病生焉 \n。诸风掉眩，皆属于肝。诸暴强直，皆属于风。 \n《气交变大论》曰∶岁木太过，风气流行，脾土受邪。民病飧泄，食减体重，烦冤，肠 \n鸣，腹支满，上应岁星。甚则忽忽善怒，眩冒巅疾。 \n《五常政大论》曰∶厥阴司天，风气下临，脾气上从，而土且隆，黄起水乃眚，土用革 \n，体重，肌肉萎，食减口爽，风行太虚，云物摇动，目转耳鸣。 \n《六元正纪大论》曰∶厥阴所至，为风府，为璺启。厥阴所至，为风生，终为肃。木郁 \n之发，太虚埃昏，云物以扰，大风乃起，发屋折木，木有变。故民病胃脘当心而痛，上支两 \n胁，鬲咽不通，食饮不下，甚则耳鸣眩转，目不识人，善暴僵仆。太虚苍埃，天山一色，或 \n为浊色，黄黑郁若，横云不起，雨而乃发也，其气无常。长川草偃，柔叶呈阴，松吟高山， \n虎啸岩岫，怫之先兆也。 \n\n\n\n<目录>卷之十从集·杂证谟\\诸风\n\n<篇名>论古今中风之辨（共三条）\n\n属性：夫风邪中人，本皆表证，考之《内经》所载诸风，皆指外邪为言，故并无神魂昏愦，直 \n视僵仆，口眼歪斜，牙关紧急，语言謇涩，失音烦乱，摇头吐沫，痰涎壅盛，半身不遂，瘫 \n痪软弱，筋脉拘挛，抽搐螈 ，遗尿失禁等说。可见此等证候，原非外感风邪，总由内伤血 \n气也。夫风自外入者，必由浅而深，由渐而甚，自有表证。既有表证，方可治以疏散。而今 \n之所谓中风者则不然，但见有卒倒昏迷，神魂失守之类，无论其有无表邪，有无寒热，及有 \n无筋骨疼痛等证，便皆谓之中风，误亦甚矣。虽《热病篇》有偏枯一证，曰∶身偏不用而痛 \n。此以痛痹为言，非今之所谓中风也。《阴阳别论》有曰∶三阴三阳发病，为偏枯痿易，四 \n肢不举，此以经病为言，亦非所谓风也。继自越人、仲景，亦皆以外感言风，初未尝以非风 \n言风也。迨至汉末华元化所言五脏之风，则稍与《内经》不同，而始有吐沫，身直口噤，筋 \n急，舌强不能言，手足不遂等说，然犹不甚相远。再自隋唐以来，则巢氏《病源》、孙氏《 \n千金》等方，以至宋元诸家所列风证，日多日详，而是风非风始混乱莫辨，而愈失其真矣。 \n故余悉采其要，列证如前。凡《内经》所不言者，皆不得谓之风证，即或稍有相涉，亦必以 \n四诊相参，必其真有外感实邪，方可以风论治，否则误人不小也。 \n一、《难经》曰∶伤寒有几，其脉有变否？然∶伤寒有五∶有中风，有伤寒，有湿温， \n有热病，有温病。其所苦各不同。 \n详此《难经》之云中风者，本五种伤寒之一。又仲景曰∶太阳病，发热汗出，恶风脉缓 \n者，名为中风。由此观之，可见《内经》之凡言中风者，本以外感寒邪为言也，岂后世以内 \n伤属风等证悉认之为外感中风耶？ \n一、仲景《要略》曰∶夫风之为病，当半身不遂，或但臂不遂者，此为痹；脉微而数， \n中风使然。寸口脉浮而紧，紧则为寒，浮则为虚，寒虚相搏，邪在皮肤；浮者血虚，络脉空 \n虚，贼邪不泻，或左或右，邪气反缓，正气即急，正气引邪， 僻不遂。邪在于络，肌 \n肤不仁；邪在于经，即重不胜；邪入于腑，即不识人；邪入于脏，舌即难言，口吐涎。 \n观仲景之论中风者如此。其所云半身不遂者，此为痹，乃指痛风之属为言。谓其由于风 \n寒也。再如邪在皮肤，及在络、在经、入腑、入脏者，此谓由浅而深，亦皆以外邪传变为言 \n也。惟 僻吐涎二证，在《内经》诸风并无言及，而仲景创言之。故自唐宋以来，则渐 \n有中经、中血脉、中腑、中脏之说。而凡以内伤偏枯、气脱、卒倒、厥逆等证，悉认为中风 \n，而忘却真风面目矣。 \n\n\n\n<目录>卷之十从集·杂证谟\\诸风\n\n<篇名>论中风属风\n\n属性：风有真风、类风，不可不辨。凡风寒之中于外者，乃为风邪。如《九宫八风篇》之风占 \n病候，《岁露论》之虚风实风，《金匮真言论》之四时风证，《风论》之脏腑中风，《玉机"}, {"n": 6, "text": "卷六\n\n真脏论》之风痹、风瘅、痹论，《贼风篇》之风邪为痹，《疟论》《岁露论》之疟生于风， \n《评热病论》之风厥、劳风，《骨空论》之大风，《热病篇》之风痉，《病能论》之酒风， \n《咳论》之感寒咳嗽，是皆外感风邪之病也。其有不由外感而亦各为风者。如病机所云∶诸 \n暴强直，皆属于风；诸风掉眩，皆属于肝之类。是皆属风而实非外中之风也。 \n何以见之？盖有所中者谓之中，无所中者谓之属。夫既无所中，何谓之属？此以五运之气 \n，各有所主。如诸湿肿满，皆属于脾；诸寒收引，皆属于肾，是皆以所属为言，而风之属于 \n肝者，即此谓也。盖肝为东方之脏，其藏血，其主风，肝病则血病而筋失所养。筋病则掉眩 \n强直之类无所不至，而属风之证百出，此所谓皆属于肝，亦皆属于风也。夫中于风者，即真 \n风也；属于风者，即木邪也。真风者，外感之表证也；属风者，内伤之里证也，即厥逆内夺 \n之属也。 \n夫曰中曰属，此在《内经》固已显然，各有所谓。即如年辰之属鼠属牛，岂即为牛为鼠 \n乎？而后世不能明辨，遂致方论混传，表里误治。千古之弊，莫此为甚。第在《内经》则原 \n无真中、类中之分，而王安道始有此论，予甚善之。第惜其辨有未尽，故复述之，以详其说 \n。凡欲明此义者，但当于中风、属风、表证、里证四者之间。默而思之，当自见其真矣。 \n\n\n\n<目录>卷之十从集·杂证谟\\诸风\n\n<篇名>论河间中风说\n\n属性：河间《原病式》曰∶凡人风病，多因热甚，而风燥者，为其兼化，以热为其主也。俗云 \n风者，言末而忘其本也。所以中风瘫痪者，非谓肝木之风实甚而卒中之也。亦非外中于风尔 \n。由乎将息失宜而心火暴甚，肾水虚衰，不能制之，则阴虚阳实而热气怫郁，心神昏冒，筋 \n骨不用，而卒倒无所知也。多因喜、怒、思、悲、恐五志有所过极而卒中者，皆为热甚故也 \n。若病微则但僵仆，气血流通，筋脉不挛。缓者发过如故。或热气太甚，郁结壅滞，气血不 \n能宣通，阴气暴绝，则阳气后竭而死。 \n据河间此论，谓非肝木之风，亦非外中之风，由乎将息失宜，此独得之见，诚然善矣。 \n然皆谓为热甚，则不然也。凡将息失宜，五志过极，本属劳伤证也。而劳伤血气者，岂皆火 \n证？又岂无阳虚病乎？经曰∶喜怒伤气，寒暑伤形，暴怒伤阴，暴喜伤阳。夫伤阴者，水亏 \n也。伤阳者，火虚也。以虚作火，鲜不危矣。 \n又河间曰∶其中腑者，面加五色，有表证，脉浮而恶寒，拘急不仁，皆曰中腑也。其治 \n多易。中脏者，唇吻不收，舌不转而失音，鼻不闻香臭，耳聋而眼瞀，大小便闭结，皆曰中 \n脏也。其治多难。大抵中腑者多着四肢，中脏者多滞九窍。若风中腑者，先以加减续命汤， \n随证发其表；若忽中脏者，则大便多秘涩，宜以三化汤通其滞。表里证已定，别无他证，故 \n以大药和治之。 \n据此云脉浮恶寒，拘急不仁等证，本皆伤寒之类也。何又名为中腑？唇不收，舌不转， \n失音耳聋等证，本皆厥夺之类也。何又名为中脏？自中脏中腑之说并列为言，而内伤外感之 \n证，斯无辨而混乱矣。且续命汤、三化汤之属，但可以散风寒，攻实热。若所云将息失宜者 \n，岂尚堪治之以此？ \n\n\n\n<目录>卷之十从集·杂证谟\\诸风\n\n<篇名>论东垣中风说\n\n属性：东垣《发明》曰∶阳之气，以天地之疾风名之。此中风者，非外来风邪，乃本气自病也 \n。凡人年逾四旬，气衰之际，或忧喜忿怒伤其气者，多有此疾，壮岁之时无有也；若肥甚者 \n则间有之，亦是形盛气衰而如此耳。治法当和脏腑，通经络，便是治风也。 \n据东垣年逾四旬气衰之说，其发明病机，切中病情，诚出诸贤之表者，余深服之。然忧 \n、喜、忿、怒伤气者固有此疾，而酒色劳倦伤阴者尤多此疾。何以言之？盖气生于阳，形成 \n于阴。余尝曰∶察阳者，察其衰与不衰。察阴者察其坏与不坏。夫阳衰则气去，故神志昏乱 \n；阴亏则形坏，故肢体废弛，此衰坏之谓也。所以此病多在四旬之外，正以其渐伤渐败，而 \n至此始见其非外感，而总由内伤可知也。今以气脱形坏之病，顾可谓之风热而散之攻之也否 \n乎？ \n又东垣曰∶中血脉则口眼歪，中腑则肢节废，中脏则性命危，三治各不同。中血脉者， \n外有六经之形证，则从小续命汤加减。中腑者内有便溺之阻格，宜三化汤等通利之。外无六 \n经之形证，内无便溺之阻隔，宜养血通气。大秦艽汤、羌活愈风汤主之。 \n据东垣、河间之说，若有同者，若有异者。如云中腑中脏，本皆同也。而东垣又云中血 \n脉，则稍异矣。又如续命汤，在河间则以治腑病，东垣则以治血脉；三化汤在河间用以治中 \n脏，而东垣用以治中腑，则又异矣。此或因证施治，各有所宜，姑无论也。再如河间曰∶此 \n非肝木之风，亦非外中于风。东垣亦曰∶非外来风邪，乃本气自病也。夫皆曰非风，而又皆 \n曰中腑中脏，不知所中者为何物，则分明又指为风矣。夫既曰将息失宜，又曰气衰所致，本 \n皆言其虚也。而治法皆用汗下，则分明又作实邪矣。此等名目混乱，泾渭不分，若曰是，若 \n曰非，而含糊于可否之间，因致后学茫然莫知所宗。正以议论日多，不得其要，反滋千古疑 \n窦，深可慨也。至若续命、三化等汤，恐亦非神衰形坏之人所能堪者。故凡读书稽古之士， \n宜加精究。勿谓古人之法如此，便可执而混用。 \n\n\n\n<目录>卷之十从集·杂证谟\\诸风\n\n<篇名>论丹溪中风说\n\n属性：丹溪曰∶按《内经》以下，皆谓外中风邪，然地有南北之殊，不可一途而论。惟刘河间 \n作将息失宜，水不制火者极是。由今言之，西北二方，亦有真为风所中者，但极少耳；东南 \n之人，多是湿土生痰，痰生热，热生风耳。 \n据丹溪引《内经》以下皆谓外中风邪之说，不知《内经》之凡言风者，皆以外感为言， \n原非后世之所谓中风也。观《难经》五种伤寒之意可知矣。而丹溪之言，岂得内经之本意乎 \n？至若东南之人，只是湿痰生热，热生风，此仍述河间热甚之说，而非风等证。岂皆热病？即 \n云为痰，又岂无寒痰。而何以痰即生热，热即生风也？且非风则已，是风则南北俱有，若云 \n东南寒少，未必杀人则可，而云风少则不可也。非痰则已，是痰亦南北俱有。若水土之外湿 \n，东南虽多；而乳酪之内湿，则西北尤多也。虽痰之为物，本为湿动。然脾健则无，脾弱则 \n有，而脾败则甚。是可见因病所以生痰，非因痰所以生病也。凡治失其本而欲望病愈者，未 \n之有也。 \n又丹溪曰∶半身不遂，大率多痰。在左属死血与瘀血，宜四物汤加桃仁、红花、竹沥、 \n姜汁；在右属痰属气虚，宜二陈汤、四君子汤加竹沥、姜汁。 \n据丹溪此说，若乎近理，故人多信之，而不知其有不然也。夫人身血气，本不相离，焉 \n得以左为血病，右为痰气耶？盖丹溪之意，以为肝属木而位左，肝主血也；肺属金而位右， \n肺主气也；脾属土而寄位西南，故亦在右，而脾主湿与痰也。然此以五行方位之序，言其理 \n耳。岂曰西无木，东无金乎？且各经皆有左右，五脏皆有血气。即如胃之大络，乃出于左乳 \n之下，则脾胃之气亦出于左。又岂左非脾，右非肝，左必血病，右必痰气乎？然则何以辨之？ \n此惟《内经》以阴阳分血气，以左右言轻重，则至当也。经曰∶左右者，阴阳之道路也。又 \n曰∶阴胜则阳病，阳胜则阴病。又曰∶女子右为逆，左为从；男子左为逆，右为从。夫阳病 \n者，即气病也。气本乎阳，而阴邪胜之则病也。阴病者，即血病也，血本乎阴，而阳邪胜之 \n则病也。从者病轻，男病宜右，女病宜左也。逆者病重，男病畏左，女病畏右也。以此辨之 \n，而再参以脉色，察其病因，则在气在血，或重或轻，斯得其真矣。若谓左必血病，右必痰 \n气，则未免非痰治痰，非血治血，而诛伐无过，鲜不误矣。 \n\n\n\n<目录>卷之十从集·杂证谟\\诸风\n\n<篇名>论真中风\n\n属性：观刘宗浓《玉机微义》云∶余尝居凉州，其地高阜，四时多风少雨，天气常寒，每见中 \n风或暴死者有之。盖折风燥烈之甚也。时洪武乙亥秋八月，大风起自西北时，甘州城外路死 \n者数人，余亦始悟《经》谓西北之折风伤人，至病暴死之旨不诬，丹溪之言有所本也。吁！ \n医之不明运气、地理、造化、病机之微，而欲行通变之法者，难矣哉！ \n据此一说，是诚风之杀人也。然风气兼温，虽烈未必杀人，惟带寒威则杀人耳。矧以西 \n北地寒，而塞风起于八月，则寒随风至，寒必彻骨。凡暴露之人，虽曰中风，而不知实中阴 \n寒之毒也。此在强者固能支持，弱者焉得不死。然亦以所遇之异，故特纪。若此方是真中风 \n邪，则亦百十年间始或仅遭一二。而此证之不多见者，从可知矣。此外如贼风虚邪之伤人， \n则岁岁有之，处处有之，是无非外感之病，未闻有因外感而卒然昏愦致死也。矧今人之所谓 \n中风者，或于寂然无风之时，或于食饮严密之处，素无外感而忽然运仆，忽然偏废。此其是 \n风非风，又可知矣。而尽以风治，其能堪哉！ \n\n\n\n<目录>卷之十从集·杂证谟\\诸风\n\n<篇名>论续命等汤\n\n属性：按历代相传治中风之方，皆以续命等汤为主。考其所自，则始于《金匮要略》附方中有 \n《古今录验》续命汤，然此必宋时校正之所增，而非仲景本方也。此自隋唐以来，则孙氏《 \n千金方》乃有小续命、大续命、西川续命、排风等汤，故后世宗之。无不以此为中风主治矣 \n。夫续命汤以麻黄为君，而以姜、桂并用，本发散外邪之佳方也。至小续命、大续命、西川 \n续命等汤，则复加黄芩以兼桂、附，虽曰相制，而水火冰炭，道本不同，即有神妙，终非余 \n之心服者。其他无论，独怪乎河间、东垣、丹溪三子者，既于中风门皆言此病非风矣，而何 \n于本门皆首列小续命汤，而附以加减之法。曰∶无汗恶寒，麻黄续命汤；有汗恶风无热，桂 \n枝续命汤；有汗身热不恶寒，白虎续命汤；有汗身热不恶风，葛根续命汤；无汗身凉，附子 \n续命汤。若此诸法，但用治外感则可，用治内伤则不可。而三子之卷卷不舍者，皆此数方， \n又何前后之言不相应耶？再如大秦艽等汤，在《机要》《发明》俱云∶治中风外无六经之形 \n证，内无便溺之阻隔。如是血弱不能养筋，宜养血而筋自荣，以大秦艽汤，羌活愈风汤主之 \n。夫秦艽汤虽有补血之药，而寒散之剂居其半。夫既无六经之外邪，而用散何为也？既无阻 \n隔之火邪，而用寒何为也？寒散既多，又果能养血气而壮筋骨乎？秦艽汤且不可，愈风汤则尤 \n其不可者也。吾不知用此法者，果出何意？ \n\n\n\n<目录>卷之十从集·杂证谟\\诸风\n\n<篇名>论治中风（共三条）\n\n属性：凡治风之法，宜察浅深虚实及中经中脏之辨。盖中经者，邪在三阳，其病犹浅；中脏者 \n，邪入三阴，其病则甚。若在浅不治，则渐入于深；在经不治，则渐入于脏，此浅深之谓也 \n。又若正胜邪者，乃可直攻其邪；正不胜邪者，则必先顾其本，此虚实之谓也。倘不知此， \n则未有不致败者。 \n一、大风大寒直中三阴致危者，必用《金匮》续命汤去石膏治之。若风寒在经，而头疼 \n恶寒，拘急身痛者，宜麻黄汤、麻桂饮随证加减主之。甚者亦宜续命汤。若头疼有汗恶风者 \n，宜桂枝汤，或五积散。若风邪在经，热多寒少，而为偏枯疼痛发热者，宜大秦艽汤主之。 \n甚者，愈风汤亦可。 \n一、风寒诸病，无非外感证也。如轻浅在肺者，则为伤风。稍深在表里之间者，则为疟 \n疾。留连经络者，则为寒热往来。遍传六经，彻内彻外者，则为伤寒、瘟疫。久留筋骨者， \n则为风痹、痛风，或为偏风。风热上壅者，则为大头时毒。风湿相搏者，则为大风、疠风。 \n浮在肌肤者，则为斑疹、疮毒。感在岭南者，则为瘴气。凡此者皆外感风寒之病，俱有门类 \n，方论具载各条。舍此之外，但无表证者，均不得指为风也。 \n\n\n\n<目录>卷之十从集·杂证谟\\诸风\n\n<篇名>述古治权变\n\n属性：许胤宗治唐柳太后病风，脉沉欲脱，云∶服汤药无及矣。即以黄 防风煮汤数十斛，置 \n床下熏薄之。是夕果语，更药之而愈。 \n王克明治卢州王守道风噤不能语，以炽炭烧地热，洒以药汤，置病者于上，须臾小苏。 \n若此二者，以病至垂危，药不能及，亦治风之权变也。 \n\n\n\n<目录>卷之十从集·杂证谟\\诸风\n\n<篇名>诸风论列方\n\n属性：麻黄汤（散一） 桂枝汤（散九） 麻桂饮（新散七） 愈风汤（散五六） 排风汤（散百五） \n五积散（散三九） 续命汤（散五一） 小续命汤（散五二） 大续命汤（散五三） 大秦艽汤（和 \n二四五） \n\n\n\n<目录>卷之十从集·杂证谟\\诸风\n\n<篇名>论外备用方\n\n属性：二丹丸（补一五六 养阴血） 黄 丸（补一五五 虚风） 八风散（和二百四十 风邪上 \n盛） 省风汤（和二三九 风痰） 清心散（和二四九 风痰） 琥珀寿星丸（和百十三 风痰） \n涤痰汤（和二四八 风痰） 四白丹（和二五四 清气消风） 顺风匀气散（和二四二 行气 \n疏风） 薏苡仁汤（和二四七 中风流注） 虎骨散（和二百五十 半身不遂） 防风通圣散（攻 \n十六 风热便结） 三化汤（攻二九 邪实中焦） 胃风汤（散五七 虚风面肿） 秦艽升麻汤（ \n散五五 阳明中风） 地黄散（散五八 阴虚中风） 续命煮散（散五四 补虚散风） 十味锉 \n散（热四九 血弱身痛） 养正丹（热一八九 痰涎上壅） 养血当归地黄汤（和二四六 血 \n少拘挛） \n\n\n\n<目录>卷之十一从集·杂证谟\\非风\n\n<篇名>论正名（共二条）\n\n属性：非风一证，实时人所谓中风证也。此证多见卒倒，卒倒多由昏愦。本皆内伤积损颓败而 \n然，原非外感风寒所致。而古今相传，咸以中风名之，其误甚矣。故余欲易去中风二字，而 \n拟名类风，又欲拟名属风。然类风、属风，仍与风字相近，恐后人不解，仍尔模糊，故单用 \n河间、东垣之意，竟以非风名之。庶乎使人易晓，而知其本非风证矣。 \n一、凡诊诸病，必先宜正名。观《内经》诸篇所言风证，各有浅深脏腑虚实寒热之不同 \n，前义已详，本皆历历可考也。若今人之所谓中风者，则以《内经》之厥逆，悉指为风矣， \n延误至今，莫有辨者。虽丹溪云∶今世所谓风病，大率与痿证混同论治，此说固亦有之。然 \n何不云误以厥逆为风也。惟近代徐东皋有云∶ 厥类风，凡尸厥、痰厥、气厥、血厥、 \n酒厥等证，皆与中风相类。此言若乎近之，而殊亦未善也。使果风厥相类，则凡临是证者， \n曰风可也，曰厥亦可也，疑似未决，将从风乎？将从厥乎？不知《经》所言者，风自风，厥自 \n厥也。风之与厥，一表证也，一里证也。岂得谓之相类耶？奈何后人不能详察经义，而悉以 \n厥证为风。既名为风，安得不从风治。既从风治，安得不用散风之药。以风药而散厥证，所 \n散者非元气乎？因致真阴愈伤，真气愈失，是速其死矣。若知为厥，则原非外感，自与风字 \n无涉，此名之不可不正，证之不可不辨也。但名得其正，又何至有误治之患。诸厥证义详后 \n厥逆本门，当与此门通阅。 \n\n\n\n<目录>卷之十一从集·杂证谟\\非风\n\n<篇名>论有邪无邪\n\n属性：凡非风等证，在古人诸书，皆云气体虚弱，荣卫失调，则真气耗散，腠理不密，故邪气 \n乘虚而入。此言感邪之由，岂不为善，然有邪无邪，则何可不辨。夫有邪者，即伤寒疟痹之 \n属；无邪者，即非风衰败之属。有邪者，必或为寒热走注，或为肿痛偏枯，而神志依然无恙 \n也；无邪者，本无痛苦寒热，而肢节忽废，精神言语倏尔变常也。有邪者，病由乎经，即风 \n寒湿三气之外侵也；无邪者，病出乎脏，而精虚则气去，所以为眩运卒倒，气去则神去，所 \n以为昏愦无知也。有邪者，邪必乘虚而入，故当先扶正气，但通经逐邪之品不得不用以为佐 \n；无邪者，救本不暇，尚可再为杂用以伤及正气乎。 \n\n\n\n<目录>卷之十一从集·杂证谟\\非风\n\n<篇名>论肝邪\n\n属性：凡五脏皆能致病，而风厥等证何以独重肝邪，且其急暴之若此也？盖人之所赖以生者， \n惟在胃气，以胃为水谷之本也。故《经》云∶人无胃气曰死，脉无胃气亦死。夫肝邪者，即 \n胃气之贼也，一胜一负，不相并立。凡此非风等证，其病为强直掉眩之类，皆肝邪风木之化 \n也。其为四肢不用，痰涎壅盛者，皆胃败脾虚之候也。然虽曰东方之实，又岂果肝气之有余 \n耶？正以五阳俱败，肝失所养，则肝从邪化，是曰肝邪。故在阴阳类论以肝脏为最下者，正 \n谓其木能犯土，肝能犯胃也。然肝邪之见，本由脾肾之虚，使脾胃不虚，则肝木虽强，必无 \n乘脾之患；使肾水不虚，则肝木得养，又何有强直之虞。所谓胃气者，即二十五阳也，非独 \n指阳明为言也。所谓肾水者，即五脏六腑之精也，非独指少阴为言也。然则真阳败者真脏见 \n，真阴败者亦真脏见，凡脉证之见真脏者，俱为危败之兆。所谓真脏者，即肝邪也，即无胃 \n气也，此即非风、类风之病之大本也。 \n\n\n\n<目录>卷之十一从集·杂证谟\\非风\n\n<篇名>论气虚\n\n属性：凡非风卒倒等证，无非气脱而然。何也？盖人之生死，全由乎气，气聚则生，气散则死 \n。凡病此者，多以素不能慎，或七情内伤，或酒色过度，先伤五脏之真阴，此致病之本也。 \n再或内外劳伤，复有所触，以损一时之元气，或以年力衰迈，气血将离，则积损为颓，此发 \n病之因也。盖其阴亏于前，而阳伤于后，阴陷于下，而阳乏于上，以致阴阳相失，精气不交 \n，所以忽尔昏愦，卒然仆倒，此非阳气暴脱之候乎。故其为病而忽为汗出者，营卫之气脱也 \n。或为遗尿者，命门之气脱也。或口开不合者，阳明经气之脱也。或口角流涎者，太阴脏气 \n之脱也。或四肢瘫软者，肝脾之气败也。或昏倦无知、语言不出者，神败于心，精败于肾也 \n。凡此皆冲任气脱，形神俱败而然，故必于中年之后，乃有此证。 \n何今人见此，无不指为风痰而治从消散。不知风中于外，痰郁于中，皆实邪也。而实邪 \n为病，何遽令人暴绝若此？且既绝如此，尚堪几多消散？而人不能悟，良可哀也。观东垣云∶ \n气衰者多有此疾，诚知要之言也。奈后人不明其说，但以东垣为主气。又岂知气之为义乎？ \n故凡治卒倒昏沉等证，若无痰气阻塞，必须以大剂参附峻补元气。以先其急，随用地黄、当 \n归、甘杞之类，填补真阴，以培其本。盖精即气之根，气生于下，即向生之气也。经曰∶精 \n化为气，即此之谓。舍是之外，他无实济之术矣。虽然，夫以养生失道而病令至此，败坏可 \n知，犹望复全，诚非易也。第治得其法，犹可望其来复，若误治之，则何堪再误哉。 \n\n\n\n<目录>卷之十一从集·杂证谟\\非风\n\n<篇名>论痰之本\n\n属性：凡非风之多痰者，悉由中虚而然。夫痰即水也，其本在肾，其标在脾。在肾者，以水不 \n归原，水泛为痰也；在脾者，以食饮不化，土不制水也。不观之强壮之人，任其多饮多食， \n则随食随化，未见其为痰也。惟是不能食者，反能生痰，此以脾虚不能化食，而食即为痰也 \n。故凡病虚劳者，其痰必多，而病至垂危，其痰益甚，正以脾气愈虚，则全不能化，而水液 \n尽为痰也。然则，痰之与病，病由痰乎？痰由病乎？岂非痰必由于虚乎。可见天下之实痰无几 \n，而痰之宜伐者亦无几。故治痰者，必当温脾强肾以治痰之本，使根本渐充，则痰将不治而 \n自去矣。治痰诸法见后及详痰饮本门。 \n\n\n\n<目录>卷之十一从集·杂证谟\\非风\n\n<篇名>论经络痰邪\n\n属性：余尝闻之俗传云∶痰在周身，为病莫测。凡瘫痪螈 ，半身不遂等证，皆伏痰留滞而然 \n。若此痰饮岂非邪类？不去痰邪，病何由愈？余曰∶汝知痰之所自乎？凡经络之痰，盖即津血 \n之所化也。使果营卫和调，则津自津，血自血，何痰之有？惟是元阳亏损，神机耗败，则水 \n中无气，而津凝血败，皆化为痰耳。此果痰也，果精血也？岂以精血之外，而别有所谓痰者 \n耶？若谓痰在经络，非攻不去，则必并精血而尽去之。庶乎可也。否则，安有独攻其痰，而 \n津血自可无动乎？津血复伤，元气愈竭，随去随化，痰必愈甚。此所以治痰者不能尽，而所 \n尽者惟元气也。矧复有本无痰气，而妄指为痰以误攻之者，又何其昧之甚也。故凡用治痰之 \n药，如滚痰丸、清气化痰丸、搜风顺气丸之类，必其元气无伤，偶有壅滞，而或见微痰之不 \n清者。乃可暂用分消，岂云无效。若病及元气，而但知治标，则未有不日用而日败者矣。 \n\n\n\n<目录>卷之十一从集·杂证谟\\非风\n\n<篇名>论治痰（共四条）\n\n属性：治痰之法，凡非风初病而痰气不甚者，必不可猜其为痰。而妄用痰药，此大戒也。若果 \n痰涎壅盛，填塞胸膈，汤液俱不能入，则不得不先开其痰，以通药食之道。而开痰之法，惟 \n吐为捷。如古方之独圣散、茶调散、稀涎散之属，皆吐痰之剂也。但恐元气大虚，不能当此 \n峻利之物，或但用新方之吐法为妥，或用牛黄丸、抱龙丸之类，但使咽喉气通，能进汤饮即 \n止，不可尽攻其痰，致令危困，则最所当慎。以故治痰之法，又必察其可攻与否，然后用之 \n，斯无误也。若其眼直切牙，肢体拘急，面赤，强劲有力者，虽见昏沉，亦为可治。先用粗 \n筋之类，挖开其口，随以坚实笔干擦住牙关，乃用淡淡姜盐汤徐徐灌之。然后以中食二 \n指探入喉中，徐引其吐。若指不能入，则以鹅翎醮汤代指探吐亦可。如是数次，得吐气通， \n必渐苏矣。然后酌宜可以进药，此治实痰壅滞之法也。 \n一、若死证已具，而痰声漉漉于喉间者，吐亦无益，不必吐也。若痰气盛极而不能吐者 \n，亦不治之证也。又凡形气大虚者，忌用吐法，是皆不可攻者也。 \n一、凡形证已定而痰气不甚，则万勿治痰。但当调理气血，自可渐愈。如果痰涎未清， \n则治痰之法当分虚实。若气不甚虚，而或寒或湿生痰者，宜六安煎，二陈汤主之。因火为痰 \n者，宜清膈饮及竹沥、童便；火甚者，抽薪饮主之。脾虚兼呕而多痰者，六君子汤，或五味 \n异功散。阴气不足，多痰兼燥而咳者，金水六君煎。阴虚水泛为痰者，六味丸、八味丸酌而 \n用之。或为汤亦妙。脾肾虚寒，不能运化而为痰者，不必兼治痰气，只宜温补根本。若中气 \n虚者，理中汤或温胃饮；阴不足者，理阴煎之类最佳。 \n一、薛立斋曰∶若脾气亏损，痰客中焦，闭塞清道，以致四肢百骸发为诸病者，理宜壮 \n脾气为主，兼佐以治痰，则中气健而痰涎自化。非补中益气，参术二陈之类不能治。最忌行 \n气化痰及倒仓之法。 \n\n\n\n<目录>卷之十一从集·杂证谟\\非风\n\n<篇名>论寒热证（共二条）\n\n属性：凡非风口眼歪斜，有寒热之辨。在经曰∶足阳明之筋，引缺盆及颊，卒口僻，急者，目 \n不合。热则筋纵，目不开。颊筋有寒，则急引颊移口；有热则筋弛纵缓，不胜收，故僻。此 \n经以病之寒热言筋之缓急也。然而血气无亏，则虽热未必缓，虽寒未必急，亦总由血气之衰 \n可知也。尝见有引《内经》之意而曰∶偏于左者，以左寒而右热；偏于右者，以右寒而左热 \n，诚谬言也。不知偏左者，其急在左，而右本无恙也；偏右者亦然。故无论左右，凡其拘急 \n之处，即血气所亏之处也。以药治者，左右皆宜从补。以艾治者，当随其急处而灸之。盖经 \n脉既虚，须借艾火之温以行其气，气行则血行，故筋可舒而歪可正也。凡诸灸法，有言左灸 \n右，右灸左者。此亦《内经·缪刺论》之法，从之亦无不可。至若经言寒热，则凡如唇缓流 \n涎，声重，语迟含糊者，是皆纵缓之类。纵缓者多由乎热，而间亦有寒者，气虚故也。歪斜 \n牵引，抽搐反张者，皆拘急之类。拘急者多由乎寒，而间亦有热者，血虚故也。盖经所言者 \n，言理之常，余所言者，言病之变，亦无非理也。使读经不明理，必反害经意矣。故临此证 \n者，不可不加之详审。 \n一、非风螈 等证，亦有寒热之辨。观之经曰∶寒则反折筋急，热则筋弛纵不收，此固 \n其常也。然寒热皆能拘急，亦皆能弛纵，此又不可不知。如寒而拘急者，以寒盛则血凝，血 \n凝则滞涩，滞涩则拘急，此寒伤其营也。热而拘急者，以火盛则血燥，血燥则筋枯，筋枯则 \n拘急，此热伤其营也。又若寒而弛纵者，以寒盛则气虚，气虚则不摄，不摄则弛纵，此寒伤 \n其卫也。热而弛纵者，以热盛则筋软，筋软则不收，不收则弛纵，此热伤其卫也。以此辨之 \n，岂不明析，且或寒或热，必有脉证可据，但宜因证而治之。若病无寒热，则当专治血气无 \n疑矣。 \n\n\n\n<目录>卷之十一从集·杂证谟\\非风\n\n<篇名>论治血气（共二条）\n\n属性：凡非风口眼歪斜，半身不遂，及四肢无力，掉摇拘挛之属，皆筋骨之病也。夫肝主筋， \n肾主骨，肝藏血，肾藏精。精血亏损，不能滋养百骸，故筋有缓急之病，骨有痿弱之病，总 \n由精血败伤而然。即如树木之衰，一枝津液不到，即一枝枯槁，人之偏废亦犹是也。经曰∶ \n足得血而能步，掌得血而能握。今其偏废如此，岂非血气衰败之故乎？临川陈先生曰∶医风 \n先医血，血行风自灭。盖谓肝邪之见，本由肝血之虚，肝血虚则燥气乘之，而木从金化，风 \n必随之，故治此者，只当养血以除燥，则真阴复而假风自散矣。若用风药，则风能胜湿，血 \n必愈燥，大非宜也。 \n一、偏枯拘急痿弱之类，本由阴虚，言之详矣。然血气本不相离，故阴中有气，阴中亦 \n有血。何以辨之？夫血非气不行，气非血不化。凡血中无气，则病为纵缓废弛；气中无血， \n则病为抽掣拘挛。何也？盖气主动，无气则不能动，不能动则不能举矣；血主静，无血则不 \n能静，不能静则不能舒矣。故筋缓者，当责其无气；筋急者，当责其无血。无血者宜三阴煎 \n，或大营煎、小营煎之类主之。无气者宜五福饮、四君子汤、十全大补汤之类主之。其与痿 \n证之不动，痛风之不静者，义稍不同，详列本门。 \n\n\n\n<目录>卷之十一从集·杂证谟\\非风\n\n<篇名>非风诸证治法（共十二条）\n\n属性：凡非风证未有不因表里俱虚而病者也，外病者病在经。内病者，病在脏。治此之法，只 \n当以培补元气为主。若无兼证，亦不宜攻补兼施，徒致无益。盖其形体之坏，神志之乱，皆 \n根本伤败之病，何邪之有？能复其元，则庶乎可望其愈。 \n一、初病卒倒，危急不醒，但察其有无死证。如无死证，而形气不脱，又无痰气，但扶 \n定掐其人中，自当渐醒，或以白汤、姜汤徐徐灌之，亦可待其苏醒，然后察证治之。若无痰 \n无气，而息微色白，脉弱暴脱者，急以独参汤或淡姜汤灌之俱可。若其有痰甚者，以前治痰 \n法吐之；其痰不甚，或以白汤调抱龙丸一丸，以暂开其痰。无痰声者不可用。若因气厥昏沉 \n而气壅喘满，气闭不醒者，则用淡姜汤调苏合丸一丸，以暂开其气。若气不壅满者不可用。 \n其有久之不醒，或牙关不能开者，则以半夏或牙皂、细辛之类为末，少许吹入鼻中。有嚏者 \n可治，无嚏者不可治；或以皂荚为末，捻纸烧烟冲入鼻中亦可。 \n一、人于中年之后，多有此证，其衰可知。经云∶人年四十而阴气自半，正以阴虚为言 \n也。夫人生于阳而根于阴，根本衰则人必病，根本败则人必危矣。所谓根本者，即真阴也。 \n人知阴虚唯一，而不知阴虚有二∶如阴中之水虚，则多热多燥，而病在精血；阴中之火虚， \n则多寒多滞，而病在神气。若水火俱伤，则形神俱弊，难为力矣。火虚者，宜大补元煎、右 \n归饮、右归丸、八味地黄丸之类主之，庶可以益火之源；水虚者，宜左归饮、左归丸、六味 \n地黄丸之类主之，庶可以壮水之主。若气血俱虚，速宜以大补元煎之类，悉力挽回，庶可疗 \n也。凡多热多火者忌辛温，及参术姜桂之类，皆不宜轻用；多寒多湿者忌清凉，如生地、芍 \n药、麦冬、石斛之类，皆非所宜。若气虚卒倒，别无痰火气实等证，而或者妄言中风，遽用 \n牛黄丸、苏合丸之类再散其气，则不可救矣。 \n一、非风有火盛而病者，即阳证也。火甚者，宜专治其火，以徙薪饮、抽薪饮、白虎汤 \n之类酌而用之。火微者，宜兼补其阴，以一阴煎、二阴煎、或加减一阴煎之类主之。凡治火 \n之法，但使火去六七，即当调治其本。然阳盛者阴必病，故治热必从血分。甚者用苦寒，微 \n者用甘凉，欲其从乎阴也。 \n一、非风有寒盛而病者，即阴证也，专宜益火。寒微者，宜温胃饮、八味地黄丸之类主 \n之。寒甚者宜右归饮、回阳饮、理中汤、四逆汤之类主之。然寒胜者阳必病，故治寒之法， \n必从气分而从乎阳也。如阳脱寒甚者，仍宜灸关元、气海、神阙，以回其阳气。 \n一、非风眩运，掉摇惑乱者，总由气虚于上而然。经曰∶上气不足，脑为之不满，头为 \n之苦倾，目为之苦眩。又曰∶上虚则眩，此明训也。凡微觉此证，即当以五福饮之类培其中 \n气；虚甚者，即宜用大补元煎，或十全大补汤之类治之。否则，卒倒之渐所由至也。丹溪曰 \n∶无痰不作运。岂眩运者必皆痰证耶？此言最为不妥，别有详义，见眩运门。 \n一、非风麻木不仁等证，因其血气不至，所以不知痛痒。盖气虚则麻，血虚则木，麻木 \n不已，则偏枯痿废渐至日增，此魄虚之候也。经曰∶痱之为病，身无痛者，四肢不收，智乱 \n不甚。其言微知，可治；甚则不能言，不可治也。此即其类，而但有微甚之辨耳。又经曰∶ \n营气虚则不仁，卫气虚则不用，营卫俱虚，则不仁且不用，肉如故也。人身与志不相有曰死 \n，亦此类也。故凡遇此证，只宜培养血气，勿得误认为痰。 \n一、夏月卒倒，忽患非风抽搐等证，此火克金，热伤气而然。即今人之所谓暑风也。气 \n虚者宜用参 ，或十味香薷饮亦可。若水不制火而多烦渴者，宜生脉散，或人参竹叶石膏汤 \n。若火独盛者，宜瓜水绿豆饮，或用芩连之属，暂解其热。若单由伤气而无火者，宜独参汤 \n，或四君子汤。若伏阴在内，而阳虚气脱者，必用附子理中汤，或六味回阳饮之类，放胆用 \n之。勿谓夏月忌温热，此不达之言也。 \n一、肥人多有非风之证，以肥人多气虚也。何以肥人反多气虚？盖人之形体，骨为君也 \n，肉为臣也。肥人者，柔胜于刚，阴胜于阳者也。且肉以血成，总皆阴类，故肥人多有气虚 \n之证。然肥人多湿多滞，故气道多有不利。若果痰气壅滞，则不得不先为清利，宜于前治痰 \n之法随宜暂用。若无痰而气脱卒倒者，必宜四君、六君、或十全大补汤、大补元煎之类主之 \n。 \n一、非风烦热自汗，小水不利者，不可以药利之。盖津液外泄，小水必少，若再用渗利 \n，则阴水愈竭，无以制火，而躁烦益甚，但使热退汗止，则小水自利也。况自汗者多属阳明 \n之证，亦忌利小便。宜生脉散、一阴煎之类主之，火甚者，宜加减一阴煎。 \n一、非风遗尿者，由肾气之虚脱也，最为危证。宜参、 、归、术之类补之是矣。然必 \n命门火衰，所以不能收摄，其有甚者，非加桂附，终无济也。 \n一、尸厥、酒厥、痰厥、气厥、血厥之属，今人皆谓之中风，而不知总属非风也，俱详 \n后厥逆本门。 \n\n\n\n<目录>卷之十一从集·杂证谟\\非风\n\n<篇名>论用药佐使\n\n属性：凡非风而有兼证者，则通经佐使之法本不可废。盖其脉络不通，皆由血气，血气兼证， \n各有所因∶如因于风者必闭郁。因于寒者必凝涩。因于热者必干涸。因于湿者必壅滞。因于 \n虚者必不营运。诸如此者，皆能阻塞经络，此佐使之法所以亦有不同也。凡风闭者，宜散而 \n通之，如麻黄、桂枝、柴胡、羌活、细辛、白芷之属是也。寒凝者，宜热而通之，如葱、椒 \n、桂、附、干姜之属是也。热燥者，宜凉而通之，如芩、连、栀、柏、石膏、知母之属是也 \n。湿滞者，宜温利而通之，如苍术、浓朴、茵陈、萆 、五苓之属是也。血滞者，宜活而通 \n之，如芎、归、牛膝、红花、桃仁、大黄、芒硝之属是也。气滞者，宜行而通之，如木香、 \n香附、乌、沉、枳、藿之属是也。痰滞者，宜开而通之，如南星、半夏、牛黄、天竺黄、朱 \n砂、海石、玄明粉之属是也。气血虚弱者，宜温补而通之，如参、 、归、术、熟地、枸杞 \n、杜仲、牛膝之属是也。凡此通经之法，若乎尽矣，然虚实之异犹当察焉。盖通实者，各从 \n其类。使无实邪，而妄用通药，则必伤元气，反为害矣。通虚者，则或阴或阳，尤当知其要 \n也。如参 所以补气。而气虚之甚者，非姜附之佐，必不能追散失之元阳；归地所以补精血 \n，而阴虚之极者，非桂附之引，亦不能复无根之生气。寒邪在经，而客强主弱，非桂附之勇 \n则血脉不行，寒邪不去。痰湿在中而土寒水泛者，非姜附之暖，则脾肾不健，痰湿不除。此 \n通经之法，大都实者可用寒凉，虚者必宜温热也。但附子之性，刚勇而热，凡阴虚水亏而多 \n热多燥者，自非所宜；若无燥热，但涉阳虚，而诸药有不及者，非此不能达也。古人云∶附 \n子与酒同功，义可知矣。今人谓附子有毒，多不敢用，不知制用得宜，何毒之有，此诚奇品 \n，其毋忽之。 \n\n\n\n<目录>卷之十一从集·杂证谟\\非风\n\n<篇名>辨经脏诸证（共五条）\n\n属性：凡非风等证，当辨其在经在脏。经病者轻浅可延，脏病者深重可畏。经病者病连肢体， \n脏病者败在神气。虽病在经者无不由中，而表里微甚则各有所主。此经脏之不可不辨也。然 \n在经在脏，虽有不同，而曰阴曰阳，则无不本乎气血。但知气血之缓急，知阴阳之亏胜，则 \n尽其善矣。若必曰某脏某经，必用某方某药，不知通变，多失其真。故凡凿执之谈，每有说 \n得行不得者，正以心之所至，口不能宣也，必也知几知微，斯足称神悟之品。 \n一、经病之轻证∶皮毛枯涩，汗出，眩运，鼻塞者，肺之经病。血脉不荣，颜色憔悴者 \n，心之经病。肌肉消瘦，浮肿不仁，肉 筋惕，四肢不用者，脾之经病。筋力疲困，拘急掉 \n螈，胁肋胀痛者，肝之经病。口眼歪斜者，足阳明及肝胆经病。骨弱无力，坐立不能者，肾 \n之经病。 \n一、经病之危证∶皮腠冰冷，滑汗如油，畏寒之甚者，肺之经病。舌强不能言者，心肾 \n经病。唇缓口开手撒者，脾之经病。眼瞀昏黑无见，筋痛之极者，肝肾经病。耳聋绝无闻， \n骨痛之极者，肾之经病。反张戴眼，腰脊如折者，膀胱经病。 \n一、脏病之稍轻证∶咳嗽微喘，短气，悲忧不已者，病在肺脏。言语无伦，神昏多笑， \n不寐者，病在心脏。腹满少食，吐涎呕恶，吞酸嗳气，谵语多思者，病在脾胃。胸胁气逆， \n多惊多怒者，病在肝胆。少腹疼痛，二便不调，动气上冲，阴痿，呻吟多恐者，病在肾脏。 \n一、脏病之危证∶气大急大喘，或气脱失声，色灰白或紫赤者，肺肾气绝。神脱色脱， \n昏沉不醒，色赤黑者，心脏气绝。痰涎壅极，吞吐不能，呃逆不止，腹胀之极，色青黑者， \n脾胃气绝。眼闭不开，躁急扰乱，懊 囊缩，色青灰白者，肝脏气绝。声喑不出，寒厥 \n不回，二便闭不能通，泄不能禁者，肾脏气绝。 \n\n\n\n<目录>卷之十一从集·杂证谟\\非风\n\n<篇名>不治证\n\n属性：凡非风口开眼闭，手撒遗尿，吐沫直视，声如鼾睡，昏沉不醒，肉脱筋痛之极，发直， \n摇头上窜，面赤如装，或头重，面鼻山根青黑，汗缀如珠，痰声漉漉者，皆不治。 \n一、非风之脉，迟缓可生，急数弦大者死。 \n\n\n\n<目录>卷之十一从集·杂证谟\\非风\n\n<篇名>述古\n\n属性：（共二条，是皆风门论治，故列于此） \n华元化曰∶风之厥，皆由中于四时不从之气，故为病焉。有瘾疹者，有偏枯者，有失音 \n者，有历节者，有癫厥者，有疼痛者，有聋瞽者，有疮癞者，有胀满者，有喘乏者，有赤白 \n者，有青黑者，有瘙痒者，有狂妄者，皆起于风也。其脉浮虚者，自虚而得之。实大者，自 \n实而得之。弦紧者，汗出而得之。喘乏者，饮酒而得之。癫厥者，自劳而得之。手足不遂， \n语言謇涩者，房中而得之。瘾疹者，自卑湿而得之。历节疼痛者，因醉犯房而得之。聋瞽疮 \n癞者，自五味饮食、冒犯禁忌而得之。千端万状，莫离于五脏六腑而生矣。 \n薛立斋曰∶前证若因肾虚阴火而肝燥者，宜用六味地黄丸生肾水，滋肝血。若因怒动肝 \n火而血耗者，用四物加柴、栀、丹皮、茯苓以清肝火，生肝血。若因脾经郁结而血耗者，用 \n归脾、四物二汤以补脾气，生肝血。若脾气虚而痰滞者，用二陈加白术、柴胡，健脾以化痰 \n。若因脾虚湿而风痰不利者，用二陈加南星、苍术、防风，胜湿以化痰。若脾经郁而滞者， \n用归脾汤加柴胡、半夏。若肾经败液为痰者，用六味丸。 \n\n\n\n<目录>卷之十一从集·杂证谟\\非风\n\n<篇名>灸法\n\n属性：凡用灸法，必其元阳暴脱，及营卫血气不调，欲收速效，惟艾火为良。然用火之法，惟 \n阳虚多寒，经络凝滞者为宜。若火盛金衰，水亏多燥，脉数发热，咽干面赤，口渴便热等证 \n，则不可妄加艾火。若误用之，必致血愈燥而热愈甚，是反速其危矣。 \n一、凡灸法，头面上艾炷宜小不宜大，手足上乃可粗也。又须自上而下，不可先灸下， \n后灸上。 \n灸非风卒厥危急等证∶ \n神阙∶用净盐炒干，纳于脐中令满，上加浓姜一片盖定，灸百壮至五百壮，愈多愈妙。 \n姜焦则易之。或以川椒代盐；或用椒于下，上盖以盐，再盖以姜灸之，亦佳。 \n丹田、气海∶二穴俱连命门，实为生气之海，经脉之本，灸之皆有大效。 \n灸非风连脏，气塞涎上，昏危不语等证∶ \n百会、风池、大椎、肩井、曲池、间使、足三里。 \n灸口眼歪斜∶ \n听会（灸眼）、客主人（灸眼）、颊车（灸口）、地仓（灸口）、承浆（灸口）、合谷。 \n灸手足不遂，偏枯等证∶ \n百会、肩 、曲池、风市、环跳、足三里、绝骨（即悬钟）。 \n华元化曰∶心风者，宜灸心俞。肺风者，宜灸肺俞。脾风者，宜灸脾俞。肝风者，宜灸 \n肝俞。肾风者，宜灸肾俞。又治阳脱灸法，见热阵四十六。 \n\n\n\n<目录>卷之十一从集·杂证谟\\非风\n\n<篇名>非风论列方\n\n属性：四君子汤（补一） 六君子汤（补五） 金水六君煎（新和一） 大补元煎（新补一） 五福饮 \n（新补六） 五味异功散（补四） 大营煎（新补十四） 小营煎（新补十五） 十全大补汤（补二 \n十） 四物汤（补八） 归脾汤（补三二） 补中益气汤（补三十） 二阴煎（新补十） 一阴煎（新 \n补八） 加减一阴煎（新补九） 三阴煎（新补十一） 四逆汤（热十四） 十味香薷饮（和一七一 \n）独参汤（补三五） 生脉散（补五六） 六味回阳饮（新热二） 理中汤（热一） 理阴煎（新热 \n三） 温胃饮（新热五） 左归饮（新补二） 右归饮（新补三） 六味丸（补百二十） 左归丸（新 \n补四） 右归丸（新补五） 八味丸（补一二一） 二陈汤（和一） 六安煎（新和二） 白虎汤（寒 \n二） 抽薪饮（新寒三） 徙薪饮（新寒四） 绿豆饮（新寒十四） 抱龙丸（小八五） 牛黄丸（和 \n三六五） 苏合丸（和三七一） 吐法（新攻一） 独圣散（攻百六） 茶调散（攻百七） 稀涎散（ \n攻四三） 人参竹叶石膏汤（寒五） \n\n\n\n<目录>卷之十一从集·杂证谟\\非风\n\n<篇名>论外备用方\n\n属性：参附汤（补三七） 术附汤（补四一） 《神效》黄 汤（补四八 麻木） 人参膏（补一六 \n三） 地黄饮子（补九九） 青州白丸子（和百十二 痰气） 三生饮（热九四 痰盛） 愈风丹（ \n和二七四 血气受邪） 易老天麻丸（和二七五 血虚受邪） 交加散（和二五二 血虚经闭） \n三建汤（热四二 阴厥） 神应养真丹（和三一三 瘫痪） 通关散（因九八） 续断丸（和三 \n百六 脚病） 酒浸牛膝丸（和三百八 腰脚无力） 调元健步丸（和三一一 下步无力） \n\n\n\n<目录>卷之十一从集·杂证谟\\厥逆\n\n<篇名>经义（并附释义）\n\n属性：《脉解篇》曰∶内夺而厥，则为喑俳，此肾虚也。少阴不至者，厥也。 \n详本篇之言厥者，以其内夺，谓夺其五内之精气也。喑，声不能出也。俳，肢体偏废也 \n。今人见此，必皆谓之中风，而不知由于内夺，由于肾虚。盖声出于肺而本乎肾，形强在血 \n而本乎精，精气之本皆主于肾，故少阴不至则为厥。又《调经论》曰∶志不足则厥。《本神 \n篇》曰∶肾气虚则厥。观此诸论，则非风之义可知矣。故凡治此者，当以前非风证治第三条 \n等法主之。 \n《调经论》∶岐伯曰∶气之所并为血虚，血之所并为气虚。帝曰∶人之所有者，血与气 \n耳。今夫子乃言血并为虚，气并为虚，是无实乎？岐伯曰∶有者为实，无者为虚。今血与气 \n相失，故为虚焉。血与气并，则为实焉。血之与气并走于上，则为大厥。厥则暴死。气复反 \n则生，不反则死。 \n气并为血虚，血并为气虚，此阴阳之偏败也。今其气血并走于上，则阴虚于下，而神气 \n无根，是即阴阳相离之候，故致厥脱而暴死。复反者轻，不反者甚。此正时人所谓卒倒暴仆 \n之中风，亦即痰火上壅之中风，而不知实由于下虚也。然上实者，假实也，其有甚者，亦宜 \n稍为清理；下虚者，若无实邪可据，则速当峻补其下。 \n《阳明脉解篇》曰∶厥逆连脏则死，连经则生。 \n观本篇之连经连脏，本以厥逆为言，何其明显平正。盖连经者病在肌表，故轻而生；连 \n脏者病在根本，故重而死。既知此为厥逆，则凡卒倒暴仆等证，其非风也可知，而河间诸公 \n，皆以中腑中脏为言，则是风非风始混乱而莫辨矣。 \n《大奇论》曰∶脉至如喘，名曰暴厥。暴厥者，不知与人言。 \n《解精微论》曰∶厥则目无所见。夫人厥则阳气并于上，阴气并于下。阳并于上，则火 \n独光也；阴并于下，则足寒，足寒则胀也。 \n详此二论，云脉至如喘者，谓脉之急促如喘，此血气败乱之候。故致暴厥不言，即今人 \n所谓中风不语之属也。云阳并于上，阴并于下，此即上热下寒，水火不交之候，故为目无所 \n见，即中风昏眩之属也。不语者，责在肺肾。昏眩者，责在肝脾。暂见者，气复则苏。阴败 \n者，最危之候。俱当按法如前而救其本。 \n《癫狂篇》曰∶厥逆为病也，足暴清，胸若将裂，肠若将以刀切之，烦而不能食，脉大 \n小皆涩。暖取足少阴，清取足阳明。清则补之，温则泻之。 \n暴清，即暴冷也。若裂若切，谓其懊 痛楚，莫可名状，此即所谓躁扰烦乱之中风 \n也。有火者，多温热而脉洪大，宜清阴中之火；有痰者，多喘壅而脉滑实，宜开上焦之痰； \n无火无痰，多寒凉而脉涩弱，宜补其元气。凡证有若此而兼之昏乱不醒者，此真连脏之甚者 \n也。多不可治。 \n《生气通天论》曰∶阳气者，烦劳则张，精绝，辟积于夏，使人煎厥。阳气者，大怒则 \n形气绝，而血菀于上，使人薄厥。 \n此云煎厥者，即热厥之类。其因烦劳而病积于夏，亦今云暑风之属也。若见抽搐痰涎卒 \n倒者，当即以前暑风之法治之。薄厥者，急迫相搏之谓，因于大怒，即气厥血厥之属，治法 \n如后。 \n《通评虚实论》曰∶凡治消瘅仆击，偏枯痿厥，气满发逆，肥贵人，则膏粱之疾也。膈 \n塞闭绝，上下不通，则暴忧之病也。暴厥而聋，偏塞闭不通，内气暴薄也。不从内、外中风 \n之病，故瘦留着也。 \n详此膏粱之疾，即酒色之伤，脾肾之病也。暴忧之病，即悲忧伤肺之属也。内气暴薄， \n即郁怒伤肝之属也，凡此皆内伤之病。其有不从内，而外中于风者，则必留着经络，故为消 \n瘦痛痹之病。是可见内伤外感之辨，其不可混言有如此。 \n《逆顺肥瘦篇》曰∶夫冲脉者，五脏六腑之海也，五脏六腑皆禀焉。其上者，出于颃颡 \n，渗诸阳，灌诸精。其下者，注少阴之大络，出于气街，循阴股内廉，入 中，伏行 \n骨内，下至内踝之后属而别。其下者，并于少阴之经，渗三阴。其前者，伏行出跗属， \n下循跗，入大指间，渗诸络而温肌肉。故别络结则跗上不动，不动则厥，厥则寒矣。 \n详此冲脉之义，则上自头，下自足，后自背，前自腹。凡五脏六腑，十二经脉，无所不 \n禀，故称为五脏六腑十二经脉之海。夫海为百川之宗，凡诸经发源之处，即皆有会合之义， \n其于通身血气盛衰皆归乎此可知也。然冲脉起于胞中，即其经络之所，亦即其聚蓄之所，故 \n称为血海，亦称为命门。此即所谓根本之宅也。若素纵情欲，以致精气之源伤败于此，则厥 \n脱暴仆等病，亦因于此。不然，则何以忽然仆倒而神形俱败，表里俱残，全无知觉，一至于 \n此，是岂一经一脏之病之所致欤？于此察之，则实由冲脉崩败必无疑矣。故凡治此者，欲舍 \n根蒂而求其济，吾知其必无是理也。冲脉详义具《类经·经络类》第二十七篇注中。 \n《缪刺论》曰∶邪客于手足少阴太阴足阳明之络，此五络皆会于耳中，上络左角。五络 \n俱竭，令人身脉皆动，而形无知也。其状若尸，或曰尸厥。剃其左角之发方一寸，燔治，饮 \n以美酒一杯，不能饮者灌之，立已。（仍有刺法，详二十七卷耳证门） \n详此尸厥一证，乃外邪卒中之恶候。凡四时不正之气，及山魔土煞五尸魇魅之属，皆是 \n也。犯之者，忽然手足厥冷，肌肤寒栗，面目青黑，精神不守，或口噤妄言，痰涎壅塞，或 \n头旋运倒，不省人事，即名飞尸卒厥，宜用针法，具见本经。若用艾灸，则无如秦承祖灸鬼 \n法及华陀灸阳脱法为妙。凡用药之法，当知邪之所凑，必因气虚，故在本经即以左角之血余 \n，用补五络之脱竭，其义可知。若此危急之际，非用参附回阳等药，何以挽回？若果邪气壅 \n盛，胸膈不清，则不得不先为开通，然后调理，宜不换金正气散，流气饮，葱姜汤，苏合丸 \n之类酌而主之。 \n《方盛衰论》∶雷公请问，气之多少，何者为逆？何者为从？帝曰∶阳从左，阴从右，老 \n从上，少从下。是以气多少，逆皆为厥。问曰∶有余者厥耶？答曰∶一上不下，寒厥到膝。 \n少者，秋冬死。老者，秋冬生。气上不下，头痛癫疾，求阳不得，求阴不审，五部隔无征。 \n若居旷野，若伏空室，绵绵乎属不满日。是以少气之厥，令人妄梦，其极至迷。 \n此言气逆者，即为厥也。凡阴阳之气，阳从左而升，阴从右而降，故阳病者左为甚，阴 \n病者右为甚，以升者不升，降者不降，而逆其升降之气也。又人之生气，必自下而升，故老 \n人之气已衰于下，而从上者为顺；少壮之气，先盛于下，而从下者为顺。若以老人而神衰于 \n上，其所终之气可知；少壮而形衰于下，其所始之气可知，皆逆候也。及其为病而一上不下 \n，此其根本已亏，故寒厥到膝。少年以阳气方盛，而阳衰若此，故秋冬当死。老人以阳气本 \n衰，而畏寒其常，故秋冬无虑。凡此厥逆之病，谓其阳若非阳，谓其阴若非阴，五脏隔绝， \n无征可验。若不能终其日者，盖甚言其凋敝难为也。再若人之妄梦而有至迷乱昏绝者，此以 \n心肾不交而精神散越，故为厥逆。有至如此，亦总属少阴根本之病。 \n《厥论》∶岐伯曰∶阳气衰于下，则为寒厥；阴气衰于下，则为热厥。帝曰∶热厥之为 \n热也，必起于足下者，何也？岐伯曰∶阳气起于足五指之表，阴脉者集于足下，而聚于足心 \n，故阳气胜则足下热也。帝曰∶寒厥之为寒也，必从五指而上于膝者，何也？曰∶阴气起于 \n五指之里，集于膝下而聚于膝上。故阴气胜则从五指至膝上寒，其寒也，不从外，皆从内也 \n。寒厥何失而然也？此人者质壮，以秋冬夺于所用，阳气衰不能渗营其经络，阳气日损，阴 \n气独在，故手足为之寒也。热厥何如而然也？酒入于胃，则络脉满而经脉虚，阴气虚则阳气 \n入，阳气入则胃不和，胃不和则精气竭，精气竭则不营其四支也。此人必数醉若饱以入房， \n气聚于脾中不得散，酒气与谷气相搏，热盛于中。故热遍于身，内热而溺赤也。夫酒气盛而 \n悍，肾气日衰，阳气独胜。故手足为之热也。帝曰∶厥或令人腹满，或令人暴不知人 \n，或至半日远至一日乃知人者，何也？岐伯曰∶阴气盛于上则下虚，下虚则腹胀满；阳气盛 \n于上，则下气重上而邪气逆，逆则阳气乱，阳气乱则不知人也。 \n《厥论》帝曰∶愿闻六经脉之厥状病能也。岐伯曰∶巨阳之厥，则肿首头重，足不能 \n行，发为 仆，呕血善衄。阳明之厥，则癫疾欲走呼，腹满不得卧，面赤而热，妄见而 \n妄言，喘咳身热，善惊衄、呕血。少阳之厥，则暴聋颊肿而热，胁痛， 不可以运，机 \n关不利，腰不可以行，项不可以顾，发肠痈不可治，惊者死。太阴之厥，则腹满 胀， \n后不利，不饮食，食则呕，不得卧， 急挛，心痛引腹。少阴之厥，则口干溺赤，腹满 \n心痛，呕变，下泄清。厥阴之厥，则少腹肿痛，腹胀，泾溲不利，好卧屈膝，阴缩肿， \n内热，挛腰痛，虚满（前闭，谵言）。三阴俱逆，不得前后，使人手足寒，三日死。手太阴 \n厥逆，虚满而咳，善呕沫。手心主、少阴厥逆，心痛引喉，身热。死不可治。手太阳厥逆， \n耳聋泣出，项不可以顾，腰不可以俯仰。手阳明、少阳厥逆，发喉痹，嗌肿，痉。 \n详本论之寒厥热厥，虽皆以手足为言，而实以阴阳之败乱为言也。故寒厥言夺于所用， \n热厥言因于数醉，正以阴阳之气无不起于手足。故凡厥之将作，则寒热麻痹必先由手足而起 \n，及其甚也，则变出百端，或五脏六腑各有其证如此。然则手足之厥，特其形见之征兆耳。 \n而见微知着，自当因标而虑本也。 \n\n\n\n<目录>卷之十一从集·杂证谟\\厥逆\n\n<篇名>伤寒厥逆\n\n属性：仲景曰∶伤寒一二日至四五日而厥者，必发热，前热者，后必厥。厥深者，热亦深。厥 \n微者，热亦微。厥应下之，而反发汗者，必口伤烂赤。凡厥者，阴阳气不相顺接便为厥。厥 \n者，手足逆冷是也。厥少热多，其病当愈。寒多热少，阳气退，其病为进也。 \n详此仲景之厥逆，颇与《内经》有异。盖以手足言之，在《内经》则有寒厥、热厥之分 \n；在仲景则单以逆冷者为厥。再以邪正言之，在《内经》则论在元气，故其变出百端，而在 \n气在血俱有危证；在仲景则论在邪气，故单据手足，而所畏者则在阴进而阳退也。观成无己 \n曰∶厥为阴之盛也，义可知矣。诸伤寒厥逆等证，俱详具伤寒门。 \n\n\n\n<目录>卷之十一从集·杂证谟\\厥逆\n\n<篇名>论证\n\n属性：厥逆之证，危证也。盖厥者，尽也。逆者，乱也。即气血败乱之谓也，故《内经》特重 \n而详言之。如云卒厥、暴厥者，皆厥逆之总名也。如云寒厥、热厥者，分厥逆之阴阳也。 \n如云连经，连脏者，论厥逆之死生也。再若诸经脏腑之辨，亦既详矣。又近世犹有气厥、血 \n厥、痰厥、酒厥、脏厥、蛔厥等证，亦无非本之经义。观《内经》诸论已极明显，奈何后人 \n犹不能察？凡遇此证，则悉认之为中风，竟不知厥逆为何病，而通作风治，害孰甚焉！余深悲 \n之，故于前非风门悉力辨正。至于治此之法，即当以前非风证治互相参用，正所以治厥逆也 \n。其有未尽等证，仍列如后条。 \n\n\n\n<目录>卷之十一从集·杂证谟\\厥逆\n\n<篇名>论治（共七条）\n\n属性：一、寒厥热厥之治∶凡寒厥者，必四肢清凉，脉沉微不数，或虽数而无力，或畏寒喜热 \n，引衣自覆，或下痢清谷，形证多惺惺。虽此类皆属寒证，然似热非热之证犹多。故凡以手 \n足见厥而脉证俱无实热者，悉寒厥之无疑也。 \n热厥者，必先多热证，脉沉滑而数，畏热喜冷，扬手掉足，或烦躁不宁，大便秘赤，形 \n证多昏冒。凡治此二者，即当以非风门治寒治热之法主之。至若伤寒厥证，其阴其阳，亦 \n当以此法为辨。但伤寒之厥，辨在邪气，故寒厥宜温，热厥可攻也。《内经》之厥，重在 \n元气，故热厥当补阴，寒厥当补阳也。二者之治，不可不察。 \n一、气厥之证有二，以气虚、气实皆能厥也。气虚卒倒者，必其形气索然，色清白，身 \n微冷，脉微弱，此气脱证也。宜参、 、归、术、地黄、枸杞、大补元煎之属。甚者，以回 \n阳饮、独参汤之类主之。气实而厥者，其形气愤然勃然，脉沉弦而滑，胸膈喘满，此气逆证 \n也。经曰∶大怒则形气绝，而血菀于上，即此类也。治宜以排气饮，或四磨饮，或八味顺气 \n散、苏合香丸之类，先顺其气。然后随其虚实而调理之。又若因怒伤气逆，气旋去而真气受 \n损者，气本不实也；再若素多忧郁恐畏，而气怯气陷者，其虚尤可知也，若以此类而用行气 \n开滞等剂则误矣。 \n一、血厥之证有二，以血脱、血逆皆能厥也。血脱者，如大崩大吐，或产血尽脱，则气 \n亦随之而脱，故致卒仆暴死。宜先掐人中或烧醋炭，以收其气，急用人参一二两煎汤灌之， \n但使气不尽脱，必渐苏矣。然后因其寒热，徐为调理，此所谓血脱益气也。若不知此，而但 \n用血分等药，则几微之气，忽尔散失，阴无所主，无生机矣。其或有用寒凉以止血者，必致 \n败绝阳气，适足以速其死耳。血逆者，即经所云血之与气并走于上之谓，又曰∶大怒则形气 \n绝而血菀于上之类也。夫血因气逆，必须先理其气，气行则血无不行也。宜通瘀煎，或化肝 \n煎之类主之，俟血行气舒，然后随证调理。 \n一、痰厥之证，凡一时痰涎壅塞，气闭昏愦，药食俱不能通，必先宜或吐或开以治其标 \n，此不得不先救其急也。但觉痰气稍开，盒饭治其病本。如因火生痰者，宜清之降之；因风 \n寒生痰者，宜散之温之；因湿生痰者，宜燥之利之；因脾虚生痰者，自宜补脾；因肾虚生痰 \n者，自宜补肾，此痰之不必治也。但治其所以痰而痰自清矣。然犹有不可治痰者，恐愈攻愈 \n虚，而痰必愈甚也。诸治痰法，见前非风门治痰条中。 \n一、酒厥之证，即经所云热厥之属也。又经云∶酒风者，亦此类也。凡纵饮无节之人， \n多有此病，方其气血正盛，力能胜之，不知酒害之何有，及其将衰，则酒之侮人，斯可畏耳 \n。酒病极多，莫知所出，其为酒厥，则全似中风。轻者犹自知人，重者卒尔运倒，忽然昏愦 \n，或躁烦，或不语，或痰涎如涌，或气喘发热，或咳嗽，或吐血，但察其大便干燥，脉实喜 \n冷者，此湿热上壅之证，宜以抽薪饮之类，疾降其火；火之甚者，仍以梨浆饮、绿豆饮之属 \n，更迭进之，以解其毒。此证大忌辛燥等物，务使湿热渐退，神气稍复，然后用补阴等剂， \n以善其后。其有大便不实，或无火证，而脉见缓弱者，则不宜清火，但以二陈汤、六君子汤 \n或金水六君煎之类主之。若因酒伤阴，以致脾肾两虚而为厥脱者，非速救本源终无济也。凡 \n患此者，宜终身忌酒。勿使沾唇可也。若不知戒，再犯必难为矣。 \n一、色厥之证有二∶一曰暴脱，一曰动血也。凡色厥之暴脱者，必以其人本虚，偶因奇 \n遇，而悉力勉为者有之。或因相慕日久，而纵竭情欲者亦有之。故于事后则气随精去，而暴 \n脱不返。宜急掐人中，仍令阴人搂定，用口相对，务使暖气嘘通，以接其气，勿令放脱，以 \n保其神，随速用独参汤灌之。或速灸气海数十壮，以复阳气，庶可挽回。第以临时慌张，焉 \n知料理，故每致不救。然此以即病者言，所见诚不多也。其有不即病而病此者则甚多也，又 \n何以言之？以其精去于频，而气脱于渐。故每于房欲二三日之后，方见此证。第因其病不在 \n即，故不以此为病。兼之人多讳此，而不知中年之后，多有因此而病者，是皆所谓色厥也。 \n奈时师不能察，而每以中风毙之耳。凡治此者，单宜培补命门，或水或火，当以非风门治法 \n第三条者主之。又色厥之动血者，以其血气并走于上，亦血厥之属也。但与大怒血逆者不同 \n，而治法亦有所异。盖此因欲火上炎，故血随气上，必其情欲动极而欲不能遂者有之。或借 \n曲以强遏郁火者亦有之。其证则忽尔暴吐，或鼻衄不能禁止，或厥逆，或汗出，或气 \n喘，或咳嗽，此皆以阴火上冲而然。凡治此者，必先制火以抑其势，宜清化饮、四阴煎或加 \n减一阴煎之类主之。其有阴竭于下，火不归源，别无烦热脉证，而血厥不止垂危者，非镇阴 \n煎必不能救。待其势定，然后因证酌治之。 \n一、脏厥、蛔厥二证，皆伤寒证也，并见伤寒门。 \n\n\n\n<目录>卷之十一从集·杂证谟\\厥逆\n\n<篇名>述古\n\n属性：华元化《阳厥论》曰∶骤风暴热，云物飞扬，晨晦暮晴，夜炎昼冷，应寒不寒，当雨不 \n雨，水竭土坏，时岁大旱，草木枯悴，江河之涸，此天地之阳厥也。暴壅塞，忽喘促，四肢 \n不收，二腑不利，耳聋目盲，咽干口焦，喉舌生疮，鼻流清涕，颊赤心烦，头昏脑重，双晴 \n似火，一身如烧，素不能者乍能，素不欲者乍欲，登高歌笑，弃衣奔走，狂言妄语，不辨亲 \n疏，发躁无度，饮水不休，胸膈膨胀，腹胁满闷，背疽肉烂，烦溃消中，食不入胃，水不穿 \n肠，骤肿暴满，叫呼昏冒，不省人事，疼痛不知去处，此人之阳厥也。阳厥之脉，举按有力 \n者生，绝者死。《阴厥论》曰∶飞霜走雹，朝昏暮霭，云雨飘 ，风露寒冷，当热不热 \n，未寒而寒，时气淋淫，泉生田野，山摧地裂，土坏河溢，月晦日昏，此天地之阴厥也。暴 \n哑卒寒，一身拘急，四肢拳挛，唇青面黑，目直口噤，心腹满痛，头颔摇鼓，腰脚沉重，语 \n言謇涩，上吐下泻，左右不仁，大小便滑，吞吐酸渌，悲忧惨戚，喜怒无常者，此人之阴厥 \n也。阴厥之脉，举指弱，按指大者，生。举按俱绝者，死。一身悉冷，额汗自出者亦死。阴 \n厥之病，过三日勿治。 \n\n\n\n<目录>卷之十一从集·杂证谟\\厥逆\n\n<篇名>厥逆论列方\n\n属性：独参汤（补三五） 大补元煎（新补一） 六君子汤（补五） 镇阴煎（新热十三） 四阴煎（ \n新补十二） 六味回阴饮（新热二） 清化饮（新因十三） 化肝煎（新寒十） 四味回阳饮（新热 \n一） 二陈汤（和一） 排气饮（新和六） 金水六君煎（新和一） 通瘀煎（新因五） 四磨饮（和 \n五二） 加减一阴煎（新补九） 苏合香丸（和三七一） 八味顺气散（和二四四） \n\n\n\n<目录>卷之十一从集·杂证谟\\厥逆\n\n<篇名>论外备用方\n\n属性：星香汤（和二四三 痰气厥） 四逆汤（热十四 寒厥） 沉香桂附丸（热百十一 厥冷） \n三建汤（热四二 阴寒） 姜附汤（热三二 厥冷转筋） 附子理中汤（热二 虚寒） 大已寒丸 \n（热百七十 中寒） 养正丹（热一八八 痰厥不降） 四逆散（散二八 热厥） \n\n\n\n<目录>卷之十一从集·杂证谟\\伤风\n\n<篇名>经义\n\n属性：《骨空论》曰∶风者，百病之始也。风从外入，令人振寒，汗出头痛，身重恶寒。治 \n在风府，调其阴阳。不足则补，有余则泻。 \n《阴阳应象大论》曰∶邪风之至，疾如风雨。 \n《太阴阳明论》曰∶阳受风气，阴受湿气。伤于风者，上先受之；伤于湿者，下先受之 \n。 \n《岁露论》曰∶贼风邪气，乘虚伤人。 \n《八正神明论》曰∶正邪者，身形若用力汗出，腠理开，逢虚风，其中人也微。故莫如 \n其情，莫见其形。 \n《平人气象论》曰∶脉滑曰风。 \n《风论》曰∶风气藏于皮肤之间，内不得通，外不得泄。风者善行而数变，腠理开则洒 \n然寒，闭则热而闷，其寒也则衰饮食，其热也则消肌肉。故使人 栗而不能食，名曰寒 \n热。 \n《评热病论》曰∶劳风法在肺下，其为病，使人强上冥视，唾出若涕，恶风而振寒，此 \n为劳风之病。巨阳引精者三日，中年者五日，不精者七日，咳出清黄涕，其状如脓，大如弹 \n丸，从口中若鼻中出。不出则伤肺，伤肺则死也。（此节有说在咳嗽门） \n\n\n\n<目录>卷之十一从集·杂证谟\\伤风\n\n<篇名>论证\n\n属性：伤风之病，本由外感，但邪甚而深者，遍传经络，即为伤寒；邪轻而浅者，止犯皮毛， \n即为伤风。皮毛为肺之合而上通于鼻，故其在外则为鼻塞声重。甚者并连少阳、阳明之经， \n而或为头痛，或为憎寒发热；其在内则多为咳嗽，甚则邪实在肺，而为痰为喘。有寒胜而受 \n风者，身必无汗而多咳嗽，以阴邪闭郁皮毛也。有热胜而受风者，身必多汗，恶风而咳嗽， \n以阳邪开泄肌腠也。有气强者，虽见痰嗽，或五六日，或十余日，肺气疏则顽痰利，风邪渐 \n散而愈也。有气弱者，邪不易解而痰嗽日甚，或延绵数月，风邪犹在，非用辛温，必不散也 \n。有以衰老受邪，而不慎起居，则旧邪未去，新邪继之，多致终身受其累，此治之尤不易也 \n。盖凡风邪伤人，必在肩后颈根、大杼、风门、肺俞之间，由兹达肺，最近最捷，按而酸处 \n，即其径也。故凡气体薄弱，及中年以后血气渐衰者，邪必易犯，但知慎护此处，或昼坐则 \n常令微暖，或夜卧则以衣帛之类密护其处，勿使微凉，则可免终身伤风咳嗽之患。此余身验 \n切效之法，谨录之以告夫惜身同志者。 \n\n\n\n<目录>卷之十一从集·杂证谟\\伤风\n\n<篇名>论治\n\n属性：凡伤风咳嗽多痰，或喘急呕恶者，宜六安煎加减治之为最妙，二陈汤多加生姜亦可。若 \n外感风寒，咳嗽多痰，喘急而阴虚血气不足，痰有不活，气有不充，则托送无力，邪不易解 \n，宜金水六君煎，其效如神。若年衰胃弱者，尤宜用之。若伤风兼寒，而咳嗽发热者，宜柴 \n陈煎。若时行风邪在肺，咳嗽喘急多痰，而阴寒气甚，邪不易解者，宜小青龙汤，或消风百 \n解散，或金沸草散。若伤风初感，寒热往来，涕唾稠粘，胸膈不快，咳嗽多痰者，参苏饮。 \n若伤风头痛，鼻塞声重，咳嗽者，《局方》神术散，或川芎茶调散。若感风兼湿，而头目不 \n清，鼻塞声重者，宜冲和散。若风寒外闭，肢节烦疼，鼻塞声重，而内多伏火者，《局方》 \n羌活散。若太阳经伤风，发热，自汗，恶风者，桂枝汤。 \n\n\n\n<目录>卷之十一从集·杂证谟\\伤风\n\n<篇名>伤风论列方\n\n属性：六安煎（新和二） 二陈汤（和一） 金水六君煎（新和一） 参苏饮（散三四） 冲和散（散 \n八十） 消风百解散（散四六） 桂枝汤（散九） 柴陈煎（新散九） 《局方》神术散（散六五） \n小青龙汤（散八） 金沸草散（散八一） 《局方》羌活散（散八六） 川芎茶调散（散六四） \n\n\n\n<目录>卷之十一从集·杂证谟\\伤风\n\n<篇名>论外备用方\n\n属性：三拗汤（散七八 鼻塞咳嗽） 华盖散（散七九 嗽） \n\n\n\n<目录>卷之十二从集·杂证谟\\风痹\n\n<篇名>经义\n\n属性：《痹论》曰∶风寒湿三气杂至，合而为痹也。其风气胜者为行痹，寒气胜者为痛痹，湿 \n气胜者为着痹。帝曰∶其有五者，何也？岐伯曰∶以冬遇此为骨痹，以春遇此为筋痹，以夏 \n遇此为脉痹，以至阴遇此为肌痹，以秋遇此为皮痹。帝曰∶内舍五脏六腑，何气使然？岐伯 \n曰∶五脏皆有合，病久而不去者，内舍于其合也。故骨痹不已，复感于邪，内舍于肾。筋痹 \n不已，复感于邪，内舍于肝。脉痹不已，复感于邪，内舍于心。肌痹不已，复感于邪，内舍 \n于脾。皮痹不已，复感于邪，内舍于肺。所谓痹者，各以其时重感于风寒湿之气也。 \n《痹论》曰∶凡痹之客五脏者，肺痹者，烦满喘而呕。心痹者，脉不通，烦则心下鼓， \n暴上气而喘，嗌干善噫，厥气上则恐。肝痹者，夜卧则惊，多饮数小便，上为引如怀。肾痹 \n者，善胀，尻以代踵，脊以代头。脾痹者，四肢懈惰，发咳呕汁，上为大塞。肠痹者，数饮 \n而出不得，中气喘争，时发飧泄。胞痹者，少腹膀胱按之内痛，若沃以汤，涩于小便，上为 \n清涕。阴气者，静则神藏，躁则消亡，饮食自倍，肠胃乃伤。淫气喘息，痹聚在肺。淫气忧 \n思，痹聚在心。淫气遗溺，痹聚在肾。淫气乏竭，痹聚在肝。淫气肌绝，痹聚在脾。诸痹不 \n已，亦益内也。其风气胜者，其人易已也。 \n《痹论》帝曰∶痹，其时有死者，或疼久者，或易已者，其故何也？岐伯曰∶其入脏 \n者死，其留连筋骨间者疼久。其留皮肤间者，易已。帝曰∶其客于六腑者何也？曰∶此亦其 \n食饮居处，为其病本也。六腑亦各有俞，风寒湿气中其俞，而食饮应之，循俞而入，各舍其 \n腑也。帝曰∶痹或痛，或不痛，或不仁，或寒或热，或燥或湿，其故何也？曰∶痛者，寒气 \n多也，有寒故痛也。其不痛不仁者，病久入深，营卫之行涩，经络时疏，故不痛。皮肤不营 \n，故为不仁。其寒者，阳气少，阴气多，与病相益，故寒也。其热者，阳气多，阴气少，病 \n气胜，阳遭阴，故为痹热。其多汗而濡者，以其逢湿甚也，阳气少，阴气盛，两气相感，故 \n汗出而濡也。帝曰∶夫痹之为病，不痛何也？曰∶痹在于骨则重，在于脉则血凝而不流，在 \n于筋则屈不伸，在于肉则不仁，在于皮则寒。故具此五者，则不痛也。凡痹之类，逢寒则急 \n，逢热则纵。帝曰∶善。 \n《周痹篇》帝曰∶愿闻众痹。岐伯曰∶此各在其处，更发更止，更居更起，以右应左 \n，以左应右，非能周也，更发更休也。刺此者，痛虽已止，必刺其处，勿令复起。帝曰∶愿 \n闻周痹何如？曰∶周痹者，在于血脉之中，随脉以上，随脉以下，不能左右，各当其所。帝 \n曰∶刺此奈何？曰∶痛从上下者，先刺其下以过之，后刺其下以脱之。痛从下上者，先刺其 \n上以过之，后刺其下以脱之。帝曰∶此痛安生？何因而有名？曰∶风寒湿气客于外分肉之间， \n迫切而为沫，沫得寒则聚，聚则排分肉而分裂也。分裂则痛，痛则神归之。神归之则热，热 \n则痛解，痛解则厥，厥则他痹发。发则如是，此内不在脏，而外未发于皮，独居分肉之间， \n真气不能周，故命曰周痹。 \n《长刺节论》曰∶病在筋，筋挛节痛，不可以行，名曰筋痹。病在肌肤，肌肤尽痛，名 \n曰肌痹，伤于寒湿。病在骨，骨重不可举，骨髓酸痛，寒气至，名曰骨痹。 \n《寿夭刚柔篇》曰∶病在阳者命曰风，病在阴者命曰痹，阴阳俱病命曰风痹。病有形而 \n不痛者，阳之类也；无形而痛者，阴之类也。无形而痛者，其阳完而阴伤之也。急治其阴， \n无攻其阳；有形而不痛者，其阴完而阳伤之也，急治其阳，无攻其阴。阴阳俱动，乍有形， \n乍无形，加以烦心，命曰阴胜其阳，此谓不表不里，其形不久。 \n《五邪篇》曰∶邪在肾，则病骨痛阴痹。阴痹者，按之而不得，腹胀腰痛，大便难，肩 \n背颈项痛，时眩。取之涌泉、昆仑，视有血者尽取之。 \n《五脏生成篇》曰∶卧出而风吹之，血凝于肤者为痹，凝于脉者为泣，凝于足者为厥。 \n此三者，血行而不得反其空，故为痹厥也。 \n《脉要精微论》曰∶按之至骨，脉气少者，腰脊痛而身有痹也。 \n《九针论》曰∶八风伤人，内舍于骨解腰脊节腠理之间，为深痹也。故为治针，必长其 \n身，锋其末，可以取深邪远痹。 \n《四时气篇》曰∶着痹不去，久寒不已，卒取其三里。 \n《玉机真藏论》曰∶风寒客于人，使人毫毛毕直，皮肤闭而为热。当是之时，可汗而发 \n也。弗治，病患舍于肺，名曰肺痹，发咳上气。弗治，肺即传而行之肝，病名曰肝痹，一名 \n曰厥，胁痛出食。当是之时，可按若刺耳。 \n《五脏生成论》曰∶赤脉之至也，喘而坚。诊曰有积气在中，时害于食，名曰心痹。得 \n之外疾，思虑而心虚，故邪从之。白脉之至也，喘而浮，上虚下实，惊，有积气在胸中，喘 \n而虚，名曰肺痹，寒热，得之醉而使内也。青脉之至也，长而左右弹，有积气在心下支 \n，名曰肝痹，得之寒湿，与疝同法，腰痛，足清头痛。黄脉之至也，大而虚，有积气在腹 \n中，有厥气，名曰厥疝，女子同法，得之疾使四肢，汗出当风。黑脉之至也，上坚而大，有 \n积气在小腹与阴，名曰肾痹，得之沐浴清水而卧。 \n《逆调论》帝曰∶人身非衣寒也，中非有寒气也，寒从中生者何？岐伯曰∶是人多痹 \n气也，阳气少，阴气多，故身寒如从水中出。一水不能胜二火，故不能冻栗，病名曰骨痹。 \n（详寒热门） \n\n\n\n<目录>卷之十二从集·杂证谟\\风痹\n\n<篇名>论证（共二条）\n\n属性：风痹一证，即今人所谓痛风也。盖痹者，闭也。以血气为邪所闭，不得通行而病也。如 \n《痹论》曰∶风气胜者为行痹。盖风者善行数变，故其为痹，则走注历节，无有定所，是为 \n行痹，此阳邪也。曰∶寒气胜者为痛痹。以血气受寒则凝而留聚，聚则为痛，是为痛痹，此 \n阴邪也。曰∶湿气胜者为着痹。以血气受湿则濡滞，濡滞则肢体沉重而疼痛顽木，留着不移 \n，是为着痹，亦阴邪也。凡此三者，即痹之大则也。此外如五脏六腑之痹，则虽以饮食居处 \n皆能致之，然必重感于邪而内连脏气，则合而为痹矣。若欲辨其轻重，则在皮肤者轻，在筋 \n骨者甚，在脏腑者更甚。若欲辨其寒热，则多热者方是阳证，无热者便是阴证。然痹本阴邪 \n，故惟寒者多而热者少，此则不可不察。 \n观《痹论》曰∶风寒湿三气杂至，合而为痹，而《寿夭刚柔篇》又曰∶在阳者命曰风， \n在阴者命曰痹，何也？盖三气之合，乃专言痹证之所因也。曰∶在阳为风，在阴为痹。又分 \n言表里之有殊也。如风之与痹，本皆由感邪所致，但外有表证之见，而见发热头疼等证，或 \n得汗即解者，是皆有形之谓，此以阳邪在阳分，是即伤寒中风之属也，故病在阳者命曰风。 \n若既受寒邪，而初无发热头疼，又无变证，或有汗，或无汗，而筋骨之痛如故，及延绵久不 \n能愈，而外无表证之见者，是皆无形之谓，此以阴邪直走阴分，即诸痹之属也。故病在阴者 \n命曰痹。其或既有表证，而疼痛又不能愈，此即半表半里，阴阳俱病之证，故阴阳俱病者命 \n曰风痹。此所以风病在阳，而痹病在阴也。然则诸痹者，皆在阴分，亦总由真阴衰弱，精血 \n亏损，故三气得以乘之而为此诸证。经曰∶邪入于阴则痹，正谓此也。是以治痹之法，最宜 \n峻补真阴，使血气流行，则寒邪随去。若过用风湿痰滞等药而再伤阴气，必反增其病矣。 \n\n\n\n<目录>卷之十二从集·杂证谟\\风痹\n\n<篇名>风痹治法（共五条）\n\n属性：痹因外邪，病本在经，而深则连脏，故其在上则有喘呕，有吐食；在中则为胀满，为疼 \n痛；在下则为飧泄，为秘结诸病，此皆风痹之兼证也。凡见此者，当于各门权其缓急先后而 \n随证治之。 \n一、痹证之风胜者，治当从散，宜败毒散、乌药顺气散之类主之。若以风胜而兼微火者 \n，宜大秦艽汤，或九味羌活汤之类主之。 \n一、痹证之寒胜者，但察其表里俱无热证，即当从温治之，宜五积散，或小续命汤、甘 \n草附子汤之类主之。若寒甚气虚者，宜《三因》附子汤之类主之。 \n一、痹证之湿胜者，其体必重，或多寒，或多痰，或多汗，皆脾弱阴寒证也。若羌活胜 \n湿汤，乃兼风散湿之剂也。五积散，乃温经散湿之剂也。真武汤，乃温中除湿之剂也。《三 \n因》附子汤，乃补脾燥湿之剂也。调气平胃散，乃行气行湿之剂也。五苓散，乃利水导湿之 \n剂也。二陈汤，六君子汤，乃化痰去湿之剂也。大抵治湿者欲其燥，欲燥者宜从暖。盖脾土 \n喜燥而恶湿，喜暖而恶寒，故温脾即所以治湿也。然又有湿热之为病者，必见内热之证，滑 \n数之脉，方可治以清凉，宜二妙散及加味二妙丸、当归拈痛汤之类主之。其有热甚者，如抽 \n薪饮之类亦可暂用，先清其火而后调其气血。 \n一、风痹之证，大抵因虚者多，因寒者多。惟血气不充，故风寒得以入之，惟阴邪留滞 \n，故经脉为之不利，此痛痹之大端也。惟三气饮及大防风汤之类，方能奏效，凡治痹之法， \n惟此为最。其有宜酒者，即以三气饮浸酒服之亦妙，法见本方，或用易老天麻丸亦可。 \n\n\n\n<目录>卷之十二从集·杂证谟\\风痹\n\n<篇名>历节风痛\n\n属性：历节风痛，以其痛无定所，即行痹之属也。《病源》云∶历节风痛是气血本虚，或因饮 \n酒，腠理开，汗出当风所致，或因劳倦调护不谨，以致三气之邪遍历关节，与气血相搏，而 \n疼痛非常，或如虎之咬，故又有白虎历节之名。《中藏经》曰∶历节疼痛者，因醉犯房而得 \n之，此其概也。大都痛痹之证，多有昼轻而夜重者，正阴邪之在阴分也。其有遇风雨阴晦而 \n甚者，此正阴邪侮阳之证也。或得暖遇热而甚者，此湿热伤阴之火证也。有火者宜从清凉， \n有寒者宜从温热。若筋脉拘滞，伸缩不利者，此血虚血燥证也，非养血养气不可。凡诸治法 \n，总宜如前。 \n一、凡诸痹作痛者，俱宜用火龙膏贴之。 \n\n\n\n<目录>卷之十二从集·杂证谟\\风痹\n\n<篇名>风痹论列方\n\n属性：六君子汤（补五） 大防风汤（补九八） 大秦艽汤（和二四五） 小续命汤（散五二） 败毒 \n散（散三六） 五积散（散三九） 真武汤（热一四三） 二陈汤（和一） 三气饮（新热十七） \n五苓散（和一八二） 抽薪饮（新寒三） 二妙散（寒一三四） 火龙膏（外三百二十） 《三因》 \n附子汤（热二三） 甘草附子汤（热三一） 加味二妙丸（寒一三五） 易老天麻丸（和二七五） \n当归拈痛汤（寒百三十） 乌药顺气散（散九三） 九味羌活汤（散四四） 调气平胃散（和十八） \n羌活胜湿汤（和一七八） \n\n\n\n<目录>卷之十二从集·杂证谟\\风痹\n\n<篇名>论外备用方\n\n属性：大建中汤（补二四 阳虚） 愈风丹（和二七四 虚风） 活络饮（和二六九 风湿） 茯苓 \n丸（和百十四 痰饮痹痛） 换骨丹（和二七九） 史国公浸酒方（和二八一） 三痹汤（和二五 \n八血虚气滞） 蠲痹汤（和二五七 温经） 虎骨散（和二五一 风毒走注） 换腿丸（和二百 \n八十 疏邪） 桂心散（和二六五 风邪走痛） 透经解挛汤（和二七一 去风通经） 虎骨酒（ \n和三一五 强筋骨） 薏仁酒（和三一六 脚痹）秦艽地黄汤（和二六八 风热血燥） 趁痛散（ \n和二六七 行血行气） 丸（和二五六） 六味茯苓汤（和二六一 痰痹） 鸡鸣散（和 \n二八五 风湿流注） 白术酒（和一八一 中湿身痛） 独活寄生汤（和二百七十 风寒湿痹） \n续断丸（和三百五 风湿浮肿） 续断丹（和二五五 三气） 除湿蠲痹汤（和二六四 风湿） \n湿郁汤（和二六六 风湿） 薏仁汤（和二四七 流注） 熏洗痛风法（和二七三） 熏蒸法（ \n和二七二） 枳实散（和二六二 心痹痛） 加味五痹汤（和二五九 五脏痹） 人参散（和二百 \n六十 肝痹胁痛） 紫苏子汤（和二六三 肺痹胸痛） 温中法曲丸（热一二五 脾痹多寒） \n当归汤（散九一 肺痹上气） 麻黄左经汤（散九六 风邪） 半夏左经汤（散九七 风湿流注） \n大黄左经汤（散九八 闭结） 神效左经丸（散九五 三气） 虎胫骨丸（寒一三七 湿热） \n羌活散（散八七 风气） 苍术丸（寒一三三 湿热） 苦参丸（寒一三八 阴虚风热） 熨背散 \n（热一二四 胁背痛） 十味锉散（热四九 血弱挛痛） 参附渗湿汤（热一二二 寒湿痹痛） \n龙虎丹（热一二六 走注） 芎归散（热一二一 温补行散） 愈风燥湿化痰丸（和二七六） \n麻黄杏仁薏苡甘草汤（散四 风湿） \n\n\n\n<目录>卷之十二从集·杂证谟\\汗证\n\n<篇名>经义\n\n属性：《阴阳应象大论》曰∶阳之汗，以天地之雨名之。 \n《宣明五气篇》曰∶心为汗。 \n《阴阳别论》曰∶阳加于阴谓之汗。 \n《评热病论》曰∶阴虚者，阳必凑之，故少气时热而汗出也。 \n《决气篇》曰∶津脱者，腠理开，汗大泄。"}, {"n": 7, "text": "卷七\n\n《骨空论》曰∶风从外入，令人振寒，汗出头痛，身重恶寒。大风汗出，灸噫嘻 \n，噫嘻在背下侠脊傍三寸所。 \n《金匮真言论》曰∶夏暑汗不出者，秋成风疟。 \n《热论》曰∶暑当与汗皆出，勿止。 \n《生气通天论》曰∶因于暑，汗，烦则喘喝，静则多言，体若燔炭，汗出而散。汗出偏 \n沮，使人偏枯。汗出见湿，乃生痤痱。劳汗当风，寒薄为 ，郁乃痤。魄汗未尽，形弱 \n而气烁，穴俞以闭，发为风疟。阳者，卫外而为固也。 \n《评热病论》曰∶人所以汗出者，皆生于谷，谷生于精，今邪气交争于骨肉而得汗者， \n是邪却而精胜也。复热者，邪气也。汗者，精气也。今汗出而辄复热者，是邪胜也。汗出而 \n脉尚躁盛者死。 \n《热病篇》曰∶热病已得汗出，而脉尚躁，喘且复热。喘甚者，死。热病已得汗而脉尚 \n躁盛，此阴极之脉也，死；其得汗而脉静者，生。热病者脉尚盛躁而不得汗者，此阳极之脉 \n也，死；脉盛躁得汗静者，生。热病而汗且出，及脉顺可汗者，取之鱼际、太渊、大都、太 \n白，泻之则热去，补之则汗出，汗出太甚，取内踝上横脉以止之。 \n《寒热病篇》曰∶臂太阴可汗出，足阳明可汗出。故取阴而汗出甚者，止之于阳；取阳 \n而汗出甚者，止之于阴。 \n《逆顺篇》曰∶无刺 之热，无刺漉漉之汗。 \n《五禁篇》曰∶五禁、五夺、五逆者，皆不可刺。曰∶大汗出之后，是三夺也。 \n《平人气象论》曰∶尺涩脉滑，谓之多汗。 \n《邪气脏腑病形篇》曰∶肺脉缓甚为多汗，微缓为痿 、偏风，头以下汗出不可止。 \n《本藏篇》曰∶卫气者，所以温分肉，充皮毛，肥腠理，司阖关者也。 \n《经脉别论》曰∶饮食饱甚，汗出于胃。惊而夺精，汗出于心。持重远行，汗出于肾。 \n疾走恐惧，汗出于肝。摇体劳倦，汗出于脾。 \n《本病论》曰∶醉饱行房，汗出于脾。 \n《水热穴论》曰∶勇而劳甚则肾汗出。所谓玄府者，汗空也。 \n《举痛论》曰∶炅则腠理开，营卫通，汗大泄，故气泄矣。劳则喘息汗出，外内皆越， \n故气耗矣。 \n《五变篇》曰∶肉不坚，腠理疏，则善，离则腠理发泄，绝汗乃出，故旦占夕死，夕 \n占旦死。 \n\n\n\n<目录>卷之十二从集·杂证谟\\汗证\n\n<篇名>论证（共三条）\n\n属性：汗出一证，有自汗者，有盗汗者，自汗者， 然无时，而动作则益甚×汗者 \n，寐中通身汗出，觉来渐收。诸古法云∶自汗者属阳虚，腠理不固，卫气之所司也。人以卫 \n气固其表，卫气不固，则表虚自汗，而津液为之发泄也。治宜实表补阳。盗汗者属阴虚，阴 \n虚者阳必凑之，故阳蒸阴分则血热，血热则液泄而为盗汗也。治宜清火补阴。此其大法，固 \n亦不可不知也。然以余观之，则自汗亦有阴虚，盗汗亦多阳虚也。如遇烦劳大热之类，最多 \n自汗。故或以饮食之火起于胃，劳倦之火起于脾，酒色之火起于肾，皆能令人自汗，若此者 \n，谓非阳盛阴衰者而何？又若人之寤寐，总由卫气之出入，卫气者，阳气也，人于寐时则卫 \n气入于阴分，此其时非阳虚于表者而何？所以自汗盗汗亦各有阴阳之证。不得谓自汗必属阳 \n虚，盗汗必属阴虚也。然则阴阳有异，何以辨之？曰∶但察其有火无火，则或阴或阳，自可 \n见矣。盖火盛而汗出者，以火烁阴，阴虚可知也；无火而汗出者，以表气不固，阳虚可知也 \n。知斯二者，则汗出之要无余义，而治之之法，亦可得其纲领矣。 \n一、汗由血液，本乎阴也。经曰∶阳之汗，以天地之雨名之，其义可知。然汗发于阴而 \n出于阳，此其根本则由阴中之营气，而其启闭则由阳中之卫气。故凡欲疏汗而不知营卫之盛 \n衰，欲禁汗而不知橐 之牝牡，亦犹荡舟于陆而驾车于海耳。吾知其不败不已也。 \n一、汗证有阴阳。阳汗者，热汗也；阴汗者，冷汗也。人但知热能致汗，而不知寒亦致 \n汗。所谓寒者，非曰外寒，正以阳气内虚，则寒生于中而阴中无阳，阴中无阳，则阴无所主 \n而汗随气泄。故凡大惊、大恐、大惧，皆能令人汗出，是皆阳气顿消，真元失守之兆。至其 \n甚者，则如病后产后，或大吐大泻失血之后，必多有汗出者，是岂非气去而然乎？故经曰∶ \n阴胜则身寒汗出，身常清，数栗而寒，寒则厥，厥则腹满死。仲景曰∶极寒反汗出，身必冷 \n如冰，是皆阴汗之谓也。故凡治阴汗者，但当察气虚之微甚、微虚者，略扶正气，其汗自收 \n；甚虚者，非速救元气不可，即姜桂附子之属，必所当用。余别有治按在伤寒门战汗条中。 \n\n\n\n<目录>卷之十二从集·杂证谟\\汗证\n\n<篇名>汗出不治证\n\n属性：凡汗出不治之证有六∶一、汗出而喘甚者，不治。二、汗出而脉脱者，不治。三、汗出 \n而身痛甚者，不治。四、汗出发润至颠者，不治。五、汗出如油者，不治。六、汗出如珠者 \n，不治。凡见此类，不得妄为用药。 \n\n\n\n<目录>卷之十二从集·杂证谟\\汗证\n\n<篇名>论治（共八条）\n\n属性：一、阳证自汗或盗汗者，但察其脉证有火，或夜热烦渴，或便热喜冷之类，皆阳盛阴虚 \n也，宜当归六黄汤为第一，保阴煎亦妙。其或阴分虽有微火而不甚者，宜一阴煎、或加减一 \n阴煎之类主之。其有心火不宁，烦躁出汗者，宜朱砂安神丸、天王补心丹、生脉散之类主之 \n。又有本非阴虚，止因内火熏蒸，血热而多汗者，宜正气汤，或黄芩芍药汤、清化饮之类主 \n之。 \n一、阴证自汗或盗汗者，但察其内无火邪，又无火脉，便是气虚阴证，皆不可妄用凉药 \n以败阳气。若止因气虚而火未衰者，宜三阴煎、参归汤、人参建中汤之类主之。若睡中盗汗 \n而无火者，宜参苓散、独参汤主之。若阳气俱虚者，宜参附汤、大建中汤之类主之。若气虚 \n火衰之甚者，宜大补元煎、六味回阳饮之类主之。 \n一、卫气不固，腠理不密而易汗者，是亦阴证之属，宜黄 六一汤、玉屏风散、 附汤 \n之类主之。 \n一、诸病误治，有不当汗而妄汗，或虽当汗而汗之太过者，皆汗多亡阳之证，是亦阴证 \n之属，当察其虚之微甚。微虚者，宜三阴煎、五阴煎、独参汤之类主之；大虚者，非大补元 \n煎、六味回阳饮之类不可。 \n一、湿气乘脾者，亦能作汗。凡证有身重困倦，而脉见缓大，声音如从瓮中出者，多属 \n湿证。若热湿胜者，但去其火而湿自清，宜用前阳证之法。寒湿胜者，但助其火而湿自退， \n宜用前阴证之法。或用玉屏风散、四君子汤、五君子煎之类以健脾土之气，则湿去而汗自收 \n。 \n一、收汗止汗之剂，如麻黄根、浮小麦、乌梅、北五味、小黑豆、龙骨、牡蛎之属，皆 \n可随宜择用。一曰∶黄 得防风而力愈大。一曰∶官桂最能实表。一、凡汗出太多不能收者 \n，速宜用五倍子为末，以唾津调填脐中，外用帕帛缚定，过宿即止；或用何首乌为末，填脐 \n缚之，亦止。 \n一、小儿盗汗，虽是常事，在东垣诸公，皆曰不必治之。盖由血气未足也。然汗之太多 \n者，终属气分之虚。余于儿辈见汗之甚者，每以人参一钱许，煎汤与服，当夜即止。正恐他 \n日之强弱未必不由乎此，所以培补之功原不可少。 \n一、病后多汗，若伤寒，若疟疾。凡系外感寒邪，汗出热退而有汗不即止者，此以表邪 \n初解，必由腠理卫气开泄，其汗宜然，即数日旬日亦自无妨，俟卫气渐实，汗必自止，无足 \n虑也。若其他杂证，本非外感之解，而有自汗盗汗者，乃非所宜，不容不治。 \n\n\n\n<目录>卷之十二从集·杂证谟\\汗证\n\n<篇名>述古（共二条）\n\n属性：《丹溪附录》曰∶心之所藏，在内者为血，发外者为汗。盖汗乃心之液，而自汗之证， \n未有不由心肾俱虚而得之者。故阴虚阳必凑，发热而自汗；阳虚阴必乘，发厥而自汗，皆阴 \n阳偏胜所致也。 \n立斋曰∶若阳气虚弱，汗出不止，肢体倦怠，用 附汤。上气喘急，盗汗，气短头晕者 \n，用参附汤。肾气虚弱，盗汗发热者，用六味丸。若肾气虚乏，盗汗恶寒者，用八味丸。气 \n血俱虚而盗汗者，用十全大补汤。阳盛阴虚者，当归六黄汤。心肾虚弱者，斑龙丸。 \n\n\n\n<目录>卷之十二从集·杂证谟\\汗证\n\n<篇名>汗证论列方\n\n属性：大补元煎（新补一） 大建中汤（补二五） 玉屏风散（补五十） 四君子汤（补一） 五君子 \n煎（新热六） 当归六黄汤（寒六五） 独参汤（补三五）参附汤（补三七） 十全大补汤（补二十） \n参归汤（补三八） 附汤（补四三） 人参建中汤（补二六） 参苓散（补五三） 生脉散（补 \n五六） 黄 六一汤（补四九） 一阴煎（新补八） 三阴煎（新补十一） 六味回阳饮（新热二） \n五阴煎（新补十三） 保阴煎（新寒一） 天王补心丹（补百八） 六味丸（补百二十） 八味丸 \n（补一二一） 加减一阴煎（新补九） 清化饮（新因十三） 正气汤（寒六六） 黄芩芍药汤（寒 \n百九） 斑龙丸（补百二八） \n\n\n\n<目录>卷之十二从集·杂证谟\\汗证\n\n<篇名>论外备用方\n\n属性：归脾汤（补三二） 黄 汤（补四五） 大补黄 汤（补四七） 还少丹（补一三五） 柔脾汤 \n（补七一 吐衄汗） 益阴肾气丸（补一二三 血虚盗汗） 三味建中汤（补二九） 大建中汤（ \n补二五 阴汗） 人参养营汤（补二一） 心肾丸（补百十二 阴虚盗汗） 生地黄汤（寒六八 \n阴火汗） 防己黄 汤（和一七六 风湿汗） 《宣明》白术散（固三 虚风） 白术散（和三十 \n自汗益汗） 防风当归汤（和二四一 过汗反张） 牡蛎白术散（固二 酒风） 牡蛎散（固一 \n）金锁正元丹（固十八 遗精汗） 秘元丹（固三二 虚寒自汗） 麦面汤（固四 气虚汗） \n辰砂妙香散（固十五 心虚汗） 脚汗牡蛎散（因二九六） \n\n\n\n<目录>卷之十二从集·杂证谟\\痉证\n\n<篇名>经义\n\n属性：《至真要大论》曰∶诸痉项强，皆属于湿。诸暴强直，皆属于风。厥阴在泉，客胜则大 \n关节不利，内为痉强拘螈，外为不便；主胜则筋骨繇并，腰腹时痛。 \n《经筋篇》曰∶足太阳之筋病，脊反折，项筋急，肩不举，腋支，缺盘中纽痛，不可左 \n右摇。足少阴之筋病，主痫螈及痉，在外者不能俯，在内者不能仰。故阳病者腰反折不 \n能俯，阴病者不能仰。经筋之病，寒则反折筋急，热则筋弛纵不收，阴痿不用。阳急则反折 \n，阴急则俯不伸。 \n《缪刺论》曰∶邪客于足太阳之络，令人拘挛背急，引胁而痛。 \n《骨空论》曰∶督脉为病，脊强反折。 \n《生气通天论》曰∶因于湿，首如裹。湿热不攘，大筋 短，小筋弛长， 短 \n为拘，弛长为痿。 \n《经脉篇》曰∶膀胱足太阳也。是动则病冲头痛，目似脱，项似拔，脊痛腰似折，髀 \n不可以曲， 如结， 如裂，是为踝厥。是主筋所生病者。 \n《气厥论》曰∶肺移热于肾，传为柔 。 \n《诊要经终论》曰∶太阳之脉，其终也，戴眼，反折，螈 ，其色白，绝汗乃出，出则 \n死矣。 \n《六元正纪大论》曰∶太阳所至，为寝汗痉。 \n《热病篇》曰∶风痉身反折，先取足太阳及 中及血络出血；中有寒，取三里。热 \n病不可刺者有九，九日热而痉者死，腰折，螈 ，齿噤 也。 \n《厥论》曰∶手阳明、少阳厥逆，发喉痹，嗌肿，痉，治主病者。 \n\n\n\n<目录>卷之十二从集·杂证谟\\痉证\n\n<篇名>论证（共六条）\n\n属性：之为病，即《内经》之痉病也。以痉作 ，盖传写之误耳。其证则脊背反张 \n，头摇口噤，戴眼项强，四肢拘急，或见身热足寒，恶寒面赤之类皆是也。 \n仲景曰∶太阳之病，发热无汗，反恶寒者，名曰刚 。太阳病，发热汗出而不恶寒 \n者，名曰柔 。太阳病，发热脉沉而细者，名曰痉，为难治。太阳病，发汗太多，因致 \n。风病，下之则 ，复发汗，必拘急。疮家，虽身疼痛，不可发汗，汗出则 \n。 \n陈无择曰∶夫人之筋，各随经络退出于身，血气内虚，外为风寒湿热之所中，则 \n。盖风散气，故有汗而不恶寒曰柔 。寒泣血，故无汗而恶寒曰刚 。原其所因， \n多由亡血，筋无所营，故邪得以袭之。所以伤寒汗下过多，与夫病疮人，及产后致斯疾者， \n概可见矣。诊其脉皆沉伏弦紧，但阳缓阴急，则久久拘挛，阴缓阳急，则反张强直，二证各 \n异，不可不别。 \n愚谓痉之为病，强直反张病也，其病在筋脉。筋脉拘急，所以反张。其病在血液，血液 \n枯燥，所以筋挛。观仲景曰∶太阳病，发汗太多，因致痉。风病下之则成痉。疮家不可发汗 \n，汗之亦成痉。只此数言，可见病 者多由误治之坏证，其虚其实可了然矣。自仲景之 \n后，惟陈无择能知所因，曰∶多由亡血筋无所营，因而成痉，则尽之矣。但惜其言之既善， \n而复有未善者，曰∶血气内虚，外为风寒湿热所中则痉，斯言不无又误。若其所云，则仍是 \n风湿为邪，而虚反次之。不知风随汗散，而既汗之后，何复言风；湿随下行，而既下之后， \n何反致湿。盖误汗者，必伤血液。误下者，必伤真阴。阴血受伤则血燥，血燥则筋失所滋， \n筋失所滋则为拘为挛，反张强直之病势所必至，又何待风寒湿热之相袭而后为痉耶？且仲景 \n所言，言不当汗而汗也，不当下而下也。汗下既误，即因误治而成 矣。岂误治之外， \n必再受邪而后成痉，无邪则无痉哉！此陈氏之言，不惟失仲景之意，而反致后人疑惑，用持 \n两端。故凡今人之治此者，未有不以散风去湿为事，亦焉知血燥阴虚之证，尚能堪此散削否 \n？此不可不为辨察。故余列二子之论于前，以资后学之印证。 \n一、痉证甚多，而人多不识者，在不明其故而鲜有察之者耳。盖凡以暴病而见反张戴眼 \n、口噤拘急之类，皆痉病也。观仲景以汗下为言，谓其误治亡阴所以然也。余因类推，则常 \n见有不因误治，而凡属阴虚血少之辈，不能养营筋脉，以致搐挛僵仆者，皆是此证。如中风 \n之有此者，必以年力衰残，阴之败也。产妇之有此者，必以去血过多，冲任竭也。疮家之有 \n此者，必以血随脓出，营气涸也。小儿之有此者，或以风热伤阴，遂为急惊，或以汗泻亡阴 \n，遂为慢惊。凡此之类，总属阴虚之证。盖精血不亏，则虽有邪干，亦断无筋脉拘急之病， \n而病至坚强，其枯可知。故治此者，必当先以气血为主，而邪甚者，或兼治邪。若微邪者， \n通不必治邪。盖此证之所急者在元气，元气复而血脉行，则微邪自不能留，何足虑哉！奈何 \n今人但见此证，必各分门类而悉从风治。不知外感之风，寒邪证也，治宜解散。内生之风， \n血燥证也，止宜滋补。矧此数者，总由内证，本无外邪，既以伤精败血枯燥而成，而再治风 \n痰，难乎免矣。故余笔于此，以明 证之要。 \n一、仲景言痉止属太阳，而不及他经者何也？盖 必反张，其病在背，背之经络惟 \n太阳、督脉耳，言太阳则督在其中矣，此其义也。然仲景止言其表，而未详其里。考《内经 \n》之《经脉篇曰》∶足少阴之脉，贯脊属肾，其直者从肾上贯肝膈。《经筋篇》曰∶足少阴 \n之筋，循脊内挟膂，上至项，结于枕骨，与足太阳之筋合。又曰∶足太阳之筋病，脊反折， \n项筋急。足少阴之筋病，主痫螈及痉。阳病者腰反折不能俯。阴病者，不能仰。由此观 \n之，则痉之为病，乃太阳少阴之病也。盖肾与膀胱为表里，膀胱为津液之府，而肾为藏精之 \n脏，病在二经，水亏可知，故治此者，最当以真阴为主。 \n\n\n\n<目录>卷之十二从集·杂证谟\\痉证\n\n<篇名>论治（共八条）\n\n属性：一、痉证凡因汗因泻者，其气必虚。微虚者，宜三阴煎、五福饮之类主之。大虚而脉见 \n沉细，阴胜者，宜大营煎、大补元煎、十全大补汤之类主之。 \n一、痉证多汗者，宜三阴煎、参归汤、人参建中汤主之。阳气大虚，汗出或亡阳者，宜 \n参附汤、 附汤、大补元煎之类主之。若汗出兼火，多热躁者，且当归六黄汤主之。 \n一、痉因泄泻者，宜胃关煎、温胃饮之类主之。泻止而痉者，宜大营煎、五福饮之类主 \n之。 \n一、痉有兼火者，必脉见洪滑，证见烦热，宜一阴煎，或加减一阴煎主之。若火盛之甚 \n，以致阴血涸燥者，不得不先去其火，宜清化饮、保阴煎、玉女煎之类主之。 \n一、痉有表邪未解者，当察其邪之微甚及证之阴阳。若身有微热，脉不紧数者，此微邪 \n也。只补正气，其邪自散。宜五福饮之类主之。若表邪未解，阴虚无汗身热者，宜三柴胡饮 \n、四柴胡饮、补阴益气煎之类主之。若阳气大虚，阴极畏寒，邪不解而痉者，宜大温中饮主 \n之。 \n一、痉有痰盛者，不得不先清上焦。若火盛多痰者，宜用清膈煎、抱龙丸。若多痰无 \n火，宜用六安煎。凡此证候，多属虚痰虚火。因其壅滞，不得不暂为清理。但得痰气稍开， \n盒饭调理血气。 \n一、小儿吐泻及多汗之后。一、妇人产后。一、诸证大失血之后。一、凡病中风及疮毒 \n溃脓之后，皆有此证，悉当根据前法酌宜治之。 \n一、痉证有兼湿者，当如王海藏治法，详见后条。 \n\n\n\n<目录>卷之十二从集·杂证谟\\痉证\n\n<篇名>述古（共二条）\n\n属性：仲景治太阳之 ，身体强，脉沉迟者，用栝蒌桂枝汤取微汗。治刚 无汗者， \n用葛根汤。治胸满口噤，卧不着席，脚挛 齿者，用大承气汤。按此皆散逐实邪之法， \n虽此证不多见，然间或有之，则亦不可不知。 \n王海藏治刚 ，用神术汤加羌活、独活、麻黄。治柔 ，用白术汤加桂心、黄 \n。 \n\n\n\n<目录>卷之十二从集·杂证谟\\痉证\n\n<篇名>痉证论列方\n\n属性：大营煎（新补十四） 五福饮（新补六） 参归汤（补三八） 参附汤（补三七） 附汤（补 \n四三） 白术汤（和二六） 一阴煎（新补八） 三阴煎（新补十一） 保阴煎（新寒一） 温胃饮（ \n新热五） 胃关煎（新热九） 清化饮（新因十三） 玉女煎（新寒十二） 大补元煎（新补一） \n十全大补汤（补二十） 五积散（散三九） 大温中饮（新散八） 人参建中汤（补二六） 清膈煎 \n（新寒九） 二柴胡饮（新散二） 当归六黄汤（寒六五） 神术汤（和三九） 三柴胡饮（新散三） \n补阴益气煎（新补十六） 六安煎（新和二） 四柴胡饮（新散四） 加减一阴煎（新补九） 葛 \n根汤（散二九） 大承气汤（攻一） 栝蒌桂枝汤（散十二） 抱龙丸（小八五） \n\n\n\n<目录>卷之十二从集·杂证谟\\痉证\n\n<篇名>论外备用方\n\n属性：防风当归汤（和二四一 过汗反张） \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>经义\n\n属性：《阴阳应象大论》曰∶冬伤于寒，春必温病。 \n《金匮真言论》曰∶夫精者，身之本也。故藏于精者，春不病温。 \n《热论篇》帝曰∶今夫热病者，皆伤寒之类也，或愈或死，其死皆以六七日之间，其愈 \n皆以十日以上者，何也？岐伯对曰∶巨阳者，诸阳之属也。其脉连于风府，故为诸阳主气也 \n。人之伤于寒也，则为病热，热虽甚不死。其两感于寒而病者，必不免于死。帝曰∶愿闻其 \n状。岐伯曰∶伤寒一日，巨阳受之，故头项痛，腰脊强。二日，阳明受之，阳明主肉，其脉 \n侠鼻，络于目，故身热目疼而鼻干，不得卧也。三日，少阳受之，少阳主胆，其脉循胁络于 \n耳，故胸胁痛而耳聋。三阳经络皆受其病而未入于脏者，故可汗而已。四日，太阴受之，太 \n阴脉循布胃中，络于嗌，故腹满而嗌干。五日，少阴受之，少阴脉贯肾，络于肺，系舌本， \n故口燥舌干而渴。六日，厥阴受之，厥阴脉循阴器而络于肝，故烦满而囊缩。三阴三阳、五 \n脏六腑皆受病，营卫不行，五脏不通则死矣。其不两感于寒者，七日，巨阳病衰，头痛少愈 \n。八日，阳明病衰，身热少愈。九日，少阳病衰，耳聋微闻。十日，太阴病衰，腹减如故， \n则思饮食。十一日，少阴病衰，渴止不满，舌干已而嚏。十二日，厥阴病衰，囊纵，少腹微 \n下，大气皆去，病日已矣。帝曰∶治之奈何？岐伯曰∶治之各通其脏脉，病日衰已矣。其未 \n满三日者，可汗而已；其满三日者，可泄而已。 \n《热论篇》曰∶两感于寒者，病一日则巨阳与少阴俱病，则头痛口干而烦满。二日则阳 \n明与太阳俱病，则腹满，身热不欲食，谵言。三日则少阳与厥阴俱病，则耳聋，囊缩而厥， \n水浆不入，不知人，六日死。帝曰∶五脏已伤，六腑不通，营卫不行。如是之后，三日乃死 \n，何也？岐伯曰∶阳明者，十二经脉之长也，其血气盛，故不知人，三日其气乃尽，故死矣 \n。 \n《热论篇》曰∶凡病伤寒而成温者，先夏至日者，为病温。后夏至日者，为病暑。暑当 \n与汗皆出，勿止。 \n《热论篇》帝曰∶热病已愈，时有所遗者，何也？岐伯曰∶诸遗者，热甚而强食之， \n故有所遗也。若此者，皆病已衰而热有所藏，因其谷气相搏，两热相合，故有所遗也。帝曰 \n∶治遗奈何？岐伯曰∶视其虚实，调其逆从，可使必已也。帝曰∶病热当何禁之？岐伯曰∶病 \n热少愈，食肉则复，多食则遗，此其禁也。 \n《刺热篇》曰∶肝热病者，小便先黄，腹痛多卧，身热，热争则狂言及惊，胁满痛，手 \n足躁，不得安卧。庚辛甚，甲乙大汗，气逆则庚辛死。刺足厥阴、少阳。其逆则头痛员员， \n脉引冲头也。心热病者，先不乐，数日乃热，热争则卒心痛，烦闷善呕，头痛，面赤，无汗 \n。壬癸甚，丙丁大汗，气逆则壬癸死。刺手少阴、太阳。脾热病者，先头重颊痛，烦心，颜 \n青欲呕，身热，热争则腰痛不可用俯仰，腹满泄，两颔痛。甲乙甚，戊己大汗，气逆则甲乙 \n死。刺足太阴、阳明。肺热病者，先淅然厥，起毫毛，恶风寒，舌上黄，身热，热争则喘咳 \n，痛走胸膺背，不得太息，头痛不堪，汗出而寒。丙丁甚，庚辛大汗，气逆则丙丁死。刺手 \n太阴、阳明，出血如大豆，立已。肾热病者，先腰痛 酸，苦渴数饮，身热，热争 \n则项痛而强， 寒且酸，足下热，不欲言，其逆则项痛员员澹澹然。戊己甚，壬癸 \n大汗，气逆则戊己死。刺足少阴、太阳。诸汗者，至其所胜日汗出也。肝热病者，左颊先赤 \n。心热病者，颜先赤。脾热病者，鼻先赤。肺热病者，右颊先赤。肾热病者，颐先赤。病虽 \n未发，见赤色者，刺之，名曰治未病。太阳之脉色荣颧骨，热病也，荣未交，曰今且得汗， \n待时而已。与厥阴脉争见者，死期不过三日。其热病内连肾，少阳之脉色也。少阳之脉色荣 \n颊前，热病也。荣未交，曰今且得汗，待时而已。与少阴脉争见者，死期不过三日。（此一 \n节即言伤寒之两感也，详注备载《类经·疾病类》四十四） \n《热病篇》曰∶热病三日，而气口静、人迎躁者，取之诸阳，五十九刺，以泻其热而出 \n其汗，实其阴以补其不足者。身热甚，阴阳皆静者，勿刺也。其可刺者，急取之，不汗出则 \n泄。所谓勿刺者，有死征也。热病七日、八日，脉口动喘而弦者，急刺之，汗且自出，浅刺 \n手大指间。热病七日、八日，脉微小，病者溲血，口中干，一日半而死，脉代者，一日死。 \n热病已得汗出，而脉尚躁，喘且复热，勿刺肤，喘甚者死。热病七日、八日，脉不躁，躁不 \n散数，后三日中有汗，三日不汗，四日死。未曾汗者，勿腠刺之。热病不知所痛，耳聋不能 \n自收，口干，阳热甚，阴颇有寒者，热在髓，死不可治。热病而汗且出，及脉顺可汗者，取 \n之鱼际、太渊、大都、太白，泻之则热去，补之则汗出。汗出太甚，取内踝上横脉以止之。 \n热病已得汗而脉尚躁盛，此阴脉之极也，死。其得汗而脉静者，生。热病者，脉尚躁盛而不 \n得汗者，此阳脉之极也，死。脉盛躁得汗静者，生。热病不可刺者有九∶一曰汗不出，大颧 \n发赤，哕者死。二曰泄而腹满甚者，死。三曰目不明，热不已者，死。四曰老人婴儿，热而 \n腹满者，死。五曰汗不出，呕下血者，死。六曰舌本烂，热不已者，死。七曰咳而衄，汗不 \n出，出不至足者死。八曰髓热者死。九曰热而痉者死，腰折、螈 、齿噤 也。凡此九 \n者，不可刺也。太阳之脉色荣颧骨，热病也。与厥阴脉争见者，死。死期不过三日。少阳之 \n脉色荣颊前，热病也。与少阴脉争见者，死期不过三日。（本篇刺法未及详录，具载《类经 \n·针刺类》第四十） \n《评热病论》帝曰∶有病温者，汗出辄复热，而脉躁疾，不为汗衰，狂言不能食，病名 \n为何？岐伯曰∶病名阴阳交，交者，死也。人所以汗出者，皆生于谷，谷生于精。今邪气交 \n争于骨肉而得汗者，是邪却而精胜也。精胜则当能食而不复热，复热者，邪气也。汗者， \n精气也。今汗出而辄复热者，是邪胜也。不能食者，精无俾也。病而留者，其寿可立而倾也 \n。且夫热论曰∶汗出而脉尚躁盛者，死。今脉不与汗相应，此不胜其病也，其死明矣。狂言 \n者，是失志，失志者，死。今见三死，不见一生，虽愈必死也。 \n《刺志论》曰∶气盛身寒，得之伤寒；气虚身热，得之伤暑。 \n《论疾诊尺篇》曰∶尺肤热甚，脉盛躁者，病温也。其脉盛而滑者，病且出也。 \n《刺法论》帝曰∶余闻五疫之至，皆相染易，无问大小，病状相似，不施救疗，如何可 \n得不相移易者？岐伯曰∶不相染者，正气存内，邪不可干，避其毒瓦斯，天牝从来，复得其往 \n，气出于脑，即不干邪。气出于脑，即室先想心如日。欲将入于疫室，先想青气自肝而出， \n左行于东，化作林木。次想白气自肺而出，右行于西，化作戈甲。次想赤气自心而出，南行 \n于上，化作焰明。次想黑气自肾而出，北行于下，化作水。次想黄气自脾而出，存于中央， \n化作土。五气护身之毕，以想头上如北斗之煌煌，然后可入于疫室。 \n《水热穴论》帝曰∶夫子言治热病五十九俞，愿闻其处，因闻其意。岐伯曰∶头上五 \n行行五者，以越诸阳之热逆也。大杼、膺俞、缺盆、背俞，此八者，以泻胸中之热也。气街 \n、三里、巨虚上下廉，此八者，以泻胃中之热也。云门、 骨、委中、髓空，此八者以 \n泻四肢之热也。五脏俞傍五，此十者，以泻五脏之热也。凡此五十九穴者，皆热之左右也。 \n帝曰∶人伤于寒而传为热，何也？曰∶夫寒盛则生热也。 \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>论证（共二条）\n\n属性：经曰∶冬伤于寒，春必病温，是温病即伤寒也。然伤寒有四时之不同，如冬感寒邪而即 \n病者，为真伤寒。其有寒毒内侵而未至即病者，必待春温气动，真阴外越，再触寒邪，其病 \n则发，故至春犯寒，则发为温病；至夏犯寒，则发为热病，亦犹伤气者，遇气则作。伤食者 \n，遇食则发。其义一也。然而伤寒瘟疫，多起于冬不藏精及辛苦饥饿之人。盖冬不藏精，则 \n邪气乘虚易入，而饥饿劳倦之流，则受伤尤甚。故大荒之后，必有大疫，正为此也。但此辈 \n疫气既盛，势必传染。又必于体质虚浊者，先受其气。以渐遍传，则又有不待冬寒而病者矣 \n。然此以冬寒主气之为病也。至于客气变迁，岁时不同，故有冬行春令，则应冷反温，夏行 \n冬令，则应热反冷，春秋皆然，是则非其时而有其气。壮者无恙；怯者受伤。是又不止冬寒 \n，而运气不正之害，所当察而慎避者有如此。 \n一、瘟疫本即伤寒，无非外邪之病，但染时气而病无少长率相似者，是即瘟疫之谓。古 \n人有云∶瘟证因春时温气而发，乃因郁热自内而发于外，初非寒伤于表也，故宜用辛平之剂 \n。治与正伤寒用麻黄者，不同也。此说固若近理，而实有未必然者。盖瘟疫若非表证，则何 \n以必汗而后解？故余于前论中，谓其先受寒邪，再触则发，诚理势之确然也。但其时有寒热 \n，证有阴阳，治阳证热证者，即冬时亦可清解；治阴证寒证者，即春夏亦可温散。谓宜因证 \n因时者则可，谓非寒伤于表也则不可。 \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>瘟疫脉候\n\n属性：凡病伤寒瘟疫，脉洪大滑数，而数中兼缓者，可治。脉洪大而紧数甚者，危。脉虽浮大 \n而按之无力者，宜补兼表。身虽热而脉弱者，当以纯补为主，或兼温散。身大热而脉见沉涩 \n细小，足冷者，难治。瘟病四五日，身热，腹满而吐，脉来细而弦强者，十二日死。瘟病二 \n三日，头痛腹满，脉直而疾者，八日死。瘟病八九日，头身不痛，色不变，而利不止，心下 \n坚，脉不鼓，时或大者，十七日死。瘟病汗不出，或出不至下部者，死。瘟病下痢，腹中痛 \n甚者死。以上死证，言其略耳，诸所未尽，当于伤寒门参阅。 \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>治法六要\n\n属性：自古伤寒治法，苦于浩渺。余自考索以来，留心既久，每临编得其法，未必见其病，临 \n病见其证，未必合其方，可见病多变态，执滞难行，惟贵圆通而知其要耳。故余注《类经》 \n，所列伤寒治要有六∶曰汗、补、温、清、吐、下。然亦但言其概，而未及其详，今悉诸 \n法于此，用补伤寒之未备者。倘欲求仲景心法，乃当阅伤寒本门，使能彼此参证，则纲举目 \n张，自有包罗贯串之妙。既约且尽，而活人之要，当无出此。 \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>汗有六要五忌\n\n属性：治伤寒之法，余已析其六要。而六要之外，又有五忌者，何也？盖六法之中，惟汗为主 \n，正以伤寒之愈，未有不从汗解者，故法虽有六，汗实统之。而汗外五法，亦无非取汗之法 \n也。然取汗以辛散，此固其常也，而何以五法皆能取汗？六要则已，又何以有五忌之辨也？盖 \n汗由液化，其出自阳，其源自阴。若肌肤闭密，营卫不行，非用辛散，则玄府不开而汗不出 \n，此其一也。又若火邪内燔，血干液涸，非用清凉，则阴气不滋而汗不出，此其二也。又若 \n阴邪固闭，阳气不达，非用辛温，则凝结不开而汗不出，此其三也。又若营卫不足，根本内 \n亏，非用峻补，则血气不充而汗不出，此其四也。又若邪在上焦，隔遮阳道，不施吐涌，则 \n清气不升而汗不出，此其五也。又若邪入阳明，胃气壅滞，不以通下，则浊气不解而汗不出 \n，此其六也。凡此者皆取汗之道，是即所谓六要也。 \n何谓五忌？盖一曰热在表者，内非实火，大忌寒凉，寒则阴邪凝滞不散，邪必日深，阳 \n必日败，而汗不得出者死。二曰元气本弱，正不胜邪者，大忌消耗，尤忌畏补，消耗则正 \n气日消，不补则邪气日强，消者日清，甚者日甚，而必不能汗者死。三曰实邪内结，伏火 \n内炎者，大忌温补，温则愈燥，补则愈坚，而汗不得出者死。四曰中虚气弱，并忌汗诸条 \n者，大忌发散，散则气脱，气脱而汗不能出，气脱而汗不能收者死。五曰病非阳明实邪， \n并忌下诸条者，大忌通泻，泻则亡阴，阴虚则阳邪深陷，而汗不得出者，死。是即所谓五忌 \n也。能知六要而避五忌，伤寒治法尽于是矣。第假热者多，真实者少，能察秋毫于疑似，非 \n有过人之见者不能也。余之谆谆，其亦 望于潜心者耳。 \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>汗散法（共五条）\n\n属性：凡伤寒瘟疫，表证初感，速宜取汗，不可迟也。故仲景曰∶凡发汗服汤药，其方虽言日 \n三服，若病剧不解，当半日中尽三服。如服一剂，病证犹在，当复作本汤服之。至有不肯汗 \n出者，服三剂乃解。若汗不能出者，死病也。此所谓汗不宜迟也。然取汗之法，又当察其元 \n气、病气之虚实，若忽尔暴病，表证已具，而元气未亏者，但以辛平之剂，直散之可也。若 \n兼杂证，则当察其寒热温凉，酌宜而治，不得但知发散也。又若身虽大热，表证全具，而脉 \n见虚弱者，必不易汗，此即当详察补虚法，酌而治之。若不知标本，而概行强散，营竭则死。 \n一、伤寒之宜平散者，以其但有外证，内无寒热，而且元气无亏也，宜以正柴胡饮为 \n主治。此外如十神汤、参苏饮，皆可酌用。若病在阳明者，宜升麻葛根汤。若感四时瘟疫， \n而身痛发热，及烟瘴之气者，宜败毒散，或荆防败毒散。若病在三阳，而头痛鼻塞，项强身 \n痛，咳嗽者，宜神术散。若伤风兼寒，而发热咳嗽者，宜柴陈煎，或金沸草散。甚者，小青 \n龙汤。 \n一、伤寒之宜温散者，以其寒邪外盛，而内无热证，及元气无亏而气清受寒者，皆可从 \n温直散之，宜二柴胡饮为最当。若寒甚表实者，惟麻桂饮为最妙，毋疑畏也。此外如五积散 \n、麻黄汤、桂枝汤、小青龙汤、葛根汤、圣散子之类，皆可酌用。 \n一、伤寒之宜凉散者，以其外热里亦热，必脉证俱阳，而烦渴喜冷，及元气强实者，乃 \n可兼凉兼散，宜一柴胡饮为先。或九味羌活汤，柴葛解肌汤。甚者，六神通解散，皆可酌用 \n。若内外俱热，而或为热泻者，宜柴芩煎。若表里俱热而兼斑疹者，宜柴葛煎。 \n一、伤寒之宜兼补兼散者，以营卫不足，血气不充也。用药如用兵，兵进而粮饷不继则 \n兵覆，攻病而元气不继则病覆。故治虚邪之宜散者，必当先本后末，此其最要者也。若寒邪 \n在营，肝脾血少，而邪热不退者，宜三柴胡饮，或归柴饮。若寒邪在卫，脾肺气虚，而表邪 \n不解者，宜四柴胡饮。若脾胃气血不足，而邪热不解者，宜五柴胡饮。若邪在半表半里，往 \n来寒热，而微见气虚者，宜小柴胡汤。若温暑大热大渴，津枯液涸，阴虚不能作汗者，宜归 \n葛饮。若寒邪深入，而阴中阳气不足，或背恶寒者，必难散解，非理阴煎不可。若中气大虚 \n大寒，身热恶寒，或大便溏泄，而表邪不能解者，非大温中饮不可。 \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>补虚法（共三条）\n\n属性：伤寒、瘟疫，俱外侮之证，惟内实者能拒之，即有所感而邪不胜正，虽病无害。最畏者， \n惟内虚之人，正不胜邪，邪必乘虚深入，害莫大矣。故曰伤寒偏打下虚人。且今人虚弱者多 \n，强实者少，设遇挟虚伤寒，而不知速救根本，则百无一生。故伤寒书曰∶阳证得阴脉者， \n死。正以阴脉即虚证也。此欲辨之，惟脉为主，而参以形证，自无失矣。盖凡遇伤寒外热等 \n证，而脉见微弱浮空，举按无力者，即是虚证，最不易解，最不宜攻。虽欲发汗，汗亦难出 \n，即有微汗，亦不过强逼肤腠之汗，而必非营卫通达之所化。若罔顾虚实而逼之太甚，则中 \n气竭而危亡立至矣。 \n然治虚之法，须察虚实之微甚。若半虚者，必用补为主，而兼散其邪。若太虚者，则全 \n然不可治邪。而单顾其本，顾本则专以保命，命得不死，则元气必渐复，或于七日之后，或 \n十四日。甚者二十日之后，元气一胜，邪将不攻自溃，大汗至而解矣。欲知其兆，亦察其脉 \n，但得弱者渐强。小者，渐大。弦者，渐滑。紧者，渐缓。则大汗将通，吉期近矣。 \n凡用补之法，但察其胸膈何如。若胸腹多滞者，未可补。年壮气实者未可补。若气本 \n不实，而胸腹无滞，则放胆用之。又若内无热邪，而素宜用温，其或气有难行者，则必兼暖 \n胃而后可。盖补得暖而愈行，邪得暖而速散，切不可杂用消耗寒凉，以分温补之力。其或初 \n感寒邪，但见脉证真虚，邪不易散等证，则人参、熟地之类，开手盒饭速用，愈早愈妙，若 \n或迟疑，则纵寇深入，反成难制。此治虚邪最善之法也。余用此法，活人多矣。 \n常闻昧者有伤寒忌补之说，不知补者所以补中，是即托里之意。亦以寒邪如盗，其来在 \n外，元气如民，其守在中，足民正所以强中，强中正所以御外，保命玄机，惟此一着。何为 \n补住邪气？庸妄误人，莫此为甚。余因再悉于此，用补伤寒治法之未备，渐用渐熟，方知其 \n妙。自今而后，知必有不惑余言，而受余之生者，将无穷矣。 \n一、伤寒精血素弱，或阴中阳气不足，脉细弱而恶寒者，必须大助真阴，则阳从阴出， \n而表邪自可速解。惟理阴煎加柴胡、麻黄之类，或随证加减用之为最妙。若伤寒于七日八日 \n之后，脉数无力，神昏气倦，或躁扰不宁，散之不可，清之不可，而邪不能解者，只宜理阴 \n煎大剂与之，真回生神剂也。若气血俱虚而邪不能解，只宜平补者，以五福饮为主，而随证 \n加减用之，或大补元煎，或六物煎，或十全大补汤，皆可用。若脾胃中气虚弱，而邪不能解 \n者，宜四君子汤加减用之。若中气虚弱脾寒，或兼呕恶而邪不解者，宜五君子煎、温胃饮。 \n若劳倦伤脾，寒邪内陷，身热不退，当升散者，宜补中益气汤。若寒邪陷入阴分，血虚不能 \n外达，而当升散者，宜补阴益气煎。若阴虚发热，面赤口渴，烦躁，脉浮洪无力者，宜六 \n味地黄汤大剂与之，一服可愈。凡中气虚寒，表邪不解，或日久畏药，或诸药不效者，只宜 \n独参汤，或浓或淡，或冷或热，随其所好，时时代茶与之，连日勿间，使其营气渐复，则邪 \n气渐退，大有回生之妙，毋勿之也。 \n一、伤寒用补之法，与用攻用散者不同。盖攻散所以去实邪，其力峻，其效速。故凡用 \n柴胡、麻黄之类，取效在一二三剂之间，用大黄、芒硝之类，取效在一剂之间，此而不效。 \n必其用之不善，不可多也。至若用补者，所以补虚，其力柔，其功缓，虽于一二剂见效者， \n亦多有之。若积劳积损，气血虚甚者，欲其复元，诚不易也。但察其服补无碍，或于脉证间 \n略见相投，便是得补之力。故轻者二三剂，重者十余剂，方得见功，而汗出邪退以愈也。若 \n不知此理，而但于一二剂间，未见速效，则必致庸谗起，惑乱生，而全功尽弃矣。此不可不 \n深察也。 \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>温补法（共二条）\n\n属性：凡治伤寒、温疫宜温补者，为其寒邪凝滞，阳不胜阴，非温不能行，非温不能复也。如 \n寒气在经者，以邪在表也，宜用温散，法具如前；寒气在脏者，以阳气虚也，或宜温补，或 \n止温中。然用温之法，但察其外虽热而内无热者，便是假热，宜温不宜凉也；病虽热而元气虚 \n者，亦是假热，宜温不宜凉也。真热者，谁不得而知之。惟假热为难辨耳。病假热者，非用 \n甘温，热必不退，矧真寒者，又在不言可知。大都实证多真热，虚证多假热，故治实者多宜 \n用凉。治虚者多宜用温。真假不识，误人不浅矣。又真寒假热之辨，则实亦有寒，实亦有热 \n。虚亦有寒，虚亦有热，若谓实者皆热，虚者皆寒，则凿而谬矣。但实而寒者，只宜温散， \n不必滋补。虚而热者，只宜调补，最畏寒凉。盖寒凉无生意，而善败元气。若以寒凉治虚证 \n，则热未必退，且暂用则或可。久则无不败脾而危者。既已病热，又不宜寒，则总云假热， \n本非过也。 \n一、伤寒发热，而命门阳虚，或恶寒，或身痛，或呕，或痢，脉弱气虚，而表不能解者 \n，必用大温中饮。或理阴煎。若伤寒身热，心肺有寒，或呕哕而咳，或腹满而喘，止有寒邪 \n而无虚者，宜小青龙汤。若阴证伤寒，自利脉沉，身痛发热，腹痛厥逆，但有寒邪而元气无 \n虚者，当用温药，宜四逆汤。若寒在太阴，腹痛吐痢，或胀满厥逆，脾胃虚寒，而邪有不解 \n者，宜温胃饮，或理中汤。若伤寒一二日，邪在太阳，或在少阴，背恶寒而表不解者，宜附 \n子理阴煎。在仲景则用附子汤。若风寒在表，阴寒在里，外为身热，而内则泻痢不能止，或 \n见呕恶，或腹因痢痛者，此其中气下泄，则外邪益陷，必不能解，宜速用胃关煎，或大温中 \n饮。凡患伤寒，有阴阳大虚，元气将败，而邪不能解者，非六味回阳饮不可。然但有大虚大 \n寒之意，即当用此。若待其败，恐无及矣。凡阴盛隔阳，内真寒而外假热者，其证必头红面 \n赤，或干渴舌焦，或口疮喉痛，或烦喘狂躁，或身热如火，或见虚斑而蚊迹遍身，或发阴黄 \n而溺如金汁。虽其外有此证，而脉则微弱不鼓，且或为呕恶，或为泄泻，或背腹畏寒，或气 \n短似喘，或昏睡无知，或惊惶惧怯，或虽热不渴，或言虽谵妄而气促声微，或身虽躁狂而举 \n动无力，禁之则止，是皆内虚外实，真寒假热之证。须用理阴煎，或六味回阳饮、大温中饮 \n、八味地黄汤之类，大剂与之，庶可保全。若虚火上浮，喉痛热躁，不能热饮者，用井水浸 \n药冷与饮之，此用假寒之味，以解上焦之假热，真热之性，以救下焦之真寒，回阳起死，真 \n神妙之法也。其有血气本虚，用补相便。然温补既多，而病日昏愦，且见烦热难愈者。此其 \n阳邪独亢，阴气不至，而虚中有热也。但改滋阴，以犀角地黄汤加黄芩、麦冬，或一柴胡饮 \n加知母之类。此十补一清之法。一剂即效，其妙如神。医中圆活，最宜知此。 \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>清利法（共三条）\n\n属性：凡治伤寒、瘟疫，宜清利者，非止一端。盖火实者，宜清火。气实者，宜行气。食滞 \n者，宜消食。痰盛者，宜化痰。皆所谓清利也。凡此数者，滞去则气行，而表邪自解。然此 \n宜用于邪实等证，而本非虚证之所宜。其有虚中挟实者，不妨少为兼用，此中权度，自有其 \n宜。若病在危急，则毫不容谬，设不当清而妄用之，亦与扑残灯者，无异也。 \n一、伤寒火盛者，治宜清解。若热入阳明，烦渴躁热，脉洪便实，而邪有不解者，宜柴 \n胡白虎煎，或单用白虎汤、太清饮，或玉泉散。若汗后仍热者，亦宜用之。若伤寒口渴，烦 \n热赤斑，脉洪大而无力者，宜人参白虎汤。若伤寒邪在太阳，发热头痛，脉洪大，表邪未解 \n，而内热又甚者，宜一柴胡饮，或三黄石膏汤，或六神通解散。若六经通热，火邪不解，或 \n狂斑烦躁，或头红面赤，口干舌黑，脉洪邪实者，宜抽薪饮，或黄连解毒汤，或加柴胡。若 \n伤寒热入血室，吐衄斑黄，及血热血燥，不能作汗而邪不解者，宜《局方》犀角地黄汤。热 \n甚者，宜《良方》犀角地黄汤。若热邪闭结血分，大便不通，而邪不能解者，宜《拔萃》犀 \n角地黄汤。若少阴水亏，阳明火盛，热渴失血，牙痛便结，脉空作喘，而邪不能解者，宜玉 \n女煎。若伤寒阳邪亢盛，血脉不通而四肢厥逆者，谓之热厥，宜四逆散。若暑月时行瘟疫， \n表里俱热，宜清宜解者，羌活升麻汤。若伤寒热结膀胱，而小水不利，火邪不退，或挟热泄 \n泻者，宜大厘清饮，或柴芩煎，或益元散。若伤寒实热内蓄，小水不利，而口渴烦热发黄者 \n，宜茵陈饮，或大厘清饮。凡瘟疫热甚，而烦渴不宁者，宜悉尼浆时时与之，解渴退火最妙 \n，大胜于益元散。冷水禀天一之性，甘而不苦，故大能清热解烦，滋阴壮水。凡火盛水涸， \n大渴便结，营卫热闭不能作汗者，最宜用之。虽虚证不可用，然亦有当用者。但察其喉口热 \n极，唇舌干焦，大便秘结不通，而大渴喜冷者，此阴虚水亏证也，不妨与人参、熟地、桂、 \n附、干姜之属，相间并用，借以滋阴，其功不小。惟大便不结，及微热微渴，劳倦阳虚等证 \n，最不宜用，若妄用之，则多致寒颤而败。 \n一、伤寒兼杂证者，治宜调和、清利。凡伤寒兼风，发热，咳嗽多痰者，宜柴陈煎。若 \n食滞气实，邪结胃脘，而表不解者，宜大和中饮加柴胡。若感四时寒湿之气，以致脾胃不和 \n，或呕或吐，或泄泻胀满者，宜平胃散。或寒盛多吐者，宜和胃饮。若外感风寒，内停饮食 \n，头痛寒热，或为吐泻胀满者，宜藿香正气散。若感四时寒湿，发热发黄，身痛脉紧，中寒 \n泄泻，小水不利者，宜柴芩饮。若中无寒而多火者，宜柴苓汤。若外伤暑热，霍乱泄泻，小 \n水不利，腹痛胀满，内阴外阳者，宜五苓散。若外伤寒湿，一身尽痛者，羌活胜湿汤。 \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>吐法（共二条）\n\n属性：凡伤寒宜吐者，必其上焦有滞，或食或痰，结聚胸膈，而邪不得散者，当吐也；或寒邪 \n浊气内陷膈间，而为痞为痛者，当吐也，盖吐中自有发散之意。若中气虚寒，脉弱无力，及 \n气短虚烦不宁者，皆不可吐。凡用吐药，中病即止，不必尽剂。 \n一、古方吐法多用独圣散及茶调散，凡上焦邪滞皆可用之。然不若新吐法为更捷也。又 \n凡诸药皆可吐，只随证用药，煎汤服，少顷，探而吐之，则轻重可酌，标本可兼，尤其善也。 \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>下法（共二条）\n\n属性：凡伤寒、瘟疫宜下者，必阳明邪实于腑而秘结腹满者，乃可下之。或元气素强，胃气素 \n实者，亦可下之。若大便虽数日不行，而腹无胀满，及大便无壅滞不通之状，或连日不食， \n而脐腹坦然，软而无碍者，此其阳明胃腑本无实邪，切不可妄下、妄导，以泄中气。又如伤 \n寒门忌下诸条，必当加意详察，不可误用。盖诸误之害，下为尤甚，不可忽也。今见时医有 \n妄下而亦不致死者，必其元气之素强，能胜攻下者也。若概引为证，必致杀人。 \n一、伤寒邪入阳明，便秘谵语，腹满烦热，脉证俱实者，宜大承气汤，或调胃承气汤。 \n若伤寒表证未除，里证又急，表里俱实者，宜大柴胡汤。若三焦六经邪火壅结，大便不通， \n而表邪不解者，宜《局方》凉膈散。若伤寒热邪传里，当下而气血俱虚者，宜陶氏黄龙汤。 \n若伤寒热邪传里，而血虚秘结，腹胀作痛，邪不能解者，宜玉烛散。若时气瘟疫遍行，火邪 \n内蓄，三焦实热，大便秘结而邪不能退者，宜五瘟丹。若时行瘟疫发热，火浮于上，胸膈结 \n热者，宜大清丸。凡诸有宜通宜下者，但随证作引，送百顺丸一二三钱，最捷最妙。 \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>瘟疫热毒辨治（共三条）\n\n属性：瘟疫本即伤寒，然亦有稍异。以其多发于春夏，且因时气遍行，大小相似，必待日数足 \n，然后得汗而解者，是为瘟疫之证。虽古法云∶瘟病在三阳者多，三阴者少，然亦不可拘泥 \n。若见阴证阴脉，是即三阴病也，大宜辨而治之。 \n一、瘟疫之在三阳者，当辨其经。如脉浮头疼，发热身痛者，太阳证也，宜九味羌活汤 \n加减治之。若脉长，鼻干，不眠而躁者，阳明病也，宜葛根解肌汤，或十味参苏饮加减治之 \n。若脉弦而数，胸胁痛而耳聋，少阳证也，宜小柴胡汤加减治之。按此三阳之治，乃古方治瘟 \n之大略。然此证寒热虚实，无所不有，仍当察治如前，不可拘也。 \n一、瘟疫初起，而头疼身痛，憎寒发热，脉紧数洪滑，而别无他证，先宜正柴胡饮，或 \n败毒散，或十神汤。若温疫初起，多阴少阳，脉证无虚者，宜神术散。若瘟疫胸膈满闷，小 \n柴胡加枳实、橘红。热在内者，仍加黄连。若暑月时行瘟疫，表里俱热甚，宜清火解毒者， \n羌活升麻汤。若瘟疫火盛，脉洪大而热躁甚者，三黄石膏汤。若瘟疫热毒上浮，头面俱肿， \n目不能开，口干舌燥，咽喉不利者，普济消毒饮。若瘟疫脉洪大，烦躁热渴者，白虎汤。或 \n兼呕吐者，仲景竹叶石膏汤。若瘟疫发狂谵语，脉洪大滑实，而大便秘结不通者，大承气汤 \n，或鸡子清饮。若瘟疫内外俱有实邪，大便不通，当表里双解者，防风通圣散。若瘟疫病八 \n九日不退，而发斑发黄。但脉不虚不浮紧，而腹见痞满者，率可以承气、五苓合服而下之。 \n若瘟疫头身红赤，肢体热甚，烦躁不能当者。宜用解瘟疫热毒法，及内饮悉尼浆，或用井花 \n水调玉泉散，俱妙。按以上诸法，乃因时因证，皆阳证实邪之所宜。若瘟疫脉弱无力，或外虽 \n实而内则虚，或口不喜冷，大便不结之类，即非阳证，不得以身热脉数，俱认为火，虽在暑 \n月，如理中汤、理阴煎、大温中饮、大补元煎，及前温补诸法，皆当随证必用，此舍时从证 \n之妙法也。矧夏月尤多伏阴，故凡临此证者，必先察阴阳，次辨虚实，则其要也。宜切识之 \n。 \n徐东皋曰∶瘟疫六七日不解，以致热入血室，发黄身如烟熏，目如金色，口燥而热结。 \n以砭针刺曲池出恶血，仍以通圣散兼散兼下。得汗如黄水，粪如黑膏而即愈。按此即此方之 \n所谓打寒也。其法用手捋上膊，使血聚于臂，以帛缚定，乃用筋夹瓷锋，击刺肘中曲泽傍之 \n大络，使邪毒随恶血而出，亦最捷之法，穷人用之极效，然非曲池穴也。 \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>大头瘟证治（共三条）\n\n属性：大头瘟者，以天行邪毒客于三阳之经，所以憎寒发热，头目颈项或咽喉俱肿，甚至腮面 \n红赤，肩背斑肿，状如虾蟆，故又名为虾蟆瘟。大都此证多属风热，然亦有表里虚实之辨。 \n又外科有时毒证，亦即此也。方治具见本门，当参阅用之。 \n一、大头虾蟆瘟治法∶凡病在头目，内火未盛者，先当解散，宜正柴胡饮，或败毒散。 \n若时毒咽喉肿痛，内火不甚，而便利调和者，葛根牛蒡汤。时毒表里俱热，头目俱肿，宜清 \n宜散者，柴葛煎。若毒在阳明，表里俱热，多头痛鼻干，宜散者，柴葛解肌汤。若时毒三阳 \n，热极狂躁，咽喉肿痛，宜清兼散者，栀子仁汤。若时毒遍行，邪热上浮，头面俱肿，咽喉 \n不利者，普济消毒饮。若时毒风热上聚头面，宜升散者，犀角升麻汤。若时气盛行，宜清火 \n解毒者，羌活升麻汤。若时毒血热烦躁，兼赤斑者，犀角散、人参白虎汤。若时毒内外俱实 \n，当双解者，防风通圣散。若时毒 肿作痛，脉实便秘，宜下者，五利大黄汤，或漏芦 \n升麻汤，或连翘消毒散。若时毒虽盛，而外实内虚，脉弱神困，凡诸虚证有据者，必当救里 \n内托，宜参 托里散，或托里消毒散。其有阳虚假热，而兼呕恶泄泻者，如六味回阳饮之类 \n，皆所必用，不可疑也。若头项肿甚，疼痛难忍者，宜用清凉救苦散敷之。或取侧柏叶自然 \n汁，调蚯蚓泥敷之。 \n徐东皋曰∶大头虾蟆之候，因风热湿邪在于高颠之上，宜先用败毒散加羌活、黄芩、酒 \n浸大黄，随病加减，不可峻用降药，虽有硝黄之剂，亦必细细呷之。盖凡治大头瘟者，不宜 \n速攻，若攻之太峻，则邪气之在上者自如，而无过之中气反受其害而伤人也。且头乃空虚之 \n地，既着空虚，则无所不致，所以治法当先缓而后急，则邪伏也。缓治以清热消毒，虚者兼 \n益元气，胃虚食少者，兼助胃气；内实热甚，大便秘结者，以酒浸大黄下之，乃宣热而泄其 \n毒也，此为先缓后急之法。若先从鼻肿，次肿于目，又次肿于耳，渐至头上，络脑后结块则 \n止，不散，必出脓而后愈。又曰∶大头瘟太阳病，发于头上，并脑后下项，及目后赤肿者是 \n也，治宜荆防败毒散，羌活、 本行经。阳明病，发于鼻 ，并目不能开，及面部者是 \n也。或内热气喘，口干舌燥，咽喉肿痛不利，脉数大者，普济消毒饮。若内实而热者，防风通 \n圣散间服之。少阳病，发于耳之上下前后，并头角红肿者是也。若发热，或日晡潮热，或寒 \n热往来，口苦咽干，目痛，胸胁满闷者，小柴胡加消毒之药。 \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>伤寒初感治法\n\n属性：凡伤寒初感之治，本与传变者不同。盖凡病伤寒、瘟疫者，无不发热，然初感之时，其 \n邪在表，未经传里，未至郁热，虽身表有热，不过肤腠之寒邪，而内未有火，岂即阳证。斯 \n时也，但用温散，或兼托散，药对其证，无不即愈。奈何时俗之医，一见发热，便认为火， \n而芩、连、知、柏，开手便用，不知内无实热，何以当此？以寒邪得寒药，而表里俱寒，勾 \n连不解，则日以内传，寒凉妄用，则元阳日败。凡受斯害，死者多矣。此理不明，则既不知 \n表里，又不知先后，终身不省，每致误人，而且敢侈口谈医，其心果亦安乎？ \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>伤寒饮食宜忌（共二条）\n\n属性：凡伤寒饮食有宜忌者，有不宜忌者。若病伤寒而食不断者，以邪犹在表，未深入也。及 \n其稍深，而在半表半里之间，则食渐减矣，再入胸膈、胃口，则全不食矣。邪既在胃，则胃 \n口不饥，所以伤寒不食者，或十日，或二十日，皆无足虑者，亦以胃气不馁，则不败也。第 \n不欲食者，不可强食，强食则助邪；或新愈之后，胃气初醒，尤不可纵食，纵食则食复，此 \n皆大忌也。至有不宜忌者，则如劳倦内伤之人，偶感寒邪，亦必发热，此多以劳伤中气， \n本非真正伤寒外邪内陷之病，所以外虽发热，而内则饥馁，每多思食。奈何庸昧之辈，但见 \n发热，则曰饿不死伤寒，不论虚实，一概禁之。常见欲食者，索之不得，而且加以克伐寒凉 \n之药，嗟嗟！饥肠受剥，虚者益虚，内外夹攻，苦无所诉，及胃气既脱，反不欲食矣。即欲 \n救之，已无可及。余常治此证，每借食为药，所活多人，而见禁食受毙者，亦已不少，故详 \n言之。若病患时时觉饥而索食者，此其邪不在脏，胃中空虚而然，必不可禁，但不宜纵耳。 \n且因此可察虚实，关系非小，不可忽也。 \n巢氏曰∶凡瘟疫病新瘥，脾胃尚虚，谷气未复。若作劳妄动伤力，并食猪羊、鸡犬、鱼 \n脍、灸爆、肥腻、生果、面食、硬涩难消之物，停积肠胃，膈闷腹胀，便秘，或大吐大 \n下。重复发热，病作不可救矣。 \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>避疫法（共二条）\n\n属性：瘟疫乃天地之邪气，若人身正气内固，则邪不可干，自不相染。故避之之法，惟在节欲 \n节劳，或于房室劳倦之后，尤不可近，仍勿忍饥以受其气，皆要法也。至于却邪之法，则如 \n《刺法论》所云∶天牝从来，复得其往，气出于脑，即不干邪。盖天牝者，鼻也。鼻受天之 \n气，故曰天牝。气自空虚而来，亦欲其自空虚而去，即天牝从来，复得其往也。正以气通于 \n鼻，鼻通于脑，毒入脑中，则流布诸经，令人相染矣。气出于脑，谓嚏之，或张鼻以泄之， \n或受气于室，则泄气于外，而大吸精气以易之，则邪从鼻出，而毒瓦斯自散，此却邪于外之法 \n也，又如想心如日等法，盖胆属少阳，为中正之官，少阳气壮，则脏气赖以俱壮，而邪不能 \n入，此强中御邪之法也。凡探亲诊疾，事有不容已者，但知此诸法，则虽入最秽之地，自可 \n保其无虑。一方治天行时气，宅舍怪异，用降真香烧焚，大解邪秽。小儿带之，能解诸邪， \n最验。一法以福建香茶饼，不时噙口中，大辟伤寒瘴气秽恶。 \n《医统》曰∶男子病，邪气出于口；女人病，邪气出于前阴，其相对坐立之间，必须识 \n其向背。或以雄黄末涂鼻孔中，行动从容，察位而入。凡入病家，此亦医人之不可不知也。 \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>瘟疫论列方\n\n属性：麻桂饮（新散七） 理阴煎（新热三） 补中益气汤（补三十） 麻黄汤（散一） 桂枝汤（散 \n九） 补阴益气煎（新补十六） 参苏饮（散三四） 十神汤（散四十） 九味羌活汤（散四四） \n五积散（散三九） 败毒散（散三六） 荆防败毒散（痘三一） 柴葛煎（新散十四） 葛根汤（散 \n二九） 柴葛解肌汤（散三一） 归葛饮（新散十三） 神术散（散六五） 升麻葛根汤（散三十） \n归柴饮（新散十七） 柴陈煎（新散九） 柴芩煎（新散十） 羌活升麻汤（寒十二） 柴苓汤（ \n和一九二） 柴苓饮（新散十一） 十全大补汤（补二十） 圣散子（散四三） 五瘟丹（攻百一） \n六神通解散（寒十五） 四逆汤（热十四） 平胃散（和十七） 六味回阳饮（新热二） 四逆散 \n（散二八） 和胃饮（新和五） 防风通圣散（攻十六） 五福饮（新补六） 五苓散（和一八二） \n藿香正气散（和二十） 六物煎（新因二十） 一柴胡饮（新散一） 普济消毒饮（寒十三） 独参 \n汤（补三五） 二柴胡饮（新散二） 人参白虎汤（寒三） 温胃饮（新热五） 三柴胡饮（新散三） \n柴胡白虎煎（新散十二） 胃关煎（新热九） 四柴胡饮（新散四） 竹叶石膏汤（寒五） 理中 \n汤（热一） 五柴胡饮（新散五） 三黄石膏汤（寒十一） 附子汤（热二二） 正柴胡饮（新散六） \n黄连解毒汤（寒一） 白虎汤（寒二） 小柴胡汤（散十九） 《局方》凉膈散（攻十九） 太清 \n饮（新寒十三） 大柴胡汤（攻七） 解瘟热毒法（寒二四） 玉泉散（新寒十五） 大补元煎（新 \n补一） 羌活胜湿汤（和一七八） 益元散（寒百十二） 四君子汤（补一） 葛根牛蒡汤（外四五 \n）抽薪饮（新寒三） 五君子煎（新热六） 陶氏黄龙汤（攻二一） 茵陈饮（新寒八） 大温中 \n饮（新散八） 调胃承气汤（攻三） 玉女煎（新寒十二） 大和中饮（新和七） 五利大黄汤（外 \n八九） 犀角散（寒一三一） 大厘清饮（新寒五） 漏芦升麻汤（外九七） 悉尼浆（新寒十六） \n小青龙汤（散八） 连翘消毒散（外六一） 大青丸（攻百二） 金沸草散（散八一） 参 托里 \n散（外五） 玉烛散（攻二四） 大承气汤（攻一） 托里消毒散（外二） 百顺丸（新攻六） 独圣 \n散（攻百六） 栀子仁汤（寒十九） 清凉救苦散（外一三五） 茶调散（攻百七） 鸡子清饮（寒 \n十七） 犀角升麻汤（外四七） 吐法（新攻一） 犀角地黄汤（三方 寒七九、八十、八一） \n\n\n\n<目录>卷之十三性集·杂证谟\\瘟疫\n\n<篇名>论外备用方\n\n属性：夺命散（补三六 虚极） 芩连消毒散（寒十四） 陈氏正气散（和二二 风寒生冷） \n\n\n\n<目录>卷之十四性集·杂证谟\\疟疾\n\n<篇名>经义\n\n属性：《疟论》帝曰∶夫咳疟皆生于风，其蓄作有时者，何也？岐伯曰∶疟之始发也， \n先起于毫毛，伸欠乃作，寒栗鼓颔，腰脊俱痛。寒去则内外皆热，头痛如破，渴欲冷冻饮料。帝 \n曰；何气使然？曰∶阴阳上下交争，虚实更作，阴阳相移也。阳并于阴，则阴实而阳虚，阳 \n明虚则寒栗鼓颔也。巨阳虚则腰背头项痛，三阳俱虚则阴气胜，阴气胜则骨寒而痛，寒生于 \n内，故中外皆寒。阳盛则外热，阴虚则内热，外内皆热，则喘而渴，故欲冷冻饮料也。此皆得之 \n夏伤于暑，热气盛，藏于皮肤之内，肠胃之外，此荣气之所舍也。此令人汗空疏，腠理闭， \n因得秋气，汗出遇风，及得之以浴，水气舍于皮肤之内，与卫气并居。卫气者，昼日行于阳 \n，夜行于阴，此气得阳而外出，得阴而内薄，内外相搏，是以曰作。常曰∶其间日而作者何 \n也？岐伯曰∶其气之舍深，内薄于阴，阳气独发，阴邪内着，阴与阳争不得出，是以间日而 \n作也。帝曰∶其作日晏与日早者，何气使然？曰∶邪气客于风府，循膂而下，卫气一日一夜 \n大会于风府，其明日日下一节，故其作也晏。此先客于脊背也。每至于风府则腠理开，腠理 \n开则邪气入，邪气入则病作，以此日作稍益晏也。其出于风府，日下一节，二十五日下至 \n骨，二十六日入于脊内，注于伏膂之脉。其气上行，九日出于缺盆之中，其气日高，故作日 \n益早也。其间日发者，由邪气内薄于五脏，横连募原也。其道远，其气深，其行迟，不能与 \n卫气俱行，不得皆出，故间日乃作也。帝曰∶夫子言卫气每至于风府，腠理乃发，发则邪气 \n入，入则病作。今卫气日下一节，其气之发也，不当风府，其日作者奈何？曰∶此邪气客于 \n头项，循膂而下者也。故虚实不同，邪中异所，则不得当其风府也。故邪中于头项者，气至 \n头项而病；中于背者，气至背而病；中于腰脊者，气至腰脊而病；中于手足者，气至于手足 \n而病。卫气之所在，与邪气相合则病作，故风无常府；卫气之所发，必开其腠理，邪气之所 \n合，则其府也。帝曰∶疟先寒而后热者，何也？曰∶夏伤于大暑，其汗大出，腠理开发，因 \n遇夏气凄沧之水寒，藏于腠理皮肤之间，秋伤于风，则病成矣。夫寒者，阴气也。风者，阳 \n气也。先伤于寒而后伤于风，故先寒而后热也。病以时作，名曰寒疟。帝曰∶先热而后寒者 \n，何也？曰∶此先伤于风而后伤于寒，故先热而后寒也。亦以时作，名曰温疟。其但热而不 \n寒者，阴气先绝，阳气独发，则少气烦冤，手足热而欲呕，名曰瘅疟。岐伯曰∶夫疟之始发 \n也。阳气并于阴，当是之时，阳虚而阴盛，外无气，故先寒栗也。阴气逆极，则复出之阳， \n阳与阴复并于外，则阴虚而阳实，故复热而渴。夫疟气者，并于阳则阳胜，并于阴则阴胜， \n阴胜则寒，阳胜则热。疟者，风寒之气不常也。病极则复。夫病之未发也，阴未并阳，阳未 \n并阴，因而调之，真气得安，邪气乃亡，故工不能治其已发，为其气逆也。帝曰∶攻之奈何 \n？早晏何如？曰∶疟之且发也，阴阳之且移也，必从四末始也。阳已伤，阴从之，故先其时坚 \n束其处，令邪气不得入，阴气不得出，审候见之在孙络盛坚而血者，皆取之。此真往而未得 \n并者也。帝曰∶疟不发，其应何如？曰∶疟气者，必更盛更虚，当气之所在也。病在阳则热 \n而脉躁，在阴则寒而脉静，极则阴阳俱衰，卫气相离，故病得休。卫气集，则复病也。帝曰 \n∶时有间二日或至数日发，或渴或不渴，其故何也？曰∶其间日者，邪气与卫气客于六腑， \n而有时相失，不能相得，故休数日乃作也。疟者，阴阳更胜也，或甚或不甚，故或渴或不渴 \n。帝曰∶论言夏伤于暑，秋必病疟。今疟不必应者，何也？曰∶此应四时者也。其病异形者 \n，反四时也。其以秋病者，寒甚。以冬病者，寒不甚。以春病者，畏风。以夏病者，多汗。 \n帝曰∶夫病温疟与寒疟而皆安舍？舍于何脏？曰∶温疟者，得之冬中于风，寒气藏于骨髓之中 \n，至春则阳气大发，邪气不能自出，因遇大暑，脑髓烁，肌肉消，腠理发泄，或有所用力， \n邪气与汗皆出。此病藏于肾，其气先从内出之于外也。如是者，阴虚而阳盛，阳盛则热矣； \n衰则气复反入，入则阳虚，阳虚则寒矣。故先热而后寒，名曰温疟。帝曰∶瘅疟何如？曰∶ \n瘅疟者，肺素有热，气盛于身，厥逆上冲，中气实，而不外泄，因有所用力，腠理开，风寒 \n舍于皮肤之内，分肉之间而发，发则阳气盛，阳气盛而不衰则病矣。其气不及于阴，故但热 \n而不寒，气内藏于心，而外舍于分肉之间，令人消烁脱肉，故命曰瘅疟。 \n《至真要大论》帝曰∶火热或恶寒发热，有如疟状，或一日发，或间数日发，其故何 \n也？岐伯曰∶胜复之气，会遇之时，有多少也。阴气多而阳气少，则其发日远；阳气多而阴 \n气少，则其发日近。此胜复相搏，盛衰之节，疟亦同法。 \n《金匮真言论》曰∶夏暑汗不出者，秋成风疟。 \n《生气通天论》曰∶夏伤于暑，秋为咳疟。魄汗未尽，形弱而气烁，穴俞以闭，发 \n为风疟。 \n\n\n\n<目录>卷之十四性集·杂证谟\\疟疾\n\n<篇名>论证（共四条）\n\n属性：疟疾之疾，本由外感，故《内经》论疟无非曰风，曰寒，其义甚明。而后世之论，则泛 \n滥不一，总不过约言其末而反失其本，所以议论愈多，则病情愈昧矣。有辨在后，所当并察 \n。 \n凡疟因于暑，人皆知之。不知夏令炎热，此自正气之宜。然而，人有畏热者，每多避暑 \n就阴，贪凉过度，此因暑受寒，所以致疟。经曰∶夏暑汗不出者，秋成风疟，义可知也。然 \n又惟禀质薄弱，或劳倦过伤者，尤易感邪。此所以受邪有浅深，而为病有轻重也。第以病因 \n暑致，故曰受暑，而不知暑有阴阳，疟惟阴暑为病耳。至其病变，则有为寒证者，有为热证 \n者，有宜散者，有宜敛者，有宜温者，有宜清者，其要在标本虚实四字。知此四者，而因证 \n制宜，斯尽善矣。其有云伤暑而认暑为火者，有云脾寒而执以为寒者，皆一偏之见，不足凭 \n也。 \n凡疟发在夏至后，秋分前者，病在阳分，其病浅；发在秋分后，冬至前者，病在阴分， \n其病深。发在子之后，午之前者，此阳分病也，易愈；发在午之后，子之前者，此阴分病 \n也，难愈。病浅者，日作。病深者，间日作。若三日、四日者，以受邪日久，而邪气居于阴 \n分，其病尤深。 \n凡疟病自阴而渐阳，自迟而渐早者，由重而轻也；自阳而渐阴，自早而渐迟，由轻而重 \n也。凡感邪极深者，其发必迟，而多致隔日，必使渐早渐近，方是佳兆。故治此疾者，春夏 \n为易，秋冬为难。 \n\n\n\n<目录>卷之十四性集·杂证谟\\疟疾\n\n<篇名>论治（共十二条）\n\n属性：凡疟疾初作，必多寒热，大抵皆属少阳经病。其于初起，当专以散邪为主。若果形气无 \n伤，而脉证别无他故者，但宜正柴胡饮，或三柴胡饮主之。少者一、二剂，多者三、四剂， \n无有不愈。若气体本弱而感邪为疟，即宜四柴胡饮为妙，勿以初起而畏之弗用也。 \n一、治疟当辨寒热，寒胜者即为阴证，热胜者即为阳证。盖有素禀之寒热，有染触之寒 \n热，然必其表里俱有热邪，方是火证。若疟至则热，疟止则退，而内无烦热闭结等证，则不 \n得以火证论治。若内外俱有火证，而邪有不散者，一柴胡饮主之。若邪入阳明，内热之甚， \n而邪有未散者，宜柴胡白虎煎。若邪入肝肾，而热极动血者，宜柴芩煎。 \n一、疟有寒证，如无虚邪，而但以寒邪不能散，或多中寒者，宜二柴胡饮。若以寒胜而 \n兼气虚，邪有不解者，宜四柴胡饮，或补中益气汤加干姜、官桂。若寒甚热少，脉迟而兼背 \n恶寒，或多呕恶泄泻者，必用麻桂饮，或大温中饮。 \n一、中气虚弱不能胜邪，而邪不能解者，病在脾肺气分，宜补中益气汤、五柴胡饮。若 \n阴虚血液不充而邪不能解者，病在肝肾精分，宜补阴益气煎、归柴饮。此证极多，其效尤捷 \n。若发时其寒如冰，其热如烙，而面赤如脂，渴欲饮水，而热退即不渴者，以六味地黄汤加 \n柴胡、芍药、肉桂，大剂一服，即可愈。若元气虚寒之甚，阳不胜阴而邪不能解者，大温中 \n饮。若元气虚甚，或衰老积弱者，则不必兼用攻邪，只当以正气为主，但使元气不败，则邪 \n气无有不服，宜大补元煎，或十全大补汤之类主之。而又惟休疟饮为最妙。 \n一、疟疾屡散之后，取汗既多，而病不能止者。必以过伤正气，而正不胜邪，则虽止微 \n邪犹然不息，但使元气之虚者一振，散者一收，则无不顿然愈矣，宜三阴煎、五福饮，或小 \n营煎、休疟饮主之。若有微寒者，宜大营煎，或理中汤。若微有火者，宜一阴煎。若多汗不 \n收者，宜五阴煎之类主之。 \n一、疟疾久不能愈者，必其脾肾俱虚，元气不复而然。但察其脉证，尚有微邪不解者， \n当专以补中益气汤为主。若邪气已尽而疟有不止者，则当专补元气，以八珍汤、十全大补汤 \n，或大补元煎之类主之。若肾阴不足，而精不化气者，宜理阴煎最效。若阴邪凝滞而久不愈 \n者，宜于前药加姜、桂、附子。 \n一、疟作而呕吐恶食者，虽曰少阳之邪为呕吐，然实由木邪乘胃所致。但解去外邪，呕 \n当自止，宜柴陈煎，或正柴胡饮加半夏主之。若脾胃气虚而寒邪乘之，则最多呕恶之证，宜 \n温胃饮、理中汤、养中煎之类主之。若虚寒连及命门，火不生土而作呕者，宜理阴煎、右归 \n饮之类主之。若兼食滞而作呕者，必多胀满，宜加陈皮、砂仁、山楂、浓朴之类为佐。若兼 \n火邪者，必多热渴、躁烦、秘结，宜以黄芩、黄连之类为佐；若火在阳明甚者，宜加石膏。若 \n兼寒者，必胃口怕寒，或吞酸，或嗳腐，或恶心。得热稍可者，宜以姜、桂、附子、吴茱萸 \n之类为佐。 \n一、疟疾因劳辄复，连绵不已者，此脾肾虚证。盖肾主骨，肝主筋，脾主四肢，气弱不 \n胜劳苦，所以即发，但补脾肝肾，使其气强则愈。如十全大补汤、八珍汤、补中益气汤，皆 \n可酌用。 \n一、疟疾发散已多，每致阴虚水亏，而烦热多渴者，宜以西瓜汁，或悉尼浆，或冷参汤 \n，俱可滋阴截疟。无热者，不可强用。 \n一、疟痢并作而脏平邪浅者，宜胃苓汤加柴胡一、二钱。若寒湿伤脾而疟痢并作者，宜 \n温胃饮加柴胡，或胃关煎加柴胡亦妙。若湿热伤脾，下及肝肾而暴注热渴，或下纯鲜血者， \n宜柴芩煎。 \n一、疟邪未清，而过食伤脾，以致痞满连绵不已者，宜大小和中饮加柴胡。若因食而成 \n疟痞者，宜芍药枳术丸，及大小和中饮之类调之。若痞成难消者，须灸章门、水道等穴，炷 \n宜稍大，多灸，或连灸二三次，方得全愈。 \n一、古云∶治疟之法，凡将发之时，与正发之际，慎毋勉强施治，即治亦无效，必待阴 \n阳并极，势平气退之后，然后，察而治之，或于未发二三时之先，迎而夺之，可也。经曰∶ \n夫疟之未发也，阴未并阳，阳未并阴，因而调之，真气得安，邪气乃亡。故工不能治其已发 \n，为其气逆也。按此古法，殊似不然，予近治疟，每迎其锐而击之，最捷最妙。是可见古法 \n之有不必泥者。 \n\n\n\n<目录>卷之十四性集·杂证谟\\疟疾\n\n<篇名>论汗\n\n属性：凡古人治疟之法，若其久而汗多，腠理开泄，阳不能固者，必补敛之；无汗则腠理致密 \n，邪不能解，必发散之。故曰∶有汗者要无汗，扶正为主；无汗者要有汗，散邪为主。此大 \n法也。盖疟本外邪，非汗不能解，若不知散解其邪，而妄用劫剂，多致胃气受伤，邪不能解 \n，必反难愈。此宜以补剂为主，加减取汗，汗后再加补养可也。若邪在阴分，则下体最难得 \n汗，补药力到，自然汗出至足，方是佳兆。凡病此而邪有未解者，大忌饱食，亦以汗之难易 \n为优劣也。凡寒邪之自外而入者，得汗即解，如伤寒之类皆是也。而惟时瘟时疟之病，则病 \n有浅深之不同。即如病瘟者，虽有大汗而热仍不退。病疟者，屡发屡汗而疟犹不止，此其所 \n感最深，故不能以一二汗而即愈，或通身如洗而犹不能透。若此者，但当察其强弱，仍渐次 \n再汗之，方得邪解。故不可谓汗后必无邪也。此但当以脉之紧与不紧，及头身之痛与不痛， \n寒热之甚与不甚为辨耳。然又有虽已得汗，邪气将解而不守禁忌，或因于劳，或因于欲，或 \n受生冷微邪，或胃气未清，因而过食，随触随发，此其旧邪未尽而新邪又至，缠绵深固，因 \n致留连者，亦必宜仍从汗解，但其宜固宜散，则犹当以酌虚实为首务。 \n\n\n\n<目录>卷之十四性集·杂证谟\\疟疾\n\n<篇名>论标本\n\n属性：凡治疟当知标本。予尝言∶有标则治标，无标则治本，此最为治疟之肯綮。何以言之？ \n盖标以邪气言，本以正气言也。夫邪正相争，所以病疟。凡疟之初起，本由邪盛，此当治邪 \n，固无疑也。若或表散已过，或久而不愈，则于邪正之间，有不可不辨矣。盖有邪者，证必 \n猖炽，脉必弦紧，或头疼头痛未除，或汗虽出而未透，凡属形证有余者，即其病虽已久，亦 \n必有表邪之未清也。但觉有微邪，此犹宜兼标为治。若汗出已多，邪解已透，别无实证实脉 \n可据，而犹然不愈者，必由正气全虚，或以质弱，或以年衰，故余气有未能却，而真阴有未 \n能静耳。此当专治其本，但使元气既复，则无有不愈。设或不明标本，无论有邪无邪，而但 \n知攻疟，则害者多矣。予为此说虽因疟而发，然诸病皆同此理，明者，当心志之。 \n\n\n\n<目录>卷之十四性集·杂证谟\\疟疾\n\n<篇名>论厌疟\n\n属性：凡厌疟之法，今世俗相传多用之，但其有效有不效，人每疑之，而其所以然者，自有的 \n确之妙，则从来人所未知也。盖疟以邪正相争，其感之浅者，乃少阳胆经病也。惟其邪本不 \n甚，则邪正互为胜负。当此时也，亦犹楚汉相持之势，但得一助之者，为楚则楚胜，为汉则 \n汉胜，故不论何物，皆可用以为厌。但使由之，勿使知之，其人恃有所助，则胆气略壮，而 \n邪即败矣。此即《内经》移精变气之意也。然必势均力敌者，乃可以一助而胜之，正胜则愈 \n也。若果彼强我弱，势不易制者，则厌必无益。故惟邪轻日作者可厌，而邪深间日者则不能 \n厌。此自理势之使然，无庸惑也。 \n\n\n\n<目录>卷之十四性集·杂证谟\\疟疾\n\n<篇名>论截疟（共四条）\n\n属性：凡截疟之法，方固不可，然亦无必效之方。若以愚见并及治验，则未尝藉于截也。盖有 \n邪者，去邪则愈。若散邪既透，解表已过，则但收拾元气而气复即愈。惟能于邪正之间，得 \n其攻补之宜，则无不自愈，此截之最善者也。至如截疟诸方，虽不可执，亦不可无。第有效 \n于此而不效于彼者，亦以人之气血阴阳各有不同故耳。故凡用截药者，亦当察人之强弱而酌 \n以用之，庶乎得效，然亦惟轻者，易截。而重者，不易截也。兹录诸方于后，亦可备于酌用 \n。截疟常山饮，气血强壮者，可用。截疟饮，气分不足者，可用。牛膝煎，血分不足者，可 \n用。截疟丹，时气多湿者，可用。木贼煎，湿痰邪实者，可用。何人饮、休疟饮，血气大虚 \n，欲急济者，可用。小柴胡汤加常山二钱，截疟如神。追疟饮，凡气血未衰，或屡散之后， \n用之最效。 \n丹溪曰∶数发之后，便宜截而除之，久则发得中气虚弱，致病邪愈深而难治。世有砒丹 \n等截药，大毒，不可轻用。常山性暴悍，善驱逐，然能伤真气，病患稍虚怯者，勿用。 \n杨仁斋曰∶或其人素虚者，慎勿用常山等药。 \n薛立斋曰∶若病势正炽，一二发间，未宜遽截，恐邪气不去，正气反伤耳。若胃气弱者 \n，用寒凉止截，脾胃复伤，必致连绵不已。若非培养元气，决不能愈。每见饮啖生冷物者， \n病或少愈，多致脾虚胃损，反为难治。若咽酸口酸，且宜节饮食，其病潮作时，虽大渴亦只 \n姜汤乘热饮之，此亦截疟之良法。凡欲截之，若血气俱虚，用人参、生姜各一两煎服，顿止 \n。不问新久并效。 \n\n\n\n<目录>卷之十四性集·杂证谟\\疟疾\n\n<篇名>论似疟非疟\n\n属性：凡似疟非疟之病，虽有往来寒热，而时作时止，本非疟之类也。凡大病后，或产后，或 \n虚损，俱有此证。经曰∶阳虚则外寒，阴虚则内热，阴气上入阳中则恶寒，阳气下入阴中则 \n恶热。故凡无外邪而病为寒热者，必属虚证。但虚有阴阳之异，而阳虚者必多寒，阴虚者必 \n多热。阳虚者宜补其阳，如理中汤、十全大补汤加姜桂附子之类，此皆人所易知也。惟阴虚 \n之证则最不易辨，盖阴中之水虚者，阴虚也；阴中之火虚者，亦阴虚也。如其津液枯燥，精 \n血耗伤，表里上下，俱多烦热等证，此阴中之水虚也。治宜壮水以配阳，如一阴煎、六味地 \n黄汤，或加减一阴煎之类主之。其有倏热往来，或面赤如脂，而腹喜热饮，或上热如烙，而 \n下冷如冰，或喉口大热，而大便不实，此其证虽若热，而脉必细微，或虽洪大而浮空无力者，是 \n皆阳气无根而孤浮于上，此阴中之火虚也。治宜益火之本，使之归源，如海藏八味地黄丸， \n或右归饮之类主之。假热退则真寒见，自可因证而治之也。寒热门论治尤详，所当并察。 \n\n\n\n<目录>卷之十四性集·杂证谟\\疟疾\n\n<篇名>论温疟\n\n属性：温疟一证，在《内经》曰∶温疟者，得之冬中于风寒，至春夏阳气大发而为病，此即正 \n伤寒之属也。故仲景《伤寒论》有温疟一证，即此是也。此与夏伤暑而秋为疟者，本自不同 \n，当于伤寒门酌而治之。 \n\n\n\n<目录>卷之十四性集·杂证谟\\疟疾\n\n<篇名>论瘅疟\n\n属性：瘅疟一证，在《内经》曰∶肺素有热，气盛于身，发则阳气盛而不衰，故致消烁脱肉者 \n，命曰瘅疟。盖此以阳脏而病阳证也，自与诸疟不同。而治此之法有三∶如热邪内蓄，而 \n表邪未解者，则当散以苦凉；如热因邪致，表虽解而火独盛者，则当清以苦寒，此皆治其有 \n余也。若邪火虽盛，而气血已衰，真阴日耗者，急宜壮水固元，若但知泻火，则阴日以亡， \n必致不救。 \n\n\n\n<目录>卷之十四性集·杂证谟\\疟疾\n\n<篇名>论瘴疟\n\n属性：瘴疟一证，惟岭南烟瘴之地有之。盖南方风湿不常，人受其邪而致病者，因名瘴疟。然 \n瘴出地气，疟由天气，但使内知调摄，而外不受邪，则虽居瘴地，何病之有？是可见瘴以地 \n言，而疟即风寒外感之病也。但其甚者，则或至迷困喑哑，乃与常疟为稍异耳。凡治此者，"}, {"n": 8, "text": "卷八\n\n亦总不离寒热虚实，及有邪无邪，如前治疟诸法而尽之矣。外如大梁李待诏瘴疟等证，既明 \n且确，详列瘴气门，不可不察。 \n\n\n\n<目录>卷之十四性集·杂证谟\\疟疾\n\n<篇名>述古（共八条）\n\n属性：仲景曰∶疟脉自弦。弦数者多热，弦迟者多寒。 \n《机要》曰∶疟有中三阳者，有中三阴者，其证各殊也。在太阳经谓之寒疟，治多汗之 \n；在阳明经谓之热疟，治多下之；在少阳经谓之风疟，治多和之。此三阳受病，谓之暴疟， \n发在夏至后，处暑前，乃伤之浅者。在阴经则不分三经，总谓之湿疟，当从太阴经论之。发 \n在处暑后，冬至前，此乃伤之重者。 \n一、古法云∶以清脾饮治秋时正疟，随证加减，大效。若胃中有伏痰郁结者，以草果饮 \n，一服可愈。 \n丹溪曰∶邪气深入阴分、血分，而成久疟者，必当用升发药，自脏而出之于腑，然后自 \n表作汗而解。若用下药，则邪气愈陷而难出矣。 \n傅氏曰∶疟系外邪，当以汗解。或汗不得出，郁而成痰，宜养胃、化痰、发汗，邪气得 \n出，自然和也。 \n刘宗浓曰∶或问∶俗以疟为脾寒，何也？曰∶此亦有理。盖暑盛阳极，人以伏阴在内，脾 \n困体倦，腠理开发；或因纳凉于水阁木阴，及泉水澡浴，而微寒客于肌肉之间，经所谓遇夏 \n气凄沧之水寒迫之是也；或劳役饥饱内伤而即病作，故指肌肉属脾，发则恶寒战栗，乃谓之 \n脾寒耳。实由风寒暑湿之邪，郁于腠理，夏时毛窍疏通而不为病，至秋气收敛之际，表邪不 \n能发越，故往来寒热，进退不已，病势如凌疟人之状，所以名疟。即如四时伤寒，十二经皆 \n能为病。古方治法，多兼内伤取效，脾胃和而精气通，则阴阳和解，此实非脾病也。然古人 \n称疟不得为脾寒者，正恐人专于温脾之说，不明造化之源，而失病机气宜之要故也。 \n立斋曰∶大凡疟证，皆因先伤于暑，次感于风，客于营卫之间，腠理不密，复遇风寒， \n闭而不出，舍于肠胃之外，与营卫并行，昼行于阳，夜行于阴，并则病作，离则病止。并于 \n阳则热，并于阴则寒。浅则日作，深则间日。在气则早，在血则晏。其病热多寒少，心烦少 \n睡者，属心，名曰瘟疟，用柴苓汤。但寒少热，腰疼足冷者，属肾，名曰寒疟，用桂附二陈 \n汤。先寒而后大热，咳嗽者，属肺，名曰瘅疟，用参苏饮。热长寒短，筋脉揪缩者，属肝， \n名曰风疟，宜小柴胡加乌药、香附。寒热相停，呕吐痰沫者，属脾，名曰食疟，宜清脾饮。 \n若中气虚而间日发者，用补中益气汤。若寒热大作，不论先后，此太阳阳明合病。寒热作则 \n必战，经曰∶热胜则动也。发热则必汗泄。又曰∶汗出不愈，知内热也。 \n又曰∶凡日久虚疟，寒热不多，或无寒而微热者，若内因胃气虚，用四君加升麻、当归 \n。若脾血虚，用四君加川芎、当归。若中气下陷，用补中益气加茯苓、半夏。大凡久疟，多 \n属元气虚寒，盖气虚则寒，血虚则热，胃虚则恶寒，脾虚则发热，阴火下流，则寒热交作。 \n或吐涎不食，战栗泄泻，手足逆冷，皆脾胃虚弱，但补益中气，则诸证悉愈。凡人久疟，诸 \n药不效，以补中益气汤内加半夏，用人参一两，煨姜五钱，此不截之截也，一服即愈。若病 \n久者，须大补元气为主，盖养正邪自除也。 \n徐东皋曰∶疟疾多因风寒暑湿而得之，乃天之邪气所伤，当以汗解。故仲景、河间悉用 \n发表之药，但以寒热多少，分经络而治。 \n\n\n\n<目录>卷之十四性集·杂证谟\\疟疾\n\n<篇名>辨古（共四条）\n\n属性：陈无择《三因方》云∶夫疟备三因，外则感四气，内则动七情，饮食饥饱，房室劳逸， \n皆能致之。经所谓夏伤暑，秋咳疟者，此则因时而叙耳，不可专以此论。外所因证，有寒 \n疟，有温疟，有瘅疟，并同《素问》也。有湿疟者，寒热身重，骨节烦疼，胀满自汗，善呕 \n，因汗出复浴，湿舍皮肤，及冒雨湿也。有牝疟者，寒多不热，但惨戚振栗，病以时作，此 \n则多感阴湿，阳不能制阴也。此五种疟疾，以外感风寒暑湿，与卫气相并而成。除瘅疟独热 \n，温疟先热，牝疟无热外，诸疟皆先寒后热。内所因证，病者以蓄怒伤肝，气郁所致，名曰 \n肝疟。以喜伤心，心气耗散所致，名曰心疟。以思伤脾，气郁涎结所致，名曰脾疟。以忧伤 \n肺，肺气凝痰所致，名曰肺疟。以失志伤肾所致，名曰肾疟。所致之证，并同《素问》。此 \n五种疟疾，以感气不和，郁结痰饮所致。不内外因，有疫疟者，一岁之间，长幼相似也。有 \n鬼疟者，梦寐不祥，多生恐怖也。有瘴疟者，乍热乍寒，乍有乍无，南方多病也。有胃疟者 \n，饮食饥饱，伤胃而成，世谓食疟也。有劳疟者，经年不瘥，前后复发，微劳不任也。亦有 \n数年不瘥，结成 癖在腹胁，名曰老疟，亦曰母疟。以上诸证，各有方治，宜推而用之 \n。 \n愚谓疟疾一证，《内经》言已详尽，无可加矣。而后世议论烦多，反资疑贰，兹举陈氏 \n三因之说，以见其概。如所云湿疟者，因汗出复浴，湿舍皮肤，固一说也。然浴以热汤，避 \n彼风处，则断不致疟，惟冷水相加，疟斯成矣。若然则仍是寒气，即《内经》所云夏遇凄沧 \n水寒之证也。然此犹近似，但宜辨明寒热耳。至若牝疟无热，则《内经》并无此说，惟《金 \n匮要略》曰∶疟多寒者，名曰牝疟，蜀漆散主之，亦非曰无热也。若果全无发热，而止见寒 \n栗，此自真寒阳虚证耳，别有本门。又安得谓之疟耶？再如内因五脏之疟，在《内经·刺疟 \n论》所言六经五脏之证，不过为邪在何经之辨，原非谓七情所伤便能成疟，而此云所致之证 \n，并同《素问》，则《素问》无此说也。且既云七情所伤，则其虚实大有不同，又岂皆痰饮 \n所致耶？再若不内外因，凡鬼疟梦寐之说，此或以疟邪乱神，因致狂言似鬼者有之，岂鬼崇 \n果能为疟乎？至若胃疟，既云饮食，则明是内伤，且凡先因于疟而后滞于食者有之，未有不 \n因外邪而单有食疟者也。夫病情必有标本，标本误认，治岂无瘥？窍计陈氏之言，既以三因 \n立论，故不得不敷演其说，而烨然若有可观，不知影响之谈，不但无益于病，而且乱人意见 \n，致令临证狐疑，莫知所从，而每至于害者，皆此之类。 \n丹溪曰∶疟有暑、有风、有湿、有痰、有食积。久发者，为老疟，不已者，为疟母。风 \n暑之疟，多因夏月在风凉处歇，遂闭汗不能得泄，暑舍于内。故大法当汗之。疟而恶饮食者 \n，必从饮食上得之，当以食治。俗云脾寒，乃因名而迷其实也。苟因饮食所伤而得之，未必 \n是寒，况其他乎。 \n严用和曰∶或乘凉饮冷，当风卧湿，饥饱失时，致脾胃不和，痰积中脘，遂成此疾，所 \n谓无痰不成疟也。 \n张子和曰∶《内经》既以夏伤于暑而为疟，何世医皆以脾寒治之，用姜、附、硫黄之类 \n，甚者归之祟怪，良可笑也。又或因夏月饮食生冷之类，指为食疟，此又非也。岂知《内经 \n》之论则不然，皆夏伤于暑，遇秋风寒而后作也。邪热浅则连日，邪热深则间日，并入于里 \n则寒，并入于表则热，若此论则了不相干于脾也。治平之时，其民夷静，虽用砒石、辰砂有 \n毒之药，以热治热，亦能取效。扰攘之时，其民劳苦，内火与外火俱动，以热攻热，转为泻 \n痢、吐血、疮疡、呕吐之疾，岂与夷静之人同治哉。予尝用张长沙汗吐下三法，愈疟病极多 \n，大忌错作脾寒治之。 \n愚谓疟疾之作，本由风寒水湿之邪感而致病，亦或有非风非水而衣薄受凉，凡体怯者， \n皆能为疟。及其病深，则未免因经及脏，因表及里，故有不慎饮食而更甚者，有不慎劳役而 \n增病者，总之无非外邪为之本，岂果因食因痰有能成疟者耶？今观朱丹溪之言，亦以痰食并 \n列，严用和则悉归之痰。盖皆因陈氏之说，而殊失《内经》之正意矣。故张子和亦以祟怪为 \n笑，以食疟为非，而云治平扰攘时当分治，是皆有理确见也。独怪其以暑为火，而且谓扰攘之 \n时，其民劳苦，大忌错作脾寒治之，而尝用汗吐下三法。恐此言亦属偏见也。念余幸逢明盛 \n，固不知扰攘景象，第以劳苦过伤之人，其虚更甚，又岂无三阳疲损等证，而可俱谓之火， \n及可尽用三法乎？甚哉立言之难，于此可见，而时中之不易得也如此。 \n\n\n\n<目录>卷之十四性集·杂证谟\\疟疾\n\n<篇名>简易方\n\n属性：一方 截疟神效。用常山末二钱，乌梅肉四个研烂，酒调，临发日早服。 \n一方 不问新久疟，用常山一两，锉碎，以好酒浸一宿，瓦器煮干为末，每服二钱，水 \n一盏，煎半盏，去滓停冷，五更服之，不吐不泻，效。 \n一方 治疟神效。用蒜不拘多少，研极烂，和黄丹少许，以聚为度，丸如芡实大，候干 \n，每服一丸，新汲水空心面东吞下。 \n\n\n\n<目录>卷之十四性集·杂证谟\\疟疾\n\n<篇名>针灸法\n\n属性：刺疟论诸刺法具载本经。大椎（可灸三壮） 三椎骨节间（灸亦可愈） 间使（可灸） \n\n\n\n<目录>卷之十四性集·杂证谟\\疟疾\n\n<篇名>疟疾论列方\n\n属性：柴陈煎（新散九） 麻桂饮（新散七） 柴苓汤（和一九三） 归柴饮（新散十七） 柴芩煎（ \n新散十） 理中汤（热一） 理阴煎（新热三） 参苏饮（散三四） 养中煎（新热四） 温胃饮（新 \n热五） 大营煎（新补十四） 小营煎（新补十五） 五福饮（新补六） 一阴煎（新补八） 三阴 \n煎（新补十一） 五阴煎（新补十三） 六味丸（补百二十） 八味丸（补百二一） 八珍汤（补十 \n九） 右归饮（新补三） 胃关煎（新热九） 胃苓汤（和百九十） 牛膝煎（新因二四） 木贼煎（ \n新因二六） 十全大补汤（补二十） 何人饮（新因二五） 草果饮（和二二六） 补中益气汤（补 \n三十） 休疟饮（新补二九） 追疟饮（新因又二五） 清脾饮（和二二五） 截疟饮（和二二二） \n补阴益气煎（新补十六） 一柴胡饮（新散一） 二柴胡饮（新散二） 桂附二陈汤（热百十四） \n三柴胡饮（新散三） 四柴胡饮（新散四） 六味地黄汤（补百二十） 正柴胡饮（新散六） 小 \n柴胡汤（散十九） 加减一阴煎（新补九） 四君子汤（补一） 大补元煎（新补一） 柴胡白虎煎 \n（新散十二） 大温中饮（新散八） 大和中饮（新和七） 截疟常山饮（和二三一） 小和中饮（ \n新和八） 悉尼浆（新寒十六） \n\n\n\n<目录>卷之十四性集·杂证谟\\疟疾\n\n<篇名>论外备用方\n\n属性：归脾汤（补三二） 柴平汤（和二三三 湿疟身痛） 四善饮（和二二八 和胃消痰） 七宝 \n饮（和二二七 截疟） 截疟丹（和二百三十） 不换金正气散（和二一 寒湿瘴疟） 正气散（ \n和二三 脾滞） 祛疟饮（和二二一 邪火） 藿香正气散（和二十 寒滞） 柴葛二陈汤（和六 \n暑湿） 驱疟饮（和二百二十 邪湿） 人参养胃汤（和二三四 和胃顺气） 万安散（和二二 \n二实邪初感） 常山散（和二二九） 交加饮子（和二三二 痰食瘴） 鳖甲饮（和二二四 久 \n疟疟母） 红丸子（攻九六 消食疟） 白虎加桂枝汤（寒四 热疟） 七枣汤（热百十八 阴疟 \n）扶阳助胃汤（热百十五 中寒） 加味小柴胡汤（散二一 热邪 \n） \n\n\n\n<目录>卷之十四性集·杂证谟\\瘴气\n\n<篇名>论证\n\n属性：瘴气，惟东南之域乃有之。盖岭南地气卑湿，雾多风少，且以冬时常暖，则阴中之阳气 \n不固，夏时反凉，则阳中之阴邪易伤，故人有不知保重而纵欲多劳者，极易犯之，以致发热 \n头痛，呕吐腹胀等证。盖重者即伤寒，轻者即疟疾，第在岭南病此，则均谓之瘴耳。然阳气 \n外浮之乡，必内多真寒而外多假热；阴气不固之人，虽外有邪证而内必多虚，此则岭南瘴疫 \n之大概也。但予未经其地，此不过亿度之见耳。及阅诸家之论，最多得理，足征予言之不诬 \n也，谨详录在下，以资择用，庶临证者可无惑，而病此者得所赖矣。又细察诸论，亦已详悉 \n，第病其用补之法犹有未尽，若值内伤虚损之甚而病此将危或难愈者，必以前瘟疫门治法参 \n而用之，则庶乎有济。 \n\n\n\n<目录>卷之十四性集·杂证谟\\瘴气\n\n<篇名>瘴病所由\n\n属性：凡劳疫伤饥之人，皆内伤不足者也。所谓邪气伤虚不伤实，同一理也。观《卫生方》云 \n∶北人寓广之地者，或往来广之途者，俱有阴阳相搏之患。然居者十病二三，途者十病八九 \n。正以居者安静，途者劳伤耳。《活人三昧》论瘴疟条云∶饮食有节，起居有常，则邪气不 \n能为害。彼道路崎岖，人烟疏阔，水浆不洁，酒灸多腥，饮食起居，未免乖度，况复有阴阳 \n相搏之气乎？故曰∶瘴气惟染劳役伤饥之人者此也。又凡居岭南者，必慎起居，节饮食，寡 \n欲清心，虽有风邪勿能害也。惟内境不出，则外境不入，此理之自然。其有感而病者，皆不 \n知所慎耳。 \n\n\n\n<目录>卷之十四性集·杂证谟\\瘴气\n\n<篇名>大梁李待诏瘴疟论\n\n属性：岭南既号炎方，而又濒海，地卑而土薄。炎方土薄，故阳燠之气常泄；濒海地卑，故阴 \n湿之气常盛，二气相搏，此寒热之气所由作也。阳气泄，故冬无霜雪，四时放花，人居其地 \n，气多上壅，肤多汗出，腠理不密，盖阳不反本而然。阴气盛，故晨夕雾昏，春夏淫雨，一 \n岁之间，蒸湿过半，三伏之内，反不甚热，盛夏连雨，即复凄寒，饮食、衣服、药食之类， \n往往生醭，人居其间，类多中湿，肢体重倦，又多香港脚之疾。盖阴常偏胜而然，阴阳之气既 \n偏而相搏，故人亦因之而感受其寒热不齐之病也。又阳燠既泄，则使人本气不坚，阳不下降 \n，常浮于上，故病者多上脘郁闷，胸中虚烦。阴湿既盛，则使人下体多寒，阴不上升，常沉 \n而下，故病者多腰膝重疼，腿足寒厥。予观岭南瘴疾，证候虽或不一，然大抵阴阳各不升降 \n，上热下寒者，十有八九。况人身上本属阳，下本属阴，兹又感此阳燠阴湿不和之气，自多 \n上热下寒之证也。得病之因，正以阳气不固，每发寒热，身必大汗，又复投之以麻黄、金沸 \n、青龙等汤，再发其表，则旋踵受毙；甚者，又以胸中痞闷，用利药下之，病患下体既冷。 \n下之，则十无一生。若此者，医害之也。 \n其时余染瘴疾，全家特甚。余悉用温中固下，升降阴阳正气之药，十治十愈。二仆皆病 \n，胸中痞闷烦躁，昏不知人。一云∶愿得凉药清膈。余审其证，上热下寒，皆以生姜附子汤 \n冷温服之，即日皆醒，自言胸膈清凉，得凉药而然也，实不知附子也。翌日各与丹珠丸一粒 \n，令空心服之，遂能食粥，然后用正气、平胃等药，自尔遂得平安。更治十数人皆安。盖附 \n子用生姜煎，既能发散，以热攻热，又能导虚热向下焦，除宿冷，又能固接元气。若烦闷 \n者，放冷服之。若病烦躁，不好饮水，反畏冷不能饮者，皆其虚热，非真热也，宜服姜附汤 \n。沈存中治瘴用七枣汤，正与此同，亦一服而愈。有用术附汤而病愈甚，盖术附相济，能固 \n热气，不能发散，惟附子一味为最妙。或有脉证实非上热下寒而目黄赤者，不可用附子。脉 \n若浮洪而数，寒热往来，无汗，乃小柴胡汤证。若证有可疑，寒热不辨，宜服嘉禾散。若热 \n多者，冷服之。嘉禾散能调中气，升降阴阳，治下虚中满，疗四时瘟疫伤寒，使无变动，虽 \n伤暑及阳证伤寒，服之亦解。若或寒多，服之尤宜。服二三日，即寒热之证自判，然后随证 \n调治之，无不愈者。大抵岭南之地卑湿，又人食槟榔，多气疏而不实，四时汗出，不宜更用 \n汗药，此理甚明。亦有当汗下者，然终不多也，明者察之。 \n\n\n\n<目录>卷之十四性集·杂证谟\\瘴气\n\n<篇名>《指迷方》瘴疟论（新安王）\n\n属性：读书之余，留意医学，幸得其传，颇识方脉，就辟入南，研究此证。谓南人凡病 \n，皆谓之瘴，率不服药，惟事鬼神。夫瘴之为病，犹伤寒之病也，岂可坐视而不药耶？每为 \n中医荏苒而致不救者有之。人过桂林以南无医药，且居南方之人，往往多汗，上盈下空，不 \n可用汗吐下三法。其业医者既鲜且庸，或妄用吐汗下者，是谓虚虚。方书皆谓南方天气温暑 \n，地气郁蒸，阴多闭固，阳多发泄，草木水泉皆禀恶气，人生其间，元气不固，感而为病， \n是为之瘴。轻者，寒热往来，正类咳疟，谓之冷瘴。重者，蕴热沉沉，昼夜如卧灰火中 \n，谓之热瘴。最重者，一病便失音，莫知其所以然，谓之哑瘴。冷瘴必不死，热瘴久而死， \n哑瘴无不死，此方书之说也。然以愚意观之，所谓哑瘴者，非伤寒失音之证乎？又岂中风失 \n语之证乎？治得其道，亦多可生，安得谓之无不死耶。若夫热瘴，乃是盛夏初秋，茅生狭道 \n，人行其间，热气蒸郁，无林木以蔽日，无水泉以解渴，伏暑至重，因而感疾。或有饮酒而 \n不节者，或食煎灸而积热者，偶成此证。其热昼夜不止，稍迟二三日，则血凝而不可救矣。 \n南中谓之中箭，亦谓之中草子。然有挑草子法，乃以针刺头额及上下唇，仍以楮叶擦舌，皆 \n令出血，徐以草药解其内热，应手而愈，安得谓之久而死耶。至于冷瘴，或寒多热少，或寒 \n少热多，亦有叠日间日之作，及其愈也。疮发于唇，验其证即是外方之疟。本非重病，然每 \n因误治而致祸，亦不可以必不死而忽之。但诊其脉息极微，见其元气果虚，即与附子汤而愈 \n；若误投寒药，所谓承气入胃，阴盛乃亡。若脉洪盛，证候实热，宜服和解药而徐治之；若 \n误投热药，所谓桂枝下咽，阳盛则毙也。要在切脉，审证之虚实寒热治之，无不愈也。人谓 \n岭南水泉草木地气之毒，故凡往来岭南之人，及宦而至者，无不病瘴而至危殆者也。又谓土 \n人生长其间，与水土之气相习，外人入南必一病，但有轻重之异，若久而与之俱化则免矣。 \n此说固若有理，但备之以将养之法，解之以平易之药，决保无病，纵病亦易愈矣。且瘴之为 \n病，土人反重，外人反轻者多。盖土人淫而下元虚，又浴于溪而多感冒，恣食生冷酒馔，全 \n不知节，所以重也。然则病瘴者，不可全咎风土之殊，皆人自失节养，有以致之耳。君子之 \n居是邦也，当慎起居，节饮食，适寒温，晨酒夜食，切忌大过，或有不快，即服正气散一二 \n剂，则脾胃自壮，气血通畅，微邪速散，又何瘴之有。 \n\n\n\n<目录>卷之十四性集·杂证谟\\瘴气\n\n<篇名>岭表十说（吴兴章杰）\n\n属性：一、岭表之俗食槟榔，甚者，日至十数枚。盖瘴疟之作，率因饮食过度，气滞痰结，而 \n槟榔最能下气消食去痰，故人皆狃于近利而暗于远患。此颇类北人之食酪酥，多致肤理缜密 \n，一旦病疫当汗，则塞而不得出。峤南地热，食槟榔故脏气疏泄。若一旦病瘴当攻发，则虚 \n羸而不能堪。所以土人多瘠而色黄，岂全是气候所致。盖亦槟榔为患，殆勿思耳。 \n二、《本草》载三人触雾晨行，饮酒者，独不病。故北人度岭，率相勉饮酒，而迁客羁 \n士，往往醺酣以自适。且岭外酒价尤廉，贩夫役卒俱得肆饮，咸谓可以辟瘴。殊不知少则益 \n，而多则滋瘴之源也。何以言之？盖南土暑湿，嗜酒则多中湿毒，兼以瘴疟之作，率因上膈 \n痰饮，而酒则尤能聚痰。岭外谚云∶莫饮卯时酒，莫食申时饭，诚摄生之要也。可见酒之为 \n物，能辟瘴以生人，亦能滋瘴以害人。然则生也、死也。非酒也，顾在人也。 \n三、广南每以暑毒为患者，盖一岁之间，暑热过半，使人难避而易犯，凡起居饮食少失 \n节度，则为暑毒所中，道途之间，尤多冒暑。故土人于暑时，相戒勿出。且遐荒之境，道路 \n崎岖，而传舍饮食，皆不如欲。所以自北初至者，皆云不习水土而病，及既还，则又谓之回头 \n瘴。大率得之道路劳倦，冒犯暑气，与夫饮食居处失度也。 \n四、岭南寒暑之候不常，尤难于调摄，故凡居入与在路者，冬夏之衣皆不可缺，随其气 \n候，速宜增减，缓则致病。又岭外海风异常，稍中人则为病，坐卧易衣，时当慎也。 \n五、岭外虽以多暑为病，而四时亦有伤寒、瘟疫之疾其类不一，土人不问何疾，悉谓之 \n瘴，治疗多误。或有一岁盛寒，近类中州，而土俗素无蚕绩，冬不衣绵，居室疏漏，户扃不 \n固，忽遭岁寒，则次年瘟疫必兴。医者之治瘟疫，亦当以本法治之，而随其风土气候，与夫 \n人之强弱，酌宜可也。 \n六、瘴疟之作，多因伏暑伤冷所致，纵非饮食冷物，亦必寒邪感于外，饮食伤于内也。 \n大抵伏暑浅而寒多者，易治。伏暑深而热多者，难治。近时北医至此，用大柴胡汤治热瘴， \n须是本气壮实者，乃能堪之。如土人久服槟榔，脏气既虚，往往不能服寒药，又能当此峻剂 \n乎？然土人才见发黄，便谓不治之疾，良可哀也。 \n七、北人之来岭南，婢仆多病瘴气。盖劳役之人，饮食乖度，昼夜冒暑，夜多卧地。又 \n凡事不能避忌，故先受其毙。既与之同休戚，宜加意戒之。 \n八、俚俗有病必召巫觋而祭鬼神，士夫咸笑其信巫不信医，愚谓此可悯恻而不可以笑也 \n。夫民虽至愚，然孰不思趋利避害，况性命所系，晓然易见。若医者能愈人疾，彼何为不用 \n？盖岭外良医甚鲜，药类尤乏，且山谷海屿之民，何从而得医药？所以不免信巫也，岂得已哉 \n。 \n九、瘴病不一，而土人以哑瘴最为危急，其状初得之即失音。不过一二日，即致不救。 \n医家多言为极热所致，或云内蕴热而外为感寒所激。近见北医有用煎生附子一味愈此疾者， \n得非以热治热，或者发散寒气耶？予尝闻有饮溪涧水中毒，令人失音，则知凡失音者，未必 \n皆瘴也。溪涧水毒，灼然有之，道路多无井泉，而濒江之民与夫山行者，皆饮溪涧之水，岂 \n无邂逅遇毒者？故途人所以多病此，得非是欤。 \n十、传云岭外多毒草，彘食之，而人食其肉者亦毒人。所以北人度岭，多戒食彘。然而 \n岭南能致瘴毒者，非止一端，岂在是耶。顺泉云∶岭南之彘，在市井者，食豆与酒糟。在乡 \n村者，食糠与碎米、芋苗，未有食草者。若然，则牛马羊畜之肉，悉皆不可食也，可乎？此 \n其所以不足信也。 \n\n\n\n<目录>卷之十四性集·杂证谟\\瘴气\n\n<篇名>回头瘴说\n\n属性：旧传出岭之后，复有回头瘴者。大概与在广而发瘴，及方入广而不伏水土者不异。盖南 \n方阳气常泄，阴气常盛，二气相搏，四时悉有寒热之气，人感之，即作寒热之病。寒则战栗 \n，热则怫郁，多由得汗而解，此广瘴之寒热也。今所谓回头瘴，及方入广而不伏水土者，亦 \n不过阴阳相搏，气候不调而感疾耳。岭南天气，冬无霜雪，春寒，秋热，气候不齐，或一日而 \n忽然更变，与方外天气大不相侔。今回头瘴者，盖是先受广中之气，复感外方之气，冷热相 \n忤，寒暄不调，遂作阴阳相搏之疾，须度时候之寒热，量元气之浓薄。如出岭于孟冬时者， \n广尚多暄而少寒，或转北风，或有暴冷。若届途之际，宜服和解散、神术散之类，和脾胃以 \n逐风邪。及至外方，则天寒地冻，将及境之际，可服正气散、人参养胃汤之类。绝旧瘴以御 \n时寒可也。然此四药，亦特筌蹄耳，其实在保躬调养，酌序消详，切不可以得出瘴地而恣欲 \n，此病之所由作也。故所谓回头瘴者，岂虚语哉。 \n\n\n\n<目录>卷之十四性集·杂证谟\\瘴气\n\n<篇名>治瘴续说\n\n属性：继洪曰∶予寓岭南既久，愈知瘴疾不易用药。若病患身热而复寒，谓之冷瘴，不换金正 \n气散主之。若身热胸痞，或呕，或噎，大便不利者，嘉禾散。若病轻而觉有食积，兼用些少 \n感应丸，无积者，不可用。若病重者，不可妄用。转利，惟当温中固下。若冬末春初，因寒 \n而作大热者，小柴胡汤。夏月因暑气者，六和汤。若身极热，而头极痛，脉数者，为热瘴， \n宜用南人挑草子法，亦不可不服药。第此证病深，最为难治。盖凉药多不可用，惟宜热药， \n须得法以用之，如附子汤冷服者，是也。然此非工巧以处之则不可。如身热汗不多，头痛未 \n解，或且与和解散。如腰以上极热，腰以下稍凉，胸膈烦渴，腰腿重疼，或大便溏滑，其脉 \n数而按之不实，此阳浮阴闭也。惟李待诏生姜附子汤最妙。凡初病者，以生姜附子能发散耳 \n。若病经去汗既多，虚烦潮上，则惟恐其不敛不降，宜用熟附、干姜、沉香而冷服之。若便 \n利，则不必沉香。如烦甚，则少加竹茹。渴甚，多加人参、北五味。咳逆加丁香、淡竹叶。 \n若烦躁而有异象，眩惑，夜不安寝，可略与温胆汤。惟大便利者，不可服。若烦渴大作，宜 \n夺命散，或用冷汤，倍加人参、附子。若烦热，大便自利，或小便不涩，不可以赤为热，或 \n膝胫以下稍凉，此乃病邪所激，气血俱虚，表热无以养中，故水热而内虚也。可急服姜附汤 \n之类，及灸气海、足三里。若至四肢厥冷，两足冷甚，头额虚汗，或时咳逆，脉数而促，其 \n证多危，惟以三建汤之属，能敛心液，能壮真阳，可以更生也。又有哑瘴，即热瘴之甚者。 \n医书谓血得寒则凝泣，得热则淖溢。故热瘴面赤，心热，舌破，鼻衄，皆瘴热沸其血上涌所 \n致，故宜用挑草子法。甚则血上塞其心窍，故昏不能言，或但噫噫作声，即哑瘴也。治此者 \n，当散其血，用《局方》黑神散，立见神效。其或涎迷心窍而舌强者亦有之，却非真哑瘴也 \n，及兼风痰之证者，俱当审察而后用治。（本论有无稽之方，俱削去不录） \n\n\n\n<目录>卷之十四性集·杂证谟\\瘴气\n\n<篇名>药宜预备\n\n属性：居瘴地者，虽曰节慎起居，而防病之药不可不为之备，如人参、附子、干姜、当归、熟 \n地、紫金锭、苏合丸、不换金正气散之类，皆不可须臾离也。从宦兹土，则政事多繁，上下 \n交际，为商往来，则经营贸易，其势不容于自逸，稍觉不快，即宜如法服药以解之。微邪易 \n伏，固不致病也，惟其不能防微，则势必至于渐盛。故曰∶不治已病治未病，此之谓也。 \n\n\n\n<目录>卷之十四性集·杂证谟\\瘴气\n\n<篇名>瘴病脉候\n\n属性：两关脉洪大者，热瘴。脉数甚者，为热瘴。脉弦而紧者，为瘴疟。脉浮而紧者，宜解表 \n。脉浮缓者为伤风，其病轻。脉洪数而按之不实者，为阳浮阴闭。脉沉微而弱者，为虚寒。 \n\n\n\n<目录>卷之十四性集·杂证谟\\瘴气\n\n<篇名>瘴病愈后将养法\n\n属性：凡瘴病，不发三日后，方可洗手。七日后可洗面。半月后可梳头。一两月后，谨戒房事 \n，能戒百日，尤好。又瘴不发后，须吃素粥三日，经五日后，方可以猪脾煮羹，吃软饭。十 \n日后略可吃酒，少用肉羹。但不可食诸般骨汁。若犯之则再发，凡牛羊猪犬鸡鹅诸骨汁，须 \n并忌一月，或两月犹佳。凡犯而再发，必多困笃。 \n\n\n\n<目录>卷之十四性集·杂证谟\\瘴气\n\n<篇名>瘴气论列方\n\n属性：麻黄汤（散一） 桂枝汤（散九） 金沸草散（散八一） 和解散（和二三五） 神术散（散六 \n五） 不换金正气散（和二一） 正气散（和二三） 平胃散（和十七） 小柴胡汤（散十九） 嘉 \n禾散（和百六十） 六和汤（和一二七） 小青龙汤（散八） 术附汤（补四一） 附子汤（热二二） \n生姜附子汤（热三三） 七枣汤（热百十八） 姜附汤（热三二） 人参养胃汤（和二三七） 三 \n建汤（热四二） 冷汤（热百十九） 《局方》黑神散（妇五十） 夺命散（补三六） 温胆汤（和 \n一二五） 承气汤（攻一） 感应丸（攻五四） 紫金锭（因二百二） 苏合丸（和三七一） 丹珠 \n丸（未考） \n\n\n\n<目录>卷之十四性集·杂证谟\\瘴气\n\n<篇名>论外备用方\n\n属性：败毒散（散三六） 圣散子（散四二） 五味异功散（补四） 保和汤（和一四七，散邪顺气） \n槟榔煎（和二三六） 陈氏家传正气散（和二二） 屠苏酒（和二三七） 降椒酒（和二三八） \n理中汤（热一） 生姜煎（热百二十） 冷香汤（热八二） 养胃汤（热七十） 椒囊法（热一九二） \n干姜附子汤（热三四，阴证发热） 二味沉附汤（热百十八） 福建香茶饼（因三百二） 瘟疫 \n门诸方皆可酌用 \n\n\n\n<目录>卷之十五性集·杂证谟\\寒热\n\n<篇名>经义\n\n属性：《阴阳应象大论》曰∶积阳为天，积阴为地。阴静阳躁，阳生阴长，阳杀阴藏。阳化气 \n，阴成形。寒极生热，热极生寒。寒气生浊，热气生清。清气在下，则生飧泄；浊气在上， \n则生 胀。此阴阳反作，病之逆从也。阳胜则热，阴胜则寒。重寒则热，重热则寒。寒 \n伤形，热伤气。风胜则动，热胜则肿，燥胜则干，寒胜则浮，湿胜则濡泄。喜怒伤气，寒暑 \n伤形。冬伤于寒，春必病温；春伤于风，夏生飧泄；夏伤于暑，秋必咳疟；秋伤于湿， \n冬生咳嗽。阳胜则身热，腠理闭，喘粗为之俯仰，汗不出而热，齿干以烦冤，腹满，死，能 \n冬不能夏。阴胜则身寒，汗出，身常清，数栗而寒，寒则厥，厥则腹满，死，能夏不能冬。 \n天之邪气，感则害人五脏；水谷之寒热，感则害于六腑；地之湿气，感则害皮肉筋脉。 \n《天元纪大论》曰∶神在天为风，在地为木。在天为热，在地为火。在天为湿，在地 \n为土。在天为燥，在地为金。在天为寒，在地为水。故在天为气，在地成形，形气相感，而 \n化生万物矣。 \n《五营运大论》曰∶上下相构，寒暑相临，气相得则和，不相得则病。 \n《百病始生篇》曰∶风雨寒热，不得虚，邪不能独伤人。 \n《四气调神论》曰∶春气之应，养生之道也。逆之则伤肝，夏为寒变，奉长者少。夏气 \n之应，养长之道也。逆之则伤心，秋为咳疟，奉收者少。秋气之应，养收之道也。逆之 \n则伤肺，冬为飧泄，奉藏者少。冬气之应，养藏之道也。逆之则伤肾，春为痿厥，奉生者少 \n。 \n《金匮真言论》曰∶长夏善病洞泄寒中。 \n《气交变大论》曰∶岁木太过，风气流行，脾土受邪。岁火太过，炎暑流行，肺金受邪 \n。岁土太过，雨湿流行，肾水受邪。岁金太过，燥气流行，肝木受邪。岁水太过，寒气流行 \n，邪害心火。岁木不及，燥乃大行，生气失应。岁火不及，寒乃大行，长政不用。岁土不及 \n，风乃大行，化气不令。岁金不及，炎火乃行，生气乃用。岁水不及，湿乃大行，长气反用 \n。 \n《宣明五气篇》曰∶心恶热，肺恶寒，肝恶风，脾恶湿，肾恶燥，是谓五恶。 \n《经脉篇》曰∶肺所生病者，咳，上气喘渴，烦心胸满， 臂内前廉痛厥，掌中热 \n。气盛有余，则肩背痛，风寒汗出中风，小便数而欠。气虚则肩背痛寒，少气不足以息，溺 \n色变。大肠所生病者，气有余则当脉所过者热肿，虚则寒栗不复。胃所生病者，气盛则身以 \n前皆热，其有余于胃，则消谷善饥，溺色黄，气不足则身以前皆寒栗，胃中寒则胀满。心所 \n生病者，目黄，胁痛， 臂内后廉痛厥，掌中热痛。肾所生病者，口热舌干，咽肿上气 \n，嗌干及痛，烦心、心痛，黄胆，肠 ，脊股内后廉痛，痿厥嗜卧，足下热而痛。心主 \n所生病者，面赤目黄，喜笑不休，烦心心痛，掌中热。胆所生病者，足外反热，头痛颔痛， \n目锐 痛，缺盆腋下肿痛，马刀侠瘿，汗出振寒，疟。 \n《气厥论》曰∶肾移寒于脾，痈肿少气。脾移寒于肝，痈肿筋挛。肝移寒于心，狂，隔 \n中。心移寒于肺，肺消。肺消者，饮一溲二，死不治。肺移寒于肾，为涌水。涌水者，按腹 \n不坚，水气客于大肠，疾行则鸣濯濯，如囊裹水，水之病也。脾移热于肝，则为惊衄。肝移 \n热于心，则死。心移热于肺，传为鬲消。肺移热于肾，传为柔 。肾移热于脾，传为虚 \n，肠 ，死不可治。胞移热于膀胱，则癃，溺血。膀胱移热于小肠，膈肠不便，上为口 \n糜。小肠移热于大肠，为虑瘕，为沉。大肠移热于胃，善食而瘦，又谓之食 。胃 \n移热于胆，亦曰食 。胆移热于脑，则辛 鼻渊。鼻渊者，浊涕下不止也。传为衄 \n瞑目。故得之气厥也。 \n《寿夭刚柔篇》曰∶风寒伤形，忧恐忿怒伤气，气伤脏，乃病脏，寒伤形，乃应形，风 \n伤筋脉，筋脉乃应。 \n《咳论》曰∶皮毛者，肺之合也。皮毛先受邪气，邪气以从其合也。其寒饮食入胃，从 \n肺脉上至于肺，则肺寒。肺寒则外内合邪，因而客之，则为肺咳。 \n《刺志论》曰∶气虚身热，此谓反也。气盛身寒，得之伤寒。气虚身热，得之伤暑。气 \n实者，热也。气虚者，寒也。 \n《调经论》曰∶血气者，喜温而恶寒，寒则泣不能流，温则消而去之。帝曰∶寒湿之伤 \n人奈何？岐伯曰∶寒湿之中人也，皮肤不收，肌肉坚紧，营血泣，卫气去，故曰虚。虚者聂 \n辟气不足，按之则气足以温之，故快然而不痛。帝曰∶阴之生虚奈何？曰∶喜则气下，悲则 \n气消，消则脉空虚，因寒饮食，寒气熏满，则血泣气去，故曰虚矣。帝曰∶阳虚则外寒奈何 \n？曰∶阳受气于上焦，以温皮肤分肉之间，今寒气在外，则上焦不通。上焦不通，则寒气独 \n留于外，故寒栗。帝曰；阴虚生内热奈何？曰∶有所劳倦，形气衰少，谷气不盛，上焦不行 \n，下脘不通，胃气热，热气熏胸中，故内热。帝曰∶阳盛生外热奈何？曰∶上焦不通利，则 \n皮肤致密，腠理闭塞，玄府不通，卫气不得泄越，故外热。帝曰∶阴盛生内寒奈何？曰∶厥 \n气上逆，寒气积于胸中而不泻，不泻则温气去，寒独留则血凝泣，凝则脉不通，其脉盛大以 \n泣，故中寒。 \n《刺节真邪论》曰∶阳胜者则为热，阴胜者则为寒，寒则真气去，去则虚，虚则寒搏于 \n皮肤之间。虚邪之入于身也深，寒与热相搏，久留而内着，寒胜其热，则骨疼肉枯；热胜其 \n寒，则烂肉腐肌为脓，内伤骨，内伤骨为骨蚀。有所结，中于肉，宗气归之，邪留而不去， \n有热则化而为脓，无热则为肉疽。 \n《阴阳别论》曰∶三阳为病，发寒热。 \n《脉要精微论》曰∶风成为寒热。 \n《太阴阳明论》曰∶故犯贼风虚邪者，阳受之。阳受之则入六腑，入六腑，则身热不时 \n卧，上为喘呼。 \n《风论》曰∶风之伤人也，或为寒热，或为热中，或为寒中，或为疠风，或为偏枯，或 \n为风也。其寒也则衰饮食，其热也则消肌肉，故使人 栗而不能食，名曰寒热。风气与 \n阳明入胃，循脉而上至目内 ，其人肥，则风气不得外泄，则为热中而目黄。人瘦则外泄而 \n寒，则为寒中而泣出。 \n《举痛论》曰∶寒则腠理闭，气不行，故气收矣。炅则腠理开，营卫通，汗大泄，故气 \n泄矣。 \n《气穴论》曰∶营卫稽留，卫散营溢，气竭血着，外为发热，内为少气，疾泻无怠，以 \n通营卫，见则泻之，无问所会。邪溢气壅，脉热肉败，营卫不行，必将为脓，内销骨髓，外 \n破大 ，留于节腠，必将为败。积寒留舍，营卫不居，卷肉缩筋，肋肘不得伸，内为骨 \n痹，外为不仁，命曰不足，大寒留于溪谷也。 \n《脉解篇》曰；阳明所谓洒洒振寒者，阳明者午也，五月盛阳之阴也，阳盛而阴气加之 \n，故洒洒振寒也。 \n《经筋篇》曰∶经筋之病，寒则反折筋急，热则筋弛纵不收，阴痿不用。阳急则反折， \n阴急则俯不伸。淬刺者，刺寒急也。热则筋纵不收，无用燔针。 \n《大惑论》曰∶人之善饥而不嗜食者，何气使然？岐伯曰∶精气并于脾，热气留于胃， \n胃热则消谷，故善饥；胃气逆上则胃脘寒，故不嗜食也。 \n《逆调论》帝曰∶人身非常温也，非常热也，为之热而烦满者，何也？岐伯曰∶阴气 \n少而阳气胜，故热而烦满也。帝曰∶人身非衣寒也，中非有寒气也，寒从中生者何？曰∶是 \n人多痹气也，阳气少，阴气多，故身寒如从水中出。帝曰∶人有四肢热，逢风寒如炙如火者 \n，何也？曰∶是人者，阴气虚，阳气盛，四肢者，阳也，两阳相得而阴气虚少，少水不能灭 \n盛火，而阳独治。独治者，不能生长也，独胜而止耳。逢风而如炙如火者，是人当肉烁也。 \n帝曰∶人有身寒，汤火不能热，浓衣不能温，然不冻栗，是为何病？曰∶是人者，素肾气胜 \n，以水为事，太阳气衰，肾脂枯不长，一水不能胜两火。肾者，水也，而生于骨，骨不生则 \n髓不能满，故寒甚至骨也。所以不能冻栗者，肝一阳也，心二阳也，肾孤脏也，一水不能胜 \n二火，故不能冻栗，病名曰骨痹。是人当挛节也。 \n《评热病篇》曰∶邪气之所凑，其气必虚。阴虚者，阳必凑之，故少气时热而汗出也。 \n小便黄者，少腹中有热也。 \n《奇病论》曰∶肥者，令人内热，甘者，令人中满，故其气上溢，转为消渴，治之以兰 \n，除陈气也。 \n《论痛篇》帝曰∶人之病，或同时而伤，或易已，或难已，其故何如？少俞曰∶同时而 \n伤，其身多热者易已。多寒者，难已。 \n《五邪篇》曰∶邪在肺，则病皮肤痛，寒热，上气喘，汗出，咳动肩背。取之膺中外 \n，背三节五节之傍，以手疾按之，快然，乃刺之，取之缺盆中以越之。邪在肝，则两胁中痛 \n，寒中，恶血在内，行善掣节，时脚肿。取之行间以引胁下，补三里以温胃中，取血脉以散 \n恶血，取耳间青脉以去其掣。邪在脾胃，则病肌肉痛。阳气有余，阴气不足，则热中善饥； \n阳气不足，阴气有余，则寒中肠鸣腹痛。阴阳俱有余，若俱不足，则有寒有热，皆调于三里 \n。 \n《五癃津液别篇》曰∶天暑衣浓则腠理开，故汗出。寒留于分肉之间，聚沫则为痛。天 \n寒则腠理闭，气湿不行，水下留于膀胱，则为溺与气。 \n《通评虚实论》帝曰∶乳子而病热，脉悬小者，何如？岐伯曰∶手足温则生，寒则死 \n。帝曰∶乳子中风热，喘鸣肩息者，脉何如？曰∶喘鸣肩息者，脉实大也。缓则生，急则死 \n。 \n《脉要精微论》曰∶粗大者，阴不足，阳有余，为热中也。沉细数散者，寒热也。诸浮 \n不躁者，皆在阳，则为热。其有躁者，在手。诸细而沉者，皆在阴，则为骨痛。其有静者， \n在足。阳气有余，为身热无汗。阴气有余，为多汗身寒。阴阳有余，则无汗而寒。推而外之 \n，内而不外，有心腹积也。推而内之，外而不内，身有热也。 \n《论疾诊尺篇》曰∶尺肤热甚，脉盛躁者，病温也。其脉盛而滑者，病且出也。尺肤寒 \n，其脉小者，泄，少气。尺肤炬然，先热后寒者，寒热也。尺肤先寒，久大之而热者，亦寒 \n热也。肘所独热者，腰以上热。手所独热者，腰以下热。肘前独热者，膺前热，肘后独热者 \n，肩背热。臂中独热者，腰腹热。肘后粗以下三四寸热者，肠中有虫。掌中热者，腹中热。 \n掌中寒者，腹中寒。鱼上白肉有青血脉者，胃中有寒。尺炬然热，人迎大者，当夺血。尺坚 \n大，脉小甚，少气， 有加，立死。诊寒热，赤脉上下至瞳子，见一脉一岁死，见一脉 \n半一岁半死，见二脉二岁死，见二脉半二岁半死，见三脉三岁死。 \n《邪气脏腑病形篇》曰∶忧愁恐惧则伤心。形寒寒饮则伤肺，以其两寒相感，中外皆伤 \n，故气逆而上行。帝曰∶病之六变奈何？岐伯曰∶诸急者多寒，缓者多热。大者多气少血， \n小者血气皆少，滑者阳气盛，微有热，涩者多血少气，微有寒。 \n《平人气象论》曰∶寸口脉沉而弱，沉而喘，曰寒热，缓而滑曰热中。尺寒脉细，谓之 \n后泄。尺粗常热者，谓之热中。 \n《经络论》曰∶寒多则凝泣，凝泣则青黑。热多则淖泽，淖泽则黄赤。 \n《皮部论》曰∶其色多青则痛，多黑则痹，黄赤则热多，白则寒，五色皆见，则寒热也 \n。邪留于筋骨之间，寒多则筋挛骨痛，热多则筋弛骨消，肉烁 破，毛直而败。 \n《五色篇》曰∶五色奈何？曰∶青黑为痛，黄赤为热，白为寒，是为五官。人迎盛坚者 \n，伤于寒。气口盛坚者，伤于食。 \n《经脉篇》曰∶凡诊络脉，脉色青则寒且痛，赤则有热。胃中寒，手鱼之络多青矣。胃 \n中有热，鱼际络赤。其暴黑者，留久痹也。其有赤有黑有青者，寒热气也。其青短者，少气 \n也。 \n《六元正纪大论》帝曰∶夫子言用寒远寒，用热远热，愿闻何谓远？岐伯曰∶热无犯 \n热，寒无犯寒，从者和，逆者病，不可不敬畏而远之，所谓时兴六位也。帝曰∶余欲不远寒 \n，不远热，奈何？曰∶发表不远热，攻里不远寒。帝曰∶不发不攻而犯寒犯热何如？曰∶寒热 \n内贼，其病益甚。帝曰∶愿闻无病者何如？曰∶无者生之，有者甚之。帝曰∶生者何如？曰∶ \n不远热则热至，不远寒则寒至，寒至则坚否腹满，痛急下痢之病生矣。热至则身热，吐下霍 \n乱，痈疽疮疡，瞀郁，注下， ，肿胀，呕，鼽衄，头痛，骨节变，肉痛，血溢 \n，血泄，淋秘之病生矣。帝曰∶治之奈何？曰∶时必顺之，犯者，治以胜也。 \n《师传篇》∶岐伯曰∶夫治民与自治，未有逆而能治之者也。夫惟顺而已矣。百姓民众 \n皆欲顺其志也。帝曰∶顺之奈何？曰∶入国问俗，入家问讳，上堂问礼，临病患问所便。 \n帝曰∶便病患奈何？曰∶中热消瘅则便寒，寒中之属则便热。胃中热则消谷，令人悬心善饥 \n。脐以上皮热，肠中热，则出黄如糜。脐以下皮寒，胃中寒，则腹胀；肠中寒，则肠鸣飧泄 \n。胃中寒，肠中热，则胀而且泄。胃中热，肠中寒，则疾饥，小腹痛胀。 \n《至真要大论》曰∶寒者热之，热者寒之，微者逆之，甚者从之。帝曰∶何谓逆从？岐 \n伯曰∶逆者正治，从者反治，从少从多，观其事也。帝曰∶有病热者，寒之而热；有病寒者 \n，热之而寒，二者皆在，新病复起，奈何治？曰∶诸寒之而热者取之阴，热之而寒者取之阳 \n。所谓求其属也。 \n《八正神明论》曰∶天温日明，则人血淖溢而卫气浮，故血易泻，气易行。天寒日阴， \n则人血凝泣而卫气沉。是以天寒无刺，天温无凝，月生无泻，月满无补，月郭空无治，是谓 \n得时而调之。 \n《骨空论》曰∶灸寒热之法先灸项大椎，以年为壮数。次灸撅骨，以年为壮数。视背俞 \n陷者灸之。举臂肩上陷者灸之。两季胁之间灸之。外踝上绝骨之端灸之。足小指次指间灸之 \n。下陷脉灸之。外踝后灸之。缺盆骨上切之坚痛如筋者，灸之。膺中陷骨间灸之。掌 \n束骨下灸之。脐下关元三寸灸之。毛际动脉灸之。膝下三寸分间灸之。足阳明跗上动脉灸之 \n。颠上一灸之。犬所啮之处灸之三壮。凡当灸二十九处。伤食灸之。不已者，必视其经之过 \n于阳者，数刺其俞而药之。 \n\n\n\n<目录>卷之十五性集·杂证谟\\寒热\n\n<篇名>论证\n\n属性：病有寒热者，由阴阳之有偏胜也。凡阳胜则热，以阴之衰也。阴胜则寒，以阳之衰也。 \n故曰∶发热恶寒者，发于阳也；无热恶寒者，发于阴也。此寒热之病有不同，而阴阳之不可 \n不察也。又若外来之寒热，由风寒之外感。内生之寒热，由脏气之内伤，此寒热之因有不同 \n，而表里之不可不察也。虽曰阳证多热，阴证多寒，然极热者反有寒证，极寒者亦有热证， \n此又真假之不可不察也。虽曰外入之邪多有余，内出之邪多不足，然阳盛生外热，阳虚生外 \n寒，阴盛生内寒，阴虚生内热，此又虚实之不可不察也。诸如此者，有证可据，有脉可诊， \n有因可问。且经文尽发其深秘，已列前条，余有寒热篇，亦悉其证候，具在首卷。及伤寒门 \n，亦有寒热辨。但因此以详求其理，则可尽悉其要，而辨治自无难也。 \n一、寒热真假篇，义详一卷及火证门论虚火条中。 \n一、治法有逆从论，在一卷论治篇中。 \n\n\n\n<目录>卷之十五性集·杂证谟\\寒热\n\n<篇名>论诸寒证治（共五条）\n\n属性：凡寒病之由于外者，或由风寒以伤形，或由生冷以伤脏；其由于内者，或由劳欲以败阳 \n，或由禀赋之气弱。若寒自外入者，必由浅及深，多致呕恶胀满，或为疼痛泄泻；寒由内生 \n者，必由脏及表，所以战栗憎寒，或为厥逆拘挛。总之，热者多实，寒者多虚。故凡治寒证 \n者，当兼察其虚而仍察其脏，此不易之法也。 \n一、凡阴毒寒邪直中三阴者，此即伤寒类所谓直中阴经之阴证也。其于仓卒受寒，以致 \n身冷战栗，或四体拘挛，或心肠疼痛，或口噤失音，昏迷厥逆，或吐泻蜷卧，脉来微细，或 \n沉紧无神者，皆其证也。切不可妄用风药，再散其气，但速宜温中，则寒邪自散。轻则理中 \n汤、温胃饮，甚则四逆汤、大温中饮，或附子理阴煎之类主之。其有势在危急，唇青囊缩， \n无脉者，宜用华陀救阳脱方急治之。或仍灸气海、关元二、三十壮，但得手足渐温，脉微出 \n者，乃可生也。一方以胡椒研碎，用滚酒泡服，外用葱盐熨法。一方用黑豆二合炒热，以酒 \n烹入，滚数沸，去豆取酒，服二碗即愈。 \n一、寒中太阴，则中脘疼痛，宜理中汤、温胃饮。寒中少阴，则脐腹疼痛，宜归气饮， \n或五积散加吴茱萸。寒中厥阴，则少腹疼痛，宜四逆汤、归气饮、暖肝煎。其有寒中三阴而 \n寒滞不散，因致胀满痛甚者，宜暂用排气饮，或韩氏温中汤，先散其滞，然后调补之。或用 \n五味沉附汤，或暖肝煎，俱可择用。 \n一、生冷内伤，以致脏腑多寒，或为疼痛，或为呕吐，或为泄泻等证，治法随见各门。 \n又或素禀阳脏，每多恃强，好食生冷茶水，而变阳为阴者，治亦同前。 \n一、禀赋素弱，多有阳衰阴胜者，此先天之阳气不足也。或斫丧太过，以致命门火衰者 \n，此后天之阳气失守也。其证则未冷先寒，或手足清厥，或身为寒栗，或脾胃不健，或肚腹 \n不实，或小水频数，或阳道不壮，或每多恐畏，或眼耳少神，是皆阳虚生寒也，治宜温补元 \n气。其微者，宜五君子煎、理阴煎、六气煎、温胃饮、寿脾煎之类，择而用之。其甚者，宜 \n大补元煎、右归饮、右归丸、四味回阳饮、六味回阳饮、海藏八味地黄丸之类主之。其有脾 \n肾虚寒，每多腹痛飧泄。肾泄者，宜九气丹、一气丹，并于泄泻门求法治之。 \n\n\n\n<目录>卷之十五性集·杂证谟\\寒热\n\n<篇名>论诸热证治（共四条）\n\n属性：凡热病之作，亦自有内外之辨。如感风寒而传化为热，或因时气而火盛为热，此皆外来 \n之热，即伤寒、瘟疫、时毒、咳疟之属也。至若内生之热，则有因饮食而致者，有因劳 \n倦而致者，有因酒色而致者，有因七情而致者，有因药饵而致者，有因过暖而致者，有因阴 \n虚而致者，有偶感而致者，有累积而致者。虽其所因不同，而病候无过表里。故在外者，但 \n当察经络之深浅；在内者，但当察脏腑之阴阳。凡此诸证，在各门具有方论者，兹不再赘。 \n且热即火也。故治热之法，即当于火证门通融用之。其有未尽之义，仍列于后。 \n一、治热之法，凡微热之气，宜凉以和之。大热之气，宜寒以制之。郁热在经络者，宜 \n疏之、发之。结热在脏腑者，宜通之、利之。阴虚之热者，宜壮水以平之。无根之热者，宜 \n益火以培之。此其中有宜降者，所谓高者抑之也。有宜散者，所谓下者举之也。有相类者， \n所谓逆者正治也。有相反者，所谓从者反治也。治热之法，不过如此，而鲜有得其善者，岂 \n亦由学力之未至乎。 \n一、五脏之热证有可据者。如肺气上通于鼻，而下主于皮毛。心气上通于舌，而下主于 \n血脉。脾气上通于口，而下主于四肢。胃气上通于头面牙龈，而下主于肌肉。肝气上通于目 \n，而下主于筋节。肾气上通于喉、耳，而下主于二阴。而六腑之气，亦可因表里以察之，此 \n皆病在形体也。凡有诸中者必形诸外，故必有热证可据，方可以热论治，医中关系，惟此为 \n最。 \n一、治五脏之热，当察微甚。如心经之微热者，宜二阴煎、安神丸、天王补心丹、导赤 \n散之类，皆可随证酌用；其热甚者，如泻心汤、黄连解毒汤、八正散、《直指》黄芩汤，及 \n犀角地黄汤三方，皆其类也。肺经微热者，宜加减一阴煎、《正传》麦门冬汤、泻白散之类 \n主之；其热甚者，宜黄芩清肺饮、黄芩知母汤之类主之。肝经微热者，宜化肝煎、保阴煎； \n热甚者，宜加味龙胆泻肝汤、芍药清肝散、七正散。脾胃微热者，清化饮、黄芩芍药汤。阳 \n明热甚者，白虎汤、太清饮、泻黄散、玉泉散。肾经微热者，一阴煎、滋阴八味丸。热甚者 \n，正气汤、丹溪大补阴丸。肾虚兼胃火者，玉女煎。膀胱微热者，五淋散；热甚者，大厘清 \n饮、化阴煎。三焦微热者，徙薪饮；热甚者，抽薪饮、大连翘饮、凉膈散、三补丸、大金花 \n丸之类，择宜用之。凡清火退热方论甚多，此亦言其约耳。欲尽其义，当详考寒阵二类。 \n\n\n\n<目录>卷之十五性集·杂证谟\\寒热\n\n<篇名>论寒热往来证治（共三条）\n\n属性：凡寒热往来之病，其证有二∶盖一以外邪不解而然；一以阳盛阴虚而然。此其一为表证 \n，一为里证。所当辨治，不可紊也。 \n一、寒邪郁伏经络而为寒为热，此似疟非疟之类也。治法虽宜表散，然邪气得以久留者 \n，必其元气之虚而正不胜邪也。故凡治此者，皆当以兼补血气为主。若血分微虚，形气本不 \n甚弱，而邪有不解者，三柴胡饮。若火盛血燥而寒热不已者，一柴胡饮。若因劳倦，或气体 \n本弱，或肝脾不足，而邪有不净者，四柴胡饮，或五柴胡饮，或补中益气汤。若阳邪陷入阴 \n分，微兼内热，而邪有不解者，补阴益气煎。若脾胃阳气不健，中气不暖，而邪有不解者， \n温胃饮。若病久元气大虚，而寒热不退者，但当单培元气，不必兼散，宜五福饮、归脾汤， \n或大补元煎、理阴煎之类。察其阴阳，择而用之。若果阳虚，非用温补不可。 \n一、阴虚阳盛，或阴阳俱虚，而为寒热往来者。此以真阴不足，总属虚损之病也。然其 \n阴阳微甚，亦所当辨。如昼则热而夜则静者，此阳邪王于阴分，阳有余也。昼则静而夜则热 \n者，此阳邪陷入阴中，阴不足也。其有昼夜俱热，或兼烦躁多汗，而本非外感者。此证虽曰 \n重阳，而实则阴虚之极也。又有下见溏泄，或上见呕恶，而潮热夜热者，此元气无根，阳虚 \n之病也。大都阳实者，宜泻其阳，泻阳者。宜用苦寒。阴虚者，宜补其阴。补阴者，宜用甘 \n凉。惟阳虚一证，则身虽有热，大忌寒凉，此则人多不识也。然阴虚则病热，而阴气未竭者 \n，治之犹易；阳虚则病寒，而阳气未竭者，治之亦易。若孤阳无阴，而寒之不可，孤阴无阳 \n，而热之又不可，斯所谓两死之证也，无能为力矣。若阴虚阳盛而寒热往来，或夜热不止者 \n，加减一阴煎。若心经蕴热，火在阳分，而烦热往来者，二阴煎。若盗汗不止而夜热者，当 \n归六黄汤。若阴虚血热，崩淋不止而夜热者，保阴煎。若肝火不清，时多郁怒而为烦热者， \n徙薪饮。若妇人多郁多怒，而寒热不止者，加味逍遥散。若三阴亏损，血虚火盛而烦热不止 \n者，地黄膏、三才封髓丹。若男、妇、小儿，凡脾胃受伤，阳虚火浮，而为潮热夜热者，必 \n用理阴煎，或温胃饮，或大补元煎之类，方可保全。此证最多，此治最妙，勿以此为奇谈也 \n。 \n\n\n\n<目录>卷之十五性集·杂证谟\\寒热\n\n<篇名>述古\n\n属性：华元化曰∶人之寒热往来者，其病何也？此乃阴阳相胜也。阳不足则先寒后热，阴不足 \n则先热后寒。又上盛则发热，下盛则发寒。皮寒而躁者阳不足，皮热而躁者阴不足，皮寒而 \n寒者，阴盛也，皮热而热者，阳盛也。热发于下，则阴中之阳邪也，热发于上，则阳中之阳 \n邪也。寒起于上，则阳中之阴邪也。寒起于下，则阴中之阴邪也。颊赤多言而寒者，阳中之 \n阴邪也；面青多言而热者，阴中之阳邪也；面青多言而寒者，阴中之阴邪也。若不言者，不 \n可治也。阴中之阴中者，一生九死；阳中之阳中者，九生一死。阴病难治，阳病易医。诊其 \n脉候，滑实在上，则阳中之阳也；滑实在下，则阴中之阳也。微弱在上，则阳中之阴也；微 \n弱在下，则阴中之阴也。滑实在中则中热，微弱在中则中寒。寒用热取，热以寒攻。逆顺之 \n法，从乎天地，本乎阴阳也。从之者生，逆之者死。《金匮大要论》曰∶夜发寒者从，夜发 \n热者逆。昼发热者从，昼发寒者逆。逆从之道，亦在乎审明。 \n\n\n\n<目录>卷之十五性集·杂证谟\\寒热\n\n<篇名>寒热论列方\n\n属性：四逆汤（热十四） 理中汤（热一） 四味回阳饮（新热一） 温胃饮（新热五） 暖肝煎（新 \n热十五） 六味回阳饮（新热二） 寿脾煎（新热十六） 化肝煎（新寒十） 补中益气汤（补三十 \n）六气煎（新因二一） 归气饮（新热十四） 补阴益气煎（新补十六） 理阴煎（新热三） 五 \n福饮（新补六） 韩氏温中汤（热八九） 归脾汤（补三二） 五积散（散三九） 五味沉附汤（热 \n百十六） 右归饮（新补三） 右归丸（新补五） 海藏八味丸（补一二一） 一气丹（新热二二） \n九气丹（新热二三） 滋阴八味丸（新寒十七） 一阴煎（新补八） 二阴煎（新补十） 加减一 \n阴煎（新补九） 玉女煎（新寒十二） 化阴煎（新寒七） 当归六黄汤（寒六五） 白虎汤（寒二） \n泻白散（寒四二） 加味逍遥散（补九三） 清化饮（新因十三） 泻黄散（寒五七） 天王补心 \n丹（补百八） 玉泉散（新寒十五） 太清饮（新寒十三） 三才封髓丹（寒一六六） 保阴煎（新 \n寒一） 泻心汤（寒二七） 华佗阳脱方（热四六） 抽薪饮（新寒三） 徙薪饮（新寒四） 黄连 \n解毒汤（寒一） 七正散（寒百十六） 八正散（寒百十五） 黄芩芍药汤（寒百九） 五淋散（寒 \n百十七） 导赤散（寒一二二） 芍药清肝散（寒六一） 正气汤（寒六六） 凉膈散（攻十九） \n黄芩知母汤（寒五一） 三补丸（寒一六二） 安神丸（寒一四二） 黄芩清肺饮（寒三八） 排气 \n饮（新和六） 地黄膏（寒九一） 《直指》黄芩汤（寒百七） 大温中饮（新散八） 大补元煎（ \n新补一） 丹溪大补阴丸（寒一五七） 五君子煎（新热六） 大厘清饮（新寒五） 《正传》麦 \n门冬汤（寒四四） 大连翘饮（寒七八） 大金花丸（攻五五） 犀角地黄汤（寒八十、八一、八 \n二） 一柴胡饮（新散一） 三柴胡饮（新散三） 四柴胡饮（新散四） 五柴胡饮（新散五） 加 \n味龙胆泻肝汤（寒六四） \n\n\n\n<目录>卷之十五性集·杂证谟\\寒热\n\n<篇名>论外备用方\n\n属性：人参养营汤（补二一） 加味归脾汤（补三三） 调中益气汤（补三一 虚邪） 术附汤（补 \n四一 中寒） 参附汤（补三七 厥冷） 《金匮》大建中汤（补二三 中寒） 逍遥散（补九二 \n血虚发热） 圣愈汤（补九十 虚热） 八味大建中汤（补二五 阴寒） 人参固本丸（补百六 \n阴虚热） 益阴肾气丸（补一二五） 七味白术散（补五五 虚热渴） 柴苓汤（和一九二 寒 \n热泻） 藿香正气散（和二十 风寒） 龙脑鸡苏丸（和三七二 阴虚烦热） 四逆散（散二八 \n热厥） 小柴胡汤（散十九） 加减小柴胡汤（散二二 寒热腹痛） 九味羌活汤（散四四 外邪 \n寒热） 退热汤（寒九三 急劳大热） 秦艽扶羸汤（寒九二 虚劳） 黄 鳖甲煎（寒九十 虚 \n劳） 地骨皮散（寒七四 热渴） 《局方》大已寒丸（热百七十 中寒） 十补丸（热一七三 \n肾虚寒） 已寒丸（热一七二 阻阳于下） 《元戎》大己寒丸（热一七一 冷秘） 四逆汤（热 \n十四 寒厥） 附子汤（热二二 背恶寒） 附子理中汤（热二 寒厥） 温胃汤（热十二 温中 \n）三建汤（热四二 阴寒厥逆） 扶阳助胃汤（热百十五 中寒） 《保命》柴胡四物汤（补十 \n二虚劳） \n\n\n\n<目录>卷之十五性集·杂证谟\\暑证\n\n<篇名>经义\n\n属性：《热论》曰∶凡病伤寒而成温者，先夏至日者为病温，后夏至日者为病暑。暑当与汗皆 \n出，勿止。 \n《生气通天论》曰∶因于暑，汗，烦则喘满，静则多言，体若燔炭，汗出而散。 \n《刺志论》曰∶气盛身寒，得之伤寒。气虚身热，得之伤暑。 \n《金匮真言论》曰∶夏暑汗不出者，秋成风疟。 \n《阴阳应象大论》曰∶夏伤于暑，秋必咳疟。 \n\n\n\n<目录>卷之十五性集·杂证谟\\暑证\n\n<篇名>论证（共七条）\n\n属性：暑本夏月之热病，然有中暑而病者，有因暑而致病者，此其病有不同，而总由于暑。故 \n其为病，则有阴阳二证∶曰阴暑，曰阳暑，治犹冰炭，不可不辨也。阴暑者，因暑而受寒者 \n也。凡人之畏暑贪凉，不避寒气，则或于深堂大厦，或于风地树阴，或以乍热乍寒之时，不 \n谨衣被。以致寒邪袭于肌表，而病为发热头痛，无汗恶寒，身形拘急，肢体酸痛等证。 \n此以暑月受寒，故名阴暑，即伤寒也。惟宜温散为主，当以伤寒法治之也。又有不慎口腹， \n过食生冷，以致寒凉伤脏，而为呕吐、泻痢、腹痛等证，此亦因暑受寒，但以寒邪在内，治 \n宜温中为主，是亦阴暑之属也。阳暑者，乃因暑而受热者也，在仲景即谓之中 。凡以 \n盛暑烈日之时，或于长途，或于田野，不辞劳苦，以致热毒伤阴，而病为头痛烦躁，肌体大 \n热，大渴大汗，脉浮气喘，或无气以动等证。此以暑月受热，故名阳暑。治宜察气之虚实， \n火之微甚，或补或清，以固其气。此与阴暑之治，大有不同，若或因暑之名，而不分表里， \n不察阴阳，则误人不浅矣。 \n一、阴暑证，或在于表，或在于里。惟富贵安逸之人多有之。总由恣情任性，不慎风寒 \n所致也。阳暑证，惟辛苦劳役之人多有之。由乎触冒暑热，有势所不容已也。然暑热逼人者 \n，畏而可避，可避则犯之者少；阴寒袭入者，快而莫知，莫知则犯之者多。故凡有病暑者， \n阳暑不多见，而阴暑居其八九。今之人治暑者，但见发热头痛等证，则必曰此中暑也。而所 \n用无非寒凉，其不达也亦甚矣。 \n一、伤寒之病，虽同为寒邪，而名有不同也。伤暑之名，虽可同为暑邪，而病有不同也 \n。伤寒之名有不同者，在冬之寒，即谓之正伤寒；在春之温，即谓之温病；在夏之暑，即谓 \n之暑病。是温病、暑病。亦皆伤寒之别名耳。经曰∶冬伤于寒，春必温病。又曰∶凡病伤寒 \n而成温者，先夏至日者为病温，后夏至日者为病暑，即此谓也。伤暑之病有不同者，其因暑 \n而感寒者，寒则伤形，即伤寒也；因暑而受热者，热则伤气，即伤暑也。是内伤外感，俱有 \n暑病之不同耳。经曰∶气盛身寒，得之伤寒；气虚身热，得之伤暑，即此谓也。盖气盛身寒 \n者，谓身受寒邪而气无恙也，故曰伤寒。气虚身热者，谓身冒暑热，而热伤气也，故曰伤暑 \n。此义人多不解，而谓伤寒者必身寒，则于理不通，而大昧经旨矣。 \n一、夏月盛暑之时，必令身有微汗，此养身之道，最得时宜者也。若必使快然无汗，则 \n未免阴胜于阳，多致疾矣。观之经曰∶暑当与汗皆出，勿止。是言暑汗之勿宜止也。又曰∶ \n夏暑汗不出者，秋成风疟，是言暑汗不出之为病也。此夏月之汗宜否，盖可知矣。 \n一、夏月伏阴续论，在前第二卷《传忠录》中。 \n一、暑有八证∶脉虚，自汗，身热，背寒，面垢，烦渴，手足微冷，体重是也。凡治此 \n者，宜调理元气为主，清利次之。 \n一、中暑死者，不可使得冷，得冷便死。只宜以温暖之物，护其脐中，徐徐治之。 \n\n\n\n<目录>卷之十五性集·杂证谟\\暑证\n\n<篇名>论治（共五条）\n\n属性：一、阴暑证，凡暑月外感风寒，以致阴邪抑遏阳气，而病为发热头痛，肢体拘急酸疼， \n无汗恶寒，脉紧等症，此即伤寒之属。治以解散为主，宜正柴胡饮、小柴胡汤，或一、二、 \n三、四柴胡饮之类，酌其寒热虚实，随宜用之。若脉见微细，气体虚弱，不可发汗者，但宜 \n补中气，使元气渐充，则寒邪自散，不必攻邪也。或用补中益气汤主之。若邪感于外，而火 \n盛于内，或阳明热甚者，宜柴胡白虎煎之类主之。若寒邪在表未解，而六脉微细，背冷恶寒 \n，或呕恶泄泻，内无热证者，此正伏阴在内，而邪不易解，虽在暑月，亦速宜温中，如理阴 \n煎、理中汤、大温中饮、麻桂饮之类，皆宜速用，不可疑也。亦不可迟也。若邪盛于外而中 \n不甚虚者，或以五积散。以上诸证有不能尽者，俱宜以伤寒门诸法，察而治之。 \n一、阴暑证，凡内伤生冷，致损胃气，而病为腹痛、泄泻、呕吐者，治宜以温中散寒为 \n主。若初受寒邪，停积未散，而脾气未虚者，先宜以抑扶煎、五德丸之类主之。若胃气微虚 \n者，宜佐关煎、五德丸主之。若胃气再虚者，宜温胃饮、理中汤主之。若吐泻已甚，脾肾兼 \n伤，而痛连小腹二阴，或成痢者，宜胃关煎、理阴煎，或九气丹之类主之。若表中寒邪，内 \n伤主冷，表里俱病者，宜兼治之，以和胃饮加柴胡，或温胃饮加柴胡，或新方诸柴胡饮，察 \n虚实而用之。古方用大顺散为温中之总治，亦何足以尽之也。 \n一、阳暑以酷热伤人，本为热证，然阳中又有阴阳，此不可不辨。凡暑热中人者，其气 \n必虚，以火能克金而热伤气也。然热者不可不清，虚者不可不补，但阳中之阳者宜兼乎清， \n如身热，头痛，烦躁，大渴，大汗，脉洪滑，喜冷水，大便干结，小水赤痛之类，皆阳证 \n也。若气不甚虚，而但有火证者，宜白虎汤，或益元散主之。或火盛之甚者，惟玉泉散更妙 \n。若汗出脉虚浮，烦渴有火而少气者，宜白虎加人参汤，或仲景竹叶石膏汤、《宣明》桂苓 \n甘露饮之类主之。若眩晕少气，虽烦渴而火不甚者，宜生脉散主之。以上诸法，用治阳中之 \n阳，皆古法之善者。若虽壮热口渴，而脉虚无力，或重按全无，及神困气促者，此脾胃气虚 \n，元阳不足，假火之证，若误用白虎等剂，其危立至。 \n一、凡中暑热者，人皆知为阳证，而不知阳中有阴也。盖外中热邪，而内亦热者，此表 \n里俱热，方是阳证，治宜清补如前。若内本无热，而因热伤气，但气虚于中者，便有伏阴之 \n象，故凡治暑热之证，最当辨其阴阳虚实。若脉虚无力，或为恶寒背寒，或为呕恶，或为腹 \n痛泄泻，或四肢鼻尖微冷，或不喜凉茶凉水，或息短气促，无力以动之类，皆阳中之阴证 \n也。凡见此类，但当专顾元气，惟宜独参汤，徐徐与之为最妙。若兼微呕恶寒者，宜加煨姜 \n与人参等分主之。再其甚者，则养中煎、理中汤、五君子煎，或五福饮、理阴煎之类，皆当 \n随宜用之。若虚寒之甚，则舍时从证，桂附皆所必用，切不可因暑热之名，而执用寒凉解暑 \n等剂再伐阳气，则变有不可测也。若夏月于盛暑中，过于劳倦，因而中暑者，其劳倦既已伤 \n脾，暑热又以伤气，此本内伤大虚之候，当专以调补为先，然后察其有火无火，或有邪无邪 \n，而兼治如前可也。 \n一、夏月因暑致病，而医有不知伏阴，误投寒剂，以致吐泻腹痛，或外热内寒，烦躁多 \n渴，状若伤寒。但察其脉微神困，便是阴盛格阳之证，速宜温药以救其内。 \n一、夏月既伤暑热，复伤生冷，外热内寒者，当专以内寒为主。有滞者，清其滞；无滞 \n者，益其气。但温中理脾，脾气既复，而暑无不退也。 \n\n\n\n<目录>卷之十五性集·杂证谟\\暑证\n\n<篇名>论香薷饮\n\n属性：香薷饮乃夏月通用之药饵，常见富贵之家多有备此。令老少时常服之，用以防暑。而不 \n知人之宜此者少，不宜此者多也。若误用之，必反致疾，何也？盖香薷一物，气香窜而性沉 \n寒。惟其气窜，所以能通达上下，而去菀蒸之湿热。惟其性寒，所以能解渴除烦，而清搏 \n结之火邪。然必果属阳脏，果有火邪，果脾胃气强，肥甘过度，而宜寒畏热者，乃足以当之 \n，且赖其清凉，未必无益。若气本不充，则服之最能损气。火本非实，而服之乃以败阳。凡 \n素禀阴柔，及年质将半，饮食不健，躯体素弱之辈，不知利害而效尤妄用者，未有不反助伏 \n阴，损伤胃气，而致为吐泻腹痛，及阴寒危败等证。若加黄连，其寒尤甚，浓朴破气，均非 \n所宜。用者不可不审。 \n\n\n\n<目录>卷之十五性集·杂证谟\\暑证\n\n<篇名>述古（共六条）\n\n属性：仲景曰∶其伤于四时之气皆能为病。冬时严寒，中而即病者，名曰伤寒。不即病者，寒 \n毒藏于肌肤，至春变为温病，至夏变为暑病。暑病者，热极重于温也。是以辛苦之人，春夏 \n多温热病，皆由冬时触寒所致，非时行之气也。凡时行者，春时应暖而复大寒，夏时应大热 \n而反大凉，秋时应凉而反大热，冬时应寒而反大温。此非其时而有其气，是以一岁之中，长 \n幼之病多相似者，此则时行之气也。 \n曰∶太阳中热者， 是也。其人汗出恶寒，身热而渴，白虎加人参汤主之。太阳中 \n者，身热疼痛而脉微弱，此亦夏月伤冷水，水行皮中所致也，一物瓜蒂汤吐之。太阳 \n中者，发热恶寒，身重而疼痛，其脉弦细芤迟，小便已，洒洒然毛丛，手足逆冷，小 \n有劳，身即热，口开，前板齿燥。若发汗则恶寒甚，加温针则发热甚，数下之则淋甚。 \n洁古曰∶静而得之为中暑，动而得之为中热。中暑者阴证，中热者阳证。 \n陈无择曰∶暑热喜归心，心中之，使人噎闷，昏不知人。入肝则眩晕顽痹。入脾则昏睡 \n不觉，入肺则喘满痿 ，入肾则消渴。凡中 死者，治之切不可用冷，惟宜温养。 \n道途中无汤，即以热土熨脐中，仍使更溺其土，取以罨于脐上，概可见矣。凡觉中暑，急嚼 \n生姜一大块，水送下。如已迷闷，嚼大蒜一大瓣，水送下，如不能嚼，水研灌之，立醒。 \n戴氏曰∶夏月卒倒，不省人事，名曰暑风。 \n王节斋曰∶治暑之法，清心利小便最好。暑伤气，宜补真气为要。又有恶寒，或四肢逆 \n冷，甚者迷闷不省，而为霍乱吐痢，痰滞呕逆，腹痛泻痢，此则非暑伤人，乃因暑而自致之 \n病也。以其因暑而得，故亦谓之暑病，治法不同。若吐泻，脉沉微甚者，不可用凉药，可用 \n附子大顺散，或附子理中汤加芍药。若夏月多食冷物，及过饮茶水，致伤脾胃，则吐泻霍乱 \n。故治暑药多宜温脾消食。治湿利小便，医者要识此意。 \n薛立斋曰∶按东垣先生云∶暑热之时，无病之人，或避暑热，纳凉于深堂大厦得之者， \n名曰中暑。其病必头痛恶寒，身形拘急，肢节疼痛，烦热无汗，为房室阴寒之气所遏，使周 \n身阳气不得伸越，以大顺散热药主之。若行人或农夫，于日中劳役得之者，名曰中热，其病 \n必苦头痛，躁热恶热，肌热大渴，汗泄懒动，为天热外伤肺气，以苍术白虎汤凉剂主之。 \n若人元气不足，用前药不应，宜补中益气汤主之。大抵夏月阳气浮于外，阴气伏于内。若人 \n饮食劳倦，内伤中气，或酷暑劳役，外伤阳气者多患之，法当调补元气为主，而佐以解暑。 \n若中暑，乃阴寒之证，法当补阳气为主，少佐以解暑。故先哲多用姜、桂、附子之类，此推 \n《内经》舍时从证之良法也。今患暑证殁，而手足指甲或肢体青黯，此皆不究其因，不温补 \n其内，而泛用香薷饮之类所误也。又曰∶前证当分别中暑、中 ，脉虚、脉沉，无汗、 \n有汗，发热、不热，作渴、不渴，或泻、不泻，饮寒、饮热。辨其阴阳虚实，不可泛投寒凉 \n之剂。盖谓夏月伏阴在内，古人用附子大顺散之类，温补阳气，厥有旨哉。何今人之老弱， \n至夏月患食少体倦，发热作渴，或吐泻腹痛头痛诸证，反服香薷饮，复伤元气，无不招引暑 \n证，以致不起。至若清暑益气汤内用泽泻、苍术、黄柏之类，必审其果有湿热壅滞，方可用 \n之。否则反致亏损其阴，用当审察。 \n\n\n\n<目录>卷之十五性集·杂证谟\\暑证\n\n<篇名>暑证论列方\n\n属性：理中汤（热一） 理阴煎（新热三） 柴胡白虎煎（新散十二） 益元散（寒百十二） 玉泉散 \n（新寒十五） 竹叶石膏汤（寒五） 养中煎（新热四） 温胃饮（新热五） 四柴胡饮（新散四） \n胃关煎（新热九） 佐关煎（新热十） 大温中饮（新散八） 五德丸（新热十八） 九气丹（新热 \n二三） 五君子煎（新热六） 麻桂饮（新散七） 香薷饮（和一六九） 补中益气汤（补三十） \n生脉散（补五六） 小柴胡汤（散十九） 清暑益气汤（和一六八） 白虎汤（寒二） 五福饮（新 \n补六） 正柴胡饮（新散六） 苍术白虎汤（寒二） 和胃饮（新和五） 一柴胡饮（新散一） 白 \n虎加人参汤（寒三） 抑扶煎（新热十一） 二柴胡饮（新散二） 附子大顺散（热七八） 五积散 \n（散三九） 三柴胡饮（新散三） 一物瓜蒂汤（攻百五） 《宣明》桂苓甘露饮（寒八） \n\n\n\n<目录>卷之十五性集·杂证谟\\暑证\n\n<篇名>论外备用方\n\n属性：五物香薷饮（和百七十） 十味香薷饮（和一七一） 黄连香薷饮（和一七二 中热） 缩脾 \n饮（和一七三 暑毒吐泻） 四物地榆散（寒九六 昏迷） 子和桂苓甘露饮（寒九 虚热渴） \n\n\n\n<目录>卷之十五性集·杂证谟\\火证\n\n<篇名>经义\n\n属性：《天元纪大论》曰∶君火以明，相火以位。神在天为风，在地为木。在天为热，在地为 \n火。在天为湿，在地为土。在天为燥，在地为金。在天为寒，在地为水。故在天为气，在地 \n为形，形气相感而化生万物矣。天地者，万物之上下也。左右者，阴阳之道路也。水火者， \n阴阳之征兆也。金木者，生成之终始也。寒、暑、燥、湿、风、火，天之阴阳也。三阴三阳 \n上奉之。木火土金水火，地之阴阳也，生长化收藏下应之。天以阳生阴长，地以阳杀阴藏。 \n甲己之岁，土运统之。乙庚之岁，金运统之。丙辛之岁，水运统之。丁壬之岁，木运统之。 \n戊癸之岁，火运统之。厥阴之上，风气主之。少阴之上，热气主之。太阴之上，湿气主之。 \n少阳之上，相火主之。阳明之上，燥气主之。太阳之上，寒气主之。所谓本也，是谓六元。 \n《五营运大论》曰∶燥胜则地干，暑胜则地热，风胜则地动，湿胜则地泥，寒胜则地裂 \n，火胜则地固矣。 \n《六微旨大论》曰∶显明之右，君火之位也；君火之右，退行一步，相火治之；复行一 \n步，土气治之；复行一步，金气治之；复行一步，水气治之；复行一步，木气治之；复行一 \n步，君火治之。相火之下，水气承之，君火之下，阴精承之。君位臣则顺，臣位君则逆，所 \n谓二火也。 \n《至真要大论》曰∶少阴司天为热化，在泉为苦化，不司气化，居气为灼化。少阳司天 \n为火化，在泉为苦化，司气为丹化，间气为明化。 \n《藏气法时论》曰∶五行者，金木水火土也。更贵更贱，以知死生，以决成败，而定五 \n脏之气，间甚之时，死生之期也。 \n《阴阳应象大论》曰∶水为阴，火为阳。壮火之气衰，少火之气壮。壮火食气，气食少 \n火。壮火散气，少火生气。 \n《逆调论》曰∶一水不能胜二火，故不能冻栗。病名曰骨痹，是人当挛节也。（详列寒 \n热门） \n《解精微论》雷公请问∶哭泣之水所从生，涕所从出也？帝曰∶水之精为志，火之精为 \n神，水火相感，神志俱悲，是以目之水生也。帝曰∶厥则目无所见。夫人厥则阳气并于上， \n阴气并于下。阳并于上，则火独光也；阴并于下，则足寒，足寒则胀也。夫一水不胜五火， \n故目 盲，是以冲风，泣下而不止。夫风之中目也，阳气内守于精，是火气燔目。故见风则 \n泣下也。有以比之，夫火疾风生乃能雨，此之类也。 \n《示从容论》曰∶二火不胜三水，是以脉乱而无常也。 \n《宝命全角论》曰∶木得金而伐，火得水而灭，土得木而达，金得火而缺，水得土而绝 \n，万物尽然，不可胜竭。 \n《至真要大论》帝曰∶愿闻病机何如？岐伯曰∶诸风掉眩，皆属于肝。诸寒收引，皆 \n属于肾。诸气 郁，皆属于肺。诸湿肿满，皆属于脾。诸热瞀螈，皆属于火。诸痛痒疮 \n，皆属于心。诸厥固泄，皆属于下。诸痿喘呕，皆属于上。诸禁鼓栗，如丧神守，皆属于火 \n。诸痉项强，皆属于湿。诸逆冲上，皆属于火。诸胀腹大，皆属于热。诸躁狂越，皆属于火 \n。诸暴强直，皆属于风。诸病有声，鼓之如鼓，皆属于热。诸病 肿，疼酸惊骇，皆属 \n于火。诸转反戾，水液混浊，皆属于热。诸病水液，澄澈清冷，皆属于寒。诸呕吐酸，暴注 \n下迫，皆属于热。故《大要》曰∶谨守病机，各司其属，有者求之，无者求之，盛者责之， \n虚者责之，盛者泻之，虚则补之。必先五胜，疏其血气，令其调达，而致和平，此之谓也。 \n\n\n\n<目录>卷之十五性集·杂证谟\\火证\n\n<篇名>论君火相火之病\n\n属性：经曰∶君火以明，相火以位。此就火德辨阴阳，而悉其形气之理也。盖火本阳也，而阳 \n之在上者，为阳中之阳，故曰君火。阳之在下者，为阴中之阳，故曰相火。此天地生成之道 \n也。其在于人，则上为君火，故主于心。下为相火，故出于肾。主于心者，为神明之主，故 \n曰君火以明。出于肾者，为发生之根，故曰相火以位。至其为病，则以明者，其化虚，故君 \n火之气，有晦有明。以位者，其化实，故相火之病，能焚能燎。何也？盖化虚者，无形者也 \n，故其或衰或王，惟见于神明，神惟贵足，衰则可畏也。化实者，有形者也。故其为热为寒 \n，必着于血气，确有证据，方可言火也。此其一清一浊，有当辨者如此。然清浊虽二，而气 \n禀则一。故君火衰则相火亦败，此以无形者亏及有形者也；相火炽则君火亦炎，此以有形者 \n病及无形者也。夫生以神全，病惟形见，故火邪之为病，必根据于有位有形之相火。所谓邪火 \n者，即所谓凡火也，即所谓燎原之火也。惟不得其正，所以为病。故别以邪火名之，而实非 \n可以君相并言也。故在《内经》则又谓之畏火。正以此火有形，故可畏也。夫病以有形之火 \n，须治以有形之物，故形而火盛者，可泻以苦寒之物；形而火衰者，可助以甘温之物。此以 \n形治形，而治火之道，止于是矣。至若无形之火，则生生息息，窈窈冥冥，为先天之化，为 \n后天之神，为死生之母，为玄牝之门。又岂于形迹之间可能摹拟者哉。故有形之火不可纵， \n无形之火不可残。有能知火之邪正，而握其盈虚伸缩之权者，则神可全，病可却，而生道在 \n我矣，即吾有形，吾又何患。 \n\n\n\n<目录>卷之十五性集·杂证谟\\火证\n\n<篇名>论病机火证\n\n属性：观《内经·至真要大论》所列病机。凡言火者五，言热者四，似皆谓之火也。然诸病之 \n见于诸篇者，复有此言热而彼言寒，此言实而彼言虚者，岂果本经之自为矛盾耶？盖诸篇所 \n言，在专悉病情，故必详必尽；在本篇所言，亦不过总言五运六气之大约，原非确指为实火 \n实热也。故于篇末，复以有无虚实四字总结于后，此轩岐之明见万世，正恐后人误以火热二 \n字，悉认为真因，而晓示如此。此其火有虚实，热有真假，从可知矣。余以刘河间《原病式 \n》之谬，故于《类经》惟引《经》释《经》，不敢杜撰一言，冀在解人之惑，以救将来之误 \n耳。前三卷中，别有详辨，并《类经》详注，俱当互阅求正。 \n\n\n\n<目录>卷之十五性集·杂证谟\\火证\n\n<篇名>论虚火（共三条）\n\n属性：凡虚火证，即假热证也。余于首卷寒热真假篇，已言之详矣。然犹有未尽者，如虚火之 \n病源有二，虚火之外证有四，何也？盖一曰阴虚者能发热，此以真阴亏损，水不制火也； \n二曰阳虚者亦能发热，此以元阳败竭，火不归源也。此病源之二也。至若外证之四，则一曰 \n阳戴于上，而见于头面咽喉之间者，此其上虽热而下则寒，所谓无根之火也；二曰阳浮于外 \n，而发于皮肤肌肉之间者，此其外虽热而内则寒，所谓格阳之火也；三曰阳陷于下，而见于 \n便溺二阴之间者，此其下虽热而中则寒，所谓失位之火也；四曰阳亢乘阴，而见于精血髓液 \n之间者，此其金水败而铅汞干，所谓阴虚之火也，此外证之四也。然证虽有四，而本惟二， \n或在阴虚，或在阳虚，而尽之矣。第阴虚之火唯一，曰金水败者，是也。阳虚之火有三，曰 \n上中下者，是也。凡治此者，若以阴虚火盛，则治当壮水。壮水之法，只宜甘凉，不宜辛热"}, {"n": 9, "text": "卷九\n\n。若以阳虚发热，则治宜益火。益火之法，只宜温热，大忌清凉。第温热之效速，每于一二 \n剂间，便可奏功。甘凉之力缓，非多服不能见效也。然清凉之药，终不宜多，多则必损脾胃 \n。如不得已，则易以甘平，其庶几耳。倘甘平未效，则惟有甘温一法，斯堪实济，尚可望其 \n成功。否则，生气之机，终非清凉所能致也。此义最微，不可不察。 \n一、气本属阳，阳气不足，则寒从中生。寒从中生，则阳无所存而浮散于外，是即虚火 \n假热之谓也。而假寒之证，其义亦然。是以虚火实火，亦总由中气之有虚实耳。凡气实于内 \n而为寒者，有如严冬阳伏于下，而阴凝于上，故冰雪满地而井泉温暖也。气虚于内而为热者 \n，有如盛夏阴盛于中，而阳浮于外，故炎暑逼人而渊源清冷也。天地间理原如此，故不可见 \n热即云热，见寒即云寒，而务察其寒热之本。 \n一、火有虚实，故热有假真，而察之之法，总当以中气为之主，而外证无足凭也。故凡 \n假热之证，本中寒也；假寒之证，本内热也。中寒者，原是阴证；内热者，原是阳证。第以 \n惑者不明，故妄以寒证为假热，热证为假寒。而不知内热者当远热，内寒者当远寒。内有可 \n据，本皆真病，又何假之有？ \n\n\n\n<目录>卷之十五性集·杂证谟\\火证\n\n<篇名>论五志之火\n\n属性：经曰∶天有四时五行，以生长收藏，以生寒暑燥湿风。人有五脏化五气，以生喜怒思忧 \n恐，是即所谓五志也。此五志之化由乎五脏，而五脏之化由乎五行。故在心为喜，心主火也 \n；在肝为怒，肝主木也；在脾为思，脾主土也；在肺为忧，肺主金也；在肾为恐，肾主水也 \n。此五志各有分属，本不可以混言者也。且人有此生，即有此志，使无此志，生亦何为，是 \n生之与志，本不能离，亦不可离。而人于食息之常，孰不以五志为生，亦孰不以五志为用， \n而未闻以五志之动皆为火也。第或以用志失宜，则未免有伤脏气，故在《内经》则但言五脏 \n之伤，各有所属，五气之伤，各有所病，亦未闻以五志之伤皆云火也。而五火之说，乃始于 \n刘河间，云五志所伤皆热也。丹溪述河间而衍之曰∶五志之动，各有火起。刘宗浓又述丹溪 \n而衍之曰∶大怒则火起于肝，醉饱则火起于胃，房劳则火起于肾，悲哀动中则火起于肺，心 \n为君主，自焚则死矣。自三子之说行，则似乎五行悉化而为火，理岂然乎！ \n余尝察五志所伤之人，但见其憔悴日增，未见其俱为热病也。即因志动火者，非曰必无 \n，但伤气者十之九，动火者十之一，又岂五志皆能动火乎！而矧以怒动肝气者，最易伤脾， \n脾伤者，不可以言火也，醉饱能动胃火，胃强者固自无恙，脾弱而致病者，不可以言火也。 \n房劳本动肾火，精去而阳亢者，可以火言，精去而气亦去者，不可以言火也。外如五志之伤， \n则无非伤气败阳之证，尚可谓之火乎。无火治火，则无有不败者矣。三卷中辨丹溪第二条下 \n仍有一论，当互阅之。 \n\n\n\n<目录>卷之十五性集·杂证谟\\火证\n\n<篇名>论火证（共三条）\n\n属性：火为热病，是固然矣。然火得其正，即为阳气，此火之不可无，亦不可衰。衰则阳气之 \n虚也。火失其正，是以邪热，此火之不可有，尤不可甚。甚则真阴伤败也。然阳以元气言。 \n火以病气言，故凡病在元气者，不得以火论。何也？盖人之元气止于充足，焉得有余？既非有 \n余，则何以言火？所谓无形者其化虚，即此是也。惟病在形体者，乃可以察火证，盖其不在 \n气即在血，所谓有形者其化实，即此是也。故凡火之为病，其在外者，必见于皮肉筋骨；其 \n在内者，必见于脏腑九窍。若于形质之间，本无热证可据，而曰此火也。此热也，则总属莫 \n须有之妄谈也。矧如火证悉具，而犹有虚实之殊，真假之异，其可不为详辨乎。若果有火病 \n，则火性急烈，诚可畏也。然实火止随形质，余因谓之凡火，又谓之邪火。火之为病，病之 \n标耳，洗之涤之，又何难哉。惟虚火之病，则本于元气，元气既虚，而再攻其火，非梃即刃 \n矣。是以诸病之杀人，而尤惟火病为最者，正以凡火未必杀人，而以虚作实，则无不杀之矣 \n，不忍见也。 \n一、凡五脏之火，肺热则鼻干，甚则鼻涕出。肝热则目眵浓。心热则言笑多。脾热则善 \n饥善渴。肾热则小水热痛。凡此之类，宜从清也。诸所不尽，详一卷寒热篇。 \n一、凡察火证，必须察其虚实。虽其元气本虚，然必虚中挟实者，乃为易治。何以见之 \n？如或大便干结，或善饥多食，或神气精明，或声音强壮，而脉见有力，此皆虚中有实也， \n俱可随证清解之。若或内外俱热，而反见溏泄，或饮食少进，或声微气短，诸虚皆见，而反 \n不利温补者。此其胃气已败，生意已穷，非吉兆也。 \n\n\n\n<目录>卷之十五性集·杂证谟\\火证\n\n<篇名>论治火（共五条）\n\n属性：治实火诸法∶凡微热之气，惟凉以和之，宜徙薪饮、四阴煎、二阴煎，或加减一阴煎、 \n黄芩芍药汤、黄芩清肺饮之类，酌宜用之。大热之气，必寒以除之，宜抽薪饮、白虎汤、太 \n清饮、黄连解毒汤、玉泉散、三补丸之类主之。火甚而兼胀满闭结实热者，宜凉膈散、八正 \n散、三黄丸、大金花丸之类主之。凡火盛虚烦干渴，或有热毒难解者，宜用绿豆饮，或悉尼 \n浆，间药朝夕饮之。退火解毒最速，且无所伤，诚妙法也。 \n一、郁热之火，宜散而解之。如外邪郁伏为热者，宜正柴胡饮、小柴胡饮，或升阳散火 \n汤之类主之。若郁热在经而为痈疽、为疮疹者，宜连翘归尾煎，或芍药蒺藜煎，或当归蒺藜 \n煎之类主之，或于本门求法治之。此皆火郁发之之谓也。 \n一、虚火之与假热，其气皆虚，本或相类，然阴阳偏胜亦有不同。如阴虚生热者，此水 \n不足以济火也，治当补阴，其火乃息，宜一阴煎、左归饮、左归丸、六味地黄丸之类主之。 \n此所谓壮水之主也。如寒极生热，而火不归原，即阴盛隔阳，假热证也。治宜温补血气，其 \n热自退。宜理阴煎、右归饮、理中汤、大补元煎、六味回阳饮之类主之。此所谓益火之源也 \n。又曰温能除大热也。凡假热之证，以肾阴大虚，则阳无所附而浮散于外，故反多外热，此 \n内真寒外假热也。若非峻补真阴，何以复其元气，元气不复，则必由散而尽矣。但外热既甚 \n，多见口疮舌裂，喉干咽痛，烦渴喜冷等证，而辛热温补之剂，难以入口，故薛立斋治韩州 \n同之劳热，以加减八味丸料一斤，内肉桂一两，煎五六碗，用水浸冰冷与服，此法最善。余 \n因效之，尝以崔氏八味丸料，或右归饮，用治阴虚假热，伤寒及劳热烦渴等证，服后顿退而 \n虚寒悉见，乃进温补，无不愈者。此真神妙法也。 \n一、实火宜泻，虚火宜补，固其法也。然虚中有实者，治宜以补为主，而不得不兼乎清 \n，如加减一阴煎、保阴煎、天王补心丹、丹溪补阴丸之类是也。若实中有虚者，治宜以清为 \n主，而酌兼乎补，如清化饮、徙薪饮、大补阴丸之类是也。凡此虚中之实，实中之虚，本无 \n限则，故不得谓热者必无虚，虚者必无热。但微虚者宜从微补，微热者宜从微清。若热倍于 \n虚，而清之不及，渐增无害也。若虚倍于热，而清之太过，则伐及元阳矣。凡治火者，不可 \n不知此义。 \n一、泻火诸药∶黄连、栀子泻心肝大肠之火。山栀仁降火从小便出，其性能屈下行。石 \n膏泻肠胃之火，阳明经有实热者，非此不可。黄芩清脾肺大肠之火。黄柏泻肝肾诸经之火。 \n知母清肺胃肝肾之火。地骨皮退阴中之火，善除骨蒸夜热。生地、麦冬清肝肺，凉血中之火 \n。天门冬泻肺与大肠之火。桑白皮、川贝母、土贝母解上焦肺胃之火。柴胡、干葛解肝脾诸 \n经之郁火。龙胆草泻肝肾膀胱之火。槐花清肝肾大肠之火，能解诸毒。芍药、石斛清脾胃之 \n火。滑石利小肠膀胱之火。天花粉清痰止渴，解上焦之火。连翘泻诸经之浮火。玄参清上焦 \n之浮火。山豆根解咽喉之火。胆星开心脾胃脘之痰火。青黛、芦荟、胡黄连泻五脏之疳热郁 \n火。苦参泻疳蚀之火。木通下行，泻小肠之火。泽泻、车前子利癃闭之火。人中白清肝脾肾 \n之阴火。童便降阴中血分之浮火。大黄、朴硝泻阳明诸经实热之火。人参、黄 、白术、甘 \n草除气虚气脱阳分散失之火。熟地黄、当归、枸杞、山茱萸滋心肾不交阴分无根之火。附子 \n、干姜、肉桂救元阳失位阴盛格阳之火。凡此治火之法，已若尽之，然亦不过言其筌蹄耳， \n而神而通之，原不可以笔楮尽也。 \n\n\n\n<目录>卷之十五性集·杂证谟\\火证\n\n<篇名>述古\n\n属性：启玄子曰∶病之微小者，犹人火也，遇草而 ，遇木而燔，可以湿伏，可以水折， \n故逆其性气以折之攻之。病之大甚者，犹龙火也，得湿而焰，得水而燔，不知其性，以水湿 \n折之，适足以光焰诣天，物穷方止；识其性者，反常之理，以火逐之，则燔灼自消，焰火扑 \n灭矣。 \n\n\n\n<目录>卷之十五性集·杂证谟\\火证\n\n<篇名>火证论列方\n\n属性：白虎汤（寒二） 抽薪饮（新寒三） 徙薪饮（新寒四） 玉泉散（新寒十五） 凉膈散（攻十 \n九） 清化饮（新因十三） 三补丸（寒一六二） 三黄丸（攻六八） 八正散（寒百十五） 绿豆 \n饮（新寒十四） 悉尼浆（新寒十六） 太清饮（新寒十三） 一阴煎（新补八） 保阴煎（新寒一） \n理中汤（热一） 理阴煎（新热三） 左归饮（新补二） 左归丸（新补四） 右归饮（新补三） \n大金花丸（攻五五） 大补元煎（新补一） 小柴胡汤（散十九） 正柴胡饮（新散六） 大补阴丸 \n（寒一五七） 六味地黄丸（补百二十） 加减八味丸（外三八） 六味回阳饮（新热二） 升阳散 \n火汤（散四一） 天王补心丹（补百八） 丹溪补阴丸（寒百六十） 黄连解毒汤（寒一） 连翘归 \n尾煎（新因三二） 芍药蒺藜煎（新因三五） 当归蒺藜煎（新因三四） \n\n\n\n<目录>卷之十五性集·杂证谟\\火证\n\n<篇名>论外备用方\n\n属性：凡寒阵所列古方新方俱可酌用。 \n神芎丸（攻七二） 清凉饮子（因百三） \n\n\n\n<目录>卷之十六理集·杂证谟\\虚损\n\n<篇名>经义\n\n属性：《上古天真论》曰∶今时之人，以酒为浆，以妄为常，醉以入房，以欲竭其精，以耗散 \n其真，不知持满，不时御神，务快其心，逆于生乐，起居无节，故半百而衰也。 \n《阴阳应象大论》曰∶年四十而阴气自半也，起居衰矣。 \n《宣明五气篇》曰∶久视伤血，久卧伤气，久坐伤肉，久立伤骨，久行伤筋。 \n《评热病论》曰∶邪之所凑，其气必虚。阴虚者，阳必凑之。 \n《本神篇》曰∶五脏主藏精者也，不可伤，伤则失守而阴虚，阴虚则无气，无气则死矣 \n。 \n《通评虚实论》曰∶邪气盛则实，精气夺则虚。 \n《经脉别论》曰∶勇者气行则已，怯者则着而为病。 \n《口问篇》曰∶邪之所在，皆为不足。故上气不足，脑为之不满，耳为之苦鸣，头为之 \n苦倾，目为之眩。中气不足，溲便为之变，肠为之苦鸣。下气不足，则乃为痿厥心 。 \n《逆调论》曰∶营气虚则不仁，卫气虚则不用，营卫俱虚，则不仁且不用，肉如故也， \n人身与志不相有，曰死。 \n《玉机真藏论》曰∶五虚死，五实死。帝曰∶愿闻五虚五实。岐伯曰∶脉盛，皮热，腹 \n胀，前后不通，闷瞀，此谓五实。脉细，皮寒，气少，泄利前后，饮食不入，此谓五虚。帝 \n曰∶其时有生者，何也？曰∶浆粥入胃，泄注止，则虚者活；身汗得后利，则实者活。此其 \n候也。 \n《脉要精微论》曰∶得守者生，失守者死。得强者生，失强者死。言而微，终日乃复言 \n者，此夺气也。 \n《海论》曰∶气海有余者，气满胸中， 息面赤；气海不足，则气少不足以言。血 \n海有余，则常想其身大，怫然不知其所病；血海不足，亦常想其身小，狭然不知其所病。水 \n谷之海有余，则腹满；水谷之海不足，则饥不受谷食。髓海有余，则轻劲多力，自过其度； \n髓海不足，则脑转耳鸣，胫酸眩冒，目无所见，懈怠安卧。 \n《卫气篇》曰∶下虚则厥，上虚则眩。 \n《本输篇》曰∶三焦者，并太阳之正，入络膀胱，约下焦，实则癃闭，虚则遗溺。 \n《五癃津液别篇》曰；阴阳不和，则使液溢而下流于阴，髓液皆减而下，下过度则虚， \n虚故腰背痛而胫酸。 \n《调经论》曰∶心藏神，神有余则笑不休，神不足则悲。肺藏气，气有余则喘咳上气， \n不足则息利少气。肝藏血，血有余则怒，不足则恐。脾藏肉，形有余则腹胀，泾瘦不利，不 \n足则四肢不用。肾藏志，志有余则腹胀飧泄，不足则厥。 \n《脉解篇》曰∶内夺而厥，则为喑俳，此肾虚也。 \n《决气篇》曰∶精脱者耳聋。气脱者目不明。津脱者，腠理开，汗大泄。液脱者，骨属 \n屈伸不利，色夭，脑髓消，胫酸，耳数鸣。血脱者，色白，夭然不泽。其脉空虚，此其 \n候也。 \n《奇病论》曰∶身热如炭，颈膺如格，人迎躁盛，喘息气逆，此有余也。有癃者，一日 \n数十溲，此不足也。太阴脉细微如发者，此不足也。今外得五有余，内得二不足，此其身不 \n表不里，亦正死明矣。 \n《五禁篇》帝曰∶何谓五夺？岐伯曰∶形肉已夺，是一夺也；大夺血之后，是二夺也 \n；大汗出之后，是三夺也；大泄之后，是四夺也；新产及大血之后，是五夺也。此皆不可写 \n。 \n《藏气法时论》曰∶肝虚则目KT KT 无所见，耳无所闻，善恐惧如人将捕之。心虚则胸腹 \n大，胁下与腰相引而痛。脾虚则腹满肠鸣，飧泄，食不化。肺虚则少气不能报息，耳聋嗌干 \n。肾虚则胸中痛，大腹小腹痛，清厥，意不乐。 \n《调经论》曰∶气之所并为血虚，血之所并为气虚。有者为实，无者为虚。故气并则无 \n血，血并则无气。今血与气相失，故为虚焉。血之与气并走于上，则为大厥，厥则暴死。气 \n复反则生，不反则死。帝曰∶阴之生实奈何？岐伯曰∶喜怒不节，则阴气上逆，上逆则下虚 \n，下虚则阳气走之，故曰实矣。帝曰∶阴之生虚奈何？曰∶喜则气下，悲则气消，消则脉虚 \n空，因寒饮食，寒气熏满，则血泣气去，故曰虚矣。阳虚则外寒，阴虚则内热。 \n《刺志论》曰∶气实形实，气虚形虚，此其常也，反此者病。谷盛气盛，谷虚气虚，此 \n其常也，反此者病。脉实血实，脉虚血虚，此其常也，反此者病。气虚身热，此谓反也。谷 \n入多而气少，此谓反也。谷不入而气多，此谓反也。脉盛血少，此谓反也。脉少血多，此谓 \n反也。夫实者，气入也，虚者，气出也。气实者，热也，气虚者，寒也。 \n《根结篇》曰∶形气不足，病气有余，是邪胜也，急泻之。形气有余，病气不足，急补 \n之。形气不足，病气不足，此阴阳俱不足也，不可刺之，刺之则重不足；重不足则阴阳俱竭 \n，血气皆尽，五脏空虚，筋骨髓枯，老者绝灭，壮者不复矣。形气有余，病气有余，此谓阴 \n阳俱有余也，急泻其邪，调其虚实。故曰∶有余者泻之，不足者补之，此之谓也。 \n《本神篇》曰∶故智者之养生也，必顺四时而适寒暑，和喜怒而安居处，节阴阳而调刚 \n柔，如是则僻邪不至，长生久视。 \n\n\n\n<目录>卷之十六理集·杂证谟\\虚损\n\n<篇名>论虚损病源（共十一条）\n\n属性：凡劳伤虚损，五脏各有所主，而惟心脏最多，且心为君主之官，一身生气所系，最不可 \n伤，而人多忽而不知也，何也？夫五脏之神皆禀于心，故忧生于心，肺必应之，忧之不已， \n而戚戚幽幽，则阳气日索，营卫日消，劳伤及肺，弗亡弗已。如经曰∶尝贵后贱，虽不中邪 \n，病从内生，名曰脱营。尝富后贫，名曰失精。五气留连，病有所并，暴乐暴苦，始乐后苦 \n，皆伤精气，精气竭绝，形体毁沮。故贵脱势，虽不中邪，精神内伤，身必败亡之类，无非 \n虑竭将来，追穷已往，而二阳并伤。第其潜消暗烁于冥冥之中，人所不觉，而不知五脏之伤 \n，惟心为本，凡值此者，速宜舒情知命，力挽先天。要知人生在世，喜一日则得一日，忧一 \n日则失一日，但使灵明常醒，尚何尘魔敢犯哉！及其既病，而用参、 、归、术、益气汤之 \n类，亦不过后天之末着耳，知者当知所先也。 \n一、喜因欲遂而发，若乎无伤，而经曰∶喜伤心。又曰∶暴喜伤阳。又曰∶喜乐者，神 \n惮散而不藏。又曰∶肺喜乐无极则伤魄，魄伤则狂，狂者意不存人，皮革焦，毛悴色夭，死 \n于夏。盖心藏神，肺藏气，二阳脏也。故暴喜过甚则伤阳，而神气因以耗散。或纵喜无节， \n则淫荡流亡，以致精神疲竭，不可救药。或偶尔得志，则气盈载满，每多骄恣傲慢，自取败 \n亡，而莫知其然者多矣。然则喜为人所忽，而犹有不可忽者如此。 \n一、思本乎心。经曰∶心怵惕思虑则伤神，神伤则恐惧自失，破 脱肉，毛悴色夭 \n，死于冬。此伤心则然也。然思生于心，脾必应之，故思之不已，则劳伤在脾。经曰∶思伤 \n脾。又曰∶思则心有所存，神有所归，正气留而不行，故气结矣。凡此为病，脾气结则为噎 \n膈，为呕吐，而饮食不能运，食不运则血气日消，肌肉日削，精神日减，四肢不为用，而生 \n胀满泄泻等证，此伤心脾之阳也。夫人孰无思？而苦思难释，则劳伤至此，此养生者所当戒 \n也。然思本伤脾，而忧亦伤脾。经曰∶脾愁忧而不解则伤意，意伤则 乱，四肢不举， \n毛悴色夭，死于春。盖人之忧思，本多兼用，而心脾肺所以并伤，故致损上焦阳气。而二阳 \n之病发自心脾，以渐成虚劳之证者，断由乎此。 \n一、淫欲邪思又与忧思不同，而损惟在肾。盖心耽欲念，肾必应之，凡君火动于上，则 \n相火应于下。夫相火者，水中之火也，静而守位则为阳气，炽而无制则为龙雷，而涸泽燎原 \n，无所不至。故其在肾，则为遗淋带浊，而水液渐以干枯。炎上入肝，则逼血妄行，而为吐 \n为衄，或为营虚筋骨疼痛。又上入脾，则脾阴受伤，或为发热，而饮食悉化痰涎。再上至肺 \n，则皮毛无以扃固，而亡阳喘嗽，甚至喑哑声嘶。是皆无根虚火，阳不守舍，而光焰诣天， \n自下而上，由肾而肺，本源渐槁，上实下虚，是诚剥极之象也。凡师尼室女，失偶之辈，虽 \n非房室之劳，而私情系恋，思想无穷，或对面千里，所愿不得，则欲火摇心，真阴日削，遂 \n致虚损不救。凡五劳之中，莫此为甚，苟知重命，慎毋蹈之。 \n一、七情伤肾，恐亦居多。盖恐畏在心，肾则受之，故经曰∶恐伤肾。又曰∶恐则精却 \n。又曰∶恐惧而不解则伤精，精伤则骨酸痿厥，精时自下。余尝诊一在官少年，因恐而致 \n病，病稍愈而阳痿，及其病复，终不可疗。又尝见猝恐者，必阴缩或遗尿，是皆伤肾之征也 \n。然恐固伤肾，而怒亦伤肾。经曰∶肾盛怒而不止则伤志，志伤则喜忘其前言，腰背不可以 \n俯仰屈伸，毛悴色夭，死于季夏。是知盛怒不惟伤肝，而肾亦受其害也。 \n一、怒生于心，肝必应之，怒不知节，则劳伤在肝。经曰∶怒伤肝。又曰∶怒则气逆， \n甚则呕血及飧泄，故气上矣。盖肝为阴中之阳脏，故肝之为病，有在阴者，有在阳者。如火 \n因怒动而逼血妄行，以致气逆于上，而胀痛、喘急者，此伤其阴者也。又或气以怒伤，而木 \n郁无伸，以致侵脾气陷，而为呕为胀，为泄为痛，为食饮不行者，此伤其阳者也。然随怒随 \n消者，未必致病，脏气坚固者，未必致病，惟先天禀弱，而三阴易损者，使不知节，则东方 \n之实，多致西方之败也。然怒本伤肝，而悲哀亦最易伤肝。经曰∶肝悲哀动中则伤魂，魂伤 \n则狂妄不精，不精则不正，当人阴缩而挛筋，两胁骨不举，毛悴色夭，死于秋。盖怒盛伤肝 \n，肝气实也；悲哀伤肝，肝气虚也。但实不终实，而虚则终虚耳，虚而罔顾，则必至劳损 \n。而治当察其邪正也。 \n一、惊气本以入心，而实通于肝胆。经曰∶惊则心无所根据，神无所归，虑无所定，故气 \n乱矣。又曰∶东方色青，入通于肝，其病发惊骇。此所以惊能动心，而尤能伤及肝胆。心为 \n君主，固不可伤，而胆以中正之官，实少阳生气所居，故十一脏阳刚之气皆取决于胆，若或 \n损之，则诸脏生气，因皆消索致败，其危立见。尝见微惊致病者，惟养心安神，神复则病自 \n却。若惊畏日积，或一时大惊损胆，或致胆汁泄而通身发黄，默默无言者，皆不可救。（胆 \n黄证，论详黄胆门） \n一、色欲过度者，多成劳损。盖人自有生以后，惟赖后天精气以为立命之本，故精强神 \n亦强，神强必多寿；精虚气亦虚，气虚必多夭。其有先天所禀原不甚浓者，但知自珍，而培 \n以后天，则无不获寿。设禀赋本薄，而且恣情纵欲，再伐后天，则必成虚损，此而伤生，咎 \n将谁委？又有年将未冠，壬水方生，保养萌芽，正在此日，而无知孺子，遽摇女精。余见苞 \n萼未成而蜉蝣旦暮者多矣，良可悲也。此其责水在孺子，而在父师，使不先有明诲，俾知保 \n生之道，则彼以童心，岂识利害？而徒临期恳祷，号呼悲戚，将何济于事哉。 \n一、劳倦罔顾者，多成劳损。夫劳之于人，孰能免之，如奔走食力之夫，终日营营，而 \n未闻其劳者，岂非劳乎？但劳有不同耳。盖贫贱之劳，作息有度，无关荣辱，习以为常，何 \n病之有？惟安闲柔脆之辈，而苦竭心力，斯为害矣。故或劳于名利，而不知寒暑之伤形；或 \n劳于色欲，而不知旦暮之疲困；或劳于游荡，而忍饥竭力于呼卢驰骤之场；或劳于疾病，而 \n剥削伤残于无术庸医之手，或为诗书困厄，每缘萤雪成灾；或以好勇逞强，遂致绝筋乏力。 \n总之，不知自量，而务从勉强，则一应妄作妄为，皆能致损。凡劳倦之伤，虽曰在脾，而若 \n此诸劳不同，则凡伤筋伤骨，伤气伤血，伤精伤神，伤皮毛肌肉，则实兼之五脏矣。呜呼！ \n嗜欲迷人，其害至此。此其故，则在但知有彼，而忘其有我耳。广成子曰∶无劳女形，无摇 \n女精，乃可以长生。若此二言者，人因其简，故多易之，而不知养生之道，于此八字而尽之 \n矣，顾可以忽之也耶！ \n一、少年纵酒者多成劳损。夫酒本狂药，大损真阴，惟少饮之未必无益，多饮之难免无 \n伤，而耽饮之，则受其害者十之八九矣。且凡人之禀赋，脏有阴阳，而酒之性质，亦有阴阳 \n。盖酒成于酿，其性则热，汁化于水，其质则寒。若以阴虚者纵饮之，则质不足以滋阴，而 \n性偏动火，故热者愈热，而病为吐血、衄血、便血、尿血、喘嗽、躁烦、狂悖等证，此酒性 \n伤阴而然也。若阳虚者纵饮之，则性不足以扶阳，而质留为水，故寒者愈寒，而病为臌胀、 \n泄泻、腹痛、吞酸、少食、亡阳、暴脱等证，此酒质伤阳而然也。故纵酒者，既能伤阴，尤 \n能伤阳，害有如此，人果知否？矧酒能乱性，每致因酒妄为，则凡伤精竭力，动气失机，及 \n遇病不胜等事，无所不至，而阴受其损，多罔觉也。夫纵酒之时，固不虑其害之若此，及病 \n至沉危，犹不知为酒困之若此。故余详明于此，以为纵酒者之先觉云。（泄泻、肿胀二门俱 \n有酒论。） \n一、疾病误治及失于调理者，病后多成虚损。盖病有虚实，治有补泻，必补泻得宜，斯 \n为上工。余见世俗之医，固不知神理为何物，而且并邪正缓急，俱不知之，故每致伐人元气 \n，败人生机。而随药随毙者，已无从诉，其有幸而得免，而受其残剥，以致病后多成虚损而 \n不能复振者，此何以故也？故凡医有未明，万毋轻率，是诚仁人积德之一端也。至若失于调 \n治，致不能起，则俗云∶小孔不补，大孔叫冤，苦亦自作之而自受之耳，又何尤焉。 \n\n\n\n<目录>卷之十六理集·杂证谟\\虚损\n\n<篇名>论证（共四条）\n\n属性：凡虚损之由，具道如前，无非酒色、劳倦、七情、饮食所致。故或先伤其气，气伤必及 \n于精；或先伤其精，精伤必及于气。但精气在人，无非谓之阴分。盖阴为天一之根，形质之 \n祖，故凡损在形质者，总曰阴虚，此大目也。若分而言之，则有阴中之阴虚者，其病为发热 \n躁烦，头红面赤，唇干舌燥，咽痛口疮，吐血衄血，便血尿血，大便燥结，小水痛涩等证； \n有阴中之阳虚者，其病为怯寒憔悴，气短神疲，头运目眩，呕恶食少，腹痛飧泄，二便不禁 \n等证，甚至咳嗽吐痰，遗精盗汗，气喘声喑，筋骨疼痛，心神恍惚，肌肉尽削，梦与鬼交， \n妇人月闭等证，则无论阴阳，凡病至极，皆所必至，总由真阴之败耳。 \n然真阴所居，惟肾为主。盖肾为精血之海，而人之生气，即同天地之阳气，无非自下而 \n上，所以肾为五脏之本。故肾水亏，则肝失所滋而血燥生；肾水亏，则水不归源而脾痰起； \n肾水亏，则心肾不交而神色败；肾水亏，则盗伤肺气而喘嗽频；肾水亏，则孤阳无主而虚火 \n炽。凡劳伤等证，使非伤入根本，何以危笃至此？故凡病甚于上者，必其竭甚于下也。余故 \n曰∶虚邪之至，害必归阴；五脏之伤，穷必及肾，穷而至此，吾末如之何也矣。夫所贵乎君 \n子者，亦贵其知微而已。 \n一、凡损伤元气者，本皆虚证，而古方以虚损劳瘵各分门类，则病若有异，亦所宜辨。 \n盖虚损之谓，或有发见于一证，或有困惫于临时，凡在经在脏，但伤元气，则无非虚损病也 \n。至若劳瘵之有不同者，则或以骨蒸，或以干嗽，甚至吐血吐痰，营卫俱败， 羸日甚，此 \n其积渐有日，本末俱竭而然。但虚损之虚，有在阴分，有在阳分，然病在未深，多宜温补； \n若劳瘵之虚，深在阴中之阴分，多有不宜温补者。然凡治虚证，宜温补者，病多易治，不宜 \n温补者，病多难治。此虚劳若乎有异，而不知劳瘵之损，即损之深而虚之甚者耳。凡虚损不 \n愈，则日甚成劳矣，有不可不慎也。 \n一、虚损两颧红赤或唇红者，阴虚于下，逼阳于上也。仲景曰∶其面戴阳者，下虚故也 \n。虚而多渴者，肾水不足，引水自救也。喑唾声不出者，由肾气之竭。盖声出于喉，而根于 \n肾。经曰∶内夺而厥，则为喑俳，此肾虚也。虚而喘急者，阴虚肺格，气无所归也。喉干咽 \n痛者，真水下亏，虚火上浮也。不眠恍惚者，血不养心，神不能藏也。时多烦躁者，阳中无 \n阴，柔不济刚也。易生嗔怒，或筋急酸痛者，水亏木燥，肝失所资也。饮食不甘，肌肉 \n渐削者，脾元失守，化机日败也。心下跳动，怔忡不宁者，气不归精也。经曰∶胃之大络， \n名曰虚里，出于左乳下，其动应衣，宗气泄也。盗汗不止者，有火则阴不能守，无火则阳不 \n能固也。虚而多痰，或如清水，或多白沫者，此水泛为痰，脾虚不能制水也。骨痛如折者， \n肾主骨，真阴败竭也。腰胁痛者，肝肾虚也。膝以下冷者，命门衰绝，火不归源也。小水黄 \n涩淋沥者，真阴亏竭，气不化水也。足心如烙者，虚火烁阴，涌泉涸竭也。 \n一、凡阳虚之人，因气虚也。阳气既虚，即不能嚏。仲景曰∶欲嚏不能，此人肚中寒。 \n故凡以阳虚之证，而忽见嚏者，便有回生之兆。 \n\n\n\n<目录>卷之十六理集·杂证谟\\虚损\n\n<篇名>论脉（共三条）\n\n属性：虚损之脉，凡甚急、甚数、甚细、甚弱、甚涩、甚滑、甚短、甚长、甚浮、甚沉、甚弦 \n、甚紧、甚洪、甚实者，皆劳伤之脉。然无论浮沉大小，但渐缓则渐有生意。若弦甚者病必 \n甚，数甚者病必危，若以弦细而再加紧数，则百无一生矣。 \n《要略》曰∶脉芤者为血虚，沉迟而小者为脱气。大而无力为阳虚，数而无力为阴虚。 \n脉大而芤者为脱血。平人脉大为劳。虚极亦为劳。脉微细者盗汗。寸弱而软为上虚。尺弱软 \n涩为下虚。尺软滑疾为血虚。两关沉细为胃虚。 \n《脉经》曰∶脉来软者为虚，缓者为虚。微弱者为虚。弦者为中虚。细而弱小者，气血 \n俱虚。 \n\n\n\n<目录>卷之十六理集·杂证谟\\虚损\n\n<篇名>辨爪\n\n属性：凡劳损之病，本属阴虚，阴虚必血少。而指爪为精血之余，故凡于诊候之际，但见其指 \n爪干黄，觉有枯槁之色，则其发肤营气，具在吾目中矣。此于脉色之外，便可知其有虚损之 \n候，而损之微甚，亦可因之以辨也。 \n\n\n\n<目录>卷之十六理集·杂证谟\\虚损\n\n<篇名>论治（共七条）\n\n属性：病之虚损，变态不同。因有五劳七伤，证有营卫脏腑，然总之则人赖以生者，惟此精气 \n，而病为虚损者，亦惟此精气。气虚者，即阳虚也；精虚者，即阴虚也。凡病有火盛水亏， \n而见营卫燥津液枯者，即阴虚之证也；有水盛火亏，而见脏腑寒脾肾败者，即阳虚之证也。 \n此惟阴阳偏困所以致然。凡治此者，但当培其不足，不可伐其有余。夫既缘虚损，而再去所 \n余，则两败俱伤矣，岂不殆哉！惟是阴阳之辨，犹有不易，谓其阴阳之中，复有阴阳，其有 \n似阳非阳，似阴非阴者，使非确有真见，最易惑人，此不可不详察也。且复有阴阳俱虚者， \n则阳为有生之本，而所重者，又单在阳气耳。知乎此，则虚损之治，如指诸掌矣。 \n一、阳虚者多寒，非谓外来之寒，但阳气不足，则寒生于中也，若待既寒，则阳已败矣 \n。而不知病见虚弱，而别无热证者，便是阳虚之候，即当温补元气，使阳气渐回，则真元自 \n复矣。盖阳虚之候，多得之愁忧思虑以伤神，或劳役不节以伤力，或色欲过度而气随精去， \n或素禀元阳不足而寒凉致伤等，病皆阳气受损之所由也。欲补阳气，惟辛甘温燥之剂为宜， \n万勿兼清凉寒滑之品，以残此发生之气，如生地、芍药、天麦门冬、沙参之属，皆非所宜， \n而石斛、玄参、知、柏、芩、连、龟胶之类，则又切不可用。若气血俱虚者，宜大补元煎， \n或八珍汤，或十全大补汤。五脏俱虚，宜平补者，五福饮。命门阴分不足者，左归饮、左归 \n丸。命门阳分不足者，右归饮、右归丸。气分虚寒者，六气煎。脾肾阴分虚寒，诸变不一者 \n，理阴煎。三焦阳气大虚者，六味回阳饮。气虚脾寒者，一气丹。胃气虚寒者，温胃饮、理 \n中汤。血虚寒滞者，五物煎。 \n一、阴虚者多热，以水不济火而阴虚生热也。此病多得于酒色嗜欲，或愤怒邪思，流荡 \n狂劳，以动五脏之火，而先天元阴不足者，尤多此病。凡患虚损而多热多燥，不宜热食者， \n便是阴虚之候。欲滋其阴，惟宜甘凉醇静之物。凡阴中有火者，大忌辛温，如干姜、桂、附 \n、破故纸、白术、苍术、半夏之属，皆不可轻用；即如人参、黄 、枸杞、当归、杜仲之类 \n，是皆阴中有阳，亦当酌宜而用之，盖恐阳旺则阴愈消，热增则水益涸耳。然阴虚者，因其 \n水亏，而水亏者，又忌寒凉，盖苦劣之流，断非资补之物。其有火盛之甚，不得不从清凉者 \n，亦当兼壮水之剂，相机间用，而可止即止，以防其败，斯得滋补之大法。诸治如下∶ \n一、虚损夜热，或午后发热，或喜冷便实者，此皆阴虚生热，水不制火也，宜加减一阴 \n煎。若火在心肾，而惊悸失志者，宜二阴煎。若外热不已，而内不甚热，则但宜补阴，不可 \n清火，宜一阴煎，或六味地黄汤。其有元气不足，而虚热不已者，必用大补元煎，庶乎久之 \n自愈。寒热门论治尤详，所当参阅。 \n一、虚损咳嗽，虽五脏皆有所病，然专主则在肺肾。盖肺为金脏，金之所畏者，火也， \n金之化邪者，燥也，燥则必痒，痒则必嗽，正以肾水不能制火，所以克金，阴精不能化气， \n所以病燥，故为咳嗽、喘促、咽痛、喉疮、声哑等证。凡治此者，只宜甘凉至静之剂，滋养 \n金水，使肺肾相生，不受火制，则真阴渐复，而嗽可渐愈。火盛者，宜四阴煎加减主之。火 \n微者，宜一阴煎，六味地黄汤，或左归饮。兼受风寒而嗽者，宜金水六君煎。贝母丸治嗽最 \n佳。 \n一、虚损吐血者，伤其阴也，故或吐或衄，所不能免，但当察其有火无火，及火之微甚 \n而治之。凡火之盛者，以火载血上，而脉证之间自有热证可辨。急则治标，此不得不暂用芩 \n、连、栀、柏、竹叶、童便之属，或单以抽薪饮、徙薪饮之类主之。若阴虚而兼微火者，宜 \n保阴煎，或清化饮，或加减一阴煎主之。血止即当养血，不宜过用寒凉也。若无实火而全属 \n伤阴，则阴虚水亏，血由伤动而为吐为衄者，此宜甘纯养阴之品，以静制动，以和治伤，使 \n阴气安静得养，则血自归经。宜一阴煎，六味地黄汤，或小营煎之类主之。若阴虚连肺而兼 \n嗽兼血者，宜四阴煎加减主之。若因劳役，别无火证，心脾肾三阴受伤而动血者，宜五阴煎 \n、五福饮、六味地黄丸之类主之。若阴虚于下，格阳于上，六脉无根而大吐大衄者，此火不 \n归源，真阳失守而然，宜右归饮加减主之，或八味地黄汤亦可。此惟思虑劳倦过伤者，多有 \n此证。若因劳倦而素易呕泻，多有脾不摄血，而为吐血下血者，宜六味回阳饮大加白术主之 \n，万不可用凉药。若大吐大衄，而六脉细脱，手足厥冷，危在倾刻，而血犹不止者，速宜用 \n镇阴煎，其血自止。若血脱至甚，气亦随之，因至厥逆昏愦者，速当益气以固生机，宜六味 \n回阳饮，或四味四阳饮主之，若再用寒凉即死。总之，失血吐血，必其阴分大伤，使非加意 \n元气，培养真阴，而或专用寒凉，则其阴气愈损，血虽得止，而病必日败矣。 \n一、虚损伤阴，本由五脏，虽五脏各有所主，然五脏证治，有可分者，有不可分者。如 \n诸气之损，其治在肺；神明之损，其治在心；饮食肌肉之损，其治在脾；诸血筋膜之损，其 \n治在肝；精髓之损，其治在肾，此其可分者也。然气主于肺，而化于精；神主于心，而化于 \n气；肌肉主于脾，而土生于火；诸血藏于肝，而血化于脾胃；精髓主于肾，而受之于五脏， \n此其不可分者也。及乎既甚，则标本相传，连及脏腑，此又方之不可执言也。故凡补虚之法 \n，但当明其阴阳升降，寒热温凉之性，精中有气，气中有精之因。且凡上焦阳气不足者，必 \n下陷于肾也，当取之至阴之下。下焦真阴不足者，多飞越于上也，可不引之归源乎？所以治 \n必求本，方为尽善。然余用补之法，则悉在新方八略、八阵中，惟细察之可得其概。其有诸 \n证未备者，如遗精、梦泄、声哑、盗汗，及妇人血枯经断等证，但于各门求之，则无不俱有 \n照应。 \n\n\n\n<目录>卷之十六理集·杂证谟\\虚损\n\n<篇名>辨似损非损\n\n属性：凡似损非损之证，惟外感寒邪者乃有之。盖以外邪初感，不为解散而误作内伤，或用清 \n凉，或用消导，以致寒邪郁伏，久留不散，而为寒热往来，或为潮热咳嗽，其证则全似劳损 \n。若用治损之法以治此证，则滋阴等剂愈以留邪，热蒸既久，非损成损矣，余尝治愈数人， \n皆其证也。欲辨此者，但当详察表里，而审其致病之由。盖虚损之证，必有所因，而外感之 \n邪，其来则骤。若或身有疼痛，而微汗则热退，无汗则复热，或见大声咳嗽，脉虽弦紧而不 \n甚数，或兼和缓等证，则虽病至一两月，而邪有不解，病终不退者，本非劳损，毋误治也。 \n若寒热往来不止者，宜一二三四五柴胡饮酌宜用之，或正柴胡饮亦可。若兼咳嗽者，柴陈煎 \n。若脾肾气虚而兼咳嗽者，金水六君煎，或邪有未解而兼寒热者，仍加柴胡。 \n\n\n\n<目录>卷之十六理集·杂证谟\\虚损\n\n<篇名>虚损危候\n\n属性：凡虚损既成，不补将何以复？而有不能服人参、熟地及诸补之药者，此为虚不受补，何 \n以望生。若劳损吐血失血之后，嗽不能止，而痰多甚者，此以脾肺虚极，饮食无能化血，而 \n随食成痰，此虽非血，而实血之类也。经曰∶白血出者，死。故凡痰之最多最浊者，不可治 \n。一、左右者，阴阳之道路，其有不得左右眠而认边难转者，此其阴阳之气有所偏竭而然， \n多不可治。一、凡病虚损者，原无外邪，所以病虽至困，终不愦乱。其有患虚证别无邪热， \n而谵妄失伦者，此心脏之败，神去之兆也，必死。一、劳嗽、喑哑声不能出，或喘急气促者 \n，此肺脏之败也，必死。一、劳损肌肉脱尽者，此脾脏之败也，必死。一、筋为疲极之本 \n，凡病虚损者，多有筋骨疼痛。若痛有至极不可忍者，乃血竭不能荣筋，此肝脏之败也，必 \n死。一、劳损既久，再及大便，泄泻不能禁止者，此肾脏之败也，必死。 \n\n\n\n<目录>卷之十六理集·杂证谟\\虚损\n\n<篇名>述古（共四条）\n\n属性：《难经》曰∶损脉之为病奈何？然∶一损损于皮毛，皮聚而毛落。二损损于血脉，血脉 \n虚少，不能荣于五脏六腑。三损损于肌肉，肌肉消瘦，饮食不能为肌肤。四损损于筋，筋缓 \n不能自收持。五损损于骨，骨痿不能起于床。反此者，至脉之病也。从上下者，骨痿不能起 \n于床者死；从下上者，皮聚而毛落者死。治损之法∶损其肺者，益其气。损其心者，调 \n其营卫。损其脾者，调其饮食，适其寒温。损其肝者，缓其中。损其肾者，益其精，此治损 \n之法也。不能治其虚，安问其余？故曰∶实实虚虚，损不足而益有余，此中工之所害也。 \n（宾）按此上损下损之说，其义极精，然有未尽者，犹宜悉也。盖凡思虑劳倦外感等证 \n则伤阳，伤于阳者，病必自上而下也；色欲醉饱内伤等证则伤阴，伤于阴者，病必自下而上 \n也。如经曰∶二阳之病发心脾，有不得隐曲，女子不月之类，此即自上而下者也。又经曰∶ \n五脏主藏精者也，不可伤，伤则失守而阴虚，阴虚则无气，无气则死矣，此即自下而上者也 \n。盖自上而下者，先伤乎气。故一损损于肺，则病在声息肤腠。二损损于心，则病在血脉颜 \n色。三损损于胃，则病在饮食不调。四损损于肝，则病为螈 疼痛。五损损于肾，则病为骨 \n痿、二便不禁。此先伤于阳，而后及乎阴，阳竭于下，则孤阴无以独存，不可为也。自下而 \n上者，先伤乎精。故一损损于肾，则病为泉源干涸。二损损于肝，则病为血动筋枯。三损损 \n于脾，则病为痰涎壅盛。四损损于心，则病为神魂失守。五损损于肺，则病为喘急短气。此 \n先伤乎阴，而后及乎阳，阴竭于上，则孤阳无以独生，不可为也。故曰∶心肺损而神衰，肝 \n肾虚而形敝，脾胃损而食饮不归血气。凡明哲之士，则当察所由，而预防其渐，又何虚损之 \n可虑？若待源流俱竭，而后归罪于药之不效，医之不良，此其愚也亦甚矣。 \n《巢氏病源》曰∶夫虚劳者，五劳七伤六极是也。一曰志劳，二曰思劳，三曰心劳，四 \n曰忧劳，五曰瘦劳。又有肺劳者，短气而面浮，鼻不闻香臭。肝劳者，面目干黑，口苦，精 \n神不守，恐畏不能独卧，目视不明。心劳者，忽忽喜忘，大便苦难，或时鸭溏，口内生疮。 \n脾劳者，舌本苦直，不得咽唾。肾劳者，背难以俯仰，小便不利，色赤黄而有余沥，茎内痛 \n，阴囊湿生疮，小腹满急。六极者，一曰气极，令人内虚，五脏不足，邪气多，正气少，不 \n欲言。二曰血极，令人无颜色，眉发落，忽忽喜忘。三曰筋极，令人数转筋，十指爪甲皆 \n痛，苦倦不能久立。四曰骨极，令人酸削，齿苦痛，手足烦疼，不可以立，不欲行动。 \n五曰肌极，令人羸瘦无润泽，饮食不生肌肉。六曰精极，令人少气，吸吸然内虚， \n五脏不足，发毛落，悲伤喜忘。 \n七伤者∶一曰大饱伤脾，脾伤善噫，欲卧，面黄。二曰大怒逆气伤肝，肝伤少气，目暗。 \n三曰强力举重，久坐湿地伤肾，肾伤少精，腰背痛，厥逆下冷。四曰形寒寒饮伤肺，肺伤少 \n气，咳嗽，鼻鸣。五曰忧愁思虑伤心，心伤苦惊，喜忘喜怒。六曰风雨寒暑伤形，形伤发肤 \n枯夭。七曰大恐惧不节伤志，志伤恍惚不乐。又曰∶七伤者，一曰阴寒，二曰阴痿，三曰里 \n急，四曰精寒，五曰精少，阴下湿，六曰精清，七曰小便苦数，临事不举。 \n王节斋曰∶人若色欲过度，伤损精血，必生阴虚火动之病。睡中盗汗，午后发热，咯咯 \n咳嗽，倦怠无力，饮食少进，甚则痰涎带血，或咳血，吐血，衄血，身热脉沉数，肌肉消瘦 \n，此名劳瘵，最为难治，轻者用药数十服，重者期以岁年。然必须病患惜命，坚心定志，绝 \n房室，息妄想，戒恼怒，节饮食，以自培其根，此谓内外交治，庶可保全。 \n薛立斋曰∶劳瘵之证，大抵属足三阴亏损，虚热无火之证，故昼发夜止，夜发昼止，不 \n时而作。当用六味地黄丸为主，以补中益气汤调补脾胃。若脾胃先损者，当以补中益气汤为 \n主，以六味地黄温存肝肾，多有得生者。若误用黄柏、知母之类，则复伤脾胃，饮食日少， \n诸脏愈虚，元气下陷，腹痞作泻，则不可救矣。夫衄血吐血之类，因虚火妄动，血随火而泛 \n行，或阳气虚，不能摄血归经而妄行，其脉弦洪，乃无根之火浮于外也。大抵此证多因火土 \n太旺，金水衰涸之际，不行保养，及三冬火气潜藏，不远帏幕，戕贼真元，故至春 \n末夏初，患头疼脚软，食少体热，而为注夏之病。或少有老态，不耐寒暑，不胜劳役，四时 \n迭病，此因气血方长而劳心亏损，精血未满而早为斫丧，故其见证难以名状。若左尺脉 \n虚弱或细数，是左肾之真阴不足也，用六味丸。右尺脉迟软，或沉细而数欲绝，是命门之相 \n火不足也，用八味丸。至于两尺微弱，是阴阳俱虚也，用十补丸。此皆滋其化源也，仍须 \n参前后发热、咳嗽诸证治之。 \n\n\n\n<目录>卷之十六理集·杂证谟\\虚损\n\n<篇名>附按\n\n属性：立斋治韩州同色欲过度，烦热作渴，饮水不绝，小便淋沥，大便闭结，唾痰如涌，面目 \n俱赤，满舌生刺，唇裂身热，或身如芒刺而无定处，两足心如烙，左三部脉洪而无伦，此肾 \n阴虚，阳无所附而发于外。盖大热而甚，寒之不寒，是无水也，当峻补其阴。遂以加减八味 \n丸料一斤，用肉桂一两，以水顿煎六碗，冰冷与服，半饷熟睡，至晚又温饮一碗，诸证悉退 \n。翼日，畏寒足冷诸证仍至，是无火也，当补其阳，急与八味丸四剂，诸证俱退。 \n又治府庠王以道元气素弱，复以科场岁考，积劳致疾。至十二月，病大作，大热，泪出 \n随凝，目赤露胸，气息沉沉欲绝，脉洪大鼓指，按之如无，舌干如刺，此内真寒而外假热也 \n。遂先服十全大补汤。余曰∶服此药，其脉当收敛为善。少顷，熟睡，觉而恶寒增衣，脉顿 \n微细如丝，此虚寒之真象也。余以人参一两，加熟附三钱，水煎顿服而安。夜间脉复脱，乃 \n以参二两，熟附五钱仍愈。后以大剂参、术、归身、灸甘草等药调理而愈。 \n又治一童子，年十四岁，发热吐血，余谓宜补中益气以滋化源，不信，乃用寒凉降火， \n前证愈甚。或谓曰∶童子未室，何肾虚之有？参术补气，奚为用之？余述丹溪先生曰∶肾主闭 \n藏，肝主疏泄，二脏俱有相火，而其系上属于心。心为君火，为物所感，则相火翕然而起， \n虽不交会，而精已暗耗矣。又褚氏《精血篇》曰∶男子精未满而御女以通其精，则五脏有不 \n满之处，异日有难状之疾，正此谓也。遂用补中益气汤及地黄丸而痊。 \n\n\n\n<目录>卷之十六理集·杂证谟\\虚损\n\n<篇名>虚损论列方\n\n属性：大补元煎（新补一） 五福饮（新补六） 十全大补汤（补二十） 左归饮（新补二） 左归丸 \n（新补四） 补中益气汤（补三十） 右归饮（新补三） 右归丸（新补五） 四味回阳饮（新热一） \n一阴煎（新补八） 二阴煎（新补十） 六味回阳饮（新热二） 四阴煎（新补十二） 五阴煎（ \n新补十三） 六味地黄汤（补百二十） 理中汤（热一） 理阴煎（新热三） 八味地黄汤（补一二 \n一） 五物煎（新因三） 六气煎（新因二一） 加减八味丸（补一二二） 温胃饮（新热五） 小 \n营煎（新补十五） 金水六君煎（新和一） 镇阴煎（新热十三） 保阴煎（新寒一） 加减一阴煎 \n（新补九） 一气丹（新补二二） 十补丸（热一七三） 八珍汤（补十九） 抽薪饮（新寒三） 徙 \n薪饮（新寒四） 柴陈煎（新散九） 贝母丸（新和十八） 正柴胡饮（新散六） 诸柴胡饮（新散 \n一、二、三、四、五） \n\n\n\n<目录>卷之十六理集·杂证谟\\虚损\n\n<篇名>论外备用方\n\n属性：附子理中汤（热二 阳虚） 安肾丸（热一六七 下元虚冷） 小安肾丸（热一六七 下元 \n虚冷） 黑锡丹（热一八九 下元阳虚） 黄 鳖甲煎（寒九十 虚劳烦热） 大菟丝子丸（固三 \n六） 鳖甲地黄汤（寒八九 虚劳烦热） 地黄膏（寒九一 滋阴退热） 人参平肺汤（因一八七 \n肾虚声哑） 退热汤（寒九三 急劳大热） 加味虎潜丸（寒一六四 补虚滋阴） 人参五味 \n子汤（外一五三） 劫劳散（妇一二四） 三才封髓丹（寒一六六 滋阴降火方） 麦门冬汤（寒 \n四五 气热血焦） 大补地黄丸（寒一五九 精枯血热） \n凡补阵所载古方新方俱宜酌用。 \n\n\n\n<目录>卷之十六理集·杂证谟\\劳倦内伤\n\n<篇名>经义\n\n属性：《调经论》帝曰∶阴虚生内热奈何？岐伯曰∶有所劳倦，形气衰少，谷气不盛，上焦 \n不行，下脘不通，胃气热，热气熏胸中，故内热。夫邪之生也，或生于阴，或生于阳。其生 \n于阳者，得之风雨寒暑；其生于阴者，得之饮食居处，阴阳喜怒。 \n《太阴阳明论》曰∶故犯贼风虚邪者，阳受之；饮食不节，起居不时者，阴受之。阳受 \n之则入六腑，阴受之则入五脏。入六腑则身热不时卧，上为喘呼；入五脏，则 满闭塞 \n，下为飧泄，久为肠 。 \n《举痛论》曰∶劳则气耗。劳则喘息汗出，外内皆越，故气耗矣。 \n《痹论》曰∶阴气者，静则神藏，躁则消亡。饮食自倍，肠胃乃伤。 \n《本病论》曰∶饮食劳倦即伤脾。 \n\n\n\n<目录>卷之十六理集·杂证谟\\劳倦内伤\n\n<篇名>论证（共五条）\n\n属性：劳倦一证，即东垣所谓内伤证也。凡疾病在人，有不因外感而受病于内者，则无非内伤 \n。而东垣乃独以饮食失节，劳役不足之病为内伤，其故何也？盖外感内伤，俱有恶寒发热等 \n证，外感寒热者，即伤寒也；内伤寒热者，即劳倦也。伤寒以外邪有余，多宜攻散；劳倦以 \n内伤不足，多宜温补。然此二者，病多相类，最易惑乱，故东垣特用内伤二字，以为外感之 \n别，盖恐以劳倦之伤，作伤寒之治，则必致杀人矣。此其大义，所当先辨。 \n一、内伤之证，东垣以饮食劳倦为言。然饮食之伤有二，而劳倦之伤亦有二，当辨如下 \n。 \n一、饮食内伤之证，凡饥饱失时者，太饥则仓廪空虚，必伤胃气；太饱则运化不及，必 \n伤脾气。然时饥时饱而致病者，其伤在饥，故当以调补为主，是即东垣之所谓也。其有不因 \n饥饱，而惟以纵肆口腹，遂致留滞不化者，当以化滞消食为主，方治当从饮食门。以上饮食 \n二证，一以伤饥不足，一以留滞有余，治当知辨也。 \n一、劳倦内伤之证，有因困倦而忽然发热，或怠惰嗜卧，懒于言语，其脉缓而大，或浮 \n或细，而无外邪者，此实时人之所谓劳发也，单宜温补为主。有因积劳饥饱，致伤脾肾，则 \n最易感邪，而病为发热头痛，脉紧恶寒，类伤寒等证，此内伤外感兼而有之，是即所谓劳力 \n感寒证也。若以此为真伤寒，则既由劳伤，已因不足，是伤寒正治之法不可用也。若以此为 \n非伤寒，则甚至发斑发狂，结胸谵语等证无不有之，而不曰伤寒，则人不服也。观东垣云∶ \n大梁受围之后，死者多人，岂俱感风寒者？诚至言也。第为兵革所困者明，为利名所困者暗 \n，故今人多以劳倦而患伤寒者，无非此类。昧者不知，而妄治殃人，岂其天年之果尽耶？诚 \n可悯也。以上劳倦二证，皆为内伤，而一以无邪，一以有邪，当辨而治也。 \n一、凡饥饱劳倦，皆能伤人。盖人以饮食为生，饮食以脾胃为主，今饥饱不时，则胃气 \n伤矣。又脾主四肢，而劳倦过度，则脾气伤矣。夫人以脾胃为养生之本，根本既伤，焉有不 \n病？而人不知慎，病斯及矣。故有以劳倦致动虚火而病者，有以饥馁致伤中气而病者，或以 \n劳倦之后，加之忍饥，或以忍饥之后，加之劳倦。然而两者之中，则尤以受饥为甚，所以饥 \n时不可临病，饥时不可劳形，饥时不可受寒，饥时不可任性，饥时不可伤精，饥时不可酬应 \n，知此数者，是即却病养生之道也。凡犯此者，岂惟贫贱者为然，而富贵者尤多有之，盖有 \n势不容已，则未免劳心竭力，而邪得乘虚而入者，皆内伤不足之证也。奈时医不能察，无论 \n虚实，悉曰伤寒，但知泻火逐邪及汗吐下三法，不知忘食忘劳，既困于己，再攻再削，又困 \n于医，标本俱竭，其能生乎？余目睹受此害者多矣，恨不一时救正，其如沿习成风，释疑未 \n易，故特演东垣大意，嘱笔于此，用效长夜之灯也，观者其三思焉。 \n\n\n\n<目录>卷之十六理集·杂证谟\\劳倦内伤\n\n<篇名>论治（共四条）\n\n属性：凡因劳倦而无外感者，或身虽微热，而脉见缓大无力，全不紧数，或懒言嗜卧，或身常 \n有汗，此即劳发之证，自与外感之头疼，脉紧，筋骨酸痛者不同，治宜以补养为主，气 \n复则愈。虚在阳分者，宜四君子汤、五君子煎。虚在阴分者，三阴煎、五阴煎，或大小营 \n煎。若脾胃中气受伤者，理中汤、养中煎。若血气俱虚者，五福饮、八珍汤，或十全大补汤 \n。 \n一、劳倦饥饱不时，而致寒热往来者，以饥时脏气馁，劳时腠理开，腠理开则邪易感， \n脏气馁则邪易入，所以饥饱劳倦不慎者，多令人为头痛发热恶寒等证。虽曰此由内伤，而实 \n有外感，虽有外感，而实以内伤。故东垣制补中益气汤，以参、 、归、术，而加之升、柴 \n，以助生长之气，使胃气上升，则气复于中，而阳达于外，此实和解之良法也。第今人以劳 \n倦伤阴，而精血受病者为尤多，则 、术之属，亦有不相宜者。兹余复制补阴益气煎，凡阳 \n虚于下，水亏不能作汗，而邪有不解者，此方尤胜之。愚有治脾三方并补中益气汤论，在后 \n饮食门，当参阅之。 \n一、劳倦感邪，以致伤寒，发热，头痛身痛，凡脉紧邪盛者，不得不从解散治之。若虚 \n本不甚，而表邪不解者，宜正柴胡饮。若外邪兼火者，一柴胡饮。外邪兼寒者，二柴胡饮。 \n若气血微虚者，三柴胡饮，或四柴胡饮。其有虚甚而邪不易解者，宜理阴煎，或大温中饮， \n所不可缓也。 \n一、夏日暑热之时，或于道途，或于田野，过于劳倦，而身体薄弱者，最易伤暑，此亦 \n劳倦之属，论治详暑证门阳暑条中。 \n\n\n\n<目录>卷之十六理集·杂证谟\\劳倦内伤\n\n<篇名>辨脉\n\n属性：东垣曰∶古人以脉上辨内外伤于人迎气口，人迎脉大于气口为外伤，气口脉大于人迎为 \n内伤，此辨固是，但其说有所未尽耳。外感风寒皆有余之证，是从前客邪来也，其病必见于 \n左手，左手主表，乃行阳二十五度。内伤饮食及饮食不节，劳役所伤，皆不足之病也，必见 \n于右手，右手主里，乃行阴二十五度。故外感寒邪，则独左手人迎脉浮紧，按之洪大。紧者 \n，后甚于弦，是足太阳寒水之脉；按之洪大而有力，中见手少阴心火之脉；丁与壬合，内显 \n洪大，乃伤寒脉也。若外感风邪，则人迎脉缓，而大于气口一倍，或两倍、三倍。内伤饮食 \n，则右寸气口脉大于人迎一倍；伤之重者，过在少阴则两倍，太阴则三倍，此内伤饮食之脉 \n。 \n愚谓东垣发明内伤一证，其功诚为不小，凡其所论，有的确不易者，兹俱详述于后，或 \n稍有疑似者，姑已置之。至若辨脉一条，则有不容不辨者，乃以左为人迎主表，右为气口主 \n里；外感则左手人迎浮紧，内伤则右手气口脉大，此其长中之短也。夫人迎本阳明胃脉，在 \n结喉两旁，气口本太阴肺脉，两手所同称也。迨晋之王叔和不知何所取义，突谓左为人迎， \n右为气口，左以候表，右以候里，而东垣宗之，故亦以为言，则大谬矣。且内伤外感之分， \n乃一表一里，不容紊也。如肝肾在左，岂无里乎？肠胃在右，岂非表乎？即如仲景之论伤寒， \n亦但以浮大为表，沉细为里。历溯仲景之前，以至仓、扁、轩、岐，初未闻有以左右言表里 \n者。迨自叔和之后，则悉宗其谬，而传始讹矣。 \n即无论六经之表里，而但以亲历所见者言之，如脉见紧数，此寒邪外感也，然未有左数 \n而右不数者。又如所云左大者为风邪，右大者为饮食，则尤其不然。夫人生禀赋之常，凡右 \n脉大者，十居八九，左脉大者，十居一二。若果阳邪在表，则大者更大，岂以右脉本大，而 \n可认为食乎？若饮食在脏，则强者愈强，岂以左脉本强，而可认为寒乎？不知此之大而紧，则 \n彼之小者亦必紧，彼之小而缓，则此之大者亦必缓，若因其偏强而即起偏见，则忘其本体者 \n多矣。故以大小言，则脉体有不同，可以左右分也；若以迟疾言，则息数本相应，不可以左 \n右分也。矧左表右里之说，既非经旨，亦非病征，乌足信哉！ \n或曰∶然则内伤外感何以辨之？曰∶六脉俱有表里，左右各有阴阳。外感者，两手俱紧 \n数，但当以有力无力分阴证阳证。内伤者，左右俱缓大，又必以有神无神辨虚邪实邪。然必 \n察左右之常体，以参久暂之病因，斯可得脉证之真。不然，则表里误认，攻补倒施。自叔和 \n至今，凡阴受其殃者，不知几多人矣，此不得不为辨正，以为东垣之一助也。此别有辨，在 \n《类经·藏象类》第十一篇，所当互证。 \n\n\n\n<目录>卷之十六理集·杂证谟\\劳倦内伤\n\n<篇名>述古（共三条）\n\n属性：李东垣曰∶古之至人，穷阴阳之造化，究乎生死之际，所着《内经》，悉言人以胃气为 \n本。盖人受水谷之气以生，所谓元气、谷气、营气、卫气、清气、春升生发之气，此六者以 \n谷气上行，皆胃气之别称也。使谷气不得升浮，生长之令不行，则无阳以护其营卫，不任风 \n寒，乃生寒热，皆脾胃之气不足所致也。然而与外感风寒之证颇同而理异。内伤脾胃，乃伤 \n其气；外伤风寒，乃伤其形。伤外为有余，有余者泻之；伤内为不足，不足者补之。汗之、 \n下之、吐之、克之，皆泻也；温之、和之、调之、养之，皆补也。内伤不足之病，苟误认作 \n外感有余之病而反泻之，则虚其虚也。《难经》曰∶实实虚虚，损不足而益有余，如此死者 \n，医杀之耳。然则奈何？曰∶惟当以甘温之剂，补其中，升其阳，甘寒以泻其火则愈。《内 \n经》曰∶劳者温之，损者温之。盖温能除大热，大忌苦寒之剂泻胃土耳。今立补中益气汤。 \n又曰∶夫喜怒不节，起居不时，有所劳伤，皆损其气，气衰则火旺，火旺则乘其脾土。 \n脾主四肢，故困热无气以动，懒于言语，动作喘乏，表热自汗，心烦不安。当病之时，宜安 \n心静坐以养其气，以甘寒泻其热火，以酸味收其散气，以甘温补其中气。经言劳者温之，损 \n者温之是也。《金匮要略》曰∶平人脉大为劳，虚极亦为劳。夫劳之为病，其脉浮大，手足 \n烦热，春夏剧，秋冬火差，以黄 建中汤治之，此亦温之之意也。 \n又曰∶脾胃受劳役之疾，饮食又复失节，耽病日久，事息心安，饱食太甚，病乃大作。 \n故内伤饮食，则亦恶风寒，是营卫失守，皮肤间无阳以滋养，不能任风寒也。皮毛之绝，则 \n心肺之本亦绝矣。盖胃气不升，元气不至，无以滋养心肺，乃不足之证也。计受病不一，饮 \n食失节，劳役所伤，因而饱食，内伤者极多，外伤者间而有之。举世医者，往往将元气不足 \n之证，便作外伤风寒表实之证，而反治心肺，是重绝其表也，安得不死乎？若曰不然，请以 \n众人之耳闻目见者证之。向者壬辰改元，京师戒严，迨三月下旬，受敌者凡半月，解围之后 \n，都人之不受病者，万无一二，既病而死者，继踵而不绝，都门十有二所，每日各门所送， \n多者二千，少者不下一千，似此者几三月。此百万人岂俱感风寒外伤者耶？大都人在围城中 \n，饮食失节，劳役所伤，不待言而知。由其朝饥暮饱，起居不时，寒温失所，动经三两月， \n胃气亏之久矣，一旦饱食太过，感而伤人，而又调治失宜，其死也无疑矣。非惟大梁为然， \n远在真佑、兴定间，如东平，如太原，如凤翔，解围之后，病伤而死，无不皆然。余在大梁 \n，凡所亲见，有发表者，有以巴豆推之者，有以承气汤下之者，俄而变结胸发黄，又以陷胸 \n汤丸及茵陈汤下之，无不死者。盖初非伤寒，以调治差误，变而似真伤寒之证，皆药之罪也 \n。往者不可追，来者犹可及，辄以生平已试之效，着《内外伤辨论》一篇，推明前哲之余论 \n，历举近事之变故，庶几同志者，审其或中，触类而长之，免后人之横夭耳。 \n东垣辨气少气盛曰∶外伤风寒者，其气壅盛而有余；内伤饮食劳役者，其口鼻中气皆短 \n促不足以息。何以分之？盖外伤风寒者，心肺元气初无减损，又添邪气助之，使鼻气壅塞不 \n利，面赤，其鼻中气不能出，并从口出，但发一言，必前轻后重，其声壮厉而有力者，乃有 \n余之验也。伤风则决然鼻流清涕，其声嗄，其言响如从瓮中出，亦前轻而后重，高揭而有力 \n，皆气盛有余之验也。内伤饮食劳役者，心肺之气先损，为热所伤，热既伤气，四肢无力以 \n动，故口鼻中皆短气少气，上喘懒语，人有所问，十不欲对其一，纵勉强答之，其气亦怯， \n其声亦低，是其气短少不足之验也。明白如此，虽妇人女子亦能辨之，岂有医者反不能辨之 \n乎？ \n东垣辨头痛曰∶内证头痛，有时而作，有时而止，外证头痛，常常有之，直须传入里实 \n方罢，此内外证之不同也。 \n\n\n\n<目录>卷之十六理集·杂证谟\\劳倦内伤\n\n<篇名>劳倦论列方\n\n属性：五福饮（新补六） 养中煎（新热四） 八珍汤（补十九） 理中汤（热一） 理阴煎（新热三） \n大营煎（新补十四） 小营煎（新补十五） 四君子汤（补一） 五君子煎（新热六） 大温中饮 \n（新散八） 一柴胡饮（新散一） 二柴胡饮（新散二） 三柴胡饮（新散三） 正柴胡饮（新散六） \n十全大补汤（补二十） 补中益气汤（补三十） 补阴益气煎（新补十六） 三阴煎（新补十一） \n五阴煎（新补十三） \n\n\n\n<目录>卷之十六理集·杂证谟\\劳倦内伤\n\n<篇名>论外备用方\n\n属性：人参养营汤（补二一） 当归黄 汤（补九七 热渴脉虚） \n\n\n\n<目录>卷之十六理集·杂证谟\\关格\n\n<篇名>经义\n\n属性：《六节藏象论》曰∶人迎一盛病在少阳，二盛病在太阳，三盛病在阳明，四盛以上为格 \n阳。寸口一盛病在厥阴，二盛病在少阴，三盛病在太阴，四盛以上为关阴。人迎与寸口俱盛 \n四倍以上为关格。关格之脉羸，不能极于天地之精气，则死矣。 \n《终始篇》曰∶人迎一盛，病在足少阳；一盛而躁，病在手少阳。人迎二盛，病在足太 \n阳；二盛而躁，病在手太阳。人迎三盛，病在足阳明；三盛而躁，病在手阳明。人迎四盛， \n且大且数，名曰溢阳，溢阳为外格。脉口一盛，病在足厥阴，一盛而躁，在手心主。脉口二 \n盛，病在足少阴，二盛而躁，在手少阴。脉口三盛，病在足太阴，三盛而躁，在手太阴。脉 \n口四盛，且大且数者，名曰溢阴，溢阴为内关，内关不通，死不治。人迎与太阴脉口俱盛四 \n倍以上，命曰关格，关格者，与之短期。以上俱有刺法，详载《类经·针刺类》。 \n《禁服篇》曰∶寸口主中，人迎主外，两者相应，俱往俱来，若引绳大小齐等。春夏人 \n迎微大，秋冬寸口微大，如是者，名曰平人。人迎四倍者，且大且数，名曰溢阳，溢阳为外 \n格，死不治。必审按其寒热，以验其脏腑之病。寸口四倍者，名曰内关，内关者，且大且数 \n，死不治。必审察其本末之寒温，以验其脏腑之病。 \n《脉度篇》曰∶五脏不和则七窍不通，六腑不和则留结为痈。故邪在腑则阳脉不和，阳 \n脉不和则气留之，气留之则阳气盛矣。阳气太盛则阴不利，阴脉不利则血留之，血留之则阴 \n气盛矣。阴气太盛，则阳气不能荣也，故曰关。阳气太甚，则阴气弗能荣也，故曰格。阴阳 \n俱盛，不得相荣，故曰关格。关格者，不得尽期而死也。 \n\n\n\n<目录>卷之十六理集·杂证谟\\关格\n\n<篇名>论证（共四条）\n\n属性：关格一证在《内经》本言脉体，以明阴阳离绝之危证也，如《六节藏象论》《终始篇》 \n《禁服篇》及《脉度》《经脉》等篇言之再四，其重可知。自秦越人《三难》曰∶上鱼为溢 \n，为外关内格。入尺为覆，为内关外格。此以尺寸言关格，已失本经之意矣。又仲景曰∶在 \n尺为关，在寸为格，关则不得小便，格则吐逆。故后世自叔和、东垣以来，无不以此相传， \n而竟置关格一证于乌有矣。再至丹溪，则曰此证多死，寒在上，热在下，脉两寸俱盛四倍以 \n上，法当吐，以提其气之横格，不必在出痰也。愚谓两寸俱盛四倍，又安得为寒在上耶？且 \n脉大如此，则浮豁无根，其虚可知，又堪吐乎？谬而又谬，莫此甚矣。夫《内经》云∶人迎 \n四倍，寸口四倍，既非尺寸之谓，而曰吐逆者，特隔食一证耳，曰不得小便者，特癃闭一证 \n耳，二证自有本条，其与关格何涉？数子且然，况其他乎，又安望治此者之无谬哉！ \n一、关格证在《内经》本以人迎察六腑之阳，寸口察五脏之阴，人迎盛至四倍以上，此 \n阳明经孤阳独见，水不济火也，故曰格阳，格阳者，阴格于阳也。气口盛至四倍以上，此太 \n阴经元阴无主，气不归精也，故曰关阴，关阴者，阳关于阴也。若人迎寸口俱盛至四倍以上 \n，且大且数，此其阳气不藏，故阴中无阳，阴气不升，故阳中无阴，阴阳相离，故名关格也 \n。凡见此者，总由酒色伤肾，情欲伤精，以致阳不守舍，故脉浮气露，亢极如此，此则真阴 \n败竭，元海无根，是亢龙有悔之象，最危之候也。 \n一、《内经》以人迎寸口并诊关格，今后世诊法，则但取寸口，而不察人迎，似于法有 \n未尽，然寸口为脉之大会，而脉见于彼，未有不见于此者，所以但察气口，则人迎之脉亦可 \n概见。故凡见寸口弦大至极，甚至四倍以上，且大且数者，便是关格之脉，不得误认为火证 \n。余尝诊此数人，察其脉则如弦如革，洪大异常，故云四倍；察其证则脉动身亦动，凡乳下 \n之虚里，脐傍之动气，无不舂舂然、振振然与脉俱应者；察其形气，则上有微喘，而动作则 \n喘甚，肢体而力，而寤寐多慌张。谓其为虚损，则本无咳嗽失血等证；谓其为痰火，则又无 \n实邪发热等证，此关格之所以异也。然惟富贵之人及形体丰肥者，多有此证，求其所因，则 \n无非耽嗜少艾，中年酒色所致，是虽与劳损证若有不同，而实即劳损之别名也。此老成之人 \n所以当知慎也。有喘论在喘证门，互阅可也。 \n一、本经《脉度篇》所云∶阴气太盛，则阳气不能荣也，故曰关；阳气太盛，则阴气弗 \n能荣也，故曰格，阴阳俱盛，不能相荣，故曰关格，关格者，不得尽期而死，此举脉证而兼 \n言之也。若以脉言则如前之四倍者是也；若以证言，则又有阴阳俱盛者，以阳病极于阳分， \n而阴病极于阴分也。凡阳盛于阳者，若乎当泻，而阴分见阴，有不可泻。阴极于阴者，若乎 \n当补，而阳分见阳，又不可补。病若此者，阳自阳而阳中无阴，阴自阴而阴中无阳，上下否 \n隔，两顾弗能，补之不可，泻之又不可，是亦关格之证也，有死而已。此与真寒假热，真热 \n假寒之证，大有不同，学人当辨其疑似。 \n\n\n\n<目录>卷之十六理集·杂证谟\\关格\n\n<篇名>论治（共三条）\n\n属性：关格之脉，必弦大至极。夫弦者为中虚，浮大者为阴虚，此肾水大亏，有阳无阴之脉也 \n。治此者，宜以峻补真阴为主，然又当察其虚中之寒热，阴中之阴阳，分别处治，斯尽善也 \n。 \n一、关格证，凡兼阳脏者必多热，宜一阴煎、左归饮、左归丸之类主之。兼阴脏者必多 \n寒，宜大营煎、右归饮、右归丸之类主之。若不热不寒，脏气本平者，宜五福饮、三阴煎及 \n大补元煎之类主之。 \n一、关格证，所伤根本已甚，虽药饵必不可废，如精虚者当助其精，气虚者当助其气， \n其有言难尽悉者，宜于古今补阵诸方中择宜用之。斯固治之之法，然必须远居别室，养静澄 \n心，假以岁月，斯可全愈。若不避绝人事，加意调理，而但靠药饵，则恐一暴十寒，得失相 \n半，终无济于事也。凡患此者，不可不知。 \n\n\n\n<目录>卷之十六理集·杂证谟\\关格\n\n<篇名>关格论列方\n\n属性：五福饮（新补六） 大营煎（新补十四） 大补元煎（新补一） 一阴煎（新补八） 三阴煎（ \n新补十一） 左归饮（新补二） 左归丸（新补四） 右归饮（新补三） 右归丸（新补五） \n\n\n\n<目录>卷之十七理集·杂证谟\\饮食门\n\n<篇名>经义\n\n属性：《平人气象论》曰∶平人之常气禀于胃，胃者平人之常气也，人无胃气曰逆，逆者死。 \n人以水谷为本，故人绝水谷则死，脉无胃气亦死，所谓无胃气者，但得真脏脉，不得胃气也 \n。 \n《营卫生会篇》曰∶人受气于谷，谷入于胃，以传于肺，五脏六腑，皆以受气，其清者 \n为营，浊者为卫，营在脉中，卫在脉外。 \n《五味篇》曰；天地之精气，其大数常出三入一，故谷不入，半日则气衰，一日则气少 \n矣。 \n《平人绝谷篇》曰∶肠胃之中常留谷二斗，水一斗五升；故平人日再后，后二升半，一 \n日中五升，七日五七三斗五升，而留水谷尽矣。故平人不食饮七日而死者，水谷精气津液皆 \n尽故也。 \n《六节藏象论》曰∶天食人以五气，地食人以五味。五气入鼻，藏于心肺，上使五色修 \n明，音声能彰。五味入口，藏于肠胃，味有所藏，以养五气，气和而生，津液相成，神乃自 \n生。 \n《刺节真邪论》曰∶真气者，所受于天，与谷气并而充身也。 \n《经脉别论》曰∶食气入胃，散精于肝，淫气于筋。食气入胃，浊气归心，淫精于脉， \n脉气流经，经气归于肺，肺朝百脉，输精于皮毛。毛脉合精，行气于腑。腑精神明，留于四 \n脏，气归于权衡。权衡以平，气口成寸，以决死生。饮入于胃，游溢精气，上输于脾。脾气 \n散精，上归于肺，通调水道，下输膀胱，水精四布，五经并行，合于四时五脏阴阳，揆度以 \n为常也。 \n《口问篇》曰∶谷入于胃，胃气上注于肺。 \n《营气篇》曰∶营气之道，内谷为宝。谷入于胃，乃传之肺，流溢于中，布散于外，精 \n专者，行于经隧。 \n《病能论》曰∶食入于阴，长气于阳。 \n《阴阳应象大论》曰∶水谷之寒热，感则害于六腑。形不足者，温之以气；精不足者， \n补之以味。 \n《五脏别论》曰∶胃者水谷之海，六腑之大源也。五味入口，藏于胃以养五脏气。 \n《至真要大论》曰∶五味入胃，各归所喜，故酸先入肝，苦先入心，甘先入脾，辛先入 \n肺，咸先入肾，久而增气，物化之常也。气增而久，夭之由也。（详诸气门治气条中） \n《藏气法时论》曰∶肝苦急，急食甘以缓之。心苦缓，急食酸以收之。脾苦湿，急食 \n苦以燥之。肺苦气上逆，急食苦以泄之。肾苦燥，急食辛以润之。肝欲散，急食辛以散之。 \n心欲软，急食咸以软之。脾欲缓，急食甘以缓之。肺欲收，急食酸以收之。肾欲坚，急食苦 \n以坚之。 \n《宣明五气篇》曰∶辛走气，气病无多食辛。咸走血，血病无多食咸。苦走骨，骨病无 \n多食苦。甘走肉，肉病无多食甘。酸走筋，筋病无多食酸。 \n《九针论》曰∶病在骨，无食咸。病在血，无食苦。 \n《五味篇》曰∶肝病禁辛，心病禁咸，脾病禁酸，肾病禁甘，肺病禁苦。 \n《五味论》曰∶酸走筋，多食之，令人癃。咸走血，多食之，令人渴。辛走气，多食之 \n，令人洞心。苦走骨，多食之，令人变呕。甘走肉，多食之，令人 心。 \n《生气通天论》曰∶阴之所生，本在五味，阴之五宫，伤在五味。是故味过于酸，肝气 \n以津，脾气乃绝。味过于咸，大骨气劳，短肌，心气抑。味过于甘，心气喘满，色黑，肾气 \n不衡。味过于苦，脾气不濡，胃气乃浓。味过于辛，筋脉沮弛，精神乃央。是故谨和五味， \n骨正筋柔，气血以流，腠理以密，如是则骨气以精，谨道如法，长有天命。 \n《五脏生成篇》曰∶多食咸，则脉凝泣而变色。多食苦，则皮槁而毛拔，多食辛，则筋 \n急而爪枯。多食酸，则肉胝胸而唇揭。多食甘，则骨痛而发落。 \n《刺法论》曰∶欲令脾实，气无滞，饱无久坐，食无太酸，无食一切生物，宜甘宜淡。 \n《灵兰秘典论》曰∶脾胃者，食廪之官，五味出焉。 \n《痹论》曰∶饮食自倍，肠胃乃伤。 \n《太阴阳明论》曰∶饮食不节，起居不时者，阴受之。阴受之，则入五脏。（详脾胃门） \n《本病论》曰∶饮食劳倦则伤脾。 \n《邪气脏腑病形篇》曰∶形寒寒饮则伤肺。肾脉微缓为洞，洞者，食入还出。 \n《刺志论》曰∶谷盛气盛，谷虚气虚，此其常也。反此者病。谷入多而气少，此谓反也 \n。谷不入而气多，此谓反也。谷入多而气少者，得之有所脱血，湿居下也。谷入少而气多者 \n，邪在胃及与肺也。 \n《脉解篇》曰∶少阴所谓恶闻食臭者，胃无气，故恶闻食臭也。 \n\n\n\n<目录>卷之十七理集·杂证谟\\饮食门\n\n<篇名>论证（共五条）\n\n属性：凡饮食伤脾之证，有寒伤，有热伤，有暂病，有久病，有虚证，有实证。但热者、暂者 \n、实者，人皆易知，而寒者、久者、虚者，人多不识。如今人以生冷瓜果致伤胃气，而为泻 \n、为痢、为痛之类者，人犹以为火证，而治以寒凉者，是不识寒证也。有偶因停滞而为胀， \n为痛者，人皆知其实也，然脾胃强壮者，即滞亦易化，惟其不能化者，则最有中虚之证。故 \n或以不食亦知饥，少食即作胀；或以无饥无饱，全然不思饮食；或以胃虚兼呕而腹满膨膨； \n或以火不生土而时食时吐；或中气不化，则胸喉若有所哽，而本非饮食之滞者；或因病致伤 \n胃气，则久不思食，而本非中满之病者。且胃病于暂者多实，脾病于久者多虚。时医于此， \n无论邪正久暂，鲜有不用开胃消导等剂，是不知虚证也。盖脾胃之职，原以化食为能，今既 \n不能化食，乃其所能者病，而尚可专意克伐以害其能乎？且凡欲治病，必须先藉胃气以为行 \n药之主，若胃气实者，攻之则去，而疾常易愈，此以胃气强而药力易行也。胃气虚者，攻亦 \n不去，此非药不去病也，以胃虚本弱，攻之则益弱，而药力愈不能行也。若久攻之，非惟药 \n不能行，必致元气愈伤，病必愈甚，尽去其能，必于死矣。矧体质贵贱尤有不同，凡藜藿壮 \n夫及新暴之病，自宜消伐，惟速去为善，若以弱质弱病，而罔顾虚实，概施欲速攻治之法， \n则无不危矣。 \n一、伤食者必恶食。 \n一、素喜冷食者，内必多热，素喜热食者，内必多寒，故内寒者不喜寒，内热者不喜热 \n。然热者嗜寒，多生中寒，寒者嗜热，多生内热，此《内经》所谓久而增气，物化之常也； \n气增而久，夭之由也。故凡治病养生者，又当于素禀中察其嗜好偏胜之弊。 \n一、饮食致病，凡伤于热者，多为火证，而停滞者少；伤于寒者，多为停滞，而全非火 \n证。大都饮食之伤，必因寒物者居多，而温平者次之，热者又次之。故治此者，不可不察其 \n所因。 \n一、偶病之人，多有非食而疑食者，曰∶某日曾食某物或某肉某面，其日即病。医者不 \n论虚实，但闻此言，且见胃口不开，必先治食。夫未病之人，谁有不食？岂必预为停食而待 \n病至者，斯可信其无食乎？及其病也，则或因劳倦，或因风寒，或因七情，病发不测，而且 \n无胀无滞，与食何干？药不对病，而妄行剥削，必反增病，此斯道中之莫须有也。由此推之 \n，则凡无据无证而妄指胡猜者，皆其类也，良可慨矣。 \n\n\n\n<目录>卷之十七理集·杂证谟\\饮食门\n\n<篇名>论治（共十一条）\n\n属性：凡治饮食暂伤者，亦当辨虚实。若停滞中焦，或胀或痛者，此实证也，当先去其食，宜 \n大和中饮主之。然去食莫先于理气，又惟排气饮为佳。若所停犹在上焦，莫若用吐为捷法， \n或用吐剂亦可。若食停下焦，痛极兼胀者，须下而去之，宜神佑丸，或备急丸，或赤金豆。 \n若偶伤生冷或油浊不堪等物，以致吐泻胀痛而邪气实者，宜抑扶煎，若无寒气者，以本方去 \n吴茱萸煎服，或用排气饮、和胃饮俱佳。若痛胀不解者，宜神香散兼用之。 \n一、饮食伤脾而吐泻已甚者，但察其无中满，无腹痛，而惟呕恶不能止，此其食物必已 \n尽去，而以中气受伤，大虚而然。或其人困倦不宁，少气多汗，六脉豁大无神者，宜理中汤 \n、五君子煎，或温胃饮之类主之。若吐甚极虚者，宜四味回阳饮；泻甚极虚者，宜胃关煎。 \n凡大吐大泻之后，多为腹胀，若但外胀而内不觉胀，或恶闻食气，不欲饮食者，皆脾气大虚 \n之候，速宜用前温补诸法调治之。 \n一、凡少年小儿辈，多有纵肆口腹，以致胃气不清，或时微胀，或时疼痛，或膨膨然不 \n思饮食，此皆伤脾而然。而实亦食滞使然也。滞多者，宜和胃饮；滞少者，宜枳术丸，或芍 \n药枳术丸，日渐服之，仍节饮食，自可全愈。 \n一、凡失饥伤饱，损及脾胃，多令人胸膈痞闷，不能消化，饮食少思，口中无味，或嗳 \n气吞酸，神体困倦，此皆脾气受伤，中虚而然，宜木香人参枳术丸，或大健脾丸去黄连主之 \n。其虚甚者，宜理中汤，或温胃饮。若虚在下焦，而阴中无阳，不能生土者，惟理阴煎加减 \n主之为善。 \n一、病后胃口不开，饮食不进者，有二证。盖一以浊气未净，或余火未清，但宜以小和 \n中饮加减主之。一以脾胃受伤，病邪虽去而中气未复，故或有数日不能食，或旬日不能开， \n或胸喉中若有所哽如梅核气者，此中本无停积，但以阳气未舒，阴翳作滞，胃气太虚，不能 \n运化而然。轻则温胃饮，甚则必加人参、附子，但使阳气得行，则胃口自开也。 \n一、凡饮酒致伤者，多宜除湿利水，若或伤气，亦宜间用人参。然其证有三，不可不辨 \n。一以酒湿伤脾，致生痰逆呕吐，胸膈痞塞，饮食减少者，宜葛花解酲汤、胃苓汤、五苓散 \n之类主之。一以酒热伤阴，或致发热动血者，宜黄芩芍药汤、清化饮、徙薪饮之类主之。一 \n以酒质伤脏，致生泄泻不已，若气强力壮者，惟五苓散、胃苓汤之类，皆可除湿止泻。若因 \n湿生寒，以泻伤阴，致损命门阳气者，非胃关煎及五德丸、九气丹之类不可。 \n一、怒气伤肝，则肝木之气必侵脾土，而胃气受伤，致妨饮食。此虽以肝气之逆，然肝 \n气无不渐散，而脾气之伤，则受其困矣，此所以不必重肝，而重当在脾也。故凡遇此证，但 \n当察其逆滞之有无，如无胁痛胀满等证，则不必疏气，单宜以养脾益气为主，如五味异功散 \n、归脾汤之属是也。或于补养药中少加乌药、青皮、白豆蔻以佐之亦可。 \n一、凡时食时吐，或朝食暮吐等证，详载反胃门。 \n一、善食而瘦者，多因有火，然当察火之微甚。微火者，微清之，如生地、芍药、丹皮 \n、沙参、麦冬、石斛、竹叶、地骨皮、黄芩、知母、细甘草之属是也。若火甚者，或随食 \n随饥，随饮随渴，或肌肤燥热，二便涩结，则石膏、黄连、栀子、黄柏、龙胆草、苦参之属 \n所不可免。此当查其三焦五脏，随所在而治之。然阳盛者阴必虚，如一阴煎、二阴煎、四阴 \n煎之属，皆当择而用也。 \n一、不能食而瘦者，必其脾胃虚弱，不能健运而然，故或为嗳气、吞酸、痞满，不饥等 \n证，宜四君子汤、归脾汤。若兼寒者，宜五君子煎、养中煎、理中汤。其命门火衰者，宜右 \n归饮、右归丸、八味地黄丸之类主之。 \n一、凡喜茶叶，喜食生米者，多因胃有伏火，所以能消此物。余尝以清火滋阴之药愈此 \n者数人，盖察其脉证有火象，故随用随效也。又有喜食炭者，必其胃寒而湿，故喜此燥涩之 \n物，亦当详察脉证，宜以健脾温胃为主。 \n一、食饮所伤，治当从类，如麦芽、神曲能消米面之积；砂仁、浓朴、萝卜子、阿魏能"}]);
})();
